	},
	[20180563] = {
		ID = 20180563,
		Text = "连续两发子弹命中靶心。",
	},
	[20180564] = {
		ID = 20180564,
		Text = "但伴随着开枪的震动，凯伊的忍耐也来到一个极限。",
	},
	[20180565] = {
		ID = 20180565,
		Speaker = "凯伊",
		Text = "哈……！啊……！",
	},
	[20180566] = {
		ID = 20180566,
		Speaker = "凯伊",
		Text = "不行……！",
	},
	[20180567] = {
		ID = 20180567,
		Speaker = "凯伊",
		Text = "人家要去了！ ！ ！",
	},
	[20180568] = {
		ID = 20180568,
		Text = "凯伊的下体大量喷水，身体也开始剧烈的颤抖抽搐。",
	},
	[20180569] = {
		ID = 20180569,
		Text = "第三发子弹受到影响，只打在了三分的位置。",
	},
	[20180570] = {
		ID = 20180570,
		Speaker = "凯伊",
		Text = "不行……！不可以再刺激下去了……！",
	},
	[20180571] = {
		ID = 20180571,
		Speaker = "凯伊",
		Text = "哥、哥哥……！",
	},
	[20180572] = {
		ID = 20180572,
		Speaker = "凯伊",
		Text = "快帮人家关掉……人家没力了……！",
	},
	[20180573] = {
		ID = 20180573,
		Text = "眼看凯伊整个人都快瘫软在地，我赶紧跑过去扶住凯伊。",
	},
	[20180574] = {
		ID = 20180574,
		Text = "并帮凯伊把情趣玩具给摘了下来。",
	},
	[20180575] = {
		ID = 20180575,
		Speaker = "凯伊",
		Text = "呼……呜……",
	},
	[20180576] = {
		ID = 20180576,
		Speaker = "凯伊",
		Text = "兄弟看到了吧？",
	},
	[20180577] = {
		ID = 20180577,
		Speaker = "凯伊",
		Text = "老子还是挺厉害的吧？",
	},
	[20180578] = {
		ID = 20180578,
		Speaker = "我",
		Text = "不叫我＂哥哥＂了？",
	},
	[20180579] = {
		ID = 20180579,
		Speaker = "凯伊",
		Text = "老子、老子没有！",
	},
	[20180580] = {
		ID = 20180580,
		Speaker = "凯伊",
		Text = "老子什么都没叫！",
	},
	[20180581] = {
		ID = 20180581,
		Speaker = "我",
		Text = "(十三分确实是一个我很难超过的成绩。)",
	},
	[20180582] = {
		ID = 20180582,
		Text = "感受着漫长岁月中久违的紧张时刻，我决定……",
	},
	[20180583] = {
		ID = 20180583,
	},
	[40040001] = {
		ID = 40040001,
	},
	[40040002] = {
		ID = 40040002,
		Text = "荒野星球的风沙卷着枯草滚过脚边，招牌被晒得褪了色。",
	},
	[40040003] = {
		ID = 40040003,
		Text = "我把凯伊寄来的那张皱巴巴的信塞回口袋，顺着车辙一路走进镇子。",
	},
	[40040004] = {
		ID = 40040004,
		Text = "远远地，我就看见那道熟悉的身影——",
	},
	[40040005] = {
		ID = 40040005,
		Text = "正倚在酒馆门口跟人比手画脚，嗓门大得整条街都听得见。",
	},
	[40040006] = {
		ID = 40040006,
		Speaker = "我",
		Text = "哟，这不是荒野星球最凶的枪手吗？",
	},
	[40040007] = {
		ID = 40040007,
		Speaker = "我",
		Text = "信上写得那么可怜，我还以为妳被人打得只剩半条命了呢。",
	},
	[40040008] = {
		ID = 40040008,
		Speaker = "凯伊",
		Text = "臭小子，你这张嘴是越来越欠揍了。",
	},
	[40040009] = {
		ID = 40040009,
		Speaker = "凯伊",
		Text = "信才寄出去三天，你就巴巴地跑回来，想老子想疯了吧？",
	},
	[40040010] = {
		ID = 40040010,
		Text = "走近了才看清楚，她眼底一圈淡淡的青黑。",
	},
	[40040011] = {
		ID = 40040011,
		Text = "蓬松的浅金犬尾也没了平时的精神，蔫蔫地垂在身后。",
	},
	[40040012] = {
		ID = 40040012,
		Speaker = "我",
		Text = "说真的，妳看起来比我上次走的时候憔悴多了。",
	},
	[40040013] = {
		ID = 40040013,
		Speaker = "我",
		Text = "是不是谁欺负妳了？报上名号，我去帮妳把场子踩了。",
	},
	[40040014] = {
		ID = 40040014,
		Speaker = "凯伊",
		Text = "少往自己脸上贴金，这还不是你害的。",
	},
	[40040015] = {
		ID = 40040015,
		Speaker = "凯伊",
		Text = "自从老子被那群家伙拱上首领的位子，每天光是听村民吵架就听得老子耳朵长茧。",
	},
	[40040016] = {
		ID = 40040016,
		Speaker = "我",
		Text = "喔？所以妳把自己累成这样，是因为整天惦记村民的鸡被谁偷了，不是因为想我？",
	},
	[40040017] = {
		ID = 40040017,
		Speaker = "凯伊",
		Text = "闭嘴！你是不知道当首领有多累！",
	},
	[40040018] = {
		ID = 40040018,
		Speaker = "凯伊",
		Text = "以前老子只要顾好自己那把枪，天大地大老子最大，谁惹到老子就跟谁决斗，干脆俐落。",
	},
	[40040019] = {
		ID = 40040019,
		Speaker = "凯伊",
		Text = "现在呢？东家的井跟西家的井吵着谁先用，南边那头老母牛跑进北边的菜园。",
	},
	[40040020] = {
		ID = 40040020,
		Speaker = "凯伊",
		Text = "老子还得去给人评理，你说可笑不可笑？",
	},
	[40040021] = {
		ID = 40040021,
		Speaker = "我",
		Text = "堂堂荒野枪手，最后沦落到当老母牛的仲裁人，这下场我还真没想到。",
	},
	[40040022] = {
		ID = 40040022,
		Speaker = "凯伊",
		Text = "你少在那边看好戏！",
	},
	[40040023] = {
		ID = 40040023,
		Speaker = "凯伊",
		Text = "而且不只这样，机械公民才刚拿到平等地位，镇上一堆老顽固看不顺眼。",
	},
	[40040024] = {
		ID = 40040024,
		Speaker = "凯伊",
		Text = "天天跑来老子面前告状，说什么铁罐头不该跟人平起平坐。",
	},
	[40040025] = {
		ID = 40040025,
		Speaker = "凯伊",
		Text = "老子把话撂下去了，就得负责到底，没得反悔。",
	},
	[40040026] = {
		ID = 40040026,
		Speaker = "我",
		Text = "所以妳现在后悔把自己搞成首领了？",
	},
	[40040027] = {
		ID = 40040027,
		Speaker = "凯伊",
		Text = "才没有！老子说出口的话就得做到，就算再累，老子也不后悔。",
	},
	[40040028] = {
		ID = 40040028,
		Speaker = "我",
		Text = "妳倒是挺负责任的嘛。",
	},
	[40040029] = {
		ID = 40040029,
		Speaker = "凯伊",
		Text = "废话，老子说出口的话，跟子弹一样，打出去就收不回来了。",
	},
	[40040030] = {
		ID = 40040030,
		Speaker = "我",
		Text = "那要不要老子——啊不是，要不要我留下来帮妳分担一点？",
	},
	[40040031] = {
		ID = 40040031,
		Speaker = "凯伊",
		Text = "你？",
	},
	[40040032] = {
		ID = 40040032,
		Speaker = "凯伊",
		Text = "算了吧，你留下来，老子还得多操心一件事，怕你把哪家姑娘给拐跑。",
	},
	[40040033] = {
		ID = 40040033,
		Speaker = "我",
		Text = "妳这是在夸我还是在损我？",
	},
	[40040034] = {
		ID = 40040034,
		Speaker = "凯伊",
		Text = "随你怎么想。",
	},
	[40040035] = {
		ID = 40040035,
		Speaker = "凯伊",
		Text = "反正你人都到了，晚上留下来，老子请你喝一杯，就当谢你跑这一趟。",
	},
	[40040036] = {
		ID = 40040036,
		Speaker = "我",
		Text = "妳这是在感谢我，还是想找人陪妳喝闷酒？",
	},
	[40040037] = {
		ID = 40040037,
		Speaker = "凯伊",
		Text = "谁、谁要喝闷酒！",
	},
	[40040038] = {
		ID = 40040038,
		Speaker = "我",
		Text = "好啦好啦，别炸毛，我留下来就是了。",
	},
	[40040039] = {
		ID = 40040039,
		Text = "她哼了一声，别过脸去，尾巴却藏不住喜悦的晃了晃。",
	},
	[40040040] = {
		ID = 40040040,
		Speaker = "凯伊",
		Text = "哼，算你识相。",
	},
	[40040041] = {
		ID = 40040041,
		Speaker = "凯伊",
		Text = "老子跟你讲，这首领的位子真不是人干的，每天一睁眼就有人堵在门口——",
	},
	[40040042] = {
		ID = 40040042,
		Text = "她话还没说完，街角就传来一阵急促的脚步声，一个扛着锄头的老农匆匆忙忙地跑了过来。",
	},
	[40040043] = {
		ID = 40040043,
		Speaker = "村民",
		Text = "首领！首领您可算在这儿，快、快帮帮忙，我家那又跟隔壁吵起来了，这回差点打出人命啊！",
	},
	[40040044] = {
		ID = 40040044,
		Speaker = "凯伊",
		Text = "又是那口井？",
	},
	[40040045] = {
		ID = 40040045,
		Speaker = "凯伊",
		Text = "老子昨天才判过一次，怎么今天又吵？",
	},
	[40040046] = {
		ID = 40040046,
		Speaker = "村民",
		Text = "隔壁那家说您判得不公，非要再讨个说法不可！",
	},
	[40040047] = {
		ID = 40040047,
		Speaker = "凯伊",
		Text = "行了行了，老子这就过去。",
	},
	[40040048] = {
		ID = 40040048,
		Text = "凯伊的尾巴垂下，随村民跑去。",
	},
	[40040049] = {
		ID = 40040049,
		Text = "另一道脚步声从人群后方缓缓靠近——",
	},
	[40040050] = {
		ID = 40040050,
		Speaker = "前首领",
		Text = "你们处的还不错嘛？",
	},
	[40040051] = {
		ID = 40040051,
		Text = "迎面而来的是曾经荒野星球的首领，自从凯伊接任之后就卸下了首领一职。",
	},
	[40040052] = {
		ID = 40040052,
		Text = "那双浑浊的眼睛眯了起来。",
	},
	[40040053] = {
		ID = 40040053,
		Text = "那个笑容底下藏着什么，我一时说不上来。",
	},
	[40040054] = {
		ID = 40040054,
		Speaker = "我",
		Text = "你有什么问题吗？",
	},
	[40040055] = {
		ID = 40040055,
		Speaker = "前首领",
		Text = "我能对星球的救世主有什么意见？",
	},
	[40040056] = {
		ID = 40040056,
		Speaker = "前首领",
		Text = "只是我没想到……",
	},
	[40040057] = {
		ID = 40040057,
		Speaker = "前首领",
		Text = "把她推上这位置的人总算知道回来看看了。",
	},
	[40040058] = {
		ID = 40040058,
		Speaker = "我",
		Text = "你听起来意见挺大的。",
	},
	[40040059] = {
		ID = 40040059,
		Speaker = "前首领",
		Text = "你想多了。",
	},
	[40040060] = {
		ID = 40040060,
		Text = "风沙又卷起一阵，吹得酒馆的招牌吱呀作响。",
	},
	[40040061] = {
		ID = 40040061,
	},
	[40040062] = {
		ID = 40040062,
	},
	[40040063] = {
		ID = 40040063,
		Speaker = "农民",
		Text = "首领，今天分配到我家的水又比昨天少了半桶，这样下去我的田要旱死了！",
	},
	[40040064] = {
		ID = 40040064,
		Speaker = "凯伊",
		Text = "老子昨天不是说了，先紧着育苗期的地浇？",
	},
	[40040065] = {
		ID = 40040065,
		Speaker = "凯伊",
		Text = "你那块地都收成过一轮了，急什么！",
	},
	[40040066] = {
		ID = 40040066,
		Speaker = "机械公民",
		Text = "首领，按新规矩，水量该按需求分，不是按谁嗓门大分。",
	},
	[40040067] = {
		ID = 40040067,
		Speaker = "农民",
		Text = "你一个铁罐子懂什么分配！",
	},
	[40040068] = {
		ID = 40040068,
		Speaker = "凯伊",
		Text = "够了，老子说了算——",
	},
	[40040069] = {
		ID = 40040069,
		Speaker = "凯伊",
		Text = "铁皮说得对，水量照需求排，谁不服自己来跟老子讲道理。",
	},
	[40040070] = {
		ID = 40040070,
		Speaker = "我",
		Text = "听起来还挺像那么回事的嘛，首领大人。",
	},
	[40040071] = {
		ID = 40040071,
		Speaker = "凯伊",
		Text = "闭嘴，都是你出的主意。",
	},
	[40040072] = {
		ID = 40040072,
		Speaker = "凯伊",
		Text = "说什么机械公民要平等分配，害得老子现在天天被两边夹着骂。",
	},
	[40040073] = {
		ID = 40040073,
		Speaker = "农民",
		Text = "多亏凯伊你当初宰了那头龙，我们现在才有干净水喝呢。",
	},
	[40040074] = {
		ID = 40040074,
		Speaker = "农民",
		Text = "不然我这把老骨头早渴死在这镇上了。",
	},
	[40040075] = {
		ID = 40040075,
		Speaker = "凯伊",
		Text = "……",
	},
	[40040076] = {
		ID = 40040076,
		Speaker = "我",
		Text = "凯伊？",
	},
	[40040077] = {
		ID = 40040077,
		Speaker = "凯伊",
		Text = "咿！",
	},
	[40040078] = {
		ID = 40040078,
		Speaker = "凯伊",
		Text = "不要碰老子的尾巴！你这个混帐！",
	},
	[40040079] = {
		ID = 40040079,
		Speaker = "我",
		Text = "你好像有点心不在焉喔？",
	},
	[40040080] = {
		ID = 40040080,
		Speaker = "凯伊",
		Text = "唔……这个……",
	},
	[40040081] = {
		ID = 40040081,
		Speaker = "村民A",
		Text = "首领，隔壁的羊又跑进我家菜园了，这已经第三次！",
	},
	[40040082] = {
		ID = 40040082,
		Speaker = "村民B",
		Text = "羊自己不长眼睛，我能怎么办！你不会自己修个像样的篱笆吗？",
	},
	[40040083] = {
		ID = 40040083,
		Speaker = "凯伊",
		Text = "都少说两句，老子明天叫人重新围一道篱笆，费用你们俩平摊。",
	},
	[40040084] = {
		ID = 40040084,
		Speaker = "凯伊",
		Text = "谁再吵老子直接把羊烤了大家当下酒菜。",
	},
	[40040085] = {
		ID = 40040085,
		Speaker = "村民B",
		Text = "……那倒也不必。",
	},
	[40040086] = {
		ID = 40040086,
		Text = "日头爬到正中，街角市集的喧闹声混着铁器敲打声传来。",
	},
	[40040087] = {
		ID = 40040087,
		Text = "我们刚穿过粮店门口，就听见前头传来打翻木箱的巨响，还有女人尖细的惊叫。",
	},
	[40040088] = {
		ID = 40040088,
		Speaker = "村民",
		Text = "别、别过来！我已经没有更多的水了！",
	},
	[40040089] = {
		ID = 40040089,
		Speaker = "流氓",
		Text = "你的仓库里面明明还有！今天不交水，我把这些破铜烂铁全给掀了！",
	},
	[40040090] = {
		ID = 40040090,
		Text = "流氓一脚踹翻旁边的木箱，腰间别着一把生锈的左轮。",
	},
	[40040091] = {
		ID = 40040091,
		Speaker = "我",
		Text = "凯伊，前面。",
	},
	[40040092] = {
		ID = 40040092,
		Speaker = "凯伊",
		Text = "老子早看见了。",
	},
	[40040093] = {
		ID = 40040093,
		Speaker = "凯伊",
		Text = "喂！兄弟，这地方现在归老子管，你这是在老子的地盘上撒野啊。",
	},
	[40040094] = {
		ID = 40040094,
		Speaker = "流氓",
		Text = "哟？这不是新首领吗？听说你决斗赢了那条龙，枪法天下第一——",
	},
	[40040095] = {
		ID = 40040095,
		Speaker = "流氓",
		Text = "来啊，让老子见识见识！",
	},
	[40040096] = {
		ID = 40040096,
		Text = "我下意识屏住呼吸，等着她拔出枪——那是她的招牌，是「正面决斗」的信条。",
	},
	[40040097] = {
		ID = 40040097,
		Text = "可她的手只在枪托上轻轻一碰，又松开了，转而握紧了拳头。",
	},
	[40040098] = {
		ID = 40040098,
		Text = "话音未落，她闪过子弹、欺身而上，一肘砸在流氓腹部。",
	},
	[40040099] = {
		ID = 40040099,
		Text = "反手一个过肩摔把人掼进土堆里。",
	},
	[40040100] = {
		ID = 40040100,
		Text = "整套动作快得像是练过千百遍的体术，而不是她平时挂在嘴边的枪法。",
	},
	[40040101] = {
		ID = 40040101,
		Speaker = "凯伊",
		Text = "你这种垃圾也配让老子浪费一颗子弹？",
	},
	[40040102] = {
		ID = 40040102,
		Speaker = "流氓",
		Text = "哇啊——",
	},
	[40040103] = {
		ID = 40040103,
		Text = "流氓连滚带爬地从土堆里冲出去，连枪都没敢捡，一溜烟没了影。",
	},
	[40040104] = {
		ID = 40040104,
		Text = "凯伊站在原地，呆愣的低头望着地上的枪，额头上留下冷汗。",
	},
	[40040105] = {
		ID = 40040105,
		Speaker = "我",
		Text = "妳……怎么不开枪？",
	},
	[40040106] = {
		ID = 40040106,
		Speaker = "凯伊",
		Text = "浪费子弹。",
	},
	[40040107] = {
		ID = 40040107,
		Speaker = "我",
		Text = "妳以前打个喝醉酒闹事的都要先开一枪示威。",
	},
	[40040108] = {
		ID = 40040108,
		Speaker = "凯伊",
		Text = "老子今天心情不好。",
	},
	[40040109] = {
		ID = 40040109,
		Speaker = "村民",
		Text = "谢、谢谢首领，还有这位……",
	},
	[40040110] = {
		ID = 40040110,
		Speaker = "我",
		Text = "小事，妳人还好吧？",
	},
	[40040111] = {
		ID = 40040111,
		Speaker = "村民",
		Text = "多亏首领和这位少见的人物在，不然我这铺子怕是要关门了。",
	},
	[40040112] = {
		ID = 40040112,
		Speaker = "凯伊",
		Text = "行了行了，东西收拾收拾，以后有事直接去镇公所报，别自己扛着。",
	},
	[40040113] = {
		ID = 40040113,
		Speaker = "我",
		Text = "凯伊。",
	},
	[40040114] = {
		ID = 40040114,
		Speaker = "凯伊",
		Text = "干嘛。",
	},
	[40040115] = {
		ID = 40040115,
		Speaker = "我",
		Text = "没事，就是觉得妳今天怪怪的。",
	},
	[40040116] = {
		ID = 40040116,
		Speaker = "凯伊",
		Text = "少多管闲事，走了，天黑前还得去水塔那边巡一圈。",
	},
	[40040117] = {
		ID = 40040117,
		Speaker = "我",
		Text = "妳这首领当得，比学姊那种正经行政官还操劳啊。",
	},
	[40040118] = {
		ID = 40040118,
		Speaker = "凯伊",
		Text = "别拿老子跟那大胸部女人比，她好歹有些伙伴，老子这边啥都得自己扛。",
	},
	[40040119] = {
		ID = 40040119,
		Speaker = "我",
		Text = "所以才要我留下来帮忙啊，总会有办法的。",
	},
	[40040120] = {
		ID = 40040120,
		Speaker = "凯伊",
		Text = "谁要你帮忙了！",
	},
	[40040121] = {
		ID = 40040121,
		Text = "走到水塔时，夕阳已经把整条街染成了铁锈色的红。",
	},
	[40040122] = {
		ID = 40040122,
	},
	[40040123] = {
		ID = 40040123,
	},
	[40040124] = {
		ID = 40040124,
		Text = "深夜，荒野星球的风声卡在木墙缝隙里低鸣。",
	},
	[40040125] = {
		ID = 40040125,
		Text = "我窝在凯伊家客厅的旧沙发上迷迷糊糊地睡着。",
	},
	[40040126] = {
		ID = 40040126,
		Text = "直到一声压抑却尖锐的惊呼从隔壁房间撕开夜色——",
	},
	[40040127] = {
		ID = 40040127,
		Speaker = "凯伊",
		Text = "不要……不要过来……求你别过来……",
	},
	[40040128] = {
		ID = 40040128,
		Text = "我几乎是滚下沙发的。推开凯伊房门时，月光正好照在她发抖的背脊上——",
	},
	[40040129] = {
		ID = 40040129,
		Text = "被单被抓得皱成一团，长枪就靠在床边，像是连睡着都不肯放下防备。",
	},
	[40040130] = {
		ID = 40040130,
		Speaker = "我",
		Text = "凯伊，凯伊，醒醒——没事，我来了。",
	},
	[40040131] = {
		ID = 40040131,
		Speaker = "凯伊",
		Text = "谁、谁在那——老子的枪呢！",
	},
	[40040132] = {
		ID = 40040132,
		Speaker = "我",
		Text = "是我，妳在作梦。",
	},
	[40040133] = {
		ID = 40040133,
		Speaker = "凯伊",
		Text = "谁、谁说老子在作梦，老子只是……冷到发抖而已。",
	},
	[40040134] = {
		ID = 40040134,
		Speaker = "我",
		Text = "凯伊，告诉我妳怎么了？",
	},
	[40040135] = {
		ID = 40040135,
		Speaker = "凯伊",
		Text = "屁话，荒野星球晚上本来就冷，冻死人不偿命。",
	},
	[40040136] = {
		ID = 40040136,
		Speaker = "我",
		Text = "那我不走了，妳不说清楚我就坐在这。",
	},
	[40040137] = {
		ID = 40040137,
		Speaker = "凯伊",
		Text = "……你刚才，听到什么了。",
	},
	[40040138] = {
		ID = 40040138,
		Speaker = "我",
		Text = "妳喊了『不要过来』，喊了好几次。而且妳现在，也没力气骗我。",
	},
	[40040139] = {
		ID = 40040139,
		Speaker = "凯伊",
		Text = "……你这人，什么时候变得这么固执。",
	},
	[40040140] = {
		ID = 40040140,
		Speaker = "我",
		Text = "从妳开始半夜尖叫的时候。",
	},
	[40040141] = {
		ID = 40040141,
		Speaker = "凯伊",
		Text = "还记得我是怎么成为首领的吗？",
	},
	[40040142] = {
		ID = 40040142,
		Text = "我没有回答，只是盯着凯伊。",
	},
	[40040143] = {
		ID = 40040143,
		Speaker = "凯伊",
		Text = "……从老子杀了龙族婆娘那天开始，每天晚上，都做同一个梦。",
	},
	[40040144] = {
		ID = 40040144,
		Speaker = "凯伊",
		Text = "同样的水源，同样的三颗子弹——",
	},
	[40040145] = {
		ID = 40040145,
		Speaker = "凯伊",
		Text = "……同样的死亡。",
	},
	[40040146] = {
		ID = 40040146,
		Speaker = "我",
		Text = "凯伊，那只是梦而已。",
	},
	[40040147] = {
		ID = 40040147,
		Speaker = "凯伊",
		Text = "那不是梦。",
	},
	[40040148] = {
		ID = 40040148,
		Speaker = "凯伊",
		Text = "为了水、为了私欲，老子把她杀了。",
	},
	[40040149] = {
		ID = 40040149,
		Speaker = "我",
		Text = "妳救了这颗星球上的人。",
	},
	[40040150] = {
		ID = 40040150,
		Speaker = "凯伊",
		Text = "那代表龙族婆娘得死吗？",
	},
	[40040151] = {
		ID = 40040151,
		Speaker = "凯伊",
		Text = "梦里，扣扳机的永远是老子。",
	},
	[40040152] = {
		ID = 40040152,
		Speaker = "我",
		Text = "那不是妳的错。",
	},
	[40040153] = {
		ID = 40040153,
		Speaker = "凯伊",
		Text = "不是老子的错？老子坐上这个位置，踩的就是她的血——先祖好友唯一的女儿。",
	},
	[40040154] = {
		ID = 40040154,
		Speaker = "我",
		Text = "妳跟妳先祖不一样。",
	},
	[40040155] = {
		ID = 40040155,
		Speaker = "凯伊",
		Text = "一样，老子这辈子最痛恨的，就是被「大义」、「使命」这种鬼话牵着走——",
	},
	[40040156] = {
		ID = 40040156,
		Speaker = "凯伊",
		Text = "混帐老爸总是让我当个独行侠，离人群越远越好。",
	},
	[40040157] = {
		ID = 40040157,
		Speaker = "凯伊",
		Text = "也许是对的，也许就不该出头，染得自己一身血。",
	},
	[40040158] = {
		ID = 40040158,
		Speaker = "我",
		Text = "难怪妳今天在镇上，那个混混明明找碴，妳却没拔枪。",
	},
	[40040159] = {
		ID = 40040159,
		Speaker = "凯伊",
		Text = "……老子现在只要摸到枪柄，脑子里就会闪过那三颗子弹的重量。",
	},
	[40040160] = {
		ID = 40040160,
		Speaker = "我",
		Text = "手这么冷，妳到底抖多久了。",
	},
	[40040161] = {
		ID = 40040161,
		Speaker = "凯伊",
		Text = "……从第一次做那个梦开始，没停过。",
	},
	[40040162] = {
		ID = 40040162,
		Speaker = "我",
		Text = "为什么不早点告诉我。",
	},
	[40040163] = {
		ID = 40040163,
		Speaker = "凯伊",
		Text = "说什么，说老子这个新首领夜夜梦见自己是杀人凶手？说出去，以后谁还服老子管。",
	},
	[40040164] = {
		ID = 40040164,
		Speaker = "凯伊",
		Text = "村民们日日夜夜的感谢老子杀了龙族婆娘。",
	},
	[40040165] = {
		ID = 40040165,
		Speaker = "凯伊",
		Text = "她真的该死吗？",
	},
	[40040166] = {
		ID = 40040166,
		Speaker = "凯伊",
		Text = "如果当时，死在那边的是老子，或许轻松的些。",
	},
	[40040167] = {
		ID = 40040167,
		Speaker = "我",
		Text = "没关系，慢慢说。",
	},
	[40040168] = {
		ID = 40040168,
		Speaker = "凯伊",
		Text = "人家很抱歉，抱歉没出息到需要你这样抓着手才睡得着。",
	},
	[40040169] = {
		ID = 40040169,
		Speaker = "凯伊",
		Text = "抱歉——什么首领，连自己做的梦都控制不了。",
	},
	[40040170] = {
		ID = 40040170,
		Speaker = "我",
		Text = "妳不需要道歉，也不用一个人哭，至少我会陪妳。",
	},
	[40040171] = {
		ID = 40040171,
		Speaker = "凯伊",
		Text = "谁跟你哭了，老子只是眼睛进沙——这种鬼地方，半夜哪来的沙跑进屋里。",
	},
	[40040172] = {
		ID = 40040172,
		Speaker = "我",
		Text = "好，是沙。",
	},
	[40040173] = {
		ID = 40040173,
		Speaker = "凯伊",
		Text = "……你会留在这里吗？就……今晚。",
	},
	[40040174] = {
		ID = 40040174,
		Speaker = "我",
		Text = "我哪里都不去。",
	},
	[40040175] = {
		ID = 40040175,
		Text = "我握着凯伊渐渐放松下来的手，看着她的呼吸慢慢平稳睡去——",
	},
	[40040176] = {
		ID = 40040176,
		Speaker = "凯伊",
		Text = "……谢谢……",
	},
	[40040177] = {
		ID = 40040177,
		Text = "她不知道的是，葛蕾香此刻或许正活得好好的，藏身在某个我们谁都找不到的角落。",
	},
	[40040178] = {
		ID = 40040178,
		Text = "这个秘密我一直没说出口，此刻握着她的手。",
	},
	[40040179] = {
		ID = 40040179,
		Text = "却觉得自己像是害她多背了一份原本不该由她扛的罪。",
	},
	[40040180] = {
		ID = 40040180,
		Speaker = "我",
		Text = "我真是个混帐啊……",
	},
	[40040181] = {
		ID = 40040181,
	},
	[40040182] = {
		ID = 40040182,
	},
	[40040183] = {
		ID = 40040183,
		Text = "木桌板凳嘎吱作响，酒馆里混着劣质酒精跟尘土的味道。",
	},
	[40040184] = {
		ID = 40040184,
		Speaker = "我",
		Text = "来，我请客——",
	},
	[40040185] = {
		ID = 40040185,
		Speaker = "凯伊",
		Text = "老子的镇老子请客，这什么废话，兄弟你少啰唆。",
	},
	[40040186] = {
		ID = 40040186,
		Speaker = "我",
		Text = "难得看你笑。昨天你脸臭得跟三天没洗的袜子一样。",
	},
	[40040187] = {
		ID = 40040187,
		Speaker = "凯伊",
		Text = "谁跟你说老子臭了！",
	},
	[40040188] = {
		ID = 40040188,
		Speaker = "凯伊",
		Text = "……谁有空管什么睡不睡。",
	},
	[40040189] = {
		ID = 40040189,
		Speaker = "我",
		Text = "所以我才把你拖出来喝一杯啊。",
	},
	[40040190] = {
		ID = 40040190,
		Speaker = "凯伊",
		Text = "哈！算你有点良心，兄弟。",
	},
	[40040191] = {
		ID = 40040191,
		Text = "酒馆里骰子滚动、有人哼着跑调小调的背景声，被一声椅子拖过地板的刺耳声盖过。",
	},
	[40040192] = {
		ID = 40040192,
		Text = "一个比常人高出一个头的男人大步走向凯伊身后那张空着的圆桌坐下。",
	},
	[40040193] = {
		ID = 40040193,
		Text = "动作大得像是故意要人注意。",
	},
	[40040194] = {
		ID = 40040194,
		Speaker = "神秘男子",
		Text = "哟，这不是咱们新任的首领大人吗。",
	},
	[40040195] = {
		ID = 40040195,
		Speaker = "凯伊",
		Text = "你谁啊。",
	},
	[40040196] = {
		ID = 40040196,
		Text = "路过的，顺便来瞻仰瞻仰传说中连开三枪就杀死龙的大英雄。",
	},
	[40040197] = {
		ID = 40040197,
		Speaker = "凯伊",
		Text = "啧。",
	},
	[40040198] = {
		ID = 40040198,
		Speaker = "凯伊",
		Text = "老子心情正好，你到底想干嘛。",
	},
	[40040199] = {
		ID = 40040199,
		Speaker = "神秘男子",
		Text = "没什么啊，就是想问问——",
	},
	[40040200] = {
		ID = 40040200,
		Text = "男子刻意顿了顿，匕首在桌面上敲了两下。",
	},
	[40040202] = {
		ID = 40040202,
		Speaker = "凯伊",
		Text = "……什——！",
	},
	[40040203] = {
		ID = 40040203,
		Speaker = "我",
		Text = "！ ？",
	},
	[40040204] = {
		ID = 40040204,
		Speaker = "神秘男子",
		Text = "喔喔，反应这么大，看来我猜对了。",
	},
	[40040205] = {
		ID = 40040205,
		Text = "五、六声上膛的喀啦声几乎同时响起，围住整张桌子的方向全是黑洞洞的枪口。",
	},
	[40040206] = {
		ID = 40040206,
		Speaker = "凯伊",
		Text = "臭小子——",
	},
	[40040207] = {
		ID = 40040207,
		Text = "凯伊一脚把桌子踹翻立起当作掩体，骂声混在枪声第一响里。",
	},
	[40040208] = {
		ID = 40040208,
		Speaker = "我",
		Text = "老板妳也小心！",
	},
	[40040209] = {
		ID = 40040209,
		Text = "我扑到吧台后方保护好老板。",
	},
	[40040210] = {
		ID = 40040210,
		Speaker = "我",
		Text = "凯伊，你能开枪吗！",
	},
	[40040211] = {
		ID = 40040211,
		Speaker = "凯伊",
		Text = "废话，老子是荒野最强枪手！",
	},
	[40040212] = {
		ID = 40040212,
		Text = "凯伊的手伸出掩体开了数枪，但全部都射在了窗户和墙上。",
	},
	[40040213] = {
		ID = 40040213,
		Speaker = "神秘男子",
		Text = "喔喔喔——最强枪手连个瓶子都打不中喔？",
	},
	[40040214] = {
		ID = 40040214,
		Speaker = "凯伊",
		Text = "啧。",
	},
	[40040215] = {
		ID = 40040215,
		Speaker = "我",
		Text = "没事，这年头手抖很正常。",
	},
	[40040216] = {
		ID = 40040216,
		Speaker = "凯伊",
		Text = "你给我闭嘴！不能开枪老子也有办法！",
	},
	[40040217] = {
		ID = 40040217,
		Text = "凯伊从腰间扯出一条盘起的套索，眼神重新亮了起来。",
	},
	[40040218] = {
		ID = 40040218,
		Speaker = "凯伊",
		Text = "掩护老子。",
	},
	[40040219] = {
		ID = 40040219,
		Text = "凯伊扔出套索，套住了某人的手，用力勾住后直接将其拉倒撞向另一人。",
	},
	[40040220] = {
		ID = 40040220,
		Text = "随后她便压低身子冲了出去。",
	},
	[40040221] = {
		ID = 40040221,
		Speaker = "凯伊",
		Text = "看好了！",
	},
	[40040222] = {
		ID = 40040222,
		Text = "凯伊踩着翻倒的桌面跃过去，一脚把最近的人踹进酒柜。",
	},
	[40040223] = {
		ID = 40040223,
		Text = "高大的男人举起手想要攻击凯伊，瞬间一个白色瓷盘在他脸上破裂。",
	},
	[40040224] = {
		ID = 40040224,
		Speaker = "我",
		Text = "抱歉啊各位，这盘子是我借的，记得跟老板算帐。",
	},
	[40040225] = {
		ID = 40040225,
		Text = "趁着男人分神，凯伊直接将一个酒瓶砸在男人脸上。",
	},
	[40040226] = {
		ID = 40040226,
		Text = "几个照面下来，桌椅碎片与呻吟声取代了原本的枪响。",
	},
	[40040227] = {
		ID = 40040227,
		Text = "六个大男人东倒西歪地躺了满地，唯独那个高大的男人还在地上挣扎。",
	},
	[40040228] = {
