	[40040361] = {
		ID = 40040361,
		Speaker = "惊慌的村民",
		Text = "首、首领大人……前首领他，不知道从哪弄来一身邪气。",
	},
	[40040362] = {
		ID = 40040362,
		Speaker = "惊慌的村民",
		Text = "把守卫全打飞，抢了车站那辆老火车，直接朝铁轨那头开走了！",
	},
	[40040363] = {
		ID = 40040363,
		Speaker = "惊慌的村民",
		Text = "求求你们，一定要把那疯子拦下来，不然我们水源真的要断了！",
	},
	[40040364] = {
		ID = 40040364,
		Speaker = "凯伊",
		Text = "放心，老子既然是首领，就不会不管。",
	},
	[40040365] = {
		ID = 40040365,
		Speaker = "我",
		Text = "火车？开去哪？",
	},
	[40040366] = {
		ID = 40040366,
		Speaker = "凯伊",
		Text = "那辆破铜烂铁锈到骨子里，连车轮都焊死了，根本不该还能跑！",
	},
	[40040367] = {
		ID = 40040367,
		Speaker = "凯伊",
		Text = "那是人龙大战留下来的古迹，摆着当纪念碑用的，谁有办法让它重新动起来！",
	},
	[40040368] = {
		ID = 40040368,
		Speaker = "我",
		Text = "现在是讨论它凭什么能动的时候吗？它要开去哪，才是问题吧。",
	},
	[40040369] = {
		ID = 40040369,
		Speaker = "凯伊",
		Text = "……更大的龙族墓场，在这片大地的另一头。",
	},
	[40040370] = {
		ID = 40040370,
		Speaker = "我",
		Text = "那里跟你有什么关系？",
	},
	[40040371] = {
		ID = 40040371,
		Speaker = "凯伊",
		Text = "天知道那里有多少龙骨——那地方，不该有人再靠近。",
	},
	[40040372] = {
		ID = 40040372,
		Speaker = "我",
		Text = "所以前首领是想去挖更多力量？",
	},
	[40040373] = {
		ID = 40040373,
		Speaker = "凯伊",
		Text = "老子要是知道就不用站在这给你当靶子问了！",
	},
	[40040374] = {
		ID = 40040374,
		Speaker = "凯伊",
		Text = "而且老子现在是首领了，镇子被砸成这样，要是不去追，以后还有什么脸站在这里。",
	},
	[40040375] = {
		ID = 40040375,
		Speaker = "我",
		Text = "所以你是想证明自己配得上这个位子，还是单纯想教训那家伙？",
	},
	[40040376] = {
		ID = 40040376,
		Speaker = "凯伊",
		Text = "……以前老子只需要管自己想要什么。",
	},
	[40040377] = {
		ID = 40040377,
		Speaker = "凯伊",
		Text = "现在这破镇子也是老子的了。",
	},
	[40040378] = {
		ID = 40040378,
		Speaker = "我",
		Text = "这种时候还嘴硬，真不愧是你。行吧，那还等什么，追上去问他本人。",
	},
	[40040379] = {
		ID = 40040379,
		Speaker = "我",
		Text = "大叔，借两匹马，现在。",
	},
	[40040380] = {
		ID = 40040380,
		Text = "马、马棚也被砸了大半，剩下的都吓坏了，谁敢靠近……",
	},
	[40040381] = {
		ID = 40040381,
		Text = "我没等对方把话说完，已经翻进摇摇欲坠的馬廄，一手一个，拉出两匹还算清醒的马。",
	},
	[40040382] = {
		ID = 40040382,
		Speaker = "凯伊",
		Text = "……你到底哪来这么多乱七八糟的招数。",
	},
	[40040383] = {
		ID = 40040383,
		Speaker = "我",
		Text = "总会有办法的，上马吧，兄弟。",
	},
	[40040384] = {
		ID = 40040384,
		Speaker = "凯伊",
		Text = "谁、谁是你兄弟啊笨蛋——你学老子做什么！",
	},
	[40040385] = {
		ID = 40040385,
		Speaker = "我",
		Text = "你自己整天兄弟兄弟的，借你用一下，会少一块肉？",
	},
	[40040386] = {
		ID = 40040386,
		Speaker = "凯伊",
		Text = "……人家才不是这个意思啦。",
	},
	[40040387] = {
		ID = 40040387,
		Speaker = "我",
		Text = "脸红什么，上马吧，再拖下去，火车都翻过山头了。",
	},
	[40040388] = {
		ID = 40040388,
		Speaker = "凯伊",
		Text = "老子早就准备好了！你可跟紧点，别掉队，兄弟！",
	},
	[40040389] = {
		ID = 40040389,
	},
	[40040390] = {
		ID = 40040390,
	},
	[40040391] = {
		ID = 40040391,
		Text = "两匹马踏上铁轨旁的碎石地，马蹄声混着远方渐弱的汽笛，朝着大地的另一头追去。",
	},
	[40040392] = {
		ID = 40040392,
		Text = "远方铁轨上，一缕黑烟拖着长长的尾巴，在干裂的地平线上缓缓爬行——那辆火车，还在视线范围内。",
	},
	[40040393] = {
		ID = 40040393,
		Speaker = "我",
		Text = "看到没，烟还在冒，他跑不了多远。",
	},
	[40040394] = {
		ID = 40040394,
		Speaker = "凯伊",
		Text = "那就别废话了——追！",
	},
	[40040395] = {
		ID = 40040395,
	},
	[40040396] = {
		ID = 40040396,
	},
	[40040397] = {
		ID = 40040397,
		Speaker = "我",
		Text = "抓稳了。",
	},
	[40040398] = {
		ID = 40040398,
		Speaker = "凯伊",
		Text = "妳才要抓稳吧。",
	},
	[40040399] = {
		ID = 40040399,
		Speaker = "我",
		Text = "他还在车上吗？",
	},
	[40040400] = {
		ID = 40040400,
		Speaker = "凯伊",
		Text = "老子能闻到那股恶心的味道。",
	},
	[40040401] = {
		ID = 40040401,
		Speaker = "凯伊",
		Text = "兄弟，这次不是闹着玩的。",
	},
	[40040402] = {
		ID = 40040402,
		Text = "我半趴在马背上，让马摇摇晃晃地靠近车尾，随后奋力一跃跳上了火车尾的平台。",
	},
	[40040403] = {
		ID = 40040403,
	},
	[40040404] = {
		ID = 40040404,
	},
	[40040405] = {
		ID = 40040405,
		Text = "随后凯伊也跳了过来，被我的手拉住。",
	},
	[40040406] = {
		ID = 40040406,
		Text = "随后车厢深处传来脚步声，一下，一下，沉得不像人的重量。",
	},
	[40040407] = {
		ID = 40040407,
		Text = "门由内而外被撞开，前首领走了出来——",
	},
	[40040408] = {
		ID = 40040408,
		Text = "上次见他时那些扭曲的鳞纹还只爬到半张脸，如今已经吞掉了整条手臂。",
	},
	[40040409] = {
		ID = 40040409,
		Text = "指节肿胀变形成暗色的爪，渗着不属于人类的黑色体液，步伐却仍端着他自己以为优雅的架子。",
	},
	[40040410] = {
		ID = 40040410,
		Speaker = "我",
		Text = "他……变成这样了？",
	},
	[40040411] = {
		ID = 40040411,
		Speaker = "凯伊",
		Text = "岂止是变了。",
	},
	[40040412] = {
		ID = 40040412,
		Speaker = "前首领",
		Text = "哟，这不是新首领大人吗，还特地把跟班带来送死。",
	},
	[40040413] = {
		ID = 40040413,
		Speaker = "凯伊",
		Text = "老子可不是来送死的，是来送你上路的。",
	},
	[40040414] = {
		ID = 40040414,
		Text = "前首领抬起那只变形的手，无奈的耸肩。",
	},
	[40040415] = {
		ID = 40040415,
		Speaker = "前首领",
		Text = "可惜啊，真的可惜。",
	},
	[40040416] = {
		ID = 40040416,
		Speaker = "前首领",
		Text = "要是妳乖乖夹着尾巴逃跑，我没准还大发慈悲，留妳一条命。",
	},
	[40040417] = {
		ID = 40040417,
		Speaker = "凯伊",
		Text = "逃跑？",
	},
	[40040418] = {
		ID = 40040418,
		Speaker = "凯伊",
		Text = "老子的字典里没那个字。",
	},
	[40040419] = {
		ID = 40040419,
		Speaker = "前首领",
		Text = "那就别怪我不客气了，首领的名号，好歹也得赢回来才像话。",
	},
	[40040420] = {
		ID = 40040420,
		Speaker = "凯伊",
		Text = "少废话。",
	},
	[40040421] = {
		ID = 40040421,
		Text = "凯伊举枪瞄准他的眉心，枪口却在抖，抖得肉眼可见，一下、两下，怎么压都压不住——",
	},
	[40040422] = {
		ID = 40040422,
		Speaker = "前首领",
		Text = "喔？",
	},
	[40040423] = {
		ID = 40040423,
		Speaker = "前首领",
		Text = "堂堂神枪手，连枪都拿不稳？",
	},
	[40040424] = {
		ID = 40040424,
		Speaker = "前首领",
		Text = "看吧，果然是吓破胆了。",
	},
	[40040425] = {
		ID = 40040425,
		Speaker = "凯伊",
		Text = "抖手也照样打得中你的脸。",
	},
	[40040426] = {
		ID = 40040426,
		Text = "凯伊没回头——她把枪插回枪套，直直往前首领冲了过去。",
	},
	[40040427] = {
		ID = 40040427,
		Speaker = "前首领",
		Text = "近身？妳疯了吗。",
	},
	[40040428] = {
		ID = 40040428,
		Text = "凯伊灵活的闪躲过前首领挥舞的黑爪，随后手腕处闪出一道银光。",
	},
	[40040429] = {
		ID = 40040429,
		Text = "剑刃的碎片划过首领的脸颊，他反手一爪挥来。",
	},
	[40040430] = {
		ID = 40040430,
		Text = "凯伊侧身堪堪躲过，肩头还是被划开一道口子，但第二块碎片已经直直刺进他的侧腹——",
	},
	[40040431] = {
		ID = 40040431,
		Text = "他整个身体猛地扭曲痉挛，像是体内有什么东西正在疯狂反噬他自己，痛苦得不成人形。",
	},
	[40040432] = {
		ID = 40040432,
		Speaker = "前首领",
		Text = "臭丫头，妳以为妳能——！",
	},
	[40040433] = {
		ID = 40040433,
		Speaker = "凯伊",
		Text = "才这点伤，老子还撑得住。",
	},
	[40040434] = {
		ID = 40040434,
		Speaker = "我",
		Text = "撑得住个头，妳肩膀在流血。",
	},
	[40040435] = {
		ID = 40040435,
		Speaker = "凯伊",
		Text = "老子说没事就没事。",
	},
	[40040436] = {
		ID = 40040436,
		Text = "前首领倒在地板上痛苦的抽搐，不断的吐出黑血。",
	},
	[40040437] = {
		ID = 40040437,
		Speaker = "凯伊",
		Text = "看来龙之血也没你想的那么听话嘛。",
	},
	[40040438] = {
		ID = 40040438,
		Speaker = "前首领",
		Text = "妳以为这样就赢了？",
	},
	[40040439] = {
		ID = 40040439,
		Speaker = "凯伊",
		Text = "赢不赢，马上见真章。",
	},
	[40040440] = {
		ID = 40040440,
		Text = "前首领像是被逼急了，在地板上喃喃自语——",
	},
	[40040441] = {
		ID = 40040441,
		Text = "整辆列车猛地一震，发了疯似地加速，整辆列车都在震动。",
	},
	[40040442] = {
		ID = 40040442,
		Text = "巨大的惯性把我们都甩得东倒西歪，他趁乱一跃，扒着车顶边缘翻了上去，消失在头顶。",
	},
	[40040443] = {
		ID = 40040443,
		Speaker = "凯伊",
		Text = "想跑？",
	},
	[40040444] = {
		ID = 40040444,
		Speaker = "我",
		Text = "等等我——",
	},
	[40040445] = {
		ID = 40040445,
	},
	[40040446] = {
		ID = 40040446,
		Text = "天色和铁轨一起在脚下往后飞逝，远处的地平线被夕阳染成锈红色。",
	},
	[40040447] = {
		ID = 40040447,
		Speaker = "前首领",
		Text = "还敢追上来啊，败北者。",
	},
	[40040448] = {
		ID = 40040448,
		Speaker = "凯伊",
		Text = "废话少说，拔枪吧。",
	},
	[40040449] = {
		ID = 40040449,
		Speaker = "前首领",
		Text = "拔枪？",
	},
	[40040450] = {
		ID = 40040450,
		Text = "他放声大笑，笑声扭曲得刺耳。",
	},
	[40040451] = {
		ID = 40040451,
		Speaker = "前首领",
		Text = "子弹伤不了我，妳心里清楚得很。",
	},
	[40040452] = {
		ID = 40040452,
		Speaker = "前首领",
		Text = "妳根本没那个胆子朝我开枪。",
	},
	[40040453] = {
		ID = 40040453,
		Speaker = "凯伊",
		Text = "是吗，那你赌赌看。",
	},
	[40040454] = {
		ID = 40040454,
		Speaker = "前首领",
		Text = "赌？",
	},
	[40040455] = {
		ID = 40040455,
		Speaker = "前首领",
		Text = "哈，妳有什么筹码和我赌？",
	},
	[40040456] = {
		ID = 40040456,
		Speaker = "前首领",
		Text = "妳和妳的跟班，对我来说毫无威胁。",
	},
	[40040457] = {
		ID = 40040457,
		Speaker = "前首领",
		Text = "既然妳这么想死，那我就成全妳。",
	},
	[40040458] = {
		ID = 40040458,
		Text = "前首领把手放在枪套外，压低了身子。",
	},
	[40040459] = {
		ID = 40040459,
		Speaker = "凯伊",
		Text = "谁说老子想死了。",
	},
	[40040460] = {
		ID = 40040460,
		Text = "凯伊摸出一枚旧得发黑的银币。",
	},
	[40040461] = {
		ID = 40040461,
		Text = "她把银币往天上一抛，银色的光点在风里翻滚着往上窜。",
	},
	[40040462] = {
		ID = 40040462,
		Text = "然后她闭上了眼睛，呼吸沉了下去，像是把整个世界的杂音都关在了外面。",
	},
	[40040463] = {
		ID = 40040463,
		Speaker = "前首领",
		Text = "是我赢了。",
	},
	[40040464] = {
		ID = 40040464,
		Text = "银币落地的清脆声响起的同一瞬间。",
	},
	[40040465] = {
		ID = 40040465,
		Text = "枪声炸开——第三颗子弹笔直贯穿了前首领的左胸。",
	},
	[40040466] = {
		ID = 40040466,
		Text = "他整个身体猛地僵住，脸上的扭曲纹路以肉眼可见的速度崩裂剥落，像是连同那股力量一起被撕碎。",
	},
	[40040467] = {
		ID = 40040467,
		Speaker = "凯伊",
		Text = "为了大义牺牲吧。",
	},
	[40040468] = {
		ID = 40040468,
		Text = "睁开眼，声音冷得不像她平常的样子。",
	},
	[40040469] = {
		ID = 40040469,
		Speaker = "前首领",
		Text = "凯伊．莫提斯……",
	},
	[40040470] = {
		ID = 40040470,
		Speaker = "前首领",
		Text = "我……",
	},
	[40040471] = {
		ID = 40040471,
		Speaker = "前首领",
		Text = "诅咒……妳……",
	},
	[40040472] = {
		ID = 40040472,
		Speaker = "前首领",
		Text = "前首领往后倒去，重重摔出车顶边缘，被疾驶的列车远远甩在身后，消失​​在漫天尘土里，只剩下风声和铁轨的震动。",
	},
	[40040473] = {
		ID = 40040473,
	},
	[40040474] = {
		ID = 40040474,
	},
	[40040475] = {
		ID = 40040475,
		Text = "狂风像刀子一样刮过车顶，老旧木制车厢发出不堪负荷的哀鸣，车轮磨着铁轨尖声嘶吼——",
	},
	[40040476] = {
		ID = 40040476,
		Text = "这辆横越荒野星球的骨董列车，速度还在不断攀升。",
	},
	[40040477] = {
		ID = 40040477,
		Speaker = "凯伊",
		Text = "哇啊啊！这到底什么破车！",
	},
	[40040478] = {
		ID = 40040478,
		Speaker = "我",
		Text = "凯伊！",
	},
	[40040479] = {
		ID = 40040479,
		Speaker = "我",
		Text = "你还能骂人，看来骨头没事。",
	},
	[40040480] = {
		ID = 40040480,
		Speaker = "凯伊",
		Text = "现在是开玩笑的时候吗你！",
	},
	[40040481] = {
		ID = 40040481,
		Speaker = "我",
		Text = "这车到底怎么回事？怎么突然冲这么快？",
	},
	[40040482] = {
		ID = 40040482,
		Speaker = "凯伊",
		Text = "谁知道！那老家伙不知道对这破铜烂铁动了什么手脚。",
	},
	[40040483] = {
		ID = 40040483,
		Speaker = "我",
		Text = "操控装置全烧毁了——这车现在根本没人在开！",
	},
	[40040484] = {
		ID = 40040484,
		Speaker = "我",
		Text = "那我们去驾驶室，想办法把速度降下来！",
	},
	[40040485] = {
		ID = 40040485,
		Speaker = "凯伊",
		Text = "早试过那边的阀门，锁死了，拿枪托砸都砸不开。",
	},
	[40040486] = {
		ID = 40040486,
		Speaker = "我",
		Text = "那把车厢弄断呢？分开来减速？",
	},
	[40040487] = {
		ID = 40040487,
		Speaker = "凯伊",
		Text = "拿什么弄？你的手指头吗？",
	},
	[40040488] = {
		ID = 40040488,
		Text = "远方的地平线上，一座年久失修的铁桥缓缓浮现在沙尘之中。",
	},
	[40040489] = {
		ID = 40040489,
		Text = "桥墩锈蚀斑驳，桥面木板东缺一块西缺一块，随着列车逼近，轮廓越来越清晰。",
	},
	[40040490] = {
		ID = 40040490,
		Speaker = "凯伊",
		Text = "再这样下去绝对会翻车的。",
	},
	[40040491] = {
		ID = 40040491,
		Speaker = "我",
		Text = "这个速度，那座桥绝对会塌掉——跳车呢？",
	},
	[40040492] = {
		ID = 40040492,
		Speaker = "凯伊",
		Text = "这个速度跳车会死的！",
	},
	[40040493] = {
		ID = 40040493,
		Speaker = "我",
		Text = "那留在这里就不会摔死了吗？",
	},
	[40040494] = {
		ID = 40040494,
		Speaker = "凯伊",
		Text = "老子还没打算现在就死！",
	},
	[40040495] = {
		ID = 40040495,
		Speaker = "我",
		Text = "那你有办法？",
	},
	[40040496] = {
		ID = 40040496,
		Speaker = "凯伊",
		Text = "……没有。",
	},
	[40040497] = {
		ID = 40040497,
		Speaker = "我",
		Text = "我想想，一定有东西……降落伞……。",
	},
	[40040498] = {
		ID = 40040498,
		Text = "我开始集中意识，试着用能力凭空造出点什么。",
	},
	[40040499] = {
		ID = 40040499,
		Speaker = "我",
		Text = "锁链、挂钩、什么都好……",
	},
	[40040500] = {
		ID = 40040500,
		Text = "掌心微微发烫，却只勉强凝出几缕破碎的光丝，情绪能量不足，什么都成不了形。",
	},
	[40040501] = {
		ID = 40040501,
		Speaker = "凯伊",
		Text = "你那个玩具工厂是不是快没油了？",
	},
	[40040502] = {
		ID = 40040502,
		Speaker = "我",
		Text = "至少比干等好！",
	},
	[40040503] = {
		ID = 40040503,
		Text = "凯伊忽然没再接话，视线紧紧钉在越来越近的铁桥上，神色一寸寸沉静下来。",
	},
	[40040504] = {
		ID = 40040504,
		Speaker = "我",
		Text = "凯伊？你干嘛突然不说话。",
	},
	[40040505] = {
		ID = 40040505,
		Speaker = "凯伊",
		Text = "手伸出来，脚也是。",
	},
	[40040506] = {
		ID = 40040506,
		Speaker = "我",
		Text = "你干嘛把披风脱了？现在是要帮我保暖吗？",
	},
	[40040507] = {
		ID = 40040507,
		Speaker = "凯伊",
		Text = "闭嘴，别废话，照做就对了。",
	},
	[40040508] = {
		ID = 40040508,
		Text = "凯伊俐落地将布料一圈圈缠上我的手腕与脚踝。",
	},
	[40040509] = {
		ID = 40040509,
		Speaker = "我",
		Text = "凯伊，说清楚，你到底想干嘛？",
	},
	[40040510] = {
		ID = 40040510,
		Speaker = "凯伊",
		Text = "老子在救你的命，你给我安分点！",
	},
	[40040511] = {
		ID = 40040511,
		Speaker = "我",
		Text = "你该不会想……",
	},
	[40040512] = {
		ID = 40040512,
		Speaker = "凯伊",
		Text = "少啰嗦。",
	},
	[40040513] = {
		ID = 40040513,
		Speaker = "我",
		Text = "不行，我们一起想办法，还有时间——",
	},
	[40040514] = {
		ID = 40040514,
		Speaker = "凯伊",
		Text = "没有时间了。",
	},
	[40040515] = {
		ID = 40040515,
		Speaker = "凯伊",
		Text = "听着，帮我照顾好那个破镇，拜托你了。",
	},
	[40040516] = {
		ID = 40040516,
		Speaker = "我",
		Text = "凯伊，我不会让你——",
	},
	[40040517] = {
		ID = 40040517,
		Speaker = "凯伊",
		Text = "活下去。",
	},
	[40040518] = {
		ID = 40040518,
		Speaker = "我",
		Text = "什么？不——凯伊！",
	},
	[40040519] = {
		ID = 40040519,
		Text = "凯伊将我的身子举到半空，向着半空甩出了一道弧线。",
	},
	[40040520] = {
		ID = 40040520,
		Speaker = "我",
		Text = "凯伊！ ！",
	},
	[40040521] = {
		ID = 40040521,
		Text = "披风在狂风中猛地张开，像一具简陋却拼了命撑住的降落伞，把我从坠落的轨迹硬生生扯偏了角度。",
	},
	[40040522] = {
		ID = 40040522,
		Text = "效果有限，重重的冲击还是狠狠撞上地面——我在干裂的荒地上翻滚出一长串距离。",
	},
	[40040523] = {
		ID = 40040523,
		Text = "尘土与碎石割过皮肤，但那看似脆弱的骨头，竟奇迹似地一根都没断。",
	},
	[40040524] = {
		ID = 40040524,
		Speaker = "我",
		Text = "凯伊——！ ！",
	},
	[40040525] = {
		ID = 40040525,
		Speaker = "我",
		Text = "起来，快点站起来……",
	},
	[40040526] = {
		ID = 40040526,
		Text = "强撑着发抖的四肢想爬起身，耳边只剩下嗡鸣般的风声。",
	},
	[40040527] = {
		ID = 40040527,
		Text = "终于挣扎着抬起头，望向渐渐远去的列车——它已经冲上了那座年久失修的铁桥。",
	},
	[40040528] = {
		ID = 40040528,
		Text = "桥身承受不住那股超乎常理的重量与速度，发出一声闷响般的呻吟。",
	},
	[40040529] = {
		ID = 40040529,
		Speaker = "我",
		Text = "不……不要……",
	},
	[40040530] = {
		ID = 40040530,
		Text = "下一秒，铁桥轰然崩塌，整辆列车连同车顶的一切，直直坠入了桥下幽深的峡谷。",
	},
	[40040531] = {
		ID = 40040531,
		Text = "远方传来一声沉闷的爆炸巨响，浓烟与火光在谷底翻涌而起。",
	},
	[40040532] = {
		ID = 40040532,
	},
	[40040533] = {
		ID = 40040533,
	},
	[40040534] = {
		ID = 40040534,
		Text = "我不知道自己是怎么一路连滚带爬冲到悬崖边的。",
	},
	[40040535] = {
		ID = 40040535,
		Text = "浑身像是被拆开又勉强拼回去，每动一下都扯得骨头发疼。",
	},
	[40040536] = {
		ID = 40040536,
		Text = "凯伊——！",
	},
	[40040537] = {
		ID = 40040537,
		Text = "我扯开嗓子喊，声音撞在谷壁上碎成一片回音。",
	},
	[40040538] = {
		ID = 40040538,
		Text = "谷底只剩下一团烧得焦黑的铁壳还在无声地燃烧，浓烟一缕一缕往上窜，没有任何回应。",
	},
	[40040539] = {
		ID = 40040539,
		Text = "我瘫坐在悬崖边，手里死死攥着凯伊被扯落的那件旧披风，布料上还留着硝烟与血的味道。",
	},
	[40040540] = {
		ID = 40040540,
		Text = "四周一片死寂，只留下火焰燃烧的声音。",
	},
	[40040541] = {
		ID = 40040541,
		Text = "凯伊就这么连同列车坠入了谷底。",
	},
	[40040542] = {
		ID = 40040542,
		Text = "我的眼泪毫无防备地掉下来。",
	},
	[40040543] = {
		ID = 40040543,
		Text = "直到一阵异样的风压从头顶罩下——",
	},
	[40040544] = {
		ID = 40040544,
		Text = "我猛地抬头，一个黑色的身影正缓缓从夜空中降落，背后展开一对金色龙翼。",
	},
	[40040545] = {
		ID = 40040545,
		Text = "那淡蓝色的发丝融化在夜空中，手上抱着的是——",
	},
	[40040546] = {
		ID = 40040546,
		Speaker = "葛蕾香",
		Text = "哭的真丑呢。",
	},
	[40040547] = {
		ID = 40040547,
		Speaker = "葛蕾香",
		Text = "人类，你的蠢狗掉了。",
	},
	[40040548] = {
		ID = 40040548,
		Text = "她居高临下地飘在半空，怀里横抱着一个浑身木屑、四肢无力的狗。",
	},
	[40040549] = {
		ID = 40040549,
		Text = "语气里满是嫌弃，像捡到什么脏东西一样随口丢出这句话。",
	},
	[40040550] = {
		ID = 40040550,
		Speaker = "我",
		Text = "葛蕾香 ……？凯伊……？",
	},
	[40040551] = {
		ID = 40040551,
		Speaker = "葛蕾香",
		Text = "喂，蠢狗，还不醒醒。",
	},
	[40040552] = {
		ID = 40040552,
		Text = "她收起那对金色龙翼，稳稳落在悬崖边的碎石地上，随手把凯伊往地上一放。",
	},
	[40040553] = {
		ID = 40040553,
		Text = "接着伸手毫不客气地往凯伊脸颊上戳了几下。",
	},
	[40040554] = {
		ID = 40040554,
		Speaker = "凯伊",
		Text = "……这里……是地狱吗？",
	},
	[40040555] = {
		ID = 40040555,
		Speaker = "我",
		Text = "凯伊 ！妳还活着——太好了……",
	},
	[40040556] = {
		ID = 40040556,
		Speaker = "凯伊",
		Text = "妳……妳是不是回来统治这里的！老子——老子绝对不会让妳得逞！",
	},
	[40040557] = {
		ID = 40040557,
		Text = "凯伊猛地坐起身，视线终于聚焦在那张熟悉又陌生的脸上——",
	},
	[40040558] = {
		ID = 40040558,
		Text = "葛蕾香翻了个白眼，凯伊像被踩到尾巴一样连滚带爬地往后退了好几步。",
	},
	[40040559] = {
		ID = 40040559,
		Text = "直到后背撞上岩石才停下，脸上血色瞬间褪尽，连摸枪的手都在抖。",
	},
	[40040560] = {
		ID = 40040560,
		Speaker = "葛蕾香",
		Text = "本人只是感应到龙族的生命能量波动，才特地绕过来看看。",
	},
	[40040561] = {
		ID = 40040561,
		Speaker = "葛蕾香",
		Text = "没想到会是这种蠢事。",
	},
	[40040562] = {
		ID = 40040562,
		Speaker = "葛蕾香",
		Text = "哼，连这种等级的闹剧都能处理得如此狼狈，真是难看。",
	},
	[40040563] = {
		ID = 40040563,
		Text = "葛蕾香一脸嫌弃地环视四周的残骸，语气里藏着点连自己都没察觉的担心。",
	},
	[40040564] = {
		ID = 40040564,
		Speaker = "我",
		Text = "等等，我们好歹也是拼了命——",
	},
	[40040565] = {
		ID = 40040565,
		Speaker = "凯伊",
		Text = "别、别转移话题！妳好端端的怎么会出现在这里……",
	},
	[40040566] = {
		ID = 40040566,
		Speaker = "葛蕾香",
		Text = "闭嘴，本人现在还好端端地站在你面前，你啰唆这些过去做什么？",
	},
	[40040567] = {
		ID = 40040567,
		Speaker = "我",
		Text = "（我看着两人之间那种剑拔弩张又莫名别扭的沉默，识相地退到一旁。）",
	},
	[40040568] = {
		ID = 40040568,
		Speaker = "凯伊",
		Text = "……老子，是说真的抱歉。",
	},
	[40040569] = {
		ID = 40040569,
		Speaker = "凯伊",
		Text = "老子这阵子……每天晚上都梦到自己杀了妳。",
	},
	[40040570] = {
		ID = 40040570,
		Speaker = "凯伊",
		Text = "梦里妳倒下的样子，跟那天一模一样。",
	},
	[40040571] = {
		ID = 40040571,
		Speaker = "葛蕾香",
		Text = "蠢狗总是喜欢自己吓自己，就算真的杀死本人，那也无所谓。",
	},
	[40040572] = {
		ID = 40040572,
		Speaker = "葛蕾香",
		Text = "是本人自己决定站在那里的",
	},
	[40040573] = {
		ID = 40040573,
		Speaker = "葛蕾香",
		Text = "别什么都往自己身上背，简直跟蜗牛一样。",
	},
	[40040574] = {
		ID = 40040574,
		Speaker = "葛蕾香",
		Text = "倒是你，往后要好好照顾自己——这里毕竟也是本人的故乡，本人偶尔会回来看看。",
	},
	[40040575] = {
		ID = 40040575,
		Speaker = "凯伊",
		Text = "……妳說什么？",
	},
	[40040576] = {
		ID = 40040576,
		Speaker = "我",
		Text = "我好像……听见了什么很了不起的宣言？",
	},
	[40040577] = {
		ID = 40040577,
		Text = "我小声嘀咕，换来葛蕾香一记凶狠的瞪视，赶紧闭上嘴假装什么都没说。",
	},
	[40040578] = {
		ID = 40040578,
		Speaker = "葛蕾香",
		Text = "都听见了还不快闭嘴。",
	},
	[40040579] = {
		ID = 40040579,
		Text = "凯伊喉咙里突然发出一声短促又委屈的闷哼，活像是被主人丢下的弃犬。",
	},
	[40040580] = {
		ID = 40040580,
		Text = "连她自己都被自己的声音吓了一跳，慌张地捂住嘴。",
	},
	[40040581] = {
		ID = 40040581,
		Speaker = "葛蕾香",
		Text = "……你那是什么声音。",
	},
	[40040582] = {
		ID = 40040582,
		Speaker = "凯伊",
		Text = "没、没什么！老子才没有发出什么声音！",
	},
	[40040583] = {
		ID = 40040583,
		Text = "葛蕾香一脸嫌隙，朝着凯伊扔了一个黑色的物体。",
	},
	[40040584] = {
		ID = 40040584,
		Speaker = "葛蕾香",
		Text = "如果觉得孤单寂寞，就按一下。",
	},
	[40040585] = {
		ID = 40040585,
		Speaker = "葛蕾香",
		Text = "本人有空的话，会再回来。",
	},
	[40040586] = {
		ID = 40040586,
		Text = "凯伊手忙脚乱地接住那枚通讯器，话还没说完，葛蕾香已经张开了翅膀。",
	},
	[40040587] = {
		ID = 40040587,
		Text = "葛蕾香已经飞到半空中，正准备拉开距离离去，怀里的口袋却突然震动起来，发出通讯器接通的嗡鸣声——",
	},
	[40040588] = {
		ID = 40040588,
		Text = "葛蕾香翻了白眼，一脸嫌弃的再次降落。",
	},
	[40040589] = {
		ID = 40040589,
		Speaker = "葛蕾香",
		Text = "蠢狗，妳最好有什么很重要的……",
	},
	[40040590] = {
		ID = 40040590,
		Speaker = "凯伊",
		Text = "陪人家睡觉，一晚就好。",
	},
	[40040591] = {
		ID = 40040591,
		Speaker = "葛蕾香",
		Text = "……你这只蠢狗，胆子倒是越来越肥了。",
	},
	[40040592] = {
		ID = 40040592,
		Speaker = "葛蕾香",
		Text = "我怎么可能陪妳进城，要是被发现……",
	},
	[40040593] = {
		ID = 40040593,
		Speaker = "我",
		Text = "我刚好认识不只一个可以帮妳施展易容术的人，放心吧。",
	},
	[40040594] = {
		ID = 40040594,
		Speaker = "葛蕾香",
		Text = "……",
	},
	[40040595] = {
		ID = 40040595,
		Speaker = "凯伊",
		Text = "那就说定了喔。",
	},
	[40040596] = {
		ID = 40040596,
		Text = "葛蕾香满脸写满了鄙夷。",
	},
	[40040597] = {
		ID = 40040597,
	},
	[40040598] = {
		ID = 40040598,
	},
	[40040599] = {
		ID = 40040599,
		Text = "从那之后又过了一​​个月，一封有香水味的信辗转送到了我手上——",
	},
	[40040600] = {
		ID = 40040600,
		Text = "葛蕾香说自己还有正事要忙，已经先一步离开了荒野星球，并交代了凯伊的近况。",
	},
	[40040601] = {
		ID = 40040601,
		Text = "短短几行写得像在防备什么，却还是让我看得笑了出来。",
	},
	[40040602] = {
		ID = 40040602,
		Text = "信收好之后，我又一次动身，想看看她最近过得怎么样。",
	},
	[40040603] = {
		ID = 40040603,
		Text = "远远就能看见凯伊家那栋原本被炸穿的木造屋顶，如今已经换上了崭新的梁柱。",
	},
	[40040604] = {
		ID = 40040604,
		Text = "墙面的痕迹也被刷得干干净净，一点都看不出当初的狼藉。",
	},
	[40040605] = {
		ID = 40040605,
		Text = "我站在门前敲了好几下，屋里却安静得反常，连平时隔着门都能听见的抱怨声都没有。",
	},
	[40040606] = {
		ID = 40040606,
		Speaker = "我",
		Text = "凯伊？在家吗？",
	},
	[40040607] = {
		ID = 40040607,
		Speaker = "我",
		Text = "……该不会，真的出事了吧。",
	},
	[40040608] = {
		ID = 40040608,
		Text = "我想起凯伊当上首领后多少也结了些仇。",
	},
	[40040609] = {
		ID = 40040609,
		Text = "越想越不安，我绕到屋子侧面，找到一扇没关紧的窗户，翻身钻了进去。",
	},
	[40040610] = {
		ID = 40040610,
		Speaker = "凯伊",
		Text = "哈……哈啊……",
	},
	[40040611] = {
		ID = 40040611,
		Text = "才刚落地，一阵模糊的、带着喘息的声音就从走廊尽头的房间隐约传来，让我瞬间绷紧了全身的神经。",
	},
	[40040612] = {
		ID = 40040612,
		Speaker = "我",
		Text = "（这个声音……是被偷袭了？）",
	},
	[40040613] = {
		ID = 40040613,
		Speaker = "凯伊",
		Text = "……啊……葛蕾香……",
	},
	[40040614] = {
		ID = 40040614,
		Text = "声音又拔高了一点，中间还夹杂着布料摩擦的窸窣声，反而让我的疑惑更深了一层。",
	},
	[40040615] = {
		ID = 40040615,
		Speaker = "我",
		Text = "（凯伊？是凯伊的声音……）",
	},
	[40040616] = {
		ID = 40040616,
		Text = "我把门推开一条仅容一眼的缝隙，视线先撞见凌乱的床单，接着才看清——",
	},
	[40040617] = {
		ID = 40040617,
		Text = "凯伊整个人趴在床上，一手死死揪着枕头一角，肩胛随着急促的呼吸一起一伏。",
	},
	[40040618] = {
		ID = 40040618,
		Text = "被汗水打湿的碎发贴在泛红的侧脸上，另一只手藏在身下。",
	},
	[40040619] = {
		ID = 40040619,
		Text = "随着若有似无的动作，喉间溢出一声比一声破碎的呜咽。",
	},
	[40040620] = {
		ID = 40040620,
		Text = "她整张脸几乎埋进枕头里，那副毫无防备、近乎沉醉的表情。",
	},
	[40040621] = {
		ID = 40040621,
		Speaker = "我",
		Text = "……",
	},
	[40040622] = {
		ID = 40040622,
		Text = "我看得完全挪不开视线，捏着门板的手不知不觉又往里推了几分。",
	},
	[40040623] = {
		ID = 40040623,
		Text = "老旧的铰链「吱呀」一声，在寂静的房间里显得格外刺耳。",
	},
	[40040624] = {
		ID = 40040624,
		Text = "凯伊像是被那声响惊醒般猛地抬起头，湿润发红的双眼直直撞上站在门口的我。",
	},
	[40040625] = {
		ID = 40040625,
		Text = "两人就这样愣在原地，时间仿佛被按下了暂停键，只有她急促的呼吸声还在房间里回荡。",
	},
	[40040626] = {
		ID = 40040626,
		Speaker = "凯伊",
		Text = "呀啊啊啊啊啊！ ！",
	},
	[40040627] = {
		ID = 40040627,
		Speaker = "我",
		Text = "呃、那个——",
	},
	[40040628] = {
		ID = 40040628,
		Speaker = "凯伊",
		Text = "你、你这混帐看了多久！ ！",
	},
	[40040629] = {
		ID = 40040629,
		Speaker = "我",
		Text = "我刚刚真的只是敲门没人应，担心妳出事才翻窗进来的……",
	},
	[40040630] = {
		ID = 40040630,
		Speaker = "我",
		Text = "我想是那个吧！",
	},
	[40040631] = {
		ID = 40040631,
		Speaker = "我",
		Text = "葛蕾香龙族发情期的关系，放出了贺尔蒙让凯伊也变得怪怪的？",
	},
	[40040632] = {
		ID = 40040632,
		Speaker = "凯伊",
		Text = "呜……老子才没有怪怪的……",
	},
	[40040633] = {
		ID = 40040633,
		Speaker = "凯伊",
		Text = "只是不知道为什么……底下那边好热……",
	},
	[40040634] = {
		ID = 40040634,
		Speaker = "凯伊",
		Text = "兄弟……帮我看一下……",
	},
	[40040635] = {
		ID = 40040635,
		Speaker = "我",
		Text = "……",
	},
	[40040636] = {
		ID = 40040636,
	},
	[40040637] = {
		ID = 40040637,
	},
	[40040638] = {
		ID = 40040638,
		Speaker = "凯伊",
		Text = "哈……哈啊啊啊……",
	},
	[40040639] = {
		ID = 40040639,
		Speaker = "凯伊",
		Text = "呜喔喔喔……脑袋……脑袋……",
	},
	[40040640] = {
		ID = 40040640,
		Speaker = "凯伊",
		Text = "慢……慢一点……",
	},
	[40040641] = {
		ID = 40040641,
		Speaker = "凯伊",
		Text = "呜……！",
	},
	[40040642] = {
		ID = 40040642,
		Speaker = "我",
		Text = "真是想不到，凯伊明明平时看起来这么潇洒。",
	},
	[40040643] = {
		ID = 40040643,
		Speaker = "我",
		Text = "居然会在床上发出这种声音，简直就像发情的小狗一样。",
	},
	[40040644] = {
		ID = 40040644,
		Speaker = "凯伊",
		Text = "老子……才不是……发情……",
	},
	[40040645] = {
		ID = 40040645,
		Speaker = "凯伊",
		Text = "呜……又……又要……",
	},
	[40040646] = {
		ID = 40040646,
		Speaker = "凯伊",
		Text = "呜……哈啊啊啊——！",
	},
	[40040647] = {
		ID = 40040647,
		Speaker = "凯伊",
		Text = "兄弟……兄弟，慢点……",
	},
	[40040648] = {
		ID = 40040648,
		Speaker = "我",
		Text = "从第一次看到凯伊的时候，就一直很想这么做了。",
	},
	[40040649] = {
		ID = 40040649,
		Text = "我用力抱住凯伊的大尾巴，将脸埋进去。",
	},
	[40040650] = {
		ID = 40040650,
		Text = "并且搓揉着毛茸茸的尾巴。",
	},
	[40040651] = {
		ID = 40040651,
		Speaker = "凯伊",
		Text = "呜……呜喔喔——！",
	},
	[40040652] = {
		ID = 40040652,
		Text = "凯伊的屁股瞬间抬高，不断地抖动。",
	},
	[40040653] = {
		ID = 40040653,
		Text = "下体像泄洪一样的喷出水。",
	},
	[40040654] = {
		ID = 40040654,
		Speaker = "凯伊",
		Text = "哥……哥哥……",
	},
	[40040655] = {
		ID = 40040655,
		Speaker = "凯伊",
		Text = "人家……尾巴……",
	},
	[40040656] = {
		ID = 40040656,
		Speaker = "凯伊",
		Text = "尾巴……不可……",
	},
	[40040657] = {
		ID = 40040657,
		Speaker = "凯伊",
		Text = "哈啊啊啊去了呜呜呜——！",
	},
	[40040658] = {
		ID = 40040658,
		Text = "我继续抱着凯伊的尾巴搓揉。",
	},
	[40040659] = {
		ID = 40040659,
		Text = "也感觉到凯伊的内部不断的抖动，紧紧的吸住了肉棒不放。",
	},
	[40040660] = {
		ID = 40040660,
		Speaker = "凯伊",
		Text = "哥……哥哥……人家……",
	},
	[40040661] = {
		ID = 40040661,
		Speaker = "凯伊",
		Text = "要不行了……尾巴……",
	},
	[40040662] = {
		ID = 40040662,
		Speaker = "凯伊",
		Text = "好舒服……哈啊啊……",
	},
	[40040663] = {
		ID = 40040663,
		Speaker = "我",
		Text = "凯伊，要射了。",
	},
	[40040664] = {
		ID = 40040664,
		Speaker = "凯伊",
		Text = "呜——！",
	},
	[40040665] = {
		ID = 40040665,
		Speaker = "凯伊",
		Text = "呜……呜齁喔……",
	},
	[40040666] = {
		ID = 40040666,
		Text = "凯伊的身体不断的抽搐，在肉棒拔出时还抖了一下。",
	},
	[40040667] = {
		ID = 40040667,
		Speaker = "凯伊",
		Text = "呜……嘿……啊啊……",
	},
	[40040668] = {
		ID = 40040668,
		Speaker = "凯伊",
		Text = "哥哥……人家……呜……",
	},
	[40040669] = {
		ID = 40040669,
		Text = "凯伊就这样子抬着屁股、精液从小穴流到大腿上。",
	},
	[40040670] = {
		ID = 40040670,
		Text = "随后失去了意识。",
	},
	[40040671] = {
		ID = 40040671,
	},
	[10070408] = {
		ID = 10070408,
		Speaker = "我",
		Text = "（这女人昨天明明说要评鉴平均值的。）",
	},
	[10070410] = {
		ID = 10070410,
		Speaker = "妮芙拉",
		Text = "下官比你还想知道。",
	},
	[10070412] = {
		ID = 10070412,
	},
	[10070414] = {
		ID = 10070414,
		Text = "一个人走出来，没有随从，没有仪仗，斗篷下摆在地上拖了一小段。",
	},
	[10070415] = {
		ID = 10070415,
		Speaker = "秋比",
		Text = "（……女法王？她一个人？）",
	},
	[10070417] = {
		ID = 10070417,
		Text = "渡口的老船伕什么都没问，直接载走娜芙蒂蒂。秋比等船走远，跳上旁边那条空舟。",
	},
	[10070419] = {
		ID = 10070419,
		Text = "娜芙蒂蒂走得很快，一次都没有停下来看路。",
	},
	[10070421] = {
		ID = 10070421,
		Text = "秋比躲在一块倒下的碑石后面，探出半颗头。",
	},
	[10070423] = {
		ID = 10070423,
		Speaker = "秋比",
		Text = "（这是什么地方？）",
	},
	[10070425] = {
		ID = 10070425,
		Text = "不是礼节性的那种跪。是整个人往下沉，膝盖直接砸进沙里。",
	},
	[10070427] = {
		ID = 10070427,
		Speaker = "秋比",
		Text = "（她在说话，可是听不到。）",
	},
	[10070428] = {
		ID = 10070428,
		Text = "秋比往前挪了一点，还是听不到。",
	},
	[10070430] = {
		ID = 10070430,
		Text = "是一块蜜渍的果干。",
	},
	[10070433] = {
		ID = 10070433,
		Speaker = "娜芙蒂蒂",
		Text = "……对不起，你的父母本座都照料好了，他们现在衣食无缺，有任何问题本座都会派人解决。",
	},
	[10070434] = {
		ID = 10070434,
		Speaker = "娜芙蒂蒂",
		Text = "只求今年的灯火节，能不能请你好好回家，不要再来本座这里....",
	},
	[10070435] = {
		ID = 10070435,
		Text = "娜芙蒂蒂连续跪了好几座石塔，反覆说着相同的抱歉。",
	},
	[10070437] = {
		ID = 10070437,
		Speaker = "秋比",
		Text = "（她是跟这些石塔吵架了吗？）",
	},
	[10070438] = {
		ID = 10070438,
		Speaker = "秋比",
		Text = "（怎么一直在道歉？）",
	},
	[10070440] = {
		ID = 10070440,
	},
	[10070441] = {
		ID = 10070441,
		Text = "奇斐赤脚站在中央，抬手，落步，停住，同一个动作，反覆做了很多次。",
	},
	[10070450] = {
		ID = 10070450,
		Speaker = "我",
		Text = "你昨天跳的那个，跟今天这个不一样。",
	},
	[10070536] = {
		ID = 10070536,
		Speaker = "娜芙蒂蒂",
		Text = "……因为会生病。",
	},
	[10070537] = {
		ID = 10070537,
		Speaker = "奇斐",
		Text = "喔，那我就不看。",
	},
	[10070538] = {
		ID = 10070538,
		Text = "她说得很干脆，一点都没有怀疑。",
	},
	[10070540] = {
		ID = 10070540,
		Text = "娜芙蒂蒂站起来，把奇斐也扶起来。",
	},
	[10070542] = {
		ID = 10070542,
		Speaker = "奇斐",
		Text = "姐姐今天可以陪我久一点吗？",
	},
	[10070544] = {
		ID = 10070544,
		Text = "两个人往门口走，奇斐走三四步就停一下，娜芙蒂蒂配合着她的速度，一次都没有催。",
	},
	[10070547] = {
		ID = 10070547,
		Speaker = "娜芙蒂蒂",
		Text = "谁！",
	},
	[10070550] = {
		ID = 10070550,
		Speaker = "秋比",
		Text = "（我要赶快去找大玩偶）",
	},
	[10070551] = {
		ID = 10070551,
		Text = "转角有人，一个女人站在那里，笑意温顺如常。",
	},
	[10070554] = {
		ID = 10070554,
		Speaker = "赛诃希丝",
		Text = "好久不见呢，小妹妹。",
	},
	[10070556] = {
		ID = 10070556,
		Text = "秋比转身要往回跑，走廊的另一头已经没有路了。",
	},
	[10070558] = {
		ID = 10070558,
		Text = "秋比张开嘴要喊，喊不出声音。",
	},
	[10070560] = {
		ID = 10070560,
		Speaker = "赛诃希丝",
		Text = "这边请。",
	},
	[10070562] = {
		ID = 10070562,
		Text = "仪式空间里，芦苇席上什么都没有留下，墙角那只铜炉，香依然烧着。",
	},
	[10070564] = {
		ID = 10070564,
		Text = "娜芙蒂蒂扶着奇斐要回法老寝室，走廊上正巧遇上妮芙拉。",
	},
	[10070565] = {
		ID = 10070565,
		Speaker = "妮芙拉",
		Text = "陛下，奇斐怎么了？",
	},
	[10070566] = {
		ID = 10070566,
		Speaker = "奇斐",
		Text = "奇斐怎么了？",
	},
	[10070567] = {
		ID = 10070567,
		Text = "娜芙蒂蒂明显有点紧张，赶紧抢话。",
	},
	[10070569] = {
		ID = 10070569,
		Speaker = "妮芙拉",
		Text = "下官告退。",
	},
	[10070571] = {
		ID = 10070571,
		Speaker = "奇斐",
		Text = "姐姐，妮妮长好高了呢！",
	},
	[10070574] = {
		ID = 10070574,
	},
	[10070575] = {
		ID = 10070575,
	},
	[10070579] = {
		ID = 10070579,
		Text = "妮芙拉站在那里，全副武装，眼睛盯着走廊尽头。",
	},
	[10070581] = {
		ID = 10070581,
		Speaker = "妮芙拉",
		Text = "使者大人请回房。",
	},
	[10070582] = {
		ID = 10070582,
		Speaker = "我",
		Text = "你在等什么？",
	},
	[10070583] = {
		ID = 10070583,
		Speaker = "妮芙拉",
		Text = "例行公事。",
	},
	[10070586] = {
		ID = 10070586,
		Text = "走廊尽头有东西动了一下。",
	},
	[10070587] = {
		ID = 10070587,
		Text = "速度很快，快到我只看见一片影子擦过墙面，往侧门的方向去。",
	},
	[10070588] = {
		ID = 10070588,
		Speaker = "妮芙拉",
		Text = "来了。",
	},
	[10070590] = {
		ID = 10070590,
		Speaker = "我",
		Text = "喂！ ！ ！",
	},
	[10070591] = {
		ID = 10070591,
		Text = "我跟了上去。",
	},
	[10070594] = {
		ID = 10070594,
		Speaker = "我",
		Text = "那是什么？",
	},
	[10070596] = {
		ID = 10070596,
		Speaker = "我",
		Text = "你追过几次？",
	},
	[10070598] = {
		ID = 10070598,
		Speaker = "我",
		Text = "结果？",
	},
	[10070602] = {
		ID = 10070602,
		Speaker = "我",
		Text = "知道了。",
	},
	[10070603] = {
		ID = 10070603,
		Text = "巷子越走越窄，灯越来越少。庆典早就结束了，这一带连狗都没有。",
	},
	[10070604] = {
		ID = 10070604,
		Text = "我追到底，什么都没有。",
	},
	[10070611] = {
		ID = 10070611,
		Speaker = "我",
		Text = "唔——！",
	},
	[10070614] = {
		ID = 10070614,
		Speaker = "我",
		Text = "（这力气……）",
	},
	[10070615] = {
		ID = 10070615,
		Speaker = "我",
		Text = "你是谁。",
	},
	[10070616] = {
		ID = 10070616,
		Text = "没有回答。",
	},
	[10070617] = {
		ID = 10070617,
		Text = "那个人只是看着他。",
	},
	[10070619] = {
		ID = 10070619,
		Speaker = "我",
		Text = "等等，喂，等一下。",
	},
	[10070622] = {
		ID = 10070622,
		Speaker = "我",
		Text = "（不对，她要干嘛我知道。）",
	},
	[10070624] = {
		ID = 10070624,
		Text = "热的。",
	},
	[10070627] = {
		ID = 10070627,
		Speaker = "我",
		Text = "喂……！",
	},
	[10070632] = {
		ID = 10070632,
		Text = "那人的头不停地上下移动，不停地发出扑嗤的水声。",
	},
	[10070634] = {
		ID = 10070634,
		Speaker = "我",
		Text = "你……为什么要做这种事？",
	},
	[10070636] = {
		ID = 10070636,
		Text = "但我只能看清脸的部分轮廓。",
	},
	[10070638] = {
		ID = 10070638,
		Speaker = "我",
		Text = "唔！",
	},
	[10070640] = {
		ID = 10070640,
		Text = "她没有退开，也没有呛到。",
	},
	[10070642] = {
		ID = 10070642,
		Speaker = "我",
		Text = "（……她吞了。）",
	},
	[10070647] = {
		ID = 10070647,
		Text = "那人松开手，站起来，退了两步。",
	},
	[10070649] = {
		ID = 10070649,
		Text = "然后转身，往巷子深处跑。",
	},
	[10070651] = {
		ID = 10070651,
		Speaker = "我",
		Text = "等一下！",
	},
	[10070653] = {
		ID = 10070653,
		Text = "两三步就没有影子了。",
	},
	[10070655] = {
		ID = 10070655,
		Speaker = "我",
		Text = "（……我活了这么久。）",
	},
	[10070657] = {
		ID = 10070657,
		Speaker = "我",
		Text = "（这是第一次，我完全不知道刚才发生了什么事。）",
	},
	[10070658] = {
		ID = 10070658,
		Text = "巷子里异常地安静，",
	},
	[10070659] = {
		ID = 10070659,
		Text = "我靠在墙上，裤子还挂在膝盖上。",
	},
	[10070660] = {
		ID = 10070660,
		Text = "妮芙拉背对着他站着，肩膀在起伏。",
	},
	[10070661] = {
		ID = 10070661,
		Speaker = "妮芙拉",
		Text = "……使者大人。",
	},
	[10070664] = {
		ID = 10070664,
		Speaker = "我",
		Text = "没事。",
	},
	[10070668] = {
		ID = 10070668,
		Speaker = "妮芙拉",
		Text = "您……好了吗。",
	},
	[10070673] = {
		ID = 10070673,
		Speaker = "妮芙拉",
		Text = "报告，没有！我什么都没有看！",
	},
	[10070676] = {
		ID = 10070676,
		Speaker = "我",
		Text = "那你确认完了吗？",
	},
	[10070677] = {
		ID = 10070677,
		Speaker = "妮芙拉",
		Text = "……确认完了。",
	},
	[10070679] = {
		ID = 10070679,
		Speaker = "妮芙拉",
		Text = "使者大人。",
	},
	[10070681] = {
		ID = 10070681,
		Speaker = "妮芙拉",
		Text = "……本钱真雄厚。",
	},
	[10070682] = {
		ID = 10070682,
		Text = "我一时之间不知道该接什么。",
	},
	[10070684] = {
		ID = 10070684,
		Text = "走到河堤上，谁都没有先开口。",
	},
	[10070685] = {
		ID = 10070685,
	},
	[10070686] = {
		ID = 10070686,
		Text = "河面很暗，对岸一点灯都没有。",
	},
	[10070689] = {
		ID = 10070689,
		Speaker = "我",
		Text = "三年才出现两次？",
	},
	[10070691] = {
		ID = 10070691,
		Speaker = "我",
		Text = "那今天算第三次。",
	},
	[10070693] = {
		ID = 10070693,
		Speaker = "妮芙拉",
		Text = "而且之前，对方都是穿着大衣裸奔，或是打伤路人。",
	},
	[10070694] = {
		ID = 10070694,
		Speaker = "妮芙拉",
		Text = "从来没有像今天这样.....",
	},
	[10070696] = {
		ID = 10070696,
		Text = "妮芙拉没有回答。",
	},
	[10070699] = {
		ID = 10070699,
		Text = "我看着她的侧脸。",
	},
	[10070879] = {
		ID = 10070879,
		Speaker = "奇斐",
		Text = "你吃完了？",
	},
	[10070394] = {
		ID = 10070394,
	},
	[10070395] = {
		ID = 10070395,
		Text = "隔日午后，我在回廊来回走了三趟，第四趟的时候，妮芙拉终于从转角出现。",
	},
	[10070396] = {
		ID = 10070396,
		Speaker = "我",
		Text = "护卫长。",
	},
	[10070397] = {
		ID = 10070397,
		Speaker = "妮芙拉",
		Text = "使者大人。",
	},
	[10070398] = {
		ID = 10070398,
		Speaker = "我",
		Text = "陛下今天在哪里？",
	},
	[10070399] = {
		ID = 10070399,
		Speaker = "妮芙拉",
		Text = "陛下在批文书。",
	},
	[10070400] = {
		ID = 10070400,
		Speaker = "我",
		Text = "那我可以去？",
	},
	[10070401] = {
		ID = 10070401,
		Speaker = "妮芙拉",
		Text = "不行。",
	},
	[10070402] = {
		ID = 10070402,
		Speaker = "我",
		Text = "我还没说完。",
	},
	[10070403] = {
		ID = 10070403,
		Speaker = "妮芙拉",
		Text = "陛下交代，如果使者大人问起，就说她在忙。",
	},
	[10070404] = {
		ID = 10070404,
		Speaker = "我",
		Text = "忙到什么时候？",
	},
	[10070405] = {
		ID = 10070405,
		Speaker = "妮芙拉",
		Text = "陛下说「看心情」。",
	},
	[10070406] = {
		ID = 10070406,
		Speaker = "我",
		Text = "……她原话就是这三个字？",
	},
	[10070407] = {
		ID = 10070407,
		Speaker = "妮芙拉",
		Text = "是。",
	},
	[10070409] = {
		ID = 10070409,
		Speaker = "我",
		Text = "那护卫长，陛下平常心情什么时候会好？",
	},
	[10070411] = {
		ID = 10070411,
		Speaker = "我",
		Text = "真是让人捉摸不定的女人阿！",
	},
	[10070413] = {
		ID = 10070413,
		Text = "秋比蹲在墙头上看太阳，侧门开了。",
	},
	[10070416] = {
		ID = 10070416,
		Text = "秋比从墙头跳下来，跟了上去。",
	},
	[10070418] = {
		ID = 10070418,
		Text = "河雾很厚，上岸就看不见来时的水面。地上没有路，石塔一座一座立在雾里。",
	},
	[10070420] = {
		ID = 10070420,
		Text = "走到第三座塔前面，她停住了。",
	},
	[10070422] = {
		ID = 10070422,
		Text = "塔前的沙地上有几个旧的凹痕，是跪出来的。",
	},
	[10070424] = {
		ID = 10070424,
		Text = "娜芙蒂蒂把斗篷解下来扔在沙上，跪了下去。",
	},
	[10070426] = {
		ID = 10070426,
		Text = "她低着头，额头几乎碰到地。嘴唇在动，没有声音。",
	},
	[10070429] = {
		ID = 10070429,
		Text = "然后她从怀里拿出一个东西，放在塔前的沙上。",
	},
	[10070431] = {
		ID = 10070431,
		Speaker = "秋比",
		Text = "（看起来好好吃）",
	},
	[10070432] = {
		ID = 10070432,
		Text = "她把果干摆正，摆得很仔细，然后又跪回去。",
	},
	[10070436] = {
		ID = 10070436,
		Speaker = "秋比",
		Text = "（她好像很难过？）",
	},
	[10070439] = {
		ID = 10070439,
		Speaker = "秋比",
		Text = "（女法老跟薇拉公主一样，心事很多的样子。）",
	},
	[10070442] = {
		ID = 10070442,
		Text = "芦苇席边上放着一只矮脚铜炉，香烧了半块。",
	},
	[10070443] = {
		ID = 10070443,
		Speaker = "我",
		Text = "这个动作你做很久了。",
	},
	[10070444] = {
		ID = 10070444,
		Speaker = "奇斐",
		Text = "天神使者大人！",
	},
	[10070445] = {
		ID = 10070445,
		Speaker = "我",
		Text = "叫我舰长就好。",
	},
	[10070446] = {
		ID = 10070446,
		Speaker = "奇斐",
		Text = "天神使者舰长！",
	},
	[10070447] = {
		ID = 10070447,
		Speaker = "我",
		Text = "……舰长就好。",
	},
	[10070448] = {
		ID = 10070448,
		Speaker = "奇斐",
		Text = "好！舰长使者大人！",
	},
	[10070449] = {
		ID = 10070449,
		Speaker = "我",
		Text = "算了，你想怎么叫都可以。",
	},
	[10070451] = {
		ID = 10070451,
		Speaker = "奇斐",
		Text = "因为昨天是节庆啊，节庆的要跳得开心一点。",
	},
	[10070452] = {
		ID = 10070452,
		Speaker = "我",
		Text = "那今天这个舞是什么舞？",
	},
	[10070453] = {
		ID = 10070453,
		Speaker = "奇斐",
		Text = "我也不知道，陛下教的。",
	},
	[10070454] = {
		ID = 10070454,
		Speaker = "我",
		Text = "陛下要你练这个？",
	},
	[10070455] = {
		ID = 10070455,
		Speaker = "奇斐",
		Text = "对啊。每个月都要跳一次。",
	},
	[10070456] = {
		ID = 10070456,
		Speaker = "我",
		Text = "每个月？",
	},
	[10070457] = {
		ID = 10070457,
		Speaker = "奇斐",
		Text = "月圆的时候。",
	},
	[10070458] = {
		ID = 10070458,
		Speaker = "我",
		Text = "跳给谁看？",
	},
	[10070459] = {
		ID = 10070459,
		Speaker = "奇斐",
		Text = "神明。",
	},
	[10070460] = {
		ID = 10070460,
		Speaker = "我",
		Text = "神明会来看？",
	},
	[10070461] = {
		ID = 10070461,
		Speaker = "奇斐",
		Text = "会啊，陛下跟我说，舞蹈本来就是跳给神明看的。",
	},
	[10070462] = {
		ID = 10070462,
		Speaker = "我",
		Text = "原来如此。",
	},
	[10070463] = {
		ID = 10070463,
		Speaker = "我",
		Text = "那跳舞时也要点这个香？",
	},
	[10070464] = {
		ID = 10070464,
		Speaker = "奇斐",
		Text = "每天，早上一次，晚上一次。",
	},
	[10070465] = {
		ID = 10070465,
		Speaker = "我",
		Text = "为什么？",
	},
	[10070466] = {
		ID = 10070466,
		Speaker = "奇斐",
		Text = "陛下说我身上要有这个味道。",
	},
	[10070467] = {
		ID = 10070467,
		Speaker = "奇斐",
		Text = "很久以前就这样了。她说这个香很贵，别人不能用。",
	},
	[10070468] = {
		ID = 10070468,
		Speaker = "我",
		Text = "（很贵，别人不能用，而且每天要点两次。）",
	},
	[10070469] = {
		ID = 10070469,
		Speaker = "我",
		Text = "（……怎么感觉是记号的一种）",
	},
	[10070470] = {
		ID = 10070470,
		Speaker = "我",
		Text = "奇斐，你的手能借我一下吗？",
	},
	[10070471] = {
		ID = 10070471,
		Speaker = "奇斐",
		Text = "是",
	},
	[10070472] = {
		ID = 10070472,
		Text = "我拿起奇斐的右手端详，果然指节有一点红肿，像是捶过墙壁一样。",
	},
	[10070473] = {
		ID = 10070473,
		Speaker = "我",
		Text = "你的手怎么了？",
	},
	[10070474] = {
		ID = 10070474,
		Speaker = "奇斐",
		Text = "我也不知道，痛痛的，可能喝醉的时候跌到吧？呵呵。",
	},
	[10070475] = {
		ID = 10070475,
		Speaker = "我",
		Text = "（这眼神跟秋比一样，傻呼呼地骗不了人）",
	},
	[10070476] = {
		ID = 10070476,
		Speaker = "我",
		Text = "（但喝到断片，就能把醉汉打倒吗？）",
	},
	[10070477] = {
		ID = 10070477,
	},
	[10070478] = {
		ID = 10070478,
		Text = "秋比在王宫里乱绕。",
	},
	[10070479] = {
		ID = 10070479,
		Speaker = "秋比",
		Text = "（没有人可以讲，好无聊。）",
	},
	[10070480] = {
		ID = 10070480,
		Text = "她一路晃到王宫深处。这一带的走廊比较窄，墙上没有挂任何东西，灯也点得少。",
	},
	[10070481] = {
		ID = 10070481,
		Text = "走到底是一扇门。没有锁，也没有守卫。",
	},
	[10070482] = {
		ID = 10070482,
		Speaker = "秋比",
		Text = "（没有人守的地方，通常最有趣。）",
	},
	[10070484] = {
		ID = 10070484,
		Speaker = "秋比",
		Text = "这里是什么地方啊？ ？",
	},
	[10070485] = {
		ID = 10070485,
	},
	[10070486] = {
		ID = 10070486,
	},
	[10070487] = {
		ID = 10070487,
		Text = "秋比在王宫里绕了大半天，想找大玩偶讲早上的事。",
	},
	[10070488] = {
		ID = 10070488,
		Text = "可是人却不在房里，黛莉亚大概还埋在那面铜墙底下。",
	},
	[10070489] = {
		ID = 10070489,
		Text = "秋比走进王宫深处，推开一扇门。",
	},
	[10070490] = {
		ID = 10070490,
	},
	[10070491] = {
		ID = 10070491,
		Text = "里面很大，没有神像，没有祭坛，地上铺着一整圈芦苇席，跟广场上那圈一模一样，",
	},
	[10070492] = {
		ID = 10070492,
		Text = "只是边缘已经磨黑了。席子外围画着一圈符号，秋比一个都看不懂。",
	},
	[10070493] = {
		ID = 10070493,
		Text = "墙角有一只矮脚铜炉，香还烧着。",
	},
	[10070494] = {
		ID = 10070494,
		Speaker = "秋比",
		Text = "是舞娘妹妹的味道。",
	},
	[10070495] = {
		ID = 10070495,
		Text = "天花板正中央开了一个方形的洞，月光从那里落下来，刚好打在芦苇席的中心。",
	},
	[10070496] = {
		ID = 10070496,
		Speaker = "秋比",
		Text = "（这里是给人跳舞的地方，可是为什么要藏在这么里面？）",
	},
	[10070497] = {
		ID = 10070497,
		Text = "她走到席子边上，本来只是想摸一下。脚一踩上去，整圈符号亮了一下。",
	},
	[10070498] = {
		ID = 10070498,
		Speaker = "秋比",
		Text = "哇！",
	},
	[10070499] = {
		ID = 10070499,
		Text = "光只亮了一瞬间就灭了。秋比往后跳开，蹲在原地不敢动。",
	},
	[10070500] = {
		ID = 10070500,
		Text = "几秒后，外面走廊传来脚步声。",
	},
	[10070501] = {
		ID = 10070501,
		Speaker = "秋比",
		Text = "（糟糕！是不是有人要来抓秋比？）",
	},
	[10070502] = {
		ID = 10070502,
		Text = "她钻到门后的柱子阴影里。",
	},
	[10070503] = {
		ID = 10070503,
		Text = "门开，奇斐走了进来。",
	},
	[10070504] = {
		ID = 10070504,
		Speaker = "秋比",
		Text = "（是舞娘妹妹！）",
	},
	[10070505] = {
		ID = 10070505,
		Text = "秋比正要探出头打招呼，动作忽然停住了。",
	},
	[10070506] = {
		ID = 10070506,
		Text = "那个走路的方式不对，太慢了，而且每走三四步就停一下，一只手按在胸口。",
	},
	[10070507] = {
		ID = 10070507,
		Text = "比起舞者，更像病人走路的样子。",
	},
	[10070508] = {
		ID = 10070508,
		Text = "她走到芦苇席中央，慢慢坐下来，坐下来的时候还喘了一下。",
	},
	[10070509] = {
		ID = 10070509,
		Speaker = "奇斐",
		Text = "……好累喔。",
	},
	[10070510] = {
		ID = 10070510,
		Text = "秋比在阴影里屏住呼吸。",
	},
	[10070511] = {
		ID = 10070511,
		Speaker = "奇斐",
		Text = "姐姐今天，怎么还没来？",
	},
	[10070512] = {
		ID = 10070512,
		Text = "她抬头看那个方形的洞，月光落在她脸上。",
	},
	[10070513] = {
		ID = 10070513,
		Speaker = "奇斐",
		Text = "月亮已经到中间了，姐姐说月亮到中间就会来的。",
	},
	[10070514] = {
		ID = 10070514,
		Speaker = "秋比",
		Text = "（……姐姐？她的声音好小，跟昨天那个完全不一样。）",
	},
	[10070515] = {
		ID = 10070515,
		Text = "奇斐低下头，看着自己的两只手，翻过来，翻过去。",
	},
	[10070516] = {
		ID = 10070516,
		Speaker = "奇斐",
		Text = "我的手怎么又变粗了。",
	},
	[10070517] = {
		ID = 10070517,
		Speaker = "奇斐",
		Text = "今天可以自己走到这里都没有停。姐姐一定会很高兴。",
	},
	[10070518] = {
		ID = 10070518,
		Text = "外面走廊传来急促的脚步声。很急，而且是跑的。",
	},
	[10070519] = {
		ID = 10070519,
		Text = "门被撞开，娜芙蒂蒂冲了进来，一看到坐在席子中央的人，整个人停住了。",
	},
	[10070520] = {
		ID = 10070520,
		Speaker = "奇斐",
		Text = "姐姐。",
	},
	[10070521] = {
		ID = 10070521,
		Text = "娜芙蒂蒂走过去，走得很慢。",
	},
	[10070522] = {
		ID = 10070522,
		Speaker = "娜芙蒂蒂",
		Text = "……你怎么自己过来了。",
	},
	[10070523] = {
		ID = 10070523,
		Speaker = "奇斐",
		Text = "我等你等很久。",
	},
	[10070524] = {
		ID = 10070524,
		Speaker = "娜芙蒂蒂",
		Text = "对不起。",
	},
	[10070525] = {
		ID = 10070525,
		Speaker = "奇斐",
		Text = "没关系。你看，我今天走过来都没有停喔。",
	},
	[10070526] = {
		ID = 10070526,
		Text = "娜芙蒂蒂在她面前跪下来，跟她一样高。",
	},
	[10070527] = {
		ID = 10070527,
		Speaker = "娜芙蒂蒂",
		Text = "……很棒。",
	},
	[10070528] = {
		ID = 10070528,
		Speaker = "奇斐",
		Text = "姐姐，可以问一个问题吗？",
	},
	[10070529] = {
		ID = 10070529,
		Speaker = "娜芙蒂蒂",
		Text = "说。",
	},
	[10070530] = {
		ID = 10070530,
		Speaker = "奇斐",
		Text = "我为什么不可以照镜子？",
	},
	[10070531] = {
		ID = 10070531,
		Speaker = "娜芙蒂蒂",
		Text = "……谁跟你说镜子的。",
	},
	[10070532] = {
		ID = 10070532,
		Speaker = "奇斐",
		Text = "没有人说，宫里没有镜子，我就想，是不是不可以。",
	},
	[10070533] = {
