	[10070543] = {
		ID = 10070543,
		Speaker = "娜芙蒂蒂",
		Text = "……可以。",
	},
	[10070545] = {
		ID = 10070545,
		Text = "走到门口，奇斐忽然停下来，回过头，眼睛直直地看向柱子的阴影。",
	},
	[10070546] = {
		ID = 10070546,
		Speaker = "奇斐",
		Text = "姐姐，那边有人。",
	},
	[10070548] = {
		ID = 10070548,
		Text = "秋比拔腿就跑，冲出门，冲进走廊，往转角扑过去。",
	},
	[10070549] = {
		ID = 10070549,
		Speaker = "娜芙蒂蒂",
		Text = "站住！",
	},
	[10070552] = {
		ID = 10070552,
		Text = "秋比认得这张脸。",
	},
	[10070553] = {
		ID = 10070553,
		Speaker = "秋比",
		Text = "你！你是机械星球那个！",
	},
	[10070555] = {
		ID = 10070555,
		Speaker = "赛诃希丝",
		Text = "你刚才，看到很有趣的东西吧？",
	},
	[10070557] = {
		ID = 10070557,
		Speaker = "赛诃希丝",
		Text = "别急着走呀，难得看到这么精彩的一幕，总要有人陪我一起讲讲心得。",
	},
	[10070559] = {
		ID = 10070559,
		Text = "走廊上的灯一盏一盏暗下去。",
	},
	[10070561] = {
		ID = 10070561,
		Text = "最后一盏灯灭了。",
	},
	[10070563] = {
		ID = 10070563,
	},
	[10070568] = {
		ID = 10070568,
		Speaker = "娜芙蒂蒂",
		Text = "她没事，你忙你的。",
	},
	[10070570] = {
		ID = 10070570,
		Text = "妮芙拉转头离开之时，听到奇斐轻轻说了一句。",
	},
	[10070572] = {
		ID = 10070572,
		Speaker = "妮芙拉",
		Text = "（妮妮？）",
	},
	[10070573] = {
		ID = 10070573,
		Text = "妮芙拉疑惑地回头看了奇斐一眼。",
	},
	[10070576] = {
		ID = 10070576,
		Text = "我睡不着，在回廊上晃。",
	},
	[10070577] = {
		ID = 10070577,
		Speaker = "我",
		Text = "（秋比一整天没回来。）",
	},
	[10070578] = {
		ID = 10070578,
		Speaker = "我",
		Text = "（那丫头常常乱跑，但不会跑过夜。）",
	},
	[10070580] = {
		ID = 10070580,
		Speaker = "我",
		Text = "护卫长，这么晚还在巡？",
	},
	[10070584] = {
		ID = 10070584,
		Speaker = "我",
		Text = "例行公事需要带武器？",
	},
	[10070585] = {
		ID = 10070585,
		Text = "妮芙拉没有回答。",
	},
	[10070589] = {
		ID = 10070589,
		Text = "她拔腿就追。",
	},
	[10070592] = {
		ID = 10070592,
		Text = "那道影子跑得极快，穿过空地，翻过矮墙，一次都没有慢下来。",
	},
	[10070593] = {
		ID = 10070593,
		Text = "妮芙拉的甲片撞得叮当响，追得很吃力。",
