	[10070595] = {
		ID = 10070595,
		Speaker = "妮芙拉",
		Text = "不知道。",
	},
	[10070597] = {
		ID = 10070597,
		Speaker = "妮芙拉",
		Text = "……两次。",
	},
	[10070599] = {
		ID = 10070599,
		Speaker = "妮芙拉",
		Text = "两次都跟丢。",
	},
	[10070600] = {
		ID = 10070600,
		Text = "影子拐进街巷，妮芙拉往左，我往右。",
	},
	[10070601] = {
		ID = 10070601,
		Speaker = "妮芙拉",
		Text = "使者大人，往河边堵！",
