		Speaker = "我",
		Text = "（跟丢了。）",
	},
	[10070606] = {
		ID = 10070606,
		Speaker = "我",
		Text = "（……不对。）",
	},
	[10070607] = {
		ID = 10070607,
		Speaker = "我",
		Text = "（这个地方，不是那天我们第一次碰到奇斐的地方吗？）",
	},
	[10070608] = {
		ID = 10070608,
		Text = "背后有风，",
	},
	[10070609] = {
		ID = 10070609,
		Text = "我转身的瞬间，整个人被撞倒在墙上。",
	},
	[10070610] = {
		ID = 10070610,
		Text = "力道大得不像话。",
	},
	[10070612] = {
		ID = 10070612,
		Text = "一双手按住他的肩膀，把他钉在墙上。",
	},
	[10070613] = {
		ID = 10070613,
		Text = "夜色太暗，只看得见一个轮廓，还有垂到地上的长发。",
	},
	[10070618] = {
		ID = 10070618,
		Text = "然后蹲了下去。",
	},
	[10070620] = {
		ID = 10070620,
		Text = "腰带被解开了。",
	},
	[10070621] = {
		ID = 10070621,
		Speaker = "我",
		Text = "（……她在干嘛？）",
	},
	[10070623] = {
		ID = 10070623,
		Speaker = "我",
		Text = "（我是想问，她为什么？）",
	},
	[10070625] = {
		ID = 10070625,
		Text = "湿的。",
	},
	[10070626] = {
		ID = 10070626,
		Text = "我感觉到自己的强壮下体被又湿又暖的舌头包裹起来。",
	},
	[10070628] = {
		ID = 10070628,
		Text = "我伸手要推开她。",
	},
	[10070629] = {
		ID = 10070629,
		Text = "手按到她的头，却停住了。",
	},
	[10070630] = {
		ID = 10070630,
		Speaker = "我",
		Text = "（太舒服了，这叫我怎么反抗？）",
	},
	[10070631] = {
		ID = 10070631,
		Speaker = "我",
		Text = "（她吃得这么凶猛，怎么受得了？）",
	},
	[10070633] = {
		ID = 10070633,
		Text = "动作很急很生疏。",
	},
	[10070635] = {
		ID = 10070635,
		Text = "她抬起头。",
	},
	[10070637] = {
		ID = 10070637,
		Text = "她低下头，继续。",
	},
	[10070639] = {
		ID = 10070639,
		Text = "一切都在她嘴里结束了。",
	},
	[10070641] = {
		ID = 10070641,
		Text = "只是很安静地，把喉头吞了一下。",
	},
	[10070643] = {
		ID = 10070643,
		Speaker = "我",
		Text = "（没有犹豫。）",
	},
	[10070644] = {
		ID = 10070644,
		Text = "旁边突然传来盔甲碰撞声，我吓到往暗处一看。",
	},
	[10070645] = {
		ID = 10070645,
		Text = "妮芙拉原来不知何时就站在那里观看，她一脸错愕。",
	},
	[10070646] = {
		ID = 10070646,
		Speaker = "妮芙拉",
		Text = "使者大人？",
	},
	[10070648] = {
		ID = 10070648,
		Text = "用手背抹了一下嘴。",
	},
	[10070650] = {
		ID = 10070650,
		Speaker = "妮芙拉",
		Text = "你是． ． ． ． ．",
	},
	[10070652] = {
		ID = 10070652,
		Text = "那人快得像一阵风。",
	},
	[10070654] = {
		ID = 10070654,
		Text = "我靠在墙上，喘着气，整理自己的衣服。",
	},
	[10070656] = {
		ID = 10070656,
		Speaker = "我",
		Text = "（被女人推倒的次数，我自己都算不清楚。）",
	},
	[10070662] = {
		ID = 10070662,
		Speaker = "我",
		Text = "嗯。",
	},
	[10070663] = {
		ID = 10070663,
		Speaker = "妮芙拉",
		Text = "您没事吧。",
	},
	[10070665] = {
		ID = 10070665,
		Speaker = "妮芙拉",
		Text = "……那就好。",
	},
	[10070666] = {
		ID = 10070666,
		Speaker = "妮芙拉",
		Text = "使者大人。",
	},
	[10070667] = {
		ID = 10070667,
		Speaker = "我",
		Text = "嗯？",
	},
	[10070669] = {
		ID = 10070669,
		Text = "妮芙拉终于回过头来。",
	},
	[10070670] = {
		ID = 10070670,
		Text = "然后她的视线就停住了。",
