	[10070688] = {
		ID = 10070688,
		Speaker = "妮芙拉",
		Text = "……三年。",
	},
	[10070690] = {
		ID = 10070690,
		Speaker = "妮芙拉",
		Text = "三年出现过很多次，我追到的只有两次。",
	},
	[10070692] = {
		ID = 10070692,
		Speaker = "妮芙拉",
		Text = "……嗯。",
	},
	[10070695] = {
		ID = 10070695,
		Speaker = "我",
		Text = "你是不是知道这人是谁？",
	},
	[10070697] = {
		ID = 10070697,
		Speaker = "我",
		Text = "护卫长？",
	},
	[10070698] = {
		ID = 10070698,
		Speaker = "妮芙拉",
		Text = "报告，下官如果认得，早就将这人逮捕了。",
