	[10070700] = {
		ID = 10070700,
		Speaker = "我",
		Text = "（很明显，她刚刚应该是有认出对方．．）",
	},
	[10070701] = {
		ID = 10070701,
		Speaker = "我",
		Text = "（所以才不愿意继续追．．．）",
	},
	[10070702] = {
		ID = 10070702,
		Speaker = "我",
		Text = "（她想保护那个人？）",
	},
	[10070703] = {
		ID = 10070703,
		Speaker = "我",
		Text = "是不是有什么案子，你才需要追查这个人？",
	},
	[10070704] = {
		ID = 10070704,
		Text = "妮芙拉从怀里摸出一本册子，翻开，就着月光看。",
