	[10070706] = {
		ID = 10070706,
		Speaker = "我",
		Text = "这是什么？",
	},
	[10070707] = {
		ID = 10070707,
		Speaker = "妮芙拉",
		Text = "名册。这三年，宫里失踪的年轻女子。",
