	[10070710] = {
		ID = 10070710,
		Speaker = "我",
		Text = "十一个人失踪，没有人查？",
	},
	[10070711] = {
		ID = 10070711,
		Speaker = "妮芙拉",
		Text = "我们这里其实不太在乎这种事，特别是人已经死了，大家都要向前​​看，不要纠结。",
	},
	[10070712] = {
		ID = 10070712,
		Speaker = "我",
		Text = "等等，我知道你们拥抱死亡，但人失踪，怎么知道生死？",
	},
	[10070713] = {
		ID = 10070713,
		Speaker = "妮芙拉",
		Text = "因为有人在灯火节时，看到她们的灵魂飘回宫中，这就是死亡的证明。",
	},
	[10070714] = {
		ID = 10070714,
		Speaker = "我",
		Text = "恩？不是说灵魂要回家跟家人团聚吗？",
	},
	[10070715] = {
		ID = 10070715,
		Speaker = "妮芙拉",
		Text = "所以下官才要查！我觉得她们一定有冤屈！",
	},
	[10070716] = {
