	[10070720] = {
		ID = 10070720,
		Text = "妮芙拉把册子塞回怀里，动作很快。",
	},
	[10070721] = {
		ID = 10070721,
		Speaker = "妮芙拉",
		Text = "因为下官是孤儿长大，对于生日日期会特别敏感。",
