	[10070722] = {
		ID = 10070722,
		Speaker = "我",
		Text = "了解。",
	},
	[10070723] = {
		ID = 10070723,
		Speaker = "我",
		Text = "护卫长，你现在怀疑这人就是凶手",
	},
	[10070724] = {
		ID = 10070724,
		Speaker = "妮芙拉",
		Text = "是，而且他总在月圆后出现，所以刚刚才会带武器在宫中巡视。",
	},
	[10070725] = {
		ID = 10070725,
		Speaker = "我",
		Text = "我的同伴，秋比，一整天没有回来。",
	},
	[10070726] = {
		ID = 10070726,
		Text = "妮芙拉整个人僵住了。",
	},
	[10070727] = {
		ID = 10070727,
		Text = "她转过头来，不敢置信地看着我。",
	},
	[10070728] = {
		ID = 10070728,
		Speaker = "我",
		Text = "她有没有可能． ． ．也被带走了。",
	},
	[10070729] = {
		ID = 10070729,
	},
	[10070730] = {
		ID = 10070730,
	},
	[10070731] = {
		ID = 10070731,
		Text = "我一早就绕到侍女房的方向。",
	},
	[10070732] = {
		ID = 10070732,
		Speaker = "我",
		Text = "（昨天晚上那个人身上的香气，我可能认得。）",
	},
	[10070733] = {
		ID = 10070733,
		Speaker = "我",
		Text = "（这座宫里只有一个人身上有。）",
	},
	[10070734] = {
		ID = 10070734,
		Text = "房门开着。矮脚铜炉摆在窗边，奇斐蹲在旁边，正把一小块香料放进去。",
	},
	[10070735] = {
		ID = 10070735,
		Text = "烟先是直的，升到一半散开。",
	},
	[10070736] = {
		ID = 10070736,
		Text = "我没有进去，就站在门口，深深吸了一口气。",
	},
	[10070737] = {
		ID = 10070737,
		Speaker = "奇斐",
		Text = "咦，使者大人！",
	},
	[10070738] = {
		ID = 10070738,
		Speaker = "我",
		Text = "早。",
	},
	[10070739] = {
		ID = 10070739,
		Speaker = "奇斐",
		Text = "你怎么站在门口不进来？",
	},
	[10070740] = {
		ID = 10070740,
		Speaker = "我",
		Text = "我在闻香。",
