	[10070741] = {
		ID = 10070741,
		Speaker = "我",
		Text = "你昨晚睡得好吗？",
	},
	[10070742] = {
		ID = 10070742,
		Speaker = "奇斐",
		Text = "还可以吧。",
	},
	[10070743] = {
		ID = 10070743,
		Speaker = "我",
		Text = "一觉到天亮？",
