	[10070744] = {
		ID = 10070744,
		Speaker = "奇斐",
		Text = "……应该是吧。",
	},
	[10070745] = {
		ID = 10070745,
		Speaker = "奇斐",
		Text = "不过我早上起来脚很脏，我猜是我没洗脚就上床。",
	},
	[10070746] = {
		ID = 10070746,
		Speaker = "我",
		Text = "（她蛮习惯自圆其说的）",
	},
	[10070747] = {
		ID = 10070747,
		Text = "奇斐把铜炉盖上，跳起来拍拍膝盖。",
	},
	[10070748] = {
		ID = 10070748,
		Speaker = "奇斐",
		Text = "我先走啰，我要去找芙，有很重要的事！",
	},
	[10070749] = {
		ID = 10070749,
		Speaker = "我",
		Text = "等等，奇斐，你都不用准备灯火节吗？",
	},
	[10070750] = {
		ID = 10070750,
		Speaker = "奇斐",
		Text = "喔？我不需要准备啊，我的家人都还活着呀！",
