	[10071010] = {
		ID = 10071010,
		Text = "妮芙拉嘴角微微渗血，但还是站了起来。",
	},
	[10071011] = {
		ID = 10071011,
		Text = "娜芙蒂蒂的愤怒还在宣泄，她的权杖又指向房间的另一头。",
	},
	[10071012] = {
		ID = 10071012,
		Text = "妮芙拉眼见权杖释放的魔力即将轰向娜芙泰塔生前最爱的花瓶。",
	},
	[10071013] = {
		ID = 10071013,
		Text = "妮芙拉冲过去用肉身挡下魔力，保护花瓶。",
	},
	[10071014] = {
		ID = 10071014,
		Text = "灰尘慢慢落定。",
	},
	[10071015] = {
		ID = 10071015,
		Text = "妮芙拉抬起头。",
	},
	[10071016] = {
		ID = 10071016,
		Text = "娜芙蒂蒂站在裂开的地砖中间，一只手捂着脸。",
	},
	[10071017] = {
		ID = 10071017,
		Speaker = "娜芙蒂蒂",
		Text = "……不可能。",
	},
	[10071018] = {
		ID = 10071018,
		Speaker = "娜芙蒂蒂",
		Text = "我的泰塔，不可能会做这种事。",
	},
	[10071019] = {
		ID = 10071019,
		Text = "妮芙拉的手停在半空中。",
	},
	[10071020] = {
		ID = 10071020,
		Speaker = "妮芙拉",
		Text = "（……泰塔？）",
	},
	[10071021] = {
		ID = 10071021,
		Text = "她疑惑地看着娜芙蒂蒂",
	},
	[10071022] = {
		ID = 10071022,
		Text = "随即从怀里摸出一块布，把自己嘴角的血擦干净。",
	},
	[10071023] = {
		ID = 10071023,
		Text = "擦干净了，她才站起来。",
	},
	[10071024] = {
		ID = 10071024,
		Text = "一步，一步，走到那个捂着脸的女人面前。",
	},
	[10071025] = {
		ID = 10071025,
		Speaker = "妮芙拉",
		Text = "陛下。",
	},
	[10071026] = {
		ID = 10071026,
		Text = "她把那块布递出去。",
	},
	[10071027] = {
		ID = 10071027,
		Speaker = "妮芙拉",
		Text = "……擦一下吧。",
	},
	[10071028] = {
		ID = 10071028,
		Text = "娜芙蒂蒂没有接。",
	},
	[10071029] = {
		ID = 10071029,
		Text = "她伸手抓住妮芙拉的手臂，整个人靠了过来。",
	},
	[10071030] = {
		ID = 10071030,
		Text = "抖得很厉害。",
	},
	[10071031] = {
		ID = 10071031,
		Text = "妮芙拉维持着递布的姿势，僵在原地，很久才把手放下来，落在对方的背上。",
	},
	[10071032] = {
		ID = 10071032,
		Speaker = "妮芙拉",
		Text = "陛下． ． ． ． ．",
	},
	[10071033] = {
		ID = 10071033,
		Speaker = "妮芙拉",
		Text = "（我好久没看过陛下失控了．．．．．）",
	},
	[10071034] = {
		ID = 10071034,
		Text = "过了很久，娜芙蒂蒂开口了。",
	},
	[10071035] = {
		ID = 10071035,
		Speaker = "娜芙蒂蒂",
		Text = "你跟奇斐还有泰塔是一起长大的．",
	},
	[10071036] = {
		ID = 10071036,
		Speaker = "妮芙拉",
		Text = "……是。",
	},
	[10071037] = {
		ID = 10071037,
		Text = "娜芙蒂蒂突然改变自己的口吻，这一刻她只是妮芙拉的长辈。",
	},
	[10071038] = {
		ID = 10071038,
		Speaker = "娜芙蒂蒂",
		Text = "蒂蒂姐可以相信你对不对？你不会说出去对不对？",
	},
	[10071039] = {
		ID = 10071039,
		Speaker = "娜芙蒂蒂",
		Text = "奇斐自己也不许知道！",
	},
	[10071042] = {
		ID = 10071042,
		Text = "妮芙拉抱着娜芙蒂蒂，心里起了怜悯之心。",
	},
	[10071044] = {
		ID = 10071044,
		Text = "拨完，她转身走回宝座，把插在地上的金杖拔起来。",
	},
	[10071046] = {
		ID = 10071046,
		Text = "她坐下，重新拿起那枚冷透的蜜枣，指尖转了一圈。",
	},
	[10071048] = {
		ID = 10071048,
		Speaker = "妮芙拉",
		Text = "是。",
	},
	[10071051] = {
		ID = 10071051,
	},
	[10071054] = {
		ID = 10071054,
		Text = "她不断地回想娜芙蒂蒂陷入狂乱的神情。",
	},
	[10071057] = {
		ID = 10071057,
		Speaker = "妮芙拉",
		Text = "（但我报告的是奇斐。）",
	},
	[10071059] = {
		ID = 10071059,
		Speaker = "妮芙拉",
		Text = "（泰塔小姐，已经走了十年了。）",
	},
	[10071061] = {
		ID = 10071061,
		Speaker = "妮芙拉",
		Text = "什么． ． ． ． ． ．要把天神使者关进大牢？",
	},
	[10071063] = {
		ID = 10071063,
	},
	[10071065] = {
		ID = 10071065,
		Speaker = "娜芙蒂蒂",
		Text = "护卫长。",
	},
	[10071067] = {
		ID = 10071067,
		Speaker = "妮芙拉",
		Text = "是。",
	},
	[10071069] = {
		ID = 10071069,
		Speaker = "妮芙拉",
		Text = "……神谕？",
	},
	[10071070] = {
		ID = 10071070,
		Speaker = "娜芙蒂蒂",
		Text = "把那三个天上来的，关进大牢。",
	},
	[10071072] = {
		ID = 10071072,
		Speaker = "妮芙拉",
		Text = "陛下，前日的神谕，说他们是贵客。",
	},
	[10071073] = {
		ID = 10071073,
		Speaker = "娜芙蒂蒂",
		Text = "嗯。",
	},
	[10071074] = {
		ID = 10071074,
		Speaker = "妮芙拉",
		Text = "还说他们可能是改变冥河星球的人。",
	},
	[10071075] = {
		ID = 10071075,
		Speaker = "妮芙拉",
		Text = "……那今天这道，是什么时候降的？",
	},
	[10071076] = {
		ID = 10071076,
		Speaker = "娜芙蒂蒂",
		Text = "你在问本座话吗。",
	},
	[10071077] = {
		ID = 10071077,
		Speaker = "妮芙拉",
		Text = "下官不敢。",
	},
	[10071078] = {
		ID = 10071078,
		Speaker = "妮芙拉",
		Text = "只是神谕向来在神殿当众降下，祭司在场，全城皆知。",
	},
	[10071079] = {
		ID = 10071079,
		Speaker = "妮芙拉",
		Text = "这一道，属下没有听说。",
	},
	[10071080] = {
		ID = 10071080,
		Speaker = "娜芙蒂蒂",
		Text = "妮芙拉。",
	},
	[10071081] = {
		ID = 10071081,
		Speaker = "妮芙拉",
		Text = "在。",
	},
	[10071082] = {
		ID = 10071082,
		Speaker = "娜芙蒂蒂",
		Text = "神明要跟谁说话，需要你同意吗。",
	},
	[10071083] = {
		ID = 10071083,
		Speaker = "妮芙拉",
		Text = "……不需要。",
	},
	[10071084] = {
		ID = 10071084,
		Speaker = "娜芙蒂蒂",
		Text = "那你在问什么。",
	},
	[10071085] = {
		ID = 10071085,
		Text = "妮芙拉不敢回话。",
	},
	[10071086] = {
		ID = 10071086,
		Speaker = "娜芙蒂蒂",
		Text = "这座宫里，只有本座能直接听见祂。",
	},
	[10071087] = {
		ID = 10071087,
		Speaker = "娜芙蒂蒂",
		Text = "你今天要本座解释这件事？",
	},
	[10071088] = {
		ID = 10071088,
		Text = "妮芙拉的背绷得笔直。",
	},
	[10071089] = {
		ID = 10071089,
		Speaker = "妮芙拉",
		Text = "（……不对。）",
	},
	[10071090] = {
		ID = 10071090,
		Speaker = "妮芙拉",
		Text = "（陛下从来不用这种语气。）",
	},
	[10071091] = {
		ID = 10071091,
		Speaker = "妮芙拉",
		Text = "（陛下懒得解释任何事，可是她刚刚，解释了。）",
	},
	[10071092] = {
		ID = 10071092,
		Speaker = "妮芙拉",
		Text = "报告，下官领命。",
	},
	[10071093] = {
		ID = 10071093,
		Speaker = "娜芙蒂蒂",
		Text = "那就去。",
	},
	[10071094] = {
		ID = 10071094,
		Text = "妮芙拉转身走出去。",
	},
	[10071095] = {
		ID = 10071095,
		Text = "走到门口，娜芙蒂蒂又开口了，声音比刚才轻。",
	},
	[10071096] = {
		ID = 10071096,
		Speaker = "娜芙蒂蒂",
		Text = "不许伤他们。",
	},
	[10071099] = {
		ID = 10071099,
		Text = "妮芙拉带了六个护卫，站在门外。",
	},
	[10071100] = {
		ID = 10071100,
		Text = "门开的时候，我正在整理行李，我看这阵仗，心里来回盘算。",
	},
	[10071101] = {
		ID = 10071101,
		Speaker = "我",
		Text = "护卫长，这个阵仗是要送客吗？",
	},
	[10071102] = {
		ID = 10071102,
		Speaker = "妮芙拉",
		Text = "使者大人，请随我来。",
	},
	[10071103] = {
		ID = 10071103,
		Speaker = "我",
		Text = "去哪里？",
	},
	[10071104] = {
		ID = 10071104,
		Speaker = "妮芙拉",
		Text = "另一个房间。",
	},
	[10071105] = {
		ID = 10071105,
		Speaker = "我",
		Text = "有窗吗？",
	},
	[10071106] = {
		ID = 10071106,
		Speaker = "妮芙拉",
		Text = "……有。",
	},
	[10071107] = {
		ID = 10071107,
		Speaker = "我",
		Text = "门从哪一边锁？",
	},
	[10071108] = {
		ID = 10071108,
		Text = "妮芙拉没有回答。",
	},
	[10071109] = {
		ID = 10071109,
		Speaker = "我",
		Text = "（果然。）",
	},
	[10071110] = {
		ID = 10071110,
		Speaker = "我",
		Text = "陛下的意思？",
	},
	[10071111] = {
		ID = 10071111,
		Speaker = "妮芙拉",
		Text = "神明的意思。",
	},
	[10071112] = {
		ID = 10071112,
		Speaker = "我",
		Text = "那位神明最近很忙啊，什么都管。",
	},
	[10071114] = {
		ID = 10071114,
		Speaker = "妮芙拉",
		Text = "……使者大人，请。",
	},
	[10071115] = {
		ID = 10071115,
		Text = "我看了她三秒，把行李放下，走了出去。",
	},
	[10071116] = {
		ID = 10071116,
		Speaker = "我",
		Text = "护卫长。",
	},
	[10071117] = {
		ID = 10071117,
		Speaker = "妮芙拉",
		Text = "在。",
	},
	[10071118] = {
		ID = 10071118,
		Speaker = "我",
		Text = "秋比还是没回来，你派人找了吗？",
	},
	[10071119] = {
		ID = 10071119,
		Speaker = "妮芙拉",
		Text = "东侧、西厢、寝殿、库房，全部搜过了。",
	},
	[10071120] = {
		ID = 10071120,
		Speaker = "我",
		Text = "结果？",
	},
	[10071121] = {
		ID = 10071121,
		Speaker = "妮芙拉",
		Text = "……还在找。",
	},
	[10071122] = {
		ID = 10071122,
		Speaker = "我",
		Text = "那黛莉亚呢？",
	},
	[10071123] = {
		ID = 10071123,
		Speaker = "妮芙拉",
		Text = "黛莉亚小姐在宫里。",
	},
	[10071124] = {
		ID = 10071124,
		Speaker = "我",
		Text = "你确定？",
	},
	[10071125] = {
		ID = 10071125,
		Speaker = "妮芙拉",
		Text = "她在神殿东侧修那座钟，她每天都在那里。",
	},
	[10071126] = {
		ID = 10071126,
		Speaker = "我",
		Text = "你今天看到她了吗？",
	},
	[10071127] = {
		ID = 10071127,
		Text = "妮芙拉没有回答。",
	},
	[10071128] = {
		ID = 10071128,
		Speaker = "我",
		Text = "护卫长。",
	},
	[10071129] = {
		ID = 10071129,
		Speaker = "妮芙拉",
		Text = "……她在宫里。",
	},
	[10071130] = {
		ID = 10071130,
		Text = "她说完就转身走了，把门带上。",
	},
	[10071131] = {
		ID = 10071131,
		Speaker = "我",
		Text = "（具体出什么事，我现在还没完全看懂．．．．）",
	},
	[10071132] = {
		ID = 10071132,
		Text = "（我要反抗吗，还是要静观其变？其实我也没这么担心秋比那个可爱的神经病啦！）",
	},
	[10071133] = {
		ID = 10071133,
		Text = "（我是担心不能跟娜芙蒂蒂来第二次啊！吼！！！）",
	},
	[10071134] = {
		ID = 10071134,
	},
	[10071135] = {
		ID = 10071135,
		Text = "妮芙拉一路走过去，走得越来越快，最后几乎是跑的。",
	},
	[10071136] = {
		ID = 10071136,
		Text = "铜墙前面没有人。",
	},
	[10071137] = {
		ID = 10071137,
		Text = "图纸摊在地上，用小石头压着角。工具一件一件排开，全部没有收。",
	},
	[10071138] = {
		ID = 10071138,
		Text = "半根链条搁在最上面那张图纸上，像是有人放下来，打算等一下回来拿。",
	},
	[10071139] = {
		ID = 10071139,
		Speaker = "妮芙拉",
		Text = "黛莉亚小姐？",
	},
	[10071140] = {
		ID = 10071140,
		Text = "没有人回答。",
	},
	[10071141] = {
		ID = 10071141,
		Text = "她绕过那面铜墙，后面也没有人。",
	},
	[10071142] = {
		ID = 10071142,
		Text = "墙角有一只矮脚铜炉。",
	},
	[10071143] = {
		ID = 10071143,
		Text = "香烧完了，灰是冷的。",
	},
	[10071144] = {
		ID = 10071144,
		Speaker = "妮芙拉",
		Text = "（……这里的香，是谁点的。）",
	},
	[10071145] = {
		ID = 10071145,
		Text = "她蹲下来，看着地上那张图纸。",
	},
	[10071146] = {
		ID = 10071146,
		Text = "上面用炭笔画了很多线，最后一条画到一半，断在纸的中间。",
	},
	[10071147] = {
		ID = 10071147,
		Text = "妮芙拉伸手碰了一下那根链条。",
	},
	[10071148] = {
		ID = 10071148,
		Text = "还是温的。",
	},
	[10071149] = {
		ID = 10071149,
		Text = "她从怀里拿出那本名册，翻开。",
	},
	[10071150] = {
		ID = 10071150,
		Text = "三年，十一个名字，每一个后面都写着年纪、进宫几年、家里还有谁，还有生日。",
	},
	[10071151] = {
		ID = 10071151,
		Text = "她翻到最后一页，那页是空白的。",
	},
	[10071152] = {
		ID = 10071152,
		Text = "她突然意识到很可怕的事情，手抖动着，",
	},
	[10071153] = {
		ID = 10071153,
		Text = "她没有写。",
	},
	[10071154] = {
		ID = 10071154,
		Text = "过了很久，她把名册阖上。",
	},
	[10071156] = {
		ID = 10071156,
		Speaker = "妮芙拉",
		Text = "（写下去，就变成第十二个了。）",
	},
	[10071157] = {
		ID = 10071157,
		Text = "她把名册塞回怀里，往关押我的方向走去。",
	},
	[30140140] = {
		ID = 30140140,
		Speaker = "我",
		Text = "（啊哈~怕痒是吧~）",
	},
	[10012089] = {
		ID = 10012089,
		Speaker = "我",
		Text = "嘿咻~嘿咻~解开束缚！",
	},
	[10012099] = {
		ID = 10012099,
		Speaker = "秋比",
		Text = "嗯啊~~~这样……是在玩什么？",
	},
	[10012103] = {
		ID = 10012103,
		Speaker = "秋比",
		Text = "——嗯啊啊啊~~~",
	},
	[10012112] = {
		ID = 10012112,
		Speaker = "秋比",
		Text = "而且下面……还在震嗯啊啊啊~~~",
	},
	[10012133] = {
		ID = 10012133,
		Text = "这么会忍耐啊~那游戏难度要升级了喔~",
	},
	[10012137] = {
		ID = 10012137,
		Speaker = "秋比",
		Text = "——啊~~~~！ ！ ！",
	},
	[10012147] = {
		ID = 10012147,
		Speaker = "秋比",
		Text = "大玩偶你这样是……作弊哈哈哈嗯嗯~~~",
	},
	[10012162] = {
		ID = 10012162,
		Speaker = "我",
		Text = "呼~没想到都把妳弄到高潮了，妳还是没说认输。",
	},
	[30140037] = {
		ID = 30140037,
		Speaker = "秋比",
		Text = "嘻嘻……我缠了好多圈，还帮你绑了蝴蝶结喔！绝对解不开的~",
	},
	[30020001] = {
		ID = 30020001,
		Speaker = "格琳",
		Text = "莲占位",
	},
	[30020002] = {
		ID = 30020002,
		Speaker = "格琳",
		Text = "莲占位2",
	},
	[30120001] = {
		ID = 30120001,
		Speaker = "桔梗",
		Text = "桔梗占位",
	},
	[30120002] = {
		ID = 30120002,
		Speaker = "桔梗",
		Text = "桔梗占位2",
	},
	[30140015] = {
		ID = 30140015,
		Speaker = "秋比",
		Text = "大玩偶~（小声）",
	},
