	[10080553] = {
		ID = 10080553,
		Text = "娜芙蒂蒂闭上眼睛，很久很久，没有再睁开。",
	},
	[10080555] = {
		ID = 10080555,
	},
	[10080560] = {
		ID = 10080560,
		Text = "我准备赶往街道参加灯火节，正巧路过，看见她一个人坐着发呆。",
	},
	[10080561] = {
		ID = 10080561,
		Speaker = "我",
		Text = "怎么一个人坐在这里？",
	},
	[10080562] = {
		ID = 10080562,
		Speaker = "奇斐",
		Text = "天神使者大人？",
	},
	[10080564] = {
		ID = 10080564,
		Speaker = "奇斐",
		Text = "最近宫里好像发生了什么事。",
	},
	[10080567] = {
		ID = 10080567,
		Text = "我的手指停了一下，把到嘴边的话又吞了回去。",
	},
	[10080570] = {
		ID = 10080570,
		Speaker = "我",
		Text = "我一个外人，哪知道你们宫里发生什么事。",
	},
	[10080572] = {
		ID = 10080572,
		Speaker = "我",
		Text = "不说了，我要去参加你们的灯火节。",
	},
	[10080574] = {
		ID = 10080574,
		Speaker = "奇斐",
		Text = "等等，天神使者大人！",
	},
	[10080582] = {
		ID = 10080582,
		Speaker = "我",
		Text = "呵呵，那跟我有什么关系呢？",
	},
	[10080584] = {
		ID = 10080584,
		Text = "我愣住，一时没反应过来她在说什么。",
	},
	[10080585] = {
		ID = 10080585,
		Text = "浴池的水气还没散尽，两人站在池边，奇斐绞着手指，一脸认真。",
	},
	[10080591] = {
		ID = 10080591,
		Text = "诱惑就摆在眼前，我根本没有抵抗力，嘴上却故意板起脸。",
	},
	[10080592] = {
		ID = 10080592,
		Speaker = "我",
		Text = "大胆！",
	},
	[10080602] = {
		ID = 10080602,
		Text = "我凑近她的耳边，先是轻轻吹了一口气。",
	},
	[10080610] = {
		ID = 10080610,
		Speaker = "我",
		Text = "这里很敏感嘛。",
	},
	[10080612] = {
		ID = 10080612,
		Text = "话音刚落，我又轻轻咬了一下，她的声音瞬间拔高，自己都吓了一跳，慌忙捂住嘴。",
	},
	[10080619] = {
		ID = 10080619,
		Speaker = "奇斐",
		Text = "使者大人明明……明明就故意的——",
	},
	[10080623] = {
		ID = 10080623,
		Speaker = "奇斐",
		Text = "（这个人，怎么可以这么坏……）",
	},
	[10080628] = {
		ID = 10080628,
		Text = "他的手缓缓往下滑，指尖划过她的小腹，最后停在腿间，隔着薄薄的布料轻轻按压。",
	},
	[10080629] = {
		ID = 10080629,
		Speaker = "奇斐",
		Text = "——！",
	},
	[10080632] = {
		ID = 10080632,
		Speaker = "奇斐",
		Text = "不要说出来啦……",
	},
	[10080634] = {
		ID = 10080634,
		Speaker = "奇斐",
		Text = "（可是……这种羞耻，怎么又让人觉得，好舒服……）",
	},
	[10080642] = {
		ID = 10080642,
		Speaker = "我",
		Text = "舌尖要多绕着顶端转，这样才舒服。",
	},
	[10080645] = {
		ID = 10080645,
		Speaker = "奇斐",
		Text = "（果然……）",
	},
	[10080651] = {
		ID = 10080651,
		Text = "奇斐红着脸，双手扶上他的肩膀，慢慢坐低身子，让龟头抵在入口反覆磨蹭。",
	},
	[10080662] = {
		ID = 10080662,
		Speaker = "奇斐",
		Text = "啊——！",
	},
	[10080665] = {
		ID = 10080665,
		Speaker = "奇斐",
		Text = "嗯……啊……好深……",
	},
	[10080666] = {
		ID = 10080666,
		Speaker = "奇斐",
		Text = "（面对面的话，什么表情都被使者大人看得一清二楚……）",
	},
	[10080670] = {
		ID = 10080670,
		Speaker = "我",
		Text = "陛下就在旁边看着喔。",
	},
	[10080671] = {
		ID = 10080671,
		Speaker = "奇斐",
		Text = "陛、陛下才不会这样——",
	},
	[10080673] = {
		ID = 10080673,
		Speaker = "我",
		Text = "她现在正摸着自己的胸，一手掐着自己的乳尖，眼睛就这么盯着你看。",
	},
	[10080678] = {
		ID = 10080678,
		Speaker = "我",
		Text = "她走过来了。",
	},
	[10080688] = {
		ID = 10080688,
		Speaker = "奇斐",
		Text = "（奇斐是不是……坏掉了……）",
	},
	[10080691] = {
		ID = 10080691,
		Speaker = "奇斐",
		Text = "陛下不要咬我奶头！奇斐受不了啊！啊啊． ． ． ．",
	},
	[10080695] = {
		ID = 10080695,
		Text = "快感一波接一波地涌上来，奇斐紧紧攀着他的肩膀，指节发白，全身都在颤抖。",
	},
	[10080697] = {
		ID = 10080697,
		Text = "最后几下冲刺又急又深，奇斐的意识瞬间一片空白，尖叫着到达了顶点，同时我也在她体内释放。",
	},
	[10070057] = {
		ID = 10070057,
		Text = "秋比黛莉亚急冲冲离开河湾，我则是觉得不对劲，在巷子口绕了一下。",
	},
	[10070074] = {
		ID = 10070074,
		Text = "笑声断了，妇人抹了一下眼睛，愣愣地看着自己的手背。",
	},
	[10070079] = {
		ID = 10070079,
		Text = "女法王轻蔑一笑，纵身一跳，踏进那圈圣火与芦苇围成的舞台。",
	},
	[10070080] = {
		ID = 10070080,
		Speaker = "黛莉亚",
		Text = "哇，女法王也一起下来了！",
	},
	[10070081] = {
		ID = 10070081,
		Text = "女法王看似慵懒慢半拍的动作，举手投足娇媚横生，两女共舞促拥着气氛来到最高点。",
	},
	[10070083] = {
		ID = 10070083,
		Speaker = "我",
		Text = "怎么会有这么美的女法王． ． ． ． ．",
	},
	[10070085] = {
		ID = 10070085,
		Speaker = "黛莉亚",
		Text = "舰长先生是看傻了，这里人这么多耶． ． ．",
	},
	[10070088] = {
		ID = 10070088,
		Text = "护卫长妮芙拉悄悄地走到我身旁。",
	},
	[10070089] = {
		ID = 10070089,
		Speaker = "妮芙拉",
		Text = "天神使者您好，我是皇家护卫长妮芙拉，",
	},
	[10070090] = {
		ID = 10070090,
		Text = "陛下希望邀请您庆典结束后移驾至皇宫。",
	},
	[10070091] = {
		ID = 10070091,
		Speaker = "我",
		Text = "恩哼，因为是天上来的，所以叫天神使者吗？",
	},
	[10070093] = {
		ID = 10070093,
		Speaker = "我",
		Text = "（呵呵，有时候真受不了自己的魅力啊．．．．．）",
	},
	[10070097] = {
		ID = 10070097,
		Speaker = "秋比",
		Text = "大玩偶的魂魄已经飞走了． ． ． ．",
	},
	[10070098] = {
		ID = 10070098,
		Speaker = "黛莉亚",
		Text = "惨了． ． ．",
	},
	[10070101] = {
		ID = 10070101,
		Text = "妮芙拉领着三人进入王宫，",
	},
	[10070102] = {
		ID = 10070102,
		Text = "廊道两侧立着高大的石柱，柱身刻满了精细图纹，",
	},
	[10070103] = {
		ID = 10070103,
		Text = "走廊尽头是一道厚重的石门，两名卫兵见到妮芙拉便自动让开，门缓缓开启。",
	},
	[10070104] = {
		ID = 10070104,
		Text = "里面是一座巨大的中庭，四周回廊环绕，种著整排高耸的棕榈树，树影在月光下拉得很长。",
	},
	[10070107] = {
		ID = 10070107,
		Speaker = "妮芙拉",
		Text = "王宫跟神殿，本来就是同一批人建的。",
	},
	[10070108] = {
		ID = 10070108,
		Text = "穿过中庭，妮芙拉在一处岔路停下脚步，转身面对三人。",
	},
	[10070110] = {
		ID = 10070110,
		Text = "她看向我。",
	},
	[10070112] = {
		ID = 10070112,
		Speaker = "我",
		Text = "只有我？",
	},
	[10070114] = {
		ID = 10070114,
		Text = "黛莉亚和秋比对看一眼，黛莉亚率先反应过来，露出一个暧昧的表情。",
	},
	[10070118] = {
		ID = 10070118,
		Speaker = "黛莉亚",
		Text = "……他已经沉浸在自己想像的画面了。",
	},
	[10070122] = {
		ID = 10070122,
		Text = "转过一个弯，眼前出现一道半掩的木门，门缝里透出湿热的水气，还有隐约的水声。",
	},
	[10070125] = {
		ID = 10070125,
		Text = "她说完便离开。",
	},
	[10070127] = {
		ID = 10070127,
		Speaker = "我",
		Text = "（……怎么把我带到浴室前面？）",
	},
	[10070128] = {
		ID = 10070128,
		Speaker = "女法王",
		Text = "……你就这么喜欢本座的身体吗？",
	},
	[10070135] = {
		ID = 10070135,
		Text = "我立刻停下动作，再也不敢往前半步。",
	},
	[10070136] = {
		ID = 10070136,
		Speaker = "我",
		Text = "（两个女人？这么香艳的吗？）",
	},
	[10070158] = {
		ID = 10070158,
		Speaker = "奇斐",
		Text = "我只是离开去逛了一下，想说庆典嘛． ． ． ． ．没想到会喝醉断片． ． ．",
	},
	[10070177] = {
		ID = 10070177,
		Speaker = "窗内的声音",
		Text = "河水……将于月盈之后三日始涨，至月亏而退。",
	},
	[10070181] = {
		ID = 10070181,
		Text = "窗里的声音每一句都答得又轻又慢，答完，全场再拜一次。",
	},
	[10070182] = {
		ID = 10070182,
		Speaker = "窗内声音",
		Text = "关于天神使者． ． ． ．请三位务必留步到灯火节。",
	},
	[10070185] = {
		ID = 10070185,
		Speaker = "奇斐",
		Text = "用来引导从冥河中暂时返回的家人灵魂。",
	},
	[10070188] = {
		ID = 10070188,
		Text = "神谕揭示完毕，众人鱼贯走出。",
	},
	[10070189] = {
		ID = 10070189,
		Speaker = "娜芙蒂蒂",
		Text = "几位请随本座来，有件事想请教你们。",
	},
	[10070190] = {
		ID = 10070190,
	},
	[10070196] = {
		ID = 10070196,
		Speaker = "黛莉亚",
		Text = "至少一千年！可是它的咬合角度……不对，那个角度现在都做不出来。",
	},
	[10070198] = {
		ID = 10070198,
		Speaker = "黛莉亚",
		Text = "所以它现在还会转啊！ ！",
	},
	[10070200] = {
		ID = 10070200,
		Speaker = "黛莉亚",
		Text = "我可以。",
	},
	[10070201] = {
		ID = 10070201,
		Speaker = "娜芙蒂蒂",
		Text = "哦？",
	},
	[10070204] = {
		ID = 10070204,
		Speaker = "娜芙蒂蒂",
		Text = "神谕也是这么指示的。",
	},
	[10070209] = {
		ID = 10070209,
		Text = "娜芙蒂蒂慵懒目光，突然勾向我，眼里的笑意让我冷不住发寒。",
	},
	[10070211] = {
		ID = 10070211,
		Speaker = "娜芙蒂蒂",
		Text = "呵呵，本座不在意这些小事。",
	},
	[10070213] = {
		ID = 10070213,
		Speaker = "我",
		Text = "求之不得！一切麻烦陛下了！",
	},
	[10070216] = {
		ID = 10070216,
		Text = "我下意识地看向奇斐，发现奇斐的眼神率真，完全不同于昨夜河湾边的她。",
	},
	[10070224] = {
		ID = 10070224,
		Text = "东岸是屋舍、炊烟、晾着的衣服；西岸是黄土，寸草不生，远处几座尖顶立在雾里。",
	},
	[10070228] = {
		ID = 10070228,
		Speaker = "娜芙蒂蒂",
		Text = "整片都是。走三天，走不完。",
	},
	[10070230] = {
		ID = 10070230,
		Speaker = "我",
		Text = "不会不舒服吗？",
	},
	[10070231] = {
		ID = 10070231,
		Speaker = "娜芙蒂蒂",
		Text = "为什么要不舒服。",
	},
	[10070237] = {
		ID = 10070237,
		Speaker = "娜芙蒂蒂",
		Text = "十五岁挑地。二十岁请人刻名字。名字刻得越深越好，深了风吹不掉。",
	},
	[10070239] = {
		ID = 10070239,
		Speaker = "娜芙蒂蒂",
		Text = "不然呢，死了才准备？",
	},
	[10070241] = {
		ID = 10070241,
		Speaker = "娜芙蒂蒂",
		Text = "那他们一定很慌。",
	},
	[10070245] = {
		ID = 10070245,
		Speaker = "我",
		Text = "听起来陛下有过经验？",
	},
	[10070248] = {
		ID = 10070248,
		Speaker = "娜芙蒂蒂",
		Text = "娜芙泰塔，生下来就不好。",
	},
	[10070250] = {
		ID = 10070250,
		Speaker = "娜芙蒂蒂",
		Text = "她躺着的时候，最喜欢问死了以后会怎么样。",
	},
	[10070251] = {
		ID = 10070251,
		Speaker = "娜芙蒂蒂",
		Text = "本座那时候答不出来，就去翻书。翻了十几年的书。",
	},
	[10070254] = {
		ID = 10070254,
		Speaker = "娜芙蒂蒂",
		Text = "嗯。",
	},
	[10070256] = {
		ID = 10070256,
		Speaker = "娜芙蒂蒂",
		Text = "哼，本座已经很多年没提起这事。",
	},
	[10070258] = {
		ID = 10070258,
		Speaker = "娜芙蒂蒂",
		Text = "确实。",
	},
	[10070259] = {
		ID = 10070259,
		Text = "我有些尴尬，赶忙转移话题。",
	},
	[10070263] = {
		ID = 10070263,
		Speaker = "娜芙蒂蒂",
		Text = "三个小鬼，一天到晚在宫里跑。",
	},
	[10070266] = {
		ID = 10070266,
		Speaker = "我",
		Text = "看到了。",
	},
	[10070270] = {
		ID = 10070270,
		Speaker = "我",
		Text = "为什么。",
	},
	[10070272] = {
		ID = 10070272,
		Speaker = "我",
		Text = "这样不会太压抑吗？",
	},
	[10070276] = {
		ID = 10070276,
		Speaker = "娜芙蒂蒂",
		Text = "呵，油嘴滑舌。",
	},
	[10070279] = {
		ID = 10070279,
		Text = "移动凉亭内回到皇宫内，娜芙蒂蒂半倚着栏杆，回望着我。",
	},
	[10070284] = {
		ID = 10070284,
		Speaker = "娜芙蒂蒂",
		Text = "哼，你整个下午看本座的眼神，都很火热呢。",
	},
	[10070286] = {
		ID = 10070286,
		Speaker = "娜芙蒂蒂",
		Text = "本座只是在观察外来访客。",
	},
	[10070287] = {
		ID = 10070287,
		Speaker = "我",
		Text = "观察得这么仔细？",
	},
	[10070292] = {
		ID = 10070292,
		Speaker = "娜芙蒂蒂",
		Text = "倒是说得直接。",
	},
	[10070294] = {
		ID = 10070294,
		Speaker = "我",
		Text = "好奇什么？",
	},
	[10070297] = {
		ID = 10070297,
		Speaker = "我",
		Text = "……陛下想见识？",
	},
	[10070303] = {
		ID = 10070303,
		Speaker = "我",
		Text = "是陛下说要让我见识的。",
	},
	[10070308] = {
		ID = 10070308,
		Speaker = "娜芙蒂蒂",
		Text = "……没什么。",
	},
	[10070310] = {
		ID = 10070310,
		Speaker = "我",
		Text = "稍微？",
	},
	[10070316] = {
		ID = 10070316,
		Speaker = "娜芙蒂蒂",
		Text = "……本座只是在评估。",
	},
	[10070318] = {
		ID = 10070318,
		Speaker = "我",
		Text = "陛下，好奇心会杀死一只猫的。",
	},
	[10070320] = {
		ID = 10070320,
		Speaker = "娜芙蒂蒂",
		Text = "闭嘴，让我好好感受一下，你的尺寸。",
	},
	[10070322] = {
		ID = 10070322,
		Speaker = "娜芙蒂蒂",
		Text = "……这样的速度，够吗？",
	},
	[10070325] = {
		ID = 10070325,
		Speaker = "我",
		Text = "陛下的大腿，本来就不是普通人能忍住的。",
	},
	[10070327] = {
		ID = 10070327,
		Speaker = "娜芙蒂蒂",
		Text = "但本座接受。",
	},
	[10070335] = {
		ID = 10070335,
		Speaker = "娜芙蒂蒂",
		Text = "本座知道。",
	},
	[10070337] = {
		ID = 10070337,
		Speaker = "娜芙蒂蒂",
		Text = "……外星球的人类，也不过如此。",
	},
	[10070339] = {
		ID = 10070339,
		Speaker = "我",
		Text = "……陛下。",
	},
	[10070345] = {
		ID = 10070345,
		Speaker = "娜芙蒂蒂",
		Text = "哈——！",
	},
	[10070347] = {
		ID = 10070347,
		Speaker = "我",
		Text = "谁的火灭了？",
	},
	[10070350] = {
		ID = 10070350,
		Speaker = "娜芙蒂蒂",
		Text = "哈啊……这样……太深了……！",
	},
	[10070353] = {
		ID = 10070353,
		Speaker = "我",
		Text = "陛下，闭嘴。",
	},
	[10070355] = {
		ID = 10070355,
		Speaker = "娜芙蒂蒂",
		Text = "哈啊……你……你敢叫本座闭嘴……！",
	},
	[10070356] = {
		ID = 10070356,
		Speaker = "我",
		Text = "就算我不叫你闭嘴，你也讲不出话了，不是吗？",
	},
	[10070358] = {
		ID = 10070358,
		Speaker = "我",
		Text = "刚刚不是很嚣张？",
	},
	[10070362] = {
		ID = 10070362,
		Speaker = "娜芙蒂蒂",
		Text = "哈……哈啊啊……！",
	},
	[10070363] = {
		ID = 10070363,
		Speaker = "娜芙蒂蒂",
		Text = "呜……！",
	},
	[10070365] = {
		ID = 10070365,
		Speaker = "娜芙蒂蒂",
		Text = "……里面……",
	},
	[10070367] = {
		ID = 10070367,
		Speaker = "娜芙蒂蒂",
		Text = "……闭嘴。",
	},
	[10070369] = {
		ID = 10070369,
		Speaker = "娜芙蒂蒂",
		Text = "……那是因为你太粗暴了。",
	},
	[10070371] = {
		ID = 10070371,
		Speaker = "娜芙蒂蒂",
		Text = "……嗯……",
	},
	[10070373] = {
		ID = 10070373,
	},
	[10070375] = {
		ID = 10070375,
		Speaker = "娜芙蒂蒂",
		Text = "……舰长先生。",
	},
	[10070376] = {
		ID = 10070376,
		Speaker = "我",
		Text = "嗯？",
	},
	[10070378] = {
		ID = 10070378,
		Speaker = "我",
		Text = "只是『尚且』？",
	},
	[10070016] = {
		ID = 10070016,
		Text = "三人往回走，穿过几个巷子，我的脚步慢了下来。",
	},
	[10070032] = {
		ID = 10070032,
		Text = "我没有回答，往前走到河湾。",
	},
	[10070062] = {
		ID = 10070062,
		Text = "我跟秋比黛莉亚挤进拥挤人潮，终于来到庆典的中心。",
	},
	[10070063] = {
		ID = 10070063,
		Text = "神殿广场临河而建，整片场地在眼前展开。",
	},
	[10070064] = {
		ID = 10070064,
		Text = "沙地中央，铺着一圈晒干的芦苇席，四角各燃一盆圣火，把整片广场圈成一座舞台。",
	},
	[10070065] = {
		ID = 10070065,
		Text = "高台上，君临天下的女法王指尖转着咬一半的蜜枣，慵懒的目光不知在看何处。",
	},
	[10070066] = {
		ID = 10070066,
		Text = "鼓声起，奇斐从人群中走出来，赤脚踏上芦苇席。",
	},
	[10070067] = {
		ID = 10070067,
		Speaker = "黛莉亚",
		Text = "是刚刚那个舞娘耶！",
	},
	[10070068] = {
		ID = 10070068,
		Text = "奇斐翩翩起舞，动作如流水，",
	},
	[10070069] = {
		ID = 10070069,
		Text = "脚踩着鼓点，分毫不差。",
	},
	[10070070] = {
		ID = 10070070,
		Speaker = "黛莉亚",
		Text = "哇． ． ． ．她跳得好好看喔。",
	},
	[10070071] = {
		ID = 10070071,
		Text = "旋律转高，奇斐的嘴角扬了起来，那个笑极具传染性。",
	},
	[10070072] = {
		ID = 10070072,
		Text = "前排的妇人先笑，接着是整片人群，笑得莫名其妙，笑得停不下来。",
	},
	[10070073] = {
		ID = 10070073,
		Text = "鼓点沉下去，她的手臂跟着落下，指尖划过空气。",
	},
	[10070075] = {
		ID = 10070075,
		Speaker = "秋比",
		Text = "秋比怎么有点想哭． ． ．",
	},
	[10070076] = {
		ID = 10070076,
		Speaker = "黛莉亚",
		Text = "我、我怎么也是． ． ．明明刚刚还在笑啊？",
	},
	[10070077] = {
		ID = 10070077,
		Speaker = "我",
		Text = "好厉害的舞蹈，居然能让人跟着又哭又笑． ． ． ．",
	},
	[10070078] = {
		ID = 10070078,
		Text = "忽然奇斐踏着舞步围绕在女法王身边，底下的群众知道奇斐邀请法王共舞，纷纷鼓噪。",
	},
	[10070082] = {
		ID = 10070082,
		Text = "我紧盯着女法王的浑圆上下跳动着，欲望蠢蠢欲动。",
	},
	[10070084] = {
		ID = 10070084,
		Speaker = "我",
		Text = "等等，她是不是一直盯着我看阿？",
	},
	[10070086] = {
		ID = 10070086,
		Text = "并非我的错觉，女法王的眼神总若有似无地投向我，",
	},
	[10070087] = {
		ID = 10070087,
		Text = "有那么一刻，即便相隔几十公尺，感觉自己跟女法王的欲望相通。",
	},
	[10070092] = {
		ID = 10070092,
		Speaker = "我",
		Text = "（果然，这个女法王是看上我了。）",
	},
	[10070094] = {
		ID = 10070094,
		Text = "黛莉亚看我一边装正经，一边露出淫笑，忍不住出声提醒。",
	},
	[10070095] = {
		ID = 10070095,
		Speaker = "黛莉亚",
		Text = "舰长先生． ． ． ．小心啊，你不是说对你投怀送抱的女人都是有企图的吗？",
	},
	[10070096] = {
		ID = 10070096,
		Speaker = "我",
		Text = "没问题，妮芙拉，到时候请你带路。",
	},
	[10070100] = {
		ID = 10070100,
	},
	[10070105] = {
		ID = 10070105,
		Speaker = "秋比",
		Text = "哇，这里好大喔！",
	},
	[10070106] = {
		ID = 10070106,
		Speaker = "黛莉亚",
		Text = "这种规模不晓得要花多少人力维护。",
	},
	[10070109] = {
		ID = 10070109,
		Speaker = "妮芙拉",
		Text = "两位的房间已经备好，在那个方向，会有人领路。",
	},
	[10070111] = {
		ID = 10070111,
		Speaker = "妮芙拉",
		Text = "使者大人，请跟我来，陛下正在等你。",
	},
	[10070113] = {
		ID = 10070113,
		Speaker = "妮芙拉",
		Text = "陛下是这么交代的。",
	},
	[10070115] = {
		ID = 10070115,
		Speaker = "黛莉亚",
		Text = "舰长先生……如果矛头不对，我们随时都可以走....",
	},
	[10070116] = {
		ID = 10070116,
		Speaker = "我",
		Text = "不必担心，我去去就回。",
	},
	[10070117] = {
		ID = 10070117,
		Speaker = "秋比",
		Text = "大玩偶的表情好奇怪喔！",
	},
	[10070119] = {
		ID = 10070119,
		Text = "妮芙拉没有理会两人的窃窃私语，领着我继续往深处走。",
	},
	[10070120] = {
		ID = 10070120,
		Text = "廊道越走越窄，灯笼的数量也越来越少，两侧墙上的雕纹逐渐换成更私密的花草图样。",
	},
	[10070121] = {
		ID = 10070121,
		Speaker = "我",
		Text = "（这个方向……不像是正殿。）",
	},
	[10070123] = {
		ID = 10070123,
		Speaker = "妮芙拉",
		Text = "到了。",
	},
	[10070124] = {
		ID = 10070124,
		Speaker = "妮芙拉",
		Text = "陛下在里面。",
	},
	[10070126] = {
		ID = 10070126,
		Text = "我看着那扇门，浴室飘来渐渐升温的水气，以及女人的笑声。",
	},
	[10070129] = {
		ID = 10070129,
		Text = "我闻言，下体迅速膨胀，内心的欲望压抑不住，要爆炸了！",
	},
	[10070130] = {
		ID = 10070130,
		Speaker = "我",
		Text = "（这样诱惑我，那就不客气了！）",
	},
	[10070131] = {
		ID = 10070131,
		Text = "我准备推开门，冲进去好好发泄一番。",
	},
	[10070132] = {
		ID = 10070132,
		Text = "就在我推门的刹那，浴室内传来第二个女人声音。",
	},
	[10070133] = {
		ID = 10070133,
		Speaker = "奇斐",
		Text = "嘿嘿，陛下的胸部好大好有弹性，奇斐好羡慕啊！",
	},
	[10070134] = {
		ID = 10070134,
		Speaker = "娜芙蒂蒂",
		Text = "哼哼，本座不说话，你倒是越摸越上手了。",
	},
	[10070137] = {
		ID = 10070137,
		Speaker = "娜芙蒂蒂",
		Text = "恩？外面可是舰长先生？",
	},
	[10070138] = {
		ID = 10070138,
		Speaker = "我",
		Text = "是的，陛下，这门开着。",
	},
	[10070139] = {
		ID = 10070139,
		Speaker = "娜芙蒂蒂",
		Text = "本座流了满身汗，但又想与你交流，只好委屈你在这，不见怪吧？",
	},
	[10070140] = {
		ID = 10070140,
		Speaker = "我",
		Text = "陛下，天底下的门，不是开就是关，开一半是最麻烦的。",
	},
	[10070141] = {
		ID = 10070141,
		Speaker = "娜芙蒂蒂",
		Text = "怎么，想进来？",
	},
	[10070142] = {
		ID = 10070142,
		Speaker = "我",
		Text = "我感觉我进去，陛下也不会责怪。",
	},
	[10070143] = {
		ID = 10070143,
		Speaker = "娜芙蒂蒂",
		Text = "哼，你可以试试啊？",
	},
	[10070144] = {
		ID = 10070144,
		Text = "水声哗啦一响，像是有人换了姿势。",
	},
	[10070145] = {
		ID = 10070145,
		Speaker = "奇斐",
		Text = "陛下！ ！ ！ ！ ！奇斐也在这呢！ ！",
	},
	[10070146] = {
		ID = 10070146,
		Speaker = "我",
		Text = "（舞娘奇斐？她们这么亲密吗？）",
	},
	[10070147] = {
		ID = 10070147,
		Speaker = "娜芙蒂蒂",
		Text = "呵呵，有人抗议了，玩笑话仅止于此。",
	},
	[10070148] = {
		ID = 10070148,
		Speaker = "娜芙蒂蒂",
		Text = "舰长先生，前日神谕降临，要我们好好招待贵客。",
	},
	[10070149] = {
		ID = 10070149,
		Speaker = "娜芙蒂蒂",
		Text = "因为你们是有可能改变冥河星球的救世主。",
	},
	[10070150] = {
		ID = 10070150,
		Speaker = "我",
		Text = "我不晓得这颗星球有什么需要拯救的？",
	},
	[10070151] = {
		ID = 10070151,
		Speaker = "娜芙蒂蒂",
		Text = "有时候神明的旨意，一时半刻本座也无法掌握。",
	},
	[10070152] = {
		ID = 10070152,
		Speaker = "娜芙蒂蒂",
		Text = "但本座希望明日你可以跟我们前往神庙请示神明，你不会拒绝吧？",
	},
	[10070153] = {
		ID = 10070153,
		Speaker = "我",
		Text = "陛下的邀请，当然无法拒绝。",
	},
	[10070154] = {
		ID = 10070154,
		Speaker = "娜芙蒂蒂",
		Text = "那我们明日见，护卫长妮芙拉已经准备好寝室。",
	},
	[10070155] = {
		ID = 10070155,
		Speaker = "我",
		Text = "明日见，不打扰了。",
	},
	[10070156] = {
		ID = 10070156,
		Text = "我假装离开，但实则停在浴室门口附近， 听着两女在浴室的嬉闹的声音。",
	},
	[10070157] = {
		ID = 10070157,
		Speaker = "娜芙蒂蒂",
		Text = "奇斐，本座有说过你不能随便离开王宫吧？",
	},
	[10070159] = {
		ID = 10070159,
		Speaker = "娜芙蒂蒂",
		Text = "护卫军有几个人因此被本座革职了，你可知？",
	},
	[10070160] = {
		ID = 10070160,
		Speaker = "奇斐",
		Text = "陛下． ． ．都是我不好，你不要惩罚她们好不好？",
	},
	[10070161] = {
		ID = 10070161,
		Speaker = "娜芙蒂蒂",
		Text = "哼，连个人都看不好，当什么护卫军？",
	},
	[10070162] = {
		ID = 10070162,
		Speaker = "奇斐",
		Text = "． ． ． ． ． ．",
	},
	[10070163] = {
		ID = 10070163,
		Speaker = "我",
		Text = "（她们到底是什么关系，真耐人寻味啊！）",
	},
	[10070164] = {
		ID = 10070164,
		Speaker = "我",
		Text = "（可恶，我也想跟陛下共浴啊！！）",
	},
	[10070165] = {
		ID = 10070165,
	},
	[10070166] = {
		ID = 10070166,
		Text = "金字塔内，天光从高处几道细缝斜切进来，",
	},
	[10070167] = {
		ID = 10070167,
		Text = "柱身刻满密密麻麻的图纹，一路往上延伸到看不清楚的高处。",
	},
	[10070168] = {
		ID = 10070168,
		Text = "正前方那面墙上有一扇方正大窗，离地数十公尺高，窗下跪满了祭司，额头贴地。",
	},
	[10070169] = {
		ID = 10070169,
		Speaker = "奇斐",
		Text = "使者大人，等等不要出声。",
	},
	[10070170] = {
		ID = 10070170,
		Speaker = "秋比",
		Text = "为什么？",
	},
	[10070171] = {
		ID = 10070171,
		Speaker = "奇斐",
		Text = "神明在听。",
	},
	[10070172] = {
		ID = 10070172,
		Speaker = "秋比",
		Text = "神明听得到？",
	},
	[10070173] = {
		ID = 10070173,
		Speaker = "奇斐",
		Text = "是的。",
	},
	[10070174] = {
		ID = 10070174,
		Text = "为首的老祭司举起手杖，敲了三下地砖。",
	},
	[10070175] = {
		ID = 10070175,
		Speaker = "老祭司",
		Text = "尊上在上，本季河水几时涨，几时退，请赐明示。",
	},
	[10070176] = {
		ID = 10070176,
		Text = "那扇窗里传出声音。女人的声音，很轻，很慢，但听不出年纪。",
	},
	[10070178] = {
		ID = 10070178,
		Text = "全场伏拜。",
	},
	[10070179] = {
		ID = 10070179,
		Speaker = "老祭司",
		Text = "谨遵尊上明示——！",
	},
	[10070180] = {
		ID = 10070180,
		Text = "老祭司又问了，关于节庆的日子、献祭的牲口数量、某位贵族女儿的婚期。",
	},
	[10070183] = {
		ID = 10070183,
		Speaker = "黛莉亚",
		Text = "是提到我们吗？灯火节又是什么？",
	},
	[10070184] = {
		ID = 10070184,
		Speaker = "奇斐",
		Text = "使者大人，灯火节是我们三年一度的节日，到时家家户户必须在街上点满火烛。",
	},
	[10070186] = {
		ID = 10070186,
		Speaker = "我",
		Text = "不是纪念死者，而是积极拥抱去世的家人吗？蛮有趣的。",
	},
	[10070187] = {
		ID = 10070187,
		Text = "（挺好奇窗内的神明长什么样子，哼哼，若有机会一定要看看。）",
	},
	[10070191] = {
		ID = 10070191,
		Text = "廊道尽头有一整面墙的铜制结构，齿轮、杠杆、链条，层层叠叠往上堆。",
	},
	[10070192] = {
		ID = 10070192,
		Text = "大半的齿轮都停着，表面积了厚厚一层绿锈。",
	},
	[10070193] = {
		ID = 10070193,
		Text = "黛莉亚站在门口，一动也不动。",
	},
	[10070194] = {
		ID = 10070194,
		Speaker = "秋比",
		Text = "黛莉亚？",
	},
	[10070195] = {
		ID = 10070195,
		Speaker = "黛莉亚",
		Text = "这个做工． ． ． ． ． ．",
	},
	[10070197] = {
		ID = 10070197,
		Speaker = "秋比",
		Text = "所以呢？",
	},
	[10070199] = {
		ID = 10070199,
		Speaker = "娜芙蒂蒂",
		Text = "会转，但是转速完全不对，这个星象钟已流传千年，怎么都修不好。",
	},
	[10070202] = {
		ID = 10070202,
		Speaker = "黛莉亚",
		Text = "我真的可以。",
	},
	[10070203] = {
		ID = 10070203,
		Speaker = "娜芙蒂蒂",
		Text = "舰长先生，那你们就留下来吧？",
	},
	[10070205] = {
		ID = 10070205,
		Speaker = "我",
		Text = "好吧，如果我拒绝，黛莉亚是不会放过我的。",
	},
	[10070206] = {
		ID = 10070206,
		Speaker = "黛莉亚",
		Text = "明明舰长先生自己也． ． ． ．",
	},
	[10070207] = {
		ID = 10070207,
		Speaker = "黛莉亚",
		Text = "连说梦话，都提到陛下的名字呢！",
	},
	[10070208] = {
		ID = 10070208,
		Speaker = "娜芙蒂蒂",
		Text = "喔？两位昨晚睡一起？我记得是帮你们准备了三间寝室啊？",
	},
	[10070210] = {
		ID = 10070210,
		Speaker = "我",
		Text = "唉呀，黛莉亚别胡说，是你们自己要挤到我房间的！",
	},
	[10070212] = {
		ID = 10070212,
		Speaker = "娜芙蒂蒂",
		Text = "既然你们要留下，舰长先生随本座游历冥河如何？",
	},
	[10070214] = {
		ID = 10070214,
		Text = "（这女人主动制造独处的机会，呵呵，该来的还是要来。）",
	},
	[10070215] = {
		ID = 10070215,
		Text = "黛莉亚已经蹲到那面铜墙下面去了，手指沿着一根链条摸上去，整个人像被黏住一样。",
	},
	[10070217] = {
		ID = 10070217,
		Speaker = "我",
		Text = "（跳舞的奇斐，河湾旁的奇斐，跟此时的奇斐都有些不同）",
	},
	[10070218] = {
		ID = 10070218,
		Speaker = "我",
		Text = "（这个星球上的女人怎么都这么有趣）",
	},
	[10070220] = {
		ID = 10070220,
	},
	[10070221] = {
		ID = 10070221,
		Text = "一艘华盖凉亭船停在阶梯下，四名船伕撑篙，篷顶垂着纱，四角缀着金铃。",
	},
	[10070222] = {
		ID = 10070222,
		Text = "娜芙蒂蒂已经坐在里面了，赤脚收在软垫上，手里照例转着一枚蜜枣。",
	},
	[10070223] = {
		ID = 10070223,
		Text = "船离岸，篙一撑，两岸的景色开始分成两半",
	},
	[10070226] = {
		ID = 10070226,
		Speaker = "娜芙蒂蒂",
		Text = "嗯。",
	},
	[10070227] = {
		ID = 10070227,
		Speaker = "我",
		Text = "整片都是？",
	},
	[10070229] = {
		ID = 10070229,
		Speaker = "我",
		Text = "陛下的百姓，每天睁开眼就看得到自己的坟。",
	},
	[10070232] = {
		ID = 10070232,
		Speaker = "娜芙蒂蒂",
		Text = "你家门口那条路，你每天走，你会不舒服吗。",
	},
	[10070233] = {
		ID = 10070233,
		Speaker = "我",
		Text = "那不一样。",
	},
	[10070234] = {
		ID = 10070234,
		Speaker = "娜芙蒂蒂",
		Text = "一样，迟早要走的。生生死死。",
	},
	[10070235] = {
		ID = 10070235,
		Text = "她把蜜枣核吐进手心，随手扔进河里。",
	},
	[10070236] = {
		ID = 10070236,
		Speaker = "娜芙蒂蒂",
		Text = "本座治下的人，八岁开始存钱，存的是自己的棺。",
	},
	[10070238] = {
		ID = 10070238,
		Speaker = "我",
		Text = "这么早就准备？",
	},
	[10070240] = {
		ID = 10070240,
		Speaker = "我",
		Text = "我去过的地方，大部分都是死了才准备。",
	},
	[10070242] = {
		ID = 10070242,
		Speaker = "我",
		Text = "慌得不得了。",
	},
	[10070243] = {
		ID = 10070243,
		Speaker = "娜芙蒂蒂",
		Text = "蠢！人死后，还有很多事要面对，",
	},
	[10070244] = {
		ID = 10070244,
		Speaker = "娜芙蒂蒂",
		Text = "伤心欲决怎么处理那些琐事？",
	},
	[10070246] = {
		ID = 10070246,
		Text = "娜芙蒂蒂第一次停顿，她犹豫了片刻，最后缓缓说出。",
	},
	[10070247] = {
		ID = 10070247,
		Speaker = "娜芙蒂蒂",
		Text = "本座有一个妹妹。",
	},
	[10070249] = {
		ID = 10070249,
		Speaker = "娜芙蒂蒂",
		Text = "医官说活不过十五，她活到十七。",
	},
	[10070252] = {
		ID = 10070252,
		Speaker = "娜芙蒂蒂",
		Text = "现在本座答得出来了。",
	},
	[10070253] = {
		ID = 10070253,
		Speaker = "我",
		Text = "……但她听不到了。",
	},
	[10070255] = {
		ID = 10070255,
		Text = "河水拍着船身，娜芙蒂蒂的悲伤一闪而逝。",
	},
	[10070257] = {
		ID = 10070257,
		Speaker = "我",
		Text = "抱歉，是我多问了。",
	},
	[10070260] = {
		ID = 10070260,
		Speaker = "我",
		Text = "昨天那个舞娘奇斐，跟陛下感情不错。",
	},
	[10070261] = {
		ID = 10070261,
		Speaker = "娜芙蒂蒂",
		Text = "当然，我看着她长大。",
	},
	[10070262] = {
		ID = 10070262,
		Speaker = "娜芙蒂蒂",
		Text = "她跟泰塔还有护卫长妮芙拉是一起在王宫里长大的。",
	},
	[10070264] = {
		ID = 10070264,
		Text = "娜芙蒂蒂伸手把纱帘撩开一点，看向西岸。",
	},
	[10070265] = {
		ID = 10070265,
		Speaker = "娜芙蒂蒂",
		Text = "那边的石塔，看到没有。",
	},
	[10070267] = {
		ID = 10070267,
		Speaker = "娜芙蒂蒂",
		Text = "泰塔在其中一座石塔。",
	},
	[10070268] = {
		ID = 10070268,
		Speaker = "我",
		Text = "陛下常去吗？",
	},
	[10070269] = {
		ID = 10070269,
		Speaker = "娜芙蒂蒂",
		Text = "不去。",
	},
	[10070271] = {
		ID = 10070271,
		Speaker = "娜芙蒂蒂",
		Text = "太频繁的思念会打扰灵魂安息，甚至可能让灵魂舍不得离开，无法真正前往该去的地方。",
	},
	[10070273] = {
		ID = 10070273,
		Speaker = "娜芙蒂蒂",
		Text = ".....本座累了，该回王宫了。",
	},
	[10070274] = {
		ID = 10070274,
		Speaker = "娜芙蒂蒂",
		Text = "舰长先生，本座不会压抑，跟你出游，意外地让本座心情轻松不少。",
	},
	[10070275] = {
		ID = 10070275,
		Speaker = "我",
		Text = "让人自然流露心事，是我的特质，特别对漂亮的女人有用。",
	},
	[10070278] = {
		ID = 10070278,
	},
	[10070280] = {
		ID = 10070280,
		Speaker = "娜芙蒂蒂",
		Text = "舰长先生，这样带你绕了一圈，可有更了解冥河星球？",
	},
	[10070281] = {
		ID = 10070281,
		Speaker = "我",
		Text = "当然，非常感谢陛下的导览。",
	},
	[10070282] = {
		ID = 10070282,
		Speaker = "我",
		Text = "但我更渴望了解陛下。",
	},
	[10070283] = {
		ID = 10070283,
		Text = "娜芙蒂蒂轻笑。",
	},
	[10070285] = {
		ID = 10070285,
		Speaker = "我",
		Text = "陛下的眼神，似乎也不太平常呢。",
	},
	[10070288] = {
		ID = 10070288,
		Speaker = "娜芙蒂蒂",
		Text = "……嗯，你.....就这么想要本座的身体吗？",
	},
	[10070289] = {
		ID = 10070289,
		Text = "面对娜芙蒂蒂突来的直球对决，我面不改色地回应。",
	},
	[10070290] = {
		ID = 10070290,
		Speaker = "我",
		Text = "如果陛下愿意，那会是我毕生的荣幸。",
	},
	[10070291] = {
		ID = 10070291,
		Speaker = "娜芙蒂蒂",
		Text = "……呵。",
	},
	[10070293] = {
		ID = 10070293,
		Speaker = "娜芙蒂蒂",
		Text = "不过本座也很好奇。",
	},
	[10070295] = {
		ID = 10070295,
		Speaker = "娜芙蒂蒂",
		Text = "舰长先生的本事。",
	},
	[10070296] = {
		ID = 10070296,
		Speaker = "娜芙蒂蒂",
		Text = "毕竟是外星球来的人类……本座从来没有见识过。",
	},
	[10070298] = {
		ID = 10070298,
		Speaker = "娜芙蒂蒂",
		Text = "……嗯。",
	},
