	[10080081] = {
		ID = 10080081,
		Speaker = "妮芙拉",
		Text = "就算要抓人，也应该是我执行才对，这是陛下亲自对我下的命令。",
	},
	[10080082] = {
		ID = 10080082,
		Text = "我走到牢门边，隔着铁栏看她。",
	},
	[10080083] = {
		ID = 10080083,
		Speaker = "我",
		Text = "护卫长，我问你。",
	},
	[10080084] = {
		ID = 10080084,
		Speaker = "我",
		Text = "我第一天到，就被安排站在浴室外面，听陛下洗澡。",
	},
	[10080085] = {
		ID = 10080085,
		Speaker = "我",
		Text = "是你们这里招待客人的规矩？",
	},
	[10080086] = {
		ID = 10080086,
		Text = "妮芙拉皱眉，摇头。",
	},
	[10080087] = {
		ID = 10080087,
		Speaker = "妮芙拉",
		Text = "不是啊.....但这跟黛莉亚小姐失踪有什么关系？",
	},
	[10080088] = {
		ID = 10080088,
		Speaker = "我",
		Text = "当然有，麻烦你让我把话说完。",
	},
	[10080089] = {
		ID = 10080089,
		Speaker = "妮芙拉",
		Text = "泰塔小姐过世之后，陛下已经很多年没让任何男性靠近了。",
	},
	[10080090] = {
		ID = 10080090,
		Speaker = "妮芙拉",
		Text = "我在她身边这么久，从来没见过她主动……那样『诱惑』任何人。",
	},
	[10080091] = {
		ID = 10080091,
		Text = "我点头，证实了自己的想法。",
	},
	[10080092] = {
		ID = 10080092,
		Speaker = "我",
		Text = "（从第一天就刻意让我精虫冲脑，好像早知道我喜好女色。）",
	},
	[10080093] = {
		ID = 10080093,
		Speaker = "我",
		Text = "我再问你，那座坏掉的星象钟，修不修得好，重要吗？",
	},
	[10080094] = {
		ID = 10080094,
		Speaker = "妮芙拉",
		Text = "其实早就没有人需要那座星象钟....",
	},
	[10080095] = {
		ID = 10080095,
		Speaker = "我",
		Text = "果然，黛莉亚会留在那里一整天，不会离开一步，这才是重要的地方。",
	},
	[10080096] = {
		ID = 10080096,
		Text = "妮芙拉倒抽一口气，退了半步。",
	},
	[10080097] = {
		ID = 10080097,
		Speaker = "妮芙拉",
		Text = "陛下……从一开始，就在算计你们三个？",
	},
	[10080098] = {
		ID = 10080098,
		Speaker = "我",
		Text = "不如问，她怎么知道我们的喜好？",
	},
	[10080099] = {
		ID = 10080099,
		Speaker = "我",
		Text = "唯一的解释，我猜，就是那个万能的『神谕』吧！",
	},
	[10080100] = {
		ID = 10080100,
		Speaker = "妮芙拉",
		Text = "使者大人，你不会是想去......",
	},
	[10080101] = {
		ID = 10080101,
		Speaker = "我",
		Text = "对，带我去神殿。",
	},
	[10080102] = {
		ID = 10080102,
		Speaker = "妮芙拉",
		Text = "不行。",
	},
	[10080103] = {
		ID = 10080103,
		Speaker = "妮芙拉",
		Text = "神殿深处是禁地，擅闯是死罪！",
	},
	[10080104] = {
		ID = 10080104,
		Speaker = "我",
		Text = "呵，我这辈子最不担心的，就是死罪。",
	},
	[10080105] = {
		ID = 10080105,
		Speaker = "我",
		Text = "妮芙拉，你要救你的童年好友，现在就去找陛下跟奇斐！",
	},
	[10080106] = {
		ID = 10080106,
		Speaker = "我",
		Text = "但是，我也要去救我的船员，分头进行，",
	},
	[10080107] = {
		ID = 10080107,
		Speaker = "我",
		Text = "这样就能搞清楚发生什么事，不是吗",
	},
	[10080108] = {
		ID = 10080108,
		Text = "妮芙拉犹豫，一脸为难。",
	},
	[10080109] = {
		ID = 10080109,
		Speaker = "妮芙拉",
		Text = "使者大人，抱歉！",
	},
	[10080110] = {
		ID = 10080110,
		Speaker = "妮芙拉",
		Text = "我其实，是相信你的话......但我就是不能这样放你走....",
	},
	[10080111] = {
		ID = 10080111,
		Speaker = "我",
		Text = "我懂了，对陛下的忠诚心是吧？",
	},
	[10080112] = {
		ID = 10080112,
		Speaker = "我",
		Text = "我不讨厌你这个性喔，相反的，这就是你的魅力所在。",
	},
	[10080113] = {
		ID = 10080113,
		Text = "我想了想，靠近铁栏，压低声音。",
	},
	[10080114] = {
		ID = 10080114,
		Speaker = "我",
		Text = "但是忠诚心是救不了奇斐的。",
	},
	[10080115] = {
		ID = 10080115,
		Speaker = "妮芙拉",
		Text = "使者大人有什么建议吗。",
	},
	[10080116] = {
		ID = 10080116,
		Speaker = "我",
		Text = "去找陛下，不管她在做什么，不管她在哪里，你都直接闯进去。",
	},
	[10080117] = {
		ID = 10080117,
		Speaker = "妮芙拉",
		Text = "……你在开玩笑吗？",
	},
	[10080118] = {
		ID = 10080118,
		Speaker = "我",
		Text = "我很认真。",
	},
	[10080119] = {
		ID = 10080119,
		Speaker = "妮芙拉",
		Text = "如果陛下正在议事，或是在休息呢？",
	},
	[10080120] = {
		ID = 10080120,
		Speaker = "我",
		Text = "不管在干嘛，都闯。",
	},
	[10080121] = {
		ID = 10080121,
		Speaker = "妮芙拉",
		Text = "那她会生气的。",
	},
	[10080122] = {
		ID = 10080122,
		Speaker = "我",
		Text = "生气就让她生气，你就说，是奇斐叫你这么做的。",
	},
	[10080123] = {
		ID = 10080123,
		Speaker = "我",
		Text = "你看看会发生什么事。",
	},
	[10080124] = {
		ID = 10080124,
		Text = "妮芙拉半信半疑地看着我。",
	},
	[10080125] = {
		ID = 10080125,
		Speaker = "妮芙拉",
		Text = "……好。我去。",
	},
	[10080126] = {
		ID = 10080126,
		Text = "她转身快步离去，我看着她的背影消失在转角。",
	},
	[10080127] = {
		ID = 10080127,
		Speaker = "我",
		Text = "（如果妮芙拉你不回来，我就只能想办法越狱了。）",
	},
	[10080128] = {
		ID = 10080128,
		Text = "浴室门口比平常多了两名卫兵，交叉站立，神情肃穆。",
	},
	[10080129] = {
		ID = 10080129,
		Text = "妮芙拉快步走来，卫兵立刻拦住她。",
	},
	[10080130] = {
		ID = 10080130,
		Speaker = "卫兵甲",
		Text = "陛下有令，任何人不得靠近。",
	},
	[10080131] = {
		ID = 10080131,
		Speaker = "妮芙拉",
		Text = "我有急事求见。",
	},
	[10080132] = {
		ID = 10080132,
		Speaker = "卫兵乙",
		Text = "护卫长恕罪，这是陛下亲口的吩咐。",
	},
	[10080133] = {
		ID = 10080133,
		Speaker = "妮芙拉",
		Text = "奇斐是不是也在里面？",
	},
	[10080134] = {
		ID = 10080134,
		Text = "卫兵点头。",
	},
	[10080135] = {
		ID = 10080135,
		Text = "妮芙拉停下脚步，看着那扇紧闭的门，心里忽然想起一件事。",
	},
	[10080136] = {
		ID = 10080136,
		Speaker = "妮芙拉",
		Text = "（……每个月总会有那么几天。）",
	},
	[10080137] = {
		ID = 10080137,
		Speaker = "妮芙拉",
		Text = "（陛下跟奇斐会突然变得很亲密，还会这样把人隔绝在外。）",
	},
	[10080138] = {
		ID = 10080138,
		Speaker = "妮芙拉",
		Text = "（我问过奇斐，她说不出个所以然，只当是陛下太宠她。）",
	},
	[10080139] = {
		ID = 10080139,
		Speaker = "妮芙拉",
		Text = "（她还说过，陛下有时候会叫错，叫她「泰塔」。）",
	},
	[10080140] = {
		ID = 10080140,
		Speaker = "妮芙拉",
		Text = "（……我一直以为，那只是陛下把思念投射在她身上。）",
	},
	[10080141] = {
		ID = 10080141,
		Text = "妮芙拉深吸一口气，握紧拳头。",
	},
	[10080142] = {
		ID = 10080142,
		Speaker = "妮芙拉",
		Text = "……抱歉了。",
	},
	[10080143] = {
		ID = 10080143,
		Text = "她猛然向前，肩膀直接撞开卫兵甲，另一手推开卫兵乙，冲向那扇门。",
	},
	[10080144] = {
		ID = 10080144,
		Speaker = "卫兵甲",
		Text = "护卫长！",
	},
	[10080145] = {
		ID = 10080145,
		Text = "妮芙拉一把推开门，闯了进去。",
	},
	[10080146] = {
		ID = 10080146,
		Text = "浴池里浮着厚厚一层泡沫，白茫茫的，看不清水面下的样子，也照不出任何倒影。",
	},
	[10080147] = {
		ID = 10080147,
		Text = "娜芙蒂蒂与奇斐靠坐在池边，互相帮对方搓澡，娜芙蒂蒂看见妮芙拉闯入的瞬间，脸色瞬间沉下来。",
	},
	[10080148] = {
		ID = 10080148,
		Speaker = "娜芙蒂蒂",
		Text = "护卫长！你在做什么！",
	},
	[10080149] = {
		ID = 10080149,
		Text = "妮芙拉站在门口，神情紧张，额头冒着汗。",
	},
	[10080150] = {
		ID = 10080150,
		Speaker = "妮芙拉",
		Text = "（拜托，使者大人，千万千万千万不要害我……）",
	},
	[10080151] = {
		ID = 10080151,
		Speaker = "妮芙拉",
		Text = "陛、陛下恕罪！",
	},
	[10080152] = {
		ID = 10080152,
		Speaker = "妮芙拉",
		Text = "是……是奇斐叫下官来的！她说也想让下官一起泡澡！",
	},
	[10080154] = {
		ID = 10080154,
	},
	[10080155] = {
		ID = 10080155,
		Text = "妮芙拉硬着头皮回应盛怒的娜芙蒂蒂。",
	},
	[10080156] = {
		ID = 10080156,
		Speaker = "妮芙拉",
		Text = "陛、陛下恕罪！是……是奇斐叫下官来的！她说也想让下官一起泡澡！",
	},
	[10080157] = {
		ID = 10080157,
		Text = "娜芙蒂蒂愣了一下。",
	},
	[10080158] = {
		ID = 10080158,
		Speaker = "娜芙蒂蒂",
		Text = "……是吗？",
	},
	[10080159] = {
		ID = 10080159,
		Text = "泡沫堆得高高的，奇斐就坐在娜芙蒂蒂身侧，浸在水里，笑得一脸天真。",
	},
	[10080160] = {
		ID = 10080160,
		Text = "娜芙蒂蒂没有回头问她。",
	},
	[10080161] = {
		ID = 10080161,
		Speaker = "妮芙拉",
		Text = "（……陛下没有问奇斐。）",
	},
	[10080162] = {
		ID = 10080162,
		Speaker = "妮芙拉",
		Text = "（为什么不问？）",
	},
	[10080163] = {
		ID = 10080163,
		Speaker = "娜芙蒂蒂",
		Text = "虽然是这样，但现在是本座在沐浴……",
	},
	[10080164] = {
		ID = 10080164,
		Speaker = "娜芙蒂蒂",
		Text = "你先退下，改天再来。",
	},
	[10080165] = {
		ID = 10080165,
		Text = "妮芙拉没有动。",
	},
	[10080166] = {
		ID = 10080166,
		Text = "她伸手，解开肩甲的扣环，一件一件卸下来，动作快得不像平时的她。",
	},
	[10080167] = {
		ID = 10080167,
		Speaker = "娜芙蒂蒂",
		Text = "妮芙拉？",
	},
	[10080168] = {
		ID = 10080168,
		Text = "甲片落地，内衣也跟着滑下来。",
	},
	[10080169] = {
		ID = 10080169,
		Text = "妮芙拉赤裸着身体，毫不犹豫地跨过池缘，扑通一声跳进水池。",
	},
	[10080170] = {
		ID = 10080170,
		Speaker = "妮芙拉",
		Text = "小时候，下官也是这样跟奇斐、跟泰塔小姐一起泡的。",
	},
	[10080171] = {
		ID = 10080171,
		Speaker = "妮芙拉",
		Text = "陛下不会介意吧？",
	},
	[10080172] = {
		ID = 10080172,
		Speaker = "奇斐",
		Text = "对啊！姐姐让妮妮一起泡嘛！",
	},
	[10080173] = {
		ID = 10080173,
		Speaker = "妮芙拉",
		Text = "（……这个世界上，只有泰塔会叫我妮妮。）",
	},
	[10080174] = {
		ID = 10080174,
		Speaker = "妮芙拉",
		Text = "（奇斐不会这样叫我。）",
	},
	[10080175] = {
		ID = 10080175,
		Text = "娜芙蒂蒂猛地站起，脸色格外凝重。",
	},
	[10080176] = {
		ID = 10080176,
		Speaker = "娜芙蒂蒂",
		Text = "妮芙拉，你今天……有点反常！",
	},
	[10080177] = {
		ID = 10080177,
		Speaker = "妮芙拉",
		Text = "（不管陛下怎么生气，我都要想着，我是为了救自己最重要的朋友。）",
	},
	[10080178] = {
		ID = 10080178,
		Speaker = "妮芙拉",
		Text = "（我没有叛国，我也没有背叛任何人。）",
	},
	[10080179] = {
		ID = 10080179,
		Text = "奇斐凑过来，仔细打量妮芙拉。",
	},
	[10080180] = {
		ID = 10080180,
		Speaker = "奇斐",
		Text = "妮妮，你的身材怎么变这么好？",
	},
	[10080181] = {
		ID = 10080181,
		Text = "她伸手轻轻碰了碰妮芙拉的胸口，好奇地掂了掂。",
	},
	[10080182] = {
		ID = 10080182,
		Speaker = "奇斐",
		Text = "你的胸部都比姐姐还大了呢！",
	},
	[10080183] = {
		ID = 10080183,
		Speaker = "妮芙拉",
		Text = "那、那个……你不可以随便摸人家的",
	},
	[10080184] = {
		ID = 10080184,
		Text = "话还没说完，奇斐已经凑到她耳边，指尖顺着她的锁骨滑下去，贴着肌肤游走。",
	},
	[10080185] = {
		ID = 10080185,
		Speaker = "奇斐",
		Text = "妮妮的皮肤也好滑喔，跟以前完全不一样了。",
	},
	[10080186] = {
		ID = 10080186,
		Text = "妮芙拉的身体僵硬地绷着，一动也不敢动，",
	},
	[10080187] = {
		ID = 10080187,
		Text = "眼角余光瞥见娜芙蒂蒂死死盯着这一幕，脸色一阵青一阵白。",
	},
	[10080188] = {
		ID = 10080188,
		Speaker = "妮芙拉",
		Text = "奇斐……有没有跟姐姐提过，昨天你说想推的那条全国法令？",
	},
	[10080189] = {
		ID = 10080189,
		Text = "奇斐的手停在半空中。",
	},
	[10080190] = {
		ID = 10080190,
		Text = "她歪着头，一脸真心的困惑。",
	},
	[10080191] = {
		ID = 10080191,
		Speaker = "奇斐",
		Text = "……奇斐在哪里？",
	},
	[10080192] = {
		ID = 10080192,
		Text = "妮芙拉整个人僵住，猛地转头看向娜芙蒂蒂。",
	},
	[10080193] = {
		ID = 10080193,
		Text = "娜芙蒂蒂的眼神里已经没有慌乱，只剩下一片森冷的杀意，死死锁着妮芙拉。",
	},
	[10080194] = {
		ID = 10080194,
		Speaker = "娜芙蒂蒂",
		Text = "……妮芙拉。",
	},
	[10080195] = {
		ID = 10080195,
		Speaker = "妮芙拉",
		Text = "是……是，陛下。",
	},
	[10080196] = {
		ID = 10080196,
		Speaker = "娜芙蒂蒂",
		Text = "等这里结束，你来见本座。",
	},
	[10080197] = {
		ID = 10080197,
		Text = "妮芙拉没有回答，只是点头，指尖在水面下悄悄颤抖。",
	},
	[10080198] = {
		ID = 10080198,
	},
	[10080199] = {
		ID = 10080199,
		Text = "芦苇席边的矮脚铜炉燃着薰香，烟一缕一缕笔直升起。",
	},
	[10080200] = {
		ID = 10080200,
		Text = "娜芙蒂蒂跪在席子中央，双手交叠，额头几乎贴地。",
	},
	[10080201] = {
		ID = 10080201,
		Speaker = "娜芙蒂蒂",
		Text = "……尊上。",
	},
	[10080202] = {
		ID = 10080202,
		Text = "她维持着跪姿，很久没有起身。",
	},
	[10080203] = {
		ID = 10080203,
		Speaker = "娜芙蒂蒂",
		Text = "尊上，请恕本座斗胆一问。",
	},
	[10080204] = {
		ID = 10080204,
		Speaker = "娜芙蒂蒂",
		Text = "泰塔她……为何会做出那样不堪的事？",
	},
	[10080205] = {
		ID = 10080205,
		Speaker = "娜芙蒂蒂",
		Text = "那完全不是她生前的样子。她从来，从来都不是那样的孩子。",
	},
	[10080206] = {
		ID = 10080206,
		Text = "但空中只有风穿过缝隙的声音。",
	},
	[10080207] = {
		ID = 10080207,
		Text = "过了很久，那道熟悉的、轻柔的声音才缓缓落下来。",
