		Text = "然后，今天不管遇到谁，我都要告诉他艾蕾娜今天超可爱。",
	},
	[20160222] = {
		ID = 20160222,
		Speaker = "我",
		Text = "最后再加上一个拥抱，这样总算公平了吧。",
	},
	[20160223] = {
		ID = 20160223,
		Text = "……呜！",
	},
	[20160224] = {
		ID = 20160224,
		Speaker = "艾蕾娜",
		Text = "不、不用。",
	},
	[20160225] = {
		ID = 20160225,
		Speaker = "我",
		Text = "还是艾蕾娜想要揉揉肚子呢？",
	},
	[20160226] = {
		ID = 20160226,
		Speaker = "艾蕾娜",
		Text = "呀啊！船长……",
	},
	[20160227] = {
		ID = 20160227,
		Speaker = "我",
		Text = "怎么，妳自己开的条件，我这边还没答应完呢。",
	},
	[20160228] = {
		ID = 20160228,
		Text = "够了。",
	},
	[20160229] = {
		ID = 20160229,
		Text = "吃。",
	},
	[20160230] = {
		ID = 20160230,
		Text = "现在。",
	},
	[20160231] = {
		ID = 20160231,
		Speaker = "艾蕾娜",
		Text = "不要再说了。",
	},
	[20160232] = {
		ID = 20160232,
		Speaker = "我",
		Text = "好啦好啦，我吃还不行吗。",
	},
	[20160233] = {
		ID = 20160233,
		Speaker = "艾蕾娜",
		Text = "呜……船长是……大坏人……",
	},
	[20160235] = {
		ID = 20160235,
	},
	[20160236] = {
		ID = 20160236,
		Speaker = "我",
		Text = "当然是那种一咬下去，里面塞满满的鲜奶油，多到挤出来的那种。",
	},
	[20160237] = {
		ID = 20160237,
		Speaker = "艾蕾娜",
		Text = "唔——！灌满……鲜奶油……",
	},
	[20160238] = {
		ID = 20160238,
		Speaker = "我",
		Text = "越满越好，甚至可以说，宁愿面包本体小一点，馅多一点才划算。",
	},
	[20160239] = {
		ID = 20160239,
		Speaker = "艾蕾娜",
		Text = "娇小一点……吗？船长……好色情……",
	},
	[20160240] = {
		ID = 20160240,
		Speaker = "我",
		Text = "妳的脸很红喔？",
	},
	[20160241] = {
		ID = 20160241,
		Speaker = "艾蕾娜",
		Text = "没……没事……",
	},
	[20160242] = {
