		Speaker = "艾蕾娜",
		Text = "……我知道。",
	},
	[20160515] = {
		ID = 20160515,
		Speaker = "我",
		Text = "是不是不舒服？身体哪里不对劲吗？",
	},
	[20160516] = {
		ID = 20160516,
		Text = "全身……都好烫……",
	},
	[20160517] = {
		ID = 20160517,
		Speaker = "艾蕾娜",
		Text = "不知道……为什么……",
	},
	[20160518] = {
		ID = 20160518,
		Speaker = "我",
		Text = "没有发烧的样子啊……",
	},
	[20160519] = {
		ID = 20160519,
		Speaker = "艾蕾娜",
		Text = "可是……身体、不听我的话……",
	},
	[20160520] = {
		ID = 20160520,
		Speaker = "我",
		Text = "要不要先喝口水？",
	},
	[20160521] = {
		ID = 20160521,
		Speaker = "艾蕾娜",
		Text = "……好。",
	},
	[20160522] = {
		ID = 20160522,
		Speaker = "我",
		Text = "妳、妳靠太近了吧？",
	},
	[20160523] = {
		ID = 20160523,
		Text = "……我知道。",
	},
	[20160524] = {
		ID = 20160524,
		Speaker = "艾蕾娜",
		Text = "可是停不下来。",
	},
	[20160525] = {
		ID = 20160525,
		Speaker = "我",
		Text = "喂……",
	},
	[20160526] = {
		ID = 20160526,
		Speaker = "我",
		Text = "妳的手在抖啊。",
	},
	[20160527] = {
		ID = 20160527,
		Text = "……我没事。",
	},
	[20160528] = {
		ID = 20160528,
		Speaker = "艾蕾娜",
		Text = "船长……让我靠一下……就好……",
	},
	[20160529] = {
		ID = 20160529,
		Text = "艾蕾娜大口喘气，脸红得不得了。",
	},
	[20160530] = {
		ID = 20160530,
		Text = "而且……身体还不断的在我身上扭，似乎还感觉有股液体沾上了我的裤管。",
	},
	[20160531] = {
		ID = 20160531,
		Speaker = "我",
		Text = "艾蕾娜，看着我。",
	},
	[20160532] = {
		ID = 20160532,
		Speaker = "艾蕾娜",
		Text = "……",
	},
	[20160533] = {
		ID = 20160533,
		Text = "艾蕾娜向后退了一步撞到了柜子，一罐绿色小罐子滚了出来。",
	},
	[20160534] = {
		ID = 20160534,
		Speaker = "我",
		Text = "这个是……",
	},
	[20160535] = {
		ID = 20160535,
		Text = "我弯腰捡起罐子——正是她刚才倒进鲜奶油里的那罐绿色液体。",
	},
	[20160536] = {
		ID = 20160536,
		Speaker = "艾蕾娜",
		Text = "……",
	},
	[20160538] = {
		ID = 20160538,
	},
	[20160539] = {
		ID = 20160539,
		Text = "是……",
	},
	[20160540] = {
		ID = 20160540,
		Text = "魔女小姐给我的。",
	},
	[20160541] = {
		ID = 20160541,
		Speaker = "艾蕾娜",
		Text = "她说，只要加进船长的食物里，船长就会变得很开心。",
	},
	[20160542] = {
		ID = 20160542,
		Speaker = "我",
		Text = "所以妳把它倒进了鲜奶油里。",
	},
	[20160543] = {
		ID = 20160543,
		Speaker = "艾蕾娜",
		Text = "嗯。",
	},
	[20160544] = {
		ID = 20160544,
		Text = "我打开瓶盖凑近鼻子闻了闻——一股甜腻得不自然的香气直冲脑门。",
	},
	[20160545] = {
		ID = 20160545,
		Speaker = "我",
		Text = "绝对不会错的，这……",
	},
	[20160546] = {
		ID = 20160546,
		Text = "我下半身突发勃起的反应证实了这一切。",
	},
	[20160547] = {
		ID = 20160547,
		Speaker = "我",
		Text = "这根本就是春药。",
	},
	[20160548] = {
		ID = 20160548,
		Speaker = "艾蕾娜",
		Text = "什么是……春药……",
	},
	[20160549] = {
		ID = 20160549,
		Speaker = "我",
		Text = "就是……算了，妳先坐下休息，我去倒杯水给妳。",
	},
	[20160550] = {
		ID = 20160550,
		Speaker = "艾蕾娜",
		Text = "不要走。",
	},
	[20160551] = {
		ID = 20160551,
		Speaker = "我",
		Text = "我只是去厨房那头——",
	},
	[20160552] = {
		ID = 20160552,
		Speaker = "艾蕾娜",
		Text = "不要……我要船长陪……",
	},
	[20160553] = {
		ID = 20160553,
		Text = "她整个人几乎是扑过来的，重心一下子压上我的胸口。",
	},
	[20160554] = {
		ID = 20160554,
		Text = "接着整个人压到了我的身上，把我撞倒在地板上。",
	},
	[20160555] = {
		ID = 20160555,
		Speaker = "我",
		Text = "喂——",
	},
	[20160556] = {
		ID = 20160556,
		Speaker = "艾蕾娜",
		Text = "我……可是……",
	},
	[20160557] = {
		ID = 20160557,
		Speaker = "我",
		Text = "艾蕾娜，冷静点！",
	},
	[20160558] = {
		ID = 20160558,
		Speaker = "艾蕾娜",
		Text = "船长……",
	},
	[20160559] = {
		ID = 20160559,
		Speaker = "我",
		Text = "冷静下来了吗？",
	},
	[20160560] = {
		ID = 20160560,
		Text = "她的呼吸移到我的颈侧，嘴角边缘沿着一丝没能咽下的湿意滑落——",
	},
	[20160561] = {
		ID = 20160561,
		Text = "她真的在流口水，却丝毫不觉得羞耻，只是任由那份湿热贴上我的皮肤。",
	},
	[20160562] = {
		ID = 20160562,
		Text = "下一秒，她的舌尖便顺着颈部，慢慢地舔了上去。",
	},
	[20160563] = {
		ID = 20160563,
		Speaker = "艾蕾娜",
		Text = "不管再怎么任性……船长都会原谅我的……",
	},
	[20160564] = {
		ID = 20160564,
		Speaker = "我",
		Text = "艾蕾娜，等等——",
	},
	[20160565] = {
		ID = 20160565,
		Speaker = "艾蕾娜",
		Text = "等一下也不行。",
	},
	[20160566] = {
		ID = 20160566,
		Speaker = "我",
		Text = "妳知不知道妳现在——",
	},
	[20160567] = {
		ID = 20160567,
		Text = "艾蕾娜用惊人的力气一手压住了我的胸口，另一只手脱下我的衣服。",
	},
	[20160569] = {
		ID = 20160569,
	},
	[20160570] = {
		ID = 20160570,
		Text = "船长的这里……",
	},
	[20160571] = {
		ID = 20160571,
		Text = "明明都变得那么大了……",
	},
	[20160572] = {
		ID = 20160572,
		Speaker = "艾蕾娜",
		Text = "为什么要藏起来呢……",
	},
	[20160573] = {
		ID = 20160573,
		Speaker = "我",
		Text = "艾蕾娜，等你醒来之后一定会羞耻得要死的！",
	},
	[20160574] = {
		ID = 20160574,
		Text = "不管……现在……",
	},
	[20160575] = {
		ID = 20160575,
		Text = "已经除了舒服的事情以外什么都不想思考了……",
	},
	[20160576] = {
		ID = 20160576,
		Text = "船长你看……",
	},
	[20160577] = {
		ID = 20160577,
		Text = "艾蕾娜的小穴……要把船长的肉棒吃掉了喔……",
	},
	[20160578] = {
		ID = 20160578,
		Text = "呜……",
	},
	[20160579] = {
		ID = 20160579,
		Speaker = "艾蕾娜",
		Text = "呜……哈啊啊啊啊……",
	},
	[20160580] = {
		ID = 20160580,
		Text = "插入的瞬间艾蕾娜的里面就瞬间收紧。",
	},
	[20160581] = {
		ID = 20160581,
		Text = "大口大口的喘着气，还流着口水。",
	},
	[20160582] = {
		ID = 20160582,
		Text = "哈……船长……",
	},
	[20160583] = {
		ID = 20160583,
		Text = "船长的……好舒服……",
	},
	[20160584] = {
		ID = 20160584,
		Speaker = "艾蕾娜",
		Text = "好……好大……被撑开了……",
	},
	[20160585] = {
		ID = 20160585,
		Text = "艾蕾娜将我压在地板上，不断的扭着腰。",
	},
	[20160586] = {
		ID = 20160586,
		Text = "那淫糜的模样和平时判若两人。",
	},
	[20160587] = {
		ID = 20160587,
		Speaker = "我",
		Text = "可恶啊，事已至此，就不要怪我了。",
	},
	[20160588] = {
		ID = 20160588,
		Speaker = "我",
		Text = "抱歉了，艾蕾娜。",
	},
	[20160589] = {
		ID = 20160589,
		Text = "我的双手扶住艾蕾娜的腰，主动加速了抽插。",
	},
	[20160590] = {
		ID = 20160590,
		Text = "哈啊……船长……",
	},
	[20160591] = {
		ID = 20160591,
		Text = "船长……好激烈……",
	},
	[20160592] = {
		ID = 20160592,
		Text = "好幸福……",
	},
	[20160593] = {
		ID = 20160593,
		Speaker = "艾蕾娜",
		Text = "船长……这样舒服吗？",
	},
	[20160594] = {
		ID = 20160594,
		Speaker = "我",
		Text = "艾蕾娜，已经快不行了……",
	},
	[20160595] = {
		ID = 20160595,
		Text = "船长……我也要……",
	},
	[20160596] = {
		ID = 20160596,
		Text = "呜……船长……哈啊啊……",
	},
	[20160597] = {
		ID = 20160597,
		Text = "船长的……全部在里面满满的射出来了……",
	},
	[20160598] = {
		ID = 20160598,
		Text = "好喜欢好喜欢好喜欢船长……",
	},
	[20160599] = {
		ID = 20160599,
		Text = "里面被船长标记的满满的……还想要更多……",
	},
	[20160600] = {
		ID = 20160600,
		Speaker = "艾蕾娜",
		Text = "哈……呜……",
	},
	[20160602] = {
		ID = 20160602,
	},
	[20160603] = {
		ID = 20160603,
		Text = "艾蕾娜的腰向上缓缓拔出，双腿不断地发抖。",
	},
	[20160604] = {
		ID = 20160604,
		Text = "接着直接向前倒在我身上失去了意识。",
	},
	[20160605] = {
		ID = 20160605,
		Speaker = "我",
		Text = "做爱的时候话很多这点还是老样子呢……",
	},
	[20160606] = {
		ID = 20160606,
		Speaker = "我",
		Text = "这里……得好好收拾一下了。",
	},
	[20160607] = {
		ID = 20160607,
		Text = "隔天被艾蕾娜追着道歉了一整天。",
	},
	[20160609] = {
		ID = 20160609,
	},
	[20160610] = {
		ID = 20160610,
		Text = "帮忙黛莉亚修船后，忙了一个上午，使我的肚子早早开始抗议。",
	},
	[20160611] = {
		ID = 20160611,
		Text = "转进走廊深处时，一阵混着奶油与麦香的暖烘烘气味扑面而来。",
	},
	[20160612] = {
		ID = 20160612,
		Text = "使我的脚步不由自主地被那股香味拽了过去。",
	},
	[20160613] = {
		ID = 20160613,
		Text = "转角另一头，艾蕾娜抱着一个超大的柳条篮子。",
	},
	[20160614] = {
		ID = 20160614,
		Text = "篮口冒出白色热气，兜帽边缘还沾着几点面粉，整个人几乎要被篮子挡住脸。",
	},
	[20160615] = {
		ID = 20160615,
		Speaker = "我",
		Text = "这味道……该不会是我饿过头产生的幻觉吧？",
	},
	[20160616] = {
		ID = 20160616,
		Text = "船长，早安。",
	},
	[20160617] = {
		ID = 20160617,
		Text = "这不是幻觉，是面包。",
	},
	[20160618] = {
		ID = 20160618,
		Speaker = "艾蕾娜",
		Text = "刚出炉、热腾腾。",
	},
	[20160619] = {
		ID = 20160619,
		Speaker = "我",
		Text = "等等，所以妳现在……会烤面包了？",
	},
	[20160620] = {
		ID = 20160620,
		Speaker = "艾蕾娜",
		Text = "会。",
	},
	[20160621] = {
		ID = 20160621,
		Speaker = "我",
		Text = "什么时候学的？我怎么都不知道有这回事。",
	},
	[20160622] = {
		ID = 20160622,
		Text = "伊丝娜小姐帮我在厨房整理出一块地方，专门用来烤面包的。",
	},
	[20160623] = {
		ID = 20160623,
		Speaker = "艾蕾娜",
		Text = "她说反正厨房角落空着也是空着。",
	},
	[20160624] = {
		ID = 20160624,
		Speaker = "我",
		Text = "这味道真的很犯规，妳都烤些什么？",
	},
	[20160625] = {
		ID = 20160625,
		Speaker = "艾蕾娜",
		Text = "这是奶油卷。",
	},
	[20160627] = {
		ID = 20160627,
	},
	[20160628] = {
		ID = 20160628,
		Text = "面团整齐排在铁盘上，盖上湿布放到炉边发酵。",
	},
	[20160629] = {
		ID = 20160629,
		Speaker = "我",
		Text = "那这段时间呢？我们就干坐在这里，看它慢慢膨胀？",
	},
	[20160630] = {
		ID = 20160630,
		Text = "不用干坐，我们还有事可以做。",
	},
	[20160631] = {
		ID = 20160631,
		Speaker = "艾蕾娜",
		Text = "像是做鲜奶油。",
	},
	[20160632] = {
		ID = 20160632,
		Speaker = "我",
		Text = "喔？配着面包吃？",
	},
	[20160633] = {
		ID = 20160633,
		Speaker = "我",
		Text = "妳做这种事的时候，感觉特别有自信呢。",
	},
	[20160634] = {
		ID = 20160634,
		Text = "因为只要照顺序做，就会成功。",
	},
	[20160635] = {
		ID = 20160635,
		Speaker = "艾蕾娜",
		Text = "船长喜欢怎么样的面包呢。",
	},
	[20160637] = {
		ID = 20160637,
	},
	[20160638] = {
		ID = 20160638,
		Text = "厨房地板还留着一大片奶油渍，我蹲下身擦流理台边缘。",
	},
	[20160639] = {
		ID = 20160639,
		Text = "眼角余光瞄向艾蕾娜，她正低头把打翻的奶油碗捡起来。",
	},
	[20160640] = {
		ID = 20160640,
		Speaker = "我",
		Text = "这下好了，厨房里多了一层鲜奶油地板，踩下去说不定会滑倒。",
	},
	[20160641] = {
		ID = 20160641,
		Speaker = "艾蕾娜",
		Text = "……",
	},
	[20160642] = {
		ID = 20160642,
		Speaker = "我",
		Text = "艾蕾娜？",
	},
	[20160643] = {
		ID = 20160643,
		Speaker = "艾蕾娜",
		Text = "……",
	},
	[20160644] = {
		ID = 20160644,
		Text = "她把碗放在一旁，转身面向水槽开始冲洗抹布，背始终对着我。",
	},
	[20160645] = {
		ID = 20160645,
		Text = "原本会回头看我一眼的艾蕾娜，这次却连一次也没有。",
	},
	[20160646] = {
		ID = 20160646,
		Text = "只是低着头，一言不发地擦着流理台。",
	},
	[20160647] = {
		ID = 20160647,
	},
	[30180200] = {
		ID = 30180200,
		Speaker = "凯伊",
		Text = "……兄弟！是老子！",
	},
	[20070001] = {
		ID = 20070001,
	},
	[20070002] = {
		ID = 20070002,
		Speaker = "勒瓦杜兰",
		Text = "……可爱？",
	},
	[20070003] = {
		ID = 20070003,
		Speaker = "我",
		Text = "对，可爱一点，或是像平常的那套衣服就可以了。",
	},
	[20070004] = {
		ID = 20070004,
		Speaker = "我",
		Text = "平常的这套就很不错了，我很喜欢喔。",
	},
	[20070005] = {
		ID = 20070005,
		Speaker = "勒瓦杜兰",
		Text = "……油嘴滑舌的人类。",
	},
	[20070006] = {
		ID = 20070006,
		Speaker = "我",
		Text = "所以呢，决定要穿哪件了吗？",
	},
	[20070007] = {
		ID = 20070007,
		Speaker = "勒瓦杜兰",
		Text = "……这是本王的事，你可以退下了。",
	},
	[20070008] = {
		ID = 20070008,
		Speaker = "我",
		Text = "好好好，女王陛下的秘密武器我就不打听了。",
	},
	[20070009] = {
		ID = 20070009,
		Speaker = "我",
		Text = "早点睡吧，明天集合时间可别迟到——是妳自己订的。",
	},
	[20070010] = {
		ID = 20070010,
		Speaker = "勒瓦杜兰",
		Text = "本王怎么可能迟到，人类，你关心好自己吧？",
	},
	[20070011] = {
		ID = 20070011,
		Speaker = "我",
		Text = "是——是——女王陛下，晚安了。",
	},
	[20070012] = {
		ID = 20070012,
		Text = "门关上以后，勒瓦杜兰趴在床上。",
	},
	[20070013] = {
		ID = 20070013,
		Text = "并将床上的企鹅抱枕压在身下。",
	},
	[20070014] = {
		ID = 20070014,
		Speaker = "勒瓦杜兰",
		Text = "最可爱的……吗？",
	},
	[20070015] = {
		ID = 20070015,
	},
	[20070016] = {
		ID = 20070016,
	},
	[20070017] = {
		ID = 20070017,
		Text = "动物园大门外排着零星的游客，我抱着两杯刚买的热饮。",
	},
	[20070018] = {
		ID = 20070018,
		Text = "四处张望着有没有尖耳白发、气场张扬的身影。",
	},
	[20070019] = {
		ID = 20070019,
		Text = "结果什么女王架势都没看到，只有——",
	},
	[20070020] = {
		ID = 20070020,
		Text = "大门正中央一只巨大的、黑白两色的布偶装，安安静静地站着。",
	},
	[20070021] = {
		ID = 20070021,
		Text = "两只短短的翅膀交叠在身前，姿势标准得不像话。",
	},
	[20070022] = {
		ID = 20070022,
		Speaker = "我",
		Text = "……不好意思，请问有没有看到一位长得很凶的小姐？",
	},
	[20070023] = {
		ID = 20070023,
		Text = "企鹅的嘴巴缓缓打开——露出里面一张熟悉的、绷着的脸。",
	},
	[20070024] = {
		ID = 20070024,
		Speaker = "勒瓦杜兰",
		Text = "……人类，你说谁很凶啊？",
	},
	[20070025] = {
		ID = 20070025,
		Speaker = "我",
		Text = "妳对「可爱一点」的理解有点太过于极端了。",
	},
	[20070026] = {
		ID = 20070026,
		Speaker = "勒瓦杜兰",
		Text = "哼，不愧是庶民的品味，说到可爱，那答案只能是这样了。",
	},
	[20070027] = {
		ID = 20070027,
		Speaker = "勒瓦杜兰",
		Text = "你敢笑，本王就让企鹅的嘴巴，咬住你的头。",
	},
	[20070028] = {
		ID = 20070028,
		Speaker = "我",
		Text = "不不不，我是真心觉得很可爱喔。",
	},
	[20070029] = {
		ID = 20070029,
		Speaker = "勒瓦杜兰",
		Text = "嗯哼♪~",
	},
	[20070030] = {
		ID = 20070030,
		Speaker = "我",
		Text = "我们走吧——妳想先看什么动物？",
	},
	[20070031] = {
		ID = 20070031,
		Speaker = "勒瓦杜兰",
		Text = "嗯～我想想。",
	},
	[20070032] = {
		ID = 20070032,
		Speaker = "勒瓦杜兰",
		Text = "给本王个惊喜，要出奇不意。",
	},
	[20070033] = {
		ID = 20070033,
		Speaker = "勒瓦杜兰",
		Text = "我可没有那么容易被取悦。",
	},
	[20070034] = {
		ID = 20070034,
		Speaker = "我",
		Text = "那就交给我，走吧。",
	},
	[20070035] = {
		ID = 20070035,
	},
	[20070036] = {
		ID = 20070036,
	},
	[20070037] = {
		ID = 20070037,
		Speaker = "勒瓦杜兰",
		Text = "本王可是很挑剔的，肯定是喜欢才有可能被本王穿在身上。",
	},
	[20070038] = {
		ID = 20070038,
		Speaker = "勒瓦杜兰",
		Text = "本王不喜欢的东西，都已经冻成冰块了。",
	},
	[20070039] = {
		ID = 20070039,
		Speaker = "我",
		Text = "那就没问题了，不管穿哪套都很好不是吗？",
	},
	[20070040] = {
		ID = 20070040,
		Speaker = "勒瓦杜兰",
		Text = "问了等于没问，真是没用的家臣。",
	},
	[20070041] = {
		ID = 20070041,
		Speaker = "我",
		Text = "所以呢，决定要穿哪件了吗？",
	},
	[20070042] = {
		ID = 20070042,
		Speaker = "勒瓦杜兰",
		Text = "……这是本王的事，你可以退下了。",
	},
	[20070043] = {
		ID = 20070043,
		Speaker = "我",
		Text = "好好好，女王陛下的秘密武器我就不打听了。",
	},
	[20070044] = {
		ID = 20070044,
		Speaker = "我",
		Text = "早点睡吧，明天集合时间可别迟到——是妳自己订的。",
	},
	[20070045] = {
		ID = 20070045,
		Speaker = "勒瓦杜兰",
		Text = "本王怎么可能迟到，人类，你关心好自己吧？",
	},
	[20070046] = {
		ID = 20070046,
		Speaker = "我",
		Text = "是——是——女王陛下，晚安了。",
	},
	[20070047] = {
		ID = 20070047,
		Text = "门关上以后，勒瓦杜兰趴在床上。",
	},
	[20070048] = {
		ID = 20070048,
		Text = "并将床上的企鹅抱枕压在身下。",
	},
	[20070049] = {
