	[20070107] = {
		ID = 20070107,
		Speaker = "勒瓦杜兰",
		Text = "……猴子。真是毫无想像力的选择。",
	},
	[20070108] = {
		ID = 20070108,
		Speaker = "勒瓦杜兰",
		Text = "……它们在看我。",
	},
	[20070109] = {
		ID = 20070109,
		Speaker = "我",
		Text = "很正常啊，妳今天穿得比它们还显眼。",
	},
	[20070110] = {
		ID = 20070110,
		Speaker = "勒瓦杜兰",
		Text = "……它们的眼神，跟你一模一样。",
	},
	[20070111] = {
		ID = 20070111,
		Speaker = "我",
		Text = "嗯？",
	},
	[20070112] = {
		ID = 20070112,
		Speaker = "勒瓦杜兰",
		Text = "这些应该是你的亲戚吧。",
	},
	[20070113] = {
		ID = 20070113,
		Speaker = "勒瓦杜兰",
		Text = "从刚才开始，就一直用那种无礼的视线打量我，让人很不悦。",
	},
	[20070114] = {
		ID = 20070114,
		Speaker = "我",
		Text = "我跟猴子哪来的血缘关系……",
	},
	[20070115] = {
		ID = 20070115,
		Speaker = "勒瓦杜兰",
		Text = "从演化上来说，关系匪浅。",
	},
	[20070116] = {
		ID = 20070116,
		Speaker = "勒瓦杜兰",
		Text = "这可是你们船上的蓝毛ㄚ头亲口告诉我的人类知识。",
	},
	[20070117] = {
		ID = 20070117,
		Speaker = "勒瓦杜兰",
		Text = "而且，那只胖的一直在啃东西，姿态毫无气质可言。",
	},
	[20070118] = {
		ID = 20070118,
		Speaker = "我",
		Text = "它在吃花生而已，别这样嫌弃人家。",
	},
	[20070119] = {
		ID = 20070119,
		Speaker = "勒瓦杜兰",
		Text = "……那边那只，它在荡绳子。",
	},
	[20070120] = {
		ID = 20070120,
		Speaker = "我",
		Text = "感觉妳看得很高兴？",
	},
	[20070121] = {
		ID = 20070121,
		Speaker = "勒瓦杜兰",
		Text = "……闭嘴，这只是礼貌性的关注。",
	},
	[20070122] = {
		ID = 20070122,
		Speaker = "勒瓦杜兰",
		Text = "下一个地方，走快一点。",
	},
	[20070123] = {
		ID = 20070123,
		Speaker = "我",
		Text = "喂喂，妳知道要往哪走吗？",
	},
	[20070124] = {
		ID = 20070124,
	},
	[20070125] = {
		ID = 20070125,
	},
	[20070126] = {
		ID = 20070126,
		Text = "我笑着调整方向，带她绕过一片人工瀑布，走进了阴凉的水生馆。",
	},
	[20070127] = {
		ID = 20070127,
		Text = "深蓝色的光线洒落在她的脸上。",
	},
	[20070128] = {
		ID = 20070128,
		Text = "让她整个人看起来像是浸在冰层底下的精灵。",
	},
	[20070129] = {
		ID = 20070129,
		Speaker = "我",
		Text = "这里是水生馆，我们换个安静点的地方。",
	},
	[20070130] = {
		ID = 20070130,
		Speaker = "勒瓦杜兰",
		Text = "……很凉，比较适合我。",
	},
	[20070131] = {
		ID = 20070131,
		Speaker = "勒瓦杜兰",
		Text = "不过就是鱼而已，这种生物餐桌上天天都有。",
	},
	[20070132] = {
		ID = 20070132,
		Speaker = "我",
		Text = "妳仔细看，它们是特别的鱼。",
	},
	[20070133] = {
		ID = 20070133,
		Speaker = "勒瓦杜兰",
		Text = "特别的……这是……蓝色的鱼？",
	},
	[20070134] = {
		ID = 20070134,
		Speaker = "勒瓦杜兰",
		Text = "还有橘黑相间的怪鱼？",
	},
	[20070135] = {
		ID = 20070135,
		Speaker = "勒瓦杜兰",
		Text = "看起来像是被染色过，有毒的样子。",
	},
	[20070136] = {
		ID = 20070136,
		Speaker = "我",
		Text = "这些是热带的鱼，冰雪星球可看不到。",
	},
	[20070137] = {
		ID = 20070137,
		Speaker = "勒瓦杜兰",
		Text = "本王的领土不需要这些五颜六色、傻里傻气的东西。",
	},
	[20070138] = {
		ID = 20070138,
		Text = "她说着，脸不自觉地往前凑近，额头几乎要贴上冰凉的玻璃缸壁。",
	},
	[20070139] = {
		ID = 20070139,
		Text = "眼神专注地追着一尾色彩斑斓的小丑鱼游动的轨迹。",
	},
	[20070140] = {
		ID = 20070140,
		Speaker = "我",
		Text = "喂，妳的鼻子要压扁了。",
	},
	[20070141] = {
		ID = 20070141,
		Speaker = "勒瓦杜兰",
		Text = "……别吵，它在跟本王打招呼。",
	},
	[20070142] = {
		ID = 20070142,
		Speaker = "我",
		Text = "没什么，就是觉得……妳今天很可爱。",
	},
	[20070143] = {
		ID = 20070143,
		Speaker = "勒瓦杜兰",
		Text = "……油嘴滑舌的人类，谁相信你这种话术。",
	},
	[20070144] = {
		ID = 20070144,
		Speaker = "我",
		Text = "妳耳朵都红了。",
	},
	[20070145] = {
		ID = 20070145,
		Speaker = "勒瓦杜兰",
		Text = "……那是灯光的关系，水族馆的灯光，本来就偏红。",
	},
	[20070146] = {
		ID = 20070146,
		Text = "我没有戳破这个显而易见的谎言，只是笑着任由她扯开话题。",
	},
	[20070147] = {
		ID = 20070147,
		Text = "她继续盯着水缸里悠游的鱼群不放。",
	},
	[20070148] = {
		ID = 20070148,
		Text = "这一刻，动物园外头的世界仿佛都被隔绝在玻璃之外。",
	},
	[20070149] = {
		ID = 20070149,
		Text = "只剩下我们两个人，安静地待在这片蓝色的光里。",
	},
	[20070150] = {
		ID = 20070150,
		Speaker = "勒瓦杜兰",
		Text = "这个地方，应该有企鹅吧？本王想要看企鹅。",
	},
	[20070151] = {
		ID = 20070151,
		Speaker = "我",
		Text = "遵命，女王陛下～",
	},
	[20070152] = {
		ID = 20070152,
	},
	[20070153] = {
		ID = 20070153,
	},
	[20070154] = {
		ID = 20070154,
		Speaker = "勒瓦杜兰",
		Text = "这个生物是……",
	},
	[20070155] = {
		ID = 20070155,
		Speaker = "勒瓦杜兰",
		Text = "难道是那位长角的龙族女孩的幼年体？",
	},
	[20070156] = {
		ID = 20070156,
		Speaker = "我",
		Text = "这是变色龙……",
	},
	[20070157] = {
		ID = 20070157,
		Speaker = "勒瓦杜兰",
		Text = "确实很像龙族……但要如何长成少女的样子？",
	},
	[20070158] = {
		ID = 20070158,
		Speaker = "我",
		Text = "……不，我想事情不是这样的？",
	},
	[20070159] = {
		ID = 20070159,
		Speaker = "勒瓦杜兰",
		Text = "那边那个生物又是什么？",
	},
	[20070160] = {
		ID = 20070160,
		Speaker = "我",
		Text = "这是角蛙。",
	},
	[20070161] = {
		ID = 20070161,
		Speaker = "勒瓦杜兰",
		Text = "表情看起来很愤怒，是你说的那位学姊吧？",
	},
	[20070162] = {
		ID = 20070162,
		Speaker = "勒瓦杜兰",
		Text = "那边那个卷起来的……是西西雅吧？",
	},
	[20070163] = {
		ID = 20070163,
		Speaker = "我",
		Text = "那是缩成一团的球蟒……",
	},
	[20070164] = {
		ID = 20070164,
		Speaker = "勒瓦杜兰",
		Text = "这个很像那个工具袋女孩。",
	},
	[20070165] = {
		ID = 20070165,
		Speaker = "我",
		Text = "这是负鼠……为什么会像黛莉雅？",
	},
	[20070166] = {
		ID = 20070166,
		Speaker = "勒瓦杜兰",
		Text = "随身带着一个袋子，什么都想装进去，还不够像吗？",
	},
	[20070167] = {
		ID = 20070167,
		Speaker = "我",
		Text = "我竟然无法反驳……",
	},
	[20070168] = {
		ID = 20070168,
		Speaker = "勒瓦杜兰",
		Text = "意外的挺有趣的，这坨干燥生物。",
	},
	[20070169] = {
		ID = 20070169,
		Speaker = "我",
		Text = "感觉妳一下子得罪了非常多人。",
	},
	[20070170] = {
		ID = 20070170,
		Speaker = "勒瓦杜兰",
		Text = "得罪他人只是统治者的日常工作罢了。",
	},
	[20070171] = {
		ID = 20070171,
		Speaker = "勒瓦杜兰",
		Text = "下一个地方，走快一点。",
	},
	[20070172] = {
		ID = 20070172,
		Speaker = "我",
		Text = "喂喂，妳知道要往哪走吗？",
	},
	[20070173] = {
		ID = 20070173,
	},
	[20070174] = {
		ID = 20070174,
	},
	[20070175] = {
		ID = 20070175,
		Text = "我笑着调整方向，带她绕过一片人工瀑布，走进了阴凉的水生馆。",
	},
	[20070176] = {
		ID = 20070176,
		Text = "深蓝色的光线洒落在她的脸上。",
	},
	[20070177] = {
		ID = 20070177,
		Text = "让她整个人看起来像是浸在冰层底下的精灵。",
	},
	[20070178] = {
		ID = 20070178,
		Speaker = "我",
		Text = "这里是水生馆，我们换个安静点的地方。",
	},
	[20070179] = {
		ID = 20070179,
		Speaker = "勒瓦杜兰",
		Text = "……很凉，比较适合我。",
	},
	[20070180] = {
		ID = 20070180,
		Speaker = "勒瓦杜兰",
		Text = "不过就是鱼而已，这种生物餐桌上天天都有。",
	},
	[20070181] = {
		ID = 20070181,
		Speaker = "我",
		Text = "妳仔细看，它们是特别的鱼。",
	},
	[20070182] = {
		ID = 20070182,
		Speaker = "勒瓦杜兰",
		Text = "特别的……这是……蓝色的鱼？",
	},
	[20070183] = {
		ID = 20070183,
		Speaker = "勒瓦杜兰",
		Text = "还有橘黑相间的怪鱼？",
	},
	[20070184] = {
		ID = 20070184,
		Speaker = "勒瓦杜兰",
		Text = "看起来像是被染色过，有毒的样子。",
	},
	[20070185] = {
		ID = 20070185,
		Speaker = "我",
		Text = "这些是热带的鱼，冰雪星球可看不到。",
	},
	[20070186] = {
		ID = 20070186,
		Speaker = "勒瓦杜兰",
		Text = "本王的领土不需要这些五颜六色、傻里傻气的东西。",
	},
	[20070187] = {
		ID = 20070187,
		Text = "她说着，脸不自觉地往前凑近，额头几乎要贴上冰凉的玻璃缸壁。",
	},
	[20070188] = {
		ID = 20070188,
		Text = "眼神专注地追着一尾色彩斑斓的小丑鱼游动的轨迹。",
	},
	[20070189] = {
		ID = 20070189,
		Speaker = "我",
		Text = "喂，妳的鼻子要压扁了。",
	},
	[20070190] = {
		ID = 20070190,
		Speaker = "勒瓦杜兰",
		Text = "……别吵，它在跟本王打招呼。",
	},
	[20070191] = {
		ID = 20070191,
		Speaker = "我",
		Text = "没什么，就是觉得……妳今天很可爱。",
	},
	[20070192] = {
		ID = 20070192,
		Speaker = "勒瓦杜兰",
		Text = "……油嘴滑舌的人类，谁相信你这种话术。",
	},
	[20070193] = {
		ID = 20070193,
		Speaker = "我",
		Text = "妳耳朵都红了。",
	},
	[20070194] = {
		ID = 20070194,
		Speaker = "勒瓦杜兰",
		Text = "……那是灯光的关系，水族馆的灯光，本来就偏红。",
	},
	[20070195] = {
		ID = 20070195,
		Text = "我没有戳破这个显而易见的谎言，只是笑着任由她扯开话题。",
	},
	[20070196] = {
		ID = 20070196,
		Text = "她继续盯着水缸里悠游的鱼群不放。",
	},
	[20070197] = {
		ID = 20070197,
		Text = "这一刻，动物园外头的世界仿佛都被隔绝在玻璃之外。",
	},
	[20070198] = {
		ID = 20070198,
		Text = "只剩下我们两个人，安静地待在这片蓝色的光里。",
	},
	[20070199] = {
		ID = 20070199,
		Speaker = "勒瓦杜兰",
		Text = "这个地方，应该有企鹅吧？本王想要看企鹅。",
	},
	[20070200] = {
		ID = 20070200,
		Speaker = "我",
		Text = "遵命，女王陛下～",
	},
	[20070201] = {
		ID = 20070201,
	},
	[20070202] = {
		ID = 20070202,
	},
	[20070203] = {
		ID = 20070203,
		Speaker = "勒瓦杜兰",
		Text = "这些生物蛮漂亮的。",
	},
	[20070204] = {
		ID = 20070204,
		Speaker = "勒瓦杜兰",
		Text = "不过翅膀倒是有点眼熟。",
	},
	[20070205] = {
		ID = 20070205,
		Speaker = "我",
		Text = "确实是，和妳一样都是蝴蝶翅膀。",
	},
	[20070206] = {
		ID = 20070206,
		Speaker = "勒瓦杜兰",
		Text = "……蝴蝶？听起来一点都不高贵。",
	},
	[20070207] = {
		ID = 20070207,
		Speaker = "我",
		Text = "嗯？",
	},
	[20070208] = {
		ID = 20070208,
		Speaker = "勒瓦杜兰",
		Text = "本王的翅膀可是妖精的翅膀、女神的翅膀。",
	},
	[20070209] = {
		ID = 20070209,
		Speaker = "勒瓦杜兰",
		Text = "哪是这些……这些……",
	},
	[20070210] = {
		ID = 20070210,
		Speaker = "勒瓦杜兰",
		Text = "用吸管吃饭的……",
	},
	[20070211] = {
		ID = 20070211,
		Speaker = "勒瓦杜兰",
		Text = "飞天蜘蛛能比拟的。",
	},
	[20070212] = {
		ID = 20070212,
		Speaker = "我",
		Text = "说到蜘蛛，妳看头上，好大的网。",
	},
	[20070213] = {
		ID = 20070213,
		Text = "一瞬间勒瓦杜兰便呆站在原地，仿佛石化一般。",
	},
	[20070214] = {
		ID = 20070214,
		Speaker = "我",
		Text = "？",
	},
	[20070215] = {
		ID = 20070215,
		Text = "我顺着她的视线往上看。",
	},
	[20070216] = {
		ID = 20070216,
		Text = "一只半公尺宽的蜘蛛正慢吞吞地从网中央爬过。",
	},
	[20070217] = {
		ID = 20070217,
		Speaker = "我",
		Text = "妳还好吗？",
	},
	[20070218] = {
		ID = 20070218,
		Speaker = "勒瓦杜兰",
		Text = "咿……",
	},
	[20070219] = {
		ID = 20070219,
		Speaker = "勒瓦杜兰",
		Text = "咿……咿啊啊啊啊啊啊！",
	},
	[20070220] = {
		ID = 20070220,
		Speaker = "我",
		Text = "等等我！",
	},
	[20070221] = {
		ID = 20070221,
		Text = "巨大的企鹅用相当离谱的速度冲出了昆虫馆。",
	},
	[20070222] = {
		ID = 20070222,
	},
	[20070223] = {
		ID = 20070223,
	},
	[20070224] = {
		ID = 20070224,
		Text = "我一路追出去，好不容易才在转角追上勒瓦杜兰。",
	},
	[20070225] = {
