	},
	[20070253] = {
		ID = 20070253,
	},
	[20070254] = {
		ID = 20070254,
		Speaker = "勒瓦杜兰",
		Text = "……为什么突然这么问。",
	},
	[20070255] = {
		ID = 20070255,
		Speaker = "我",
		Text = "没有为什么，就想知道嘛。",
	},
	[20070256] = {
		ID = 20070256,
		Speaker = "勒瓦杜兰",
		Text = "就庶民的兴趣来说，勉勉强强吧。",
	},
	[20070257] = {
		ID = 20070257,
		Speaker = "我",
		Text = "是吗，那就好。",
	},
	[20070258] = {
		ID = 20070258,
		Speaker = "我",
		Text = "妳今天，走路都比平常都更轻快。",
	},
	[20070259] = {
		ID = 20070259,
		Speaker = "勒瓦杜兰",
		Text = "……你在笑什么。",
	},
	[20070260] = {
		ID = 20070260,
		Speaker = "我",
		Text = "没事，只是觉得妳今天的妳，看起来特别不一样。",
	},
	[20070261] = {
		ID = 20070261,
		Speaker = "勒瓦杜兰",
		Text = "哪里不一样。",
	},
	[20070262] = {
		ID = 20070262,
		Speaker = "勒瓦杜兰",
		Text = "……本王平时走得很慢吗？",
	},
	[20070263] = {
		ID = 20070263,
		Speaker = "我",
		Text = "不是，是今天看起来特别想往下一个地方走。",
	},
	[20070264] = {
		ID = 20070264,
		Speaker = "勒瓦杜兰",
		Text = "……",
	},
	[20070265] = {
		ID = 20070265,
		Speaker = "勒瓦杜兰",
		Text = "……人类，你为什么，总喜欢带着别人到处走。",
	},
	[20070266] = {
		ID = 20070266,
		Speaker = "我",
		Text = "两个人看到有趣的东西，才有意义嘛。",
	},
	[20070267] = {
		ID = 20070267,
		Speaker = "我",
		Text = "这些事情，未来都会变成我们两个的回忆。",
	},
	[20070268] = {
		ID = 20070268,
		Speaker = "勒瓦杜兰",
		Text = "……是吗？",
	},
	[20070269] = {
		ID = 20070269,
		Speaker = "勒瓦杜兰",
		Text = "……回忆？",
	},
	[20070270] = {
		ID = 20070270,
		Speaker = "勒瓦杜兰",
		Text = "那，下次，也要再来这种地方。",
	},
	[20070271] = {
		ID = 20070271,
		Speaker = "勒瓦杜兰",
		Text = "……只是提议而已，不是命令。",
	},
	[20070272] = {
		ID = 20070272,
		Speaker = "我",
		Text = "好啊，那就说定了。",
	},
	[20070273] = {
		ID = 20070273,
		Speaker = "勒瓦杜兰",
		Text = "人类——",
	},
	[20070274] = {
		ID = 20070274,
		Speaker = "勒瓦杜兰",
		Text = "……陪我去买那个。",
	},
	[20070275] = {
		ID = 20070275,
		Speaker = "我",
		Text = "那个是哪个？",
	},
	[20070276] = {
		ID = 20070276,
		Speaker = "勒瓦杜兰",
		Text = "本王……我，想吃那个，五彩缤纷的调味雪。",
	},
	[20070277] = {
		ID = 20070277,
		Text = "勒瓦杜兰朝我伸出手，静静地等待我的回覆。",
	},
	[20070278] = {
		ID = 20070278,
		Speaker = "我",
		Text = "嗯，我们走吧。",
	},
	[20070279] = {
		ID = 20070279,
	},
	[20070280] = {
		ID = 20070280,
	},
	[20070281] = {
		ID = 20070281,
		Speaker = "勒瓦杜兰",
		Text = "……那种庶民的体验，有什么意义。",
	},
	[20070282] = {
		ID = 20070282,
		Speaker = "我",
		Text = "妳的脚已经往那边走了。",
	},
	[20070283] = {
		ID = 20070283,
		Speaker = "勒瓦杜兰",
		Text = "……闭嘴。",
	},
	[20070284] = {
		ID = 20070284,
		Text = "几只幼年企鹅摇摇摆摆凑到她脚边。",
	},
	[20070285] = {
		ID = 20070285,
		Text = "她蹲下身，指尖小心翼翼碰了碰其中一只。",
	},
	[20070286] = {
		ID = 20070286,
		Speaker = "勒瓦杜兰",
		Text = "唔！",
	},
	[20070287] = {
		ID = 20070287,
		Speaker = "勒瓦杜兰",
		Text = "……它们，很轻。",
	},
	[20070288] = {
		ID = 20070288,
		Speaker = "我",
		Text = "当然轻啊，它们还是宝宝。",
	},
	[20070289] = {
		ID = 20070289,
		Speaker = "勒瓦杜兰",
		Text = "……那，我可以抱一下吗？",
	},
	[20070290] = {
		ID = 20070290,
		Speaker = "我",
		Text = "妳都已经蹲下去了才问。",
	},
	[20070291] = {
		ID = 20070291,
		Speaker = "勒瓦杜兰",
		Text = "……闭嘴，人类。",
	},
	[20070292] = {
		ID = 20070292,
		Speaker = "勒瓦杜兰",
		Text = "……好，小心点。",
	},
	[20070293] = {
		ID = 20070293,
		Speaker = "勒瓦杜兰",
		Text = "……摸起来，比想像中还要毛茸茸的。",
	},
	[20070294] = {
		ID = 20070294,
		Speaker = "我",
		Text = "妳的表情也变得毛茸茸的了。",
	},
	[20070295] = {
		ID = 20070295,
		Speaker = "勒瓦杜兰",
		Text = "……本王的表情，一直都是这样。",
	},
	[20070296] = {
		ID = 20070296,
		Speaker = "勒瓦杜兰",
		Text = "……你，也想摸吗？",
	},
	[20070297] = {
		ID = 20070297,
		Speaker = "我",
		Text = "比起企鹅，我比较想多看妳这个表情几眼。",
	},
	[20070298] = {
		ID = 20070298,
		Speaker = "勒瓦杜兰",
		Text = "……你在说什么。",
	},
	[20070299] = {
		ID = 20070299,
		Text = "怀里的企鹅宝宝忽然拱动身子，短短的翅膀拍了两下。",
	},
	[20070300] = {
		ID = 20070300,
		Text = "接着把整张脸埋进她的下巴底下磨蹭，下一秒——",
	},
	[20070301] = {
		ID = 20070301,
		Text = "她自己也低下头，跟企鹅宝宝脸贴着脸，一下一下蹭来蹭去。",
	},
	[20070302] = {
		ID = 20070302,
		Text = "我愣愣地看着眼前这一幕——那个总是端坐在冰晶王座上。",
	},
	[20070303] = {
		ID = 20070303,
		Text = "连笑都吝啬施舍的女王，此刻正跟一只企鹅宝宝脸贴着脸蹭得浑然忘我。",
	},
	[20070304] = {
		ID = 20070304,
		Speaker = "我",
		Text = "妳真的很喜欢它耶。",
	},
	[20070305] = {
		ID = 20070305,
		Text = "她像是被按下暂停键一样猛地僵住，脸颊以肉眼可见的速度红了起来，",
	},
	[20070306] = {
		ID = 20070306,
		Text = "动作快得几乎能听见咔的一声，把企鹅宝宝重新放回工作人员手中，抬起下巴。",
	},
	[20070307] = {
		ID = 20070307,
		Speaker = "勒瓦杜兰",
		Text = "……你有什么意见吗？庶民？",
	},
	[20070308] = {
		ID = 20070308,
		Speaker = "我",
		Text = "我看到的可清楚了。",
	},
	[20070309] = {
		ID = 20070309,
		Speaker = "勒瓦杜兰",
		Text = "……你的眼睛，最近是不是该去看看了。",
	},
	[20070310] = {
		ID = 20070310,
		Speaker = "我",
		Text = "我的眼睛好得很，妳脸更红了。",
