		Text = "广播里传来闭馆前要把动物送回去休息的通知，脚步声从走道那头渐渐靠近。",
	},
	[20070418] = {
		ID = 20070418,
		Speaker = "我",
		Text = "工作人员要来把企鹅带回去了，我们也先出去吧。",
	},
	[20070419] = {
		ID = 20070419,
		Speaker = "勒瓦杜兰",
		Text = "……再一下下就好。",
	},
	[20070420] = {
		ID = 20070420,
		Speaker = "我",
		Text = "妳听，脚步声越来越近了哦。",
	},
	[20070421] = {
		ID = 20070421,
		Speaker = "勒瓦杜兰",
		Text = "……好啦，好啦。",
	},
	[20070422] = {
		ID = 20070422,
		Text = "她深吸一口气，才终于不情愿地把幼年企鹅放回冰上。",
	},
	[20070423] = {
		ID = 20070423,
		Speaker = "我",
		Text = "乖。",
	},
	[20070424] = {
		ID = 20070424,
		Speaker = "勒瓦杜兰",
		Text = "……少用这种口气跟我说话。",
	},
	[20070425] = {
		ID = 20070425,
		Text = "她起身时脚步一晃，我伸手扶住她的手臂。",
	},
	[20070426] = {
		ID = 20070426,
		Speaker = "我",
		Text = "没事，我来。",
	},
	[20070427] = {
		ID = 20070427,
		Speaker = "勒瓦杜兰",
		Text = "……本王不用你扶。",
	},
	[20070428] = {
		ID = 20070428,
		Speaker = "我",
		Text = "妳的手都在抖了还嘴硬。",
	},
	[20070429] = {
		ID = 20070429,
		Speaker = "勒瓦杜兰",
		Text = "……闭嘴。",
	},
	[20070430] = {
		ID = 20070430,
		Speaker = "我",
		Text = "这附近好像有片没什么人的雪林，先带妳过去凉快一下。",
	},
	[20070431] = {
		ID = 20070431,
		Speaker = "勒瓦杜兰",
		Text = "……动物园里，怎么会有雪林。",
	},
	[20070432] = {
		ID = 20070432,
		Speaker = "我",
		Text = "企鹅馆旁边留了一小块人工林地，给企鹅乘凉用的，平常没什么游客会绕过去。",
	},
	[20070433] = {
		ID = 20070433,
		Speaker = "勒瓦杜兰",
		Text = "……你倒是打听得挺清楚。",
	},
	[20070434] = {
		ID = 20070434,
		Speaker = "我",
		Text = "毕竟今天的目标是让妳玩得开心，不做功课怎么行。",
	},
	[20070435] = {
		ID = 20070435,
		Speaker = "勒瓦杜兰",
		Text = "……是吗。",
	},
	[20070436] = {
		ID = 20070436,
		Text = "转过一排灌木，气温骤然降了下来，连蝉鸣都稀薄了不少。",
	},
	[20070437] = {
		ID = 20070437,
		Speaker = "勒瓦杜兰",
		Text = "……这里，确实凉快多了。",
	},
	[20070438] = {
		ID = 20070438,
		Speaker = "我",
		Text = "看吧，还好我有先打听。",
	},
	[20070439] = {
		ID = 20070439,
		Speaker = "勒瓦杜兰",
		Text = "……哼，算你这次有点用。",
	},
	[20070440] = {
		ID = 20070440,
		Speaker = "我",
		Text = "妳这算是在道谢吗？",
	},
	[20070441] = {
		ID = 20070441,
		Speaker = "勒瓦杜兰",
		Text = "……随便你怎么想。",
	},
	[20070442] = {
		ID = 20070442,
		Speaker = "我",
		Text = "找个地方坐下吧，脸色好一点再走。",
	},
	[20070443] = {
		ID = 20070443,
		Speaker = "勒瓦杜兰",
		Text = "……嗯。",
	},
	[20070444] = {
		ID = 20070444,
		Speaker = "我",
		Text = "感觉好点了吗？",
	},
	[20070445] = {
		ID = 20070445,
		Speaker = "我",
		Text = "妳这是不是有点后悔穿上那套企鹅装了？",
	},
	[20070446] = {
		ID = 20070446,
		Speaker = "勒瓦杜兰",
		Text = "谁、谁会后悔这种东西？本王是那么容易动摇的存在吗？",
	},
	[20070447] = {
		ID = 20070447,
		Speaker = "勒瓦杜兰",
		Text = "但是这身皮囊，闷得跟蒸笼没两样。",
	},
	[20070448] = {
		ID = 20070448,
		Speaker = "勒瓦杜兰",
		Text = "……过来。",
	},
	[20070449] = {
		ID = 20070449,
		Speaker = "我",
		Text = "过来做什么？",
	},
	[20070450] = {
		ID = 20070450,
		Speaker = "勒瓦杜兰",
		Text = "拉链，把它拉下来。难道要我在动物园里活活闷死给你看吗？",
	},
	[20070451] = {
		ID = 20070451,
	},
	[20070452] = {
		ID = 20070452,
	},
	[20070453] = {
		ID = 20070453,
		Text = "拉链顺着她的背脊一路往下滑，企鹅装的填充外壳松开。",
	},
	[20070454] = {
		ID = 20070454,
		Text = "露出里面——什么都没有，汗水沿着她线条分明的脊背滑下去。",
	},
	[20070455] = {
		ID = 20070455,
		Text = "浸满汗水、纤细白皙的背就这样裸露在我身前。",
	},
	[20070456] = {
		ID = 20070456,
		Speaker = "我",
		Text = "……等、等一下，妳里面没穿？ ！",
	},
	[20070457] = {
		ID = 20070457,
		Speaker = "勒瓦杜兰",
		Text = "难道你以为，本王会让一层填充玩偶，隔着累赘的布料闷着我？",
	},
	[20070458] = {
		ID = 20070458,
		Speaker = "我",
		Text = "可是妳这样，汗流得跟刚从水里捞出来的一样夸张啊。",
	},
	[20070459] = {
		ID = 20070459,
		Speaker = "勒瓦杜兰",
		Text = "……看够了吗，人类。",
	},
	[20070460] = {
		ID = 20070460,
		Speaker = "勒瓦杜兰",
		Text = "……帮我……擦一擦。",
	},
	[20070461] = {
		ID = 20070461,
		Speaker = "我",
		Text = "咦？",
	},
	[20070462] = {
		ID = 20070462,
		Speaker = "勒瓦杜兰",
		Text = "你听不懂人类的语言了吗？我要你，帮我把汗擦干净。",
	},
	[20070463] = {
		ID = 20070463,
		Speaker = "我",
		Text = "用毛巾？",
	},
	[20070464] = {
		ID = 20070464,
		Speaker = "勒瓦杜兰",
		Text = "还有其他选项吗？少明知故问了。",
	},
	[20070465] = {
		ID = 20070465,
		Text = "我吞了口口水，指尖泛起一点温热的光——",
	},
	[20070466] = {
		ID = 20070466,
		Text = "脑海里想着一条干燥柔软的毛巾，下一秒，那东西就实实在在地躺在我掌心里。",
	},
	[20070467] = {
		ID = 20070467,
		Speaker = "勒瓦杜兰",
		Text = "……那项能力，还真是方便得让人火大。",
	},
	[20070468] = {
		ID = 20070468,
		Speaker = "我",
		Text = "夸奖的话我就收下了。",
	},
	[20070469] = {
		ID = 20070469,
		Speaker = "勒瓦杜兰",
		Text = "……小心点。",
	},
	[20070470] = {
		ID = 20070470,
		Text = "毛巾贴在她的背脊上来回滑动。",
	},
	[20070471] = {
		ID = 20070471,
		Text = "每擦过一次，她纤细的肩膀就跟着绷紧一次。",
	},
	[20070472] = {
		ID = 20070472,
		Speaker = "勒瓦杜兰",
		Text = "……动作，可以再轻一点吗？",
	},
	[20070473] = {
		ID = 20070473,
		Speaker = "我",
		Text = "遵命，女王陛下。",
	},
	[20070474] = {
		ID = 20070474,
		Speaker = "勒瓦杜兰",
		Text = "……人类……你越来越得寸进尺了……",
	},
	[20070475] = {
		ID = 20070475,
		Text = "毛巾顺着她的侧颈往下滑，经过锁骨时，我听见她倒抽一口气。",
	},
	[20070476] = {
		ID = 20070476,
		Speaker = "我",
		Text = "妳流的汗有够多，是不是因为里面太闷了。",
	},
	[20070477] = {
		ID = 20070477,
		Speaker = "勒瓦杜兰",
		Text = "那身衣服……根本是烤炉。",
	},
	[20070478] = {
		ID = 20070478,
		Speaker = "我",
		Text = "那我帮妳擦仔细一点好了。",
	},
	[20070479] = {
		ID = 20070479,
		Speaker = "勒瓦杜兰",
		Text = "……喂，你的手，往哪里放。",
	},
	[20070480] = {
		ID = 20070480,
		Text = "毛巾滑过她的胸口，指节不小心蹭过柔软的肌肤，她的呼吸瞬间乱了拍子。",
	},
	[20070481] = {
		ID = 20070481,
		Text = "继续往下擦，一路擦过小腹，来到她大腿内侧。",
