		Speaker = "勒瓦杜兰",
		Text = "……",
	},
	[20070485] = {
		ID = 20070485,
		Speaker = "我",
		Text = "怎么不说话了，我刚刚讲了什么奇怪的话吗？",
	},
	[20070486] = {
		ID = 20070486,
		Speaker = "勒瓦杜兰",
		Text = "哈……啊……！",
	},
	[20070487] = {
		ID = 20070487,
		Speaker = "勒瓦杜兰",
		Text = "……没事……继续。",
