		Speaker = "我",
		Text = "遵命，我的女王陛下。",
	},
	[20070489] = {
		ID = 20070489,
		Speaker = "勒瓦杜兰",
		Text = "……别用那种称呼笑我。",
	},
	[20070490] = {
