	[40030224] = {
		ID = 40030224,
		Speaker = "勒瓦杜兰",
		Text = "所以本王才在整理「放松」要怎么进行。",
	},
	[40030225] = {
		ID = 40030225,
		Speaker = "我",
		Text = "……妳这句话听起来完全没有要放松的意思。",
	},
	[40030226] = {
		ID = 40030226,
		Speaker = "勒瓦杜兰",
		Text = "有问题吗？",
	},
	[40030227] = {
		ID = 40030227,
		Text = "我把桌上最上面那张纸抽过来看，上头密密麻麻列着时间。",
	},
	[40030228] = {
		ID = 40030228,
		Speaker = "我",
		Text = "十三点整，晒太阳十五分钟。十三点十七分，散步。十四点零五分，泡热水澡。",
	},
	[40030229] = {
		ID = 40030229,
		Speaker = "我",
		Text = "还有逛市集，也写了精确时间？",
	},
	[40030230] = {
		ID = 40030230,
		Speaker = "我",
		Text = "妳的放假让我感觉像是多了一个学姊的样子。",
	},
	[40030231] = {
		ID = 40030231,
		Speaker = "我",
		Text = "瑟蕾雅确实说了这四样没错，但她应该没叫妳精确到秒吧。",
	},
	[40030232] = {
		ID = 40030232,
		Speaker = "勒瓦杜兰",
		Text = "是分钟，不是秒，本王是能允许些微误差的。",
	},
	[40030233] = {
		ID = 40030233,
		Speaker = "我",
		Text = "妳說这句话的表情，让我很想反驳妳。",
	},
	[40030234] = {
		ID = 40030234,
		Text = "我的视线往下滑，停在倒数第二行——那一行字写得比其他都工整。",
	},
	[40030235] = {
		ID = 40030235,
		Text = "笔画又深又用力，像是下笔前犹豫了很久，最后才郑重地写下去。",
	},
	[40030236] = {
		ID = 40030236,
		Speaker = "我",
		Text = "……这行为什么会有『做爱』？",
	},
	[40030237] = {
		ID = 40030237,
		Speaker = "勒瓦杜兰",
		Text = "那……那也是放松的一部分。",
	},
	[40030238] = {
		ID = 40030238,
		Speaker = "我",
		Text = "瑟蕾雅有提到这一项？",
	},
	[40030239] = {
		ID = 40030239,
		Speaker = "勒瓦杜兰",
		Text = "庶民，本王没有允许你发表意见。",
	},
	[40030240] = {
		ID = 40030240,
		Text = "勒瓦杜兰把清单抢了回去。",
	},
	[40030241] = {
		ID = 40030241,
		Speaker = "我",
		Text = "好……",
	},
	[40030242] = {
		ID = 40030242,
		Speaker = "勒瓦杜兰",
		Text = "……这样规划有什么不对吗？",
	},
	[40030243] = {
		ID = 40030243,
		Speaker = "我",
		Text = "没有不对，但放松这种事不用写计画书，走出去实际试一次就知道了。",
	},
	[40030244] = {
		ID = 40030244,
		Speaker = "勒瓦杜兰",
		Text = "……如果照你说的做，结果失败了呢？",
	},
	[40030245] = {
		ID = 40030245,
		Speaker = "我",
		Text = "那就再试一次，又不会少一块肉。",
	},
	[40030246] = {
		ID = 40030246,
		Text = "她沉默了几秒，视线在我脸上停留，最后才把清单折好，小心地收进怀里。",
	},
	[40030247] = {
		ID = 40030247,
		Speaker = "我",
		Text = "走吧，简单的去晒晒太阳。",
	},
	[40030248] = {
		ID = 40030248,
	},
	[40030249] = {
		ID = 40030249,
	},
	[40030250] = {
		ID = 40030250,
		Text = "我领着她走出教堂，午后的阳光斜斜洒在希望之丘融雪的街道上。",
	},
	[40030251] = {
		ID = 40030251,
		Speaker = "我",
		Text = "怎么样，感觉到暖了吗？",
	},
	[40030252] = {
		ID = 40030252,
		Speaker = "勒瓦杜兰",
		Text = "……有一点。",
	},
	[40030253] = {
		ID = 40030253,
		Speaker = "我",
		Text = "那就算达成了，不用照表操课吧？",
	},
	[40030254] = {
		ID = 40030254,
		Speaker = "勒瓦杜兰",
		Text = "……感觉有点随便。",
	},
	[40030255] = {
		ID = 40030255,
		Text = "一名抱着柴火的村民迎面走来，笑着想打招呼，视线对上她的脸之后脚步却顿了一下。",
	},
	[40030256] = {
		ID = 40030256,
		Text = "她慌张地点了点头，加快脚步绕了个大弯离开。",
	},
	[40030257] = {
		ID = 40030257,
		Speaker = "勒瓦杜兰",
		Text = "……她为什么跑走了？",
	},
	[40030258] = {
		ID = 40030258,
		Speaker = "我",
		Text = "妳刚刚那张脸，大概像是想把她冻起来。",
	},
	[40030259] = {
		ID = 40030259,
		Speaker = "勒瓦杜兰",
		Text = "我在尝试放松了。",
	},
	[40030260] = {
		ID = 40030260,
		Speaker = "我",
		Text = "那就边想边把表情放松一点啊。",
	},
	[40030261] = {
		ID = 40030261,
		Text = "又一对母子迎面而来，孩子好奇地伸长脖子张望。",
	},
	[40030262] = {
		ID = 40030262,
		Text = "母亲却下意识把孩子往怀里一带，低着头快步绕开，连招呼都没来得及打。",
	},
	[40030263] = {
		ID = 40030263,
		Speaker = "勒瓦杜兰",
		Text = "……又来了。",
	},
	[40030264] = {
		ID = 40030264,
		Speaker = "勒瓦杜兰",
		Text = "人类，你们是不是都觉得我很可怕？",
	},
	[40030265] = {
		ID = 40030265,
		Speaker = "我",
		Text = "不是可怕，是妳现在这张脸，跟在审判犯人差不多。",
	},
	[40030266] = {
		ID = 40030266,
		Speaker = "勒瓦杜兰",
		Text = "……我没有生气。",
	},
	[40030267] = {
		ID = 40030267,
		Speaker = "我",
		Text = "我知道，但村民不知道啊。",
	},
	[40030268] = {
		ID = 40030268,
		Speaker = "勒瓦杜兰",
		Text = "……那我该怎么做？",
	},
	[40030269] = {
		ID = 40030269,
		Speaker = "我",
		Text = "微笑，很简单的，妳试试看。",
	},
	[40030270] = {
		ID = 40030270,
		Text = "她停下脚步，侧过脸对着街边的窗户，试着扯动嘴角。",
	},
	[40030271] = {
		ID = 40030271,
		Text = "那动作僵硬得像是身体里有某块肌肉第一次被使用，勉强拉出一道生硬的弧度。",
	},
	[40030272] = {
		ID = 40030272,
		Speaker = "我",
		Text = "……妳那是在生气还是在笑？",
	},
	[40030273] = {
		ID = 40030273,
		Speaker = "勒瓦杜兰",
		Text = "……我在笑。",
	},
	[40030274] = {
		ID = 40030274,
		Speaker = "我",
		Text = "眼睛也要一起笑。",
	},
	[40030275] = {
		ID = 40030275,
		Text = "她深吸一口气，重新调整表情——这一次，嘴角总算勉强撑起一道弧度。",
	},
	[40030276] = {
		ID = 40030276,
		Speaker = "我",
		Text = "……有进步。",
	},
	[40030277] = {
		ID = 40030277,
		Speaker = "勒瓦杜兰",
		Text = "……这样，就算是放松了？",
	},
	[40030278] = {
		ID = 40030278,
	},
	[40030279] = {
		ID = 40030279,
	},
	[40030280] = {
		ID = 40030280,
		Text = "阳光把街道晒得暖洋洋的，勒瓦杜兰才刚挤出那个僵硬到近乎诡异的笑容，肩膀又立刻绷紧了回去。",
	},
	[40030281] = {
		ID = 40030281,
		Text = "她忽然停下脚步，盯着门口一块歪掉的木招牌，眉头一点一点皱了起来。",
	},
	[40030282] = {
		ID = 40030282,
		Speaker = "我",
		Text = "怎么了？",
	},
	[40030283] = {
		ID = 40030283,
		Speaker = "勒瓦杜兰",
		Text = "……那块招牌歪了。",
	},
	[40030284] = {
		ID = 40030284,
		Speaker = "我",
		Text = "所以呢？我们现在是在散步，不是巡逻。",
	},
	[40030285] = {
		ID = 40030285,
		Speaker = "勒瓦杜兰",
		Text = "……散步的时候，顺便看一下也可以。",
	},
	[40030286] = {
		ID = 40030286,
		Speaker = "勒瓦杜兰",
		Text = "你，上去把招牌扶正，快一点。",
	},
	[40030287] = {
		ID = 40030287,
		Speaker = "我",
		Text = "……好。",
	},
	[40030288] = {
		ID = 40030288,
		Speaker = "勒瓦杜兰",
		Text = "……端正多了。",
	},
	[40030289] = {
		ID = 40030289,
		Speaker = "勒瓦杜兰",
		Text = "……这堆柴火也是，歪七扭八的，去把它排好。",
	},
	[40030290] = {
		ID = 40030290,
		Speaker = "我",
		Text = "还记得我们出来是要放松的吗？",
	},
	[40030291] = {
		ID = 40030291,
		Speaker = "勒瓦杜兰",
		Text = "叠好了才能放松，动作。",
	},
	[40030292] = {
		ID = 40030292,
		Text = "我蹲下把柴火一根一根叠得整整齐齐。",
	},
	[40030293] = {
		ID = 40030293,
		Speaker = "勒瓦杜兰",
		Text = "……看到这么多不顺眼的东西，我没办法放松。",
	},
	[40030294] = {
		ID = 40030294,
		Text = "说完便转身朝一旁的萝卜田走去，指挥着里面的农民拔杂草。",
	},
	[40030295] = {
		ID = 40030295,
		Speaker = "我",
		Text = "所以妳是打算把整条街的杂草跟柴火都解决完，再开始放松？",
	},
	[40030296] = {
		ID = 40030296,
		Speaker = "勒瓦杜兰",
		Text = "……我反而无法理解你们人类怎么可以生活在如此无序的空间里。",
	},
	[40030297] = {
		ID = 40030297,
		Speaker = "我",
		Text = "妳这样下去，我们大概要放松到明年。",
	},
	[40030298] = {
		ID = 40030298,
		Speaker = "？ ？ ？",
		Text = "唉……光听这么吵，就知道你来了。",
	},
	[40030299] = {
		ID = 40030299,
		Speaker = "？ ？ ？",
		Text = "我只是睡了一觉希望之丘就被独裁者接管了吗？",
	},
	[40030300] = {
		ID = 40030300,
		Speaker = "我",
		Text = "说来话长……结论就是她跟艾蕾娜换了个身分，顺便来体验一下放松这回事。",
	},
	[40030301] = {
		ID = 40030301,
		Speaker = "西西雅",
		Text = "也许是我们其中一人书读得不够多，才会认为拔杂草算是放松。",
	},
	[40030302] = {
		ID = 40030302,
		Speaker = "我",
		Text = "这不是我让她去做的！",
	},
	[40030303] = {
		ID = 40030303,
		Speaker = "西西雅",
		Text = "我知道，并不意外——哈——",
	},
	[40030304] = {
		ID = 40030304,
		Speaker = "西西雅",
		Text = "哈啾！",
	},
	[40030305] = {
		ID = 40030305,
		Speaker = "我",
		Text = "咦？",
	},
	[40030306] = {
		ID = 40030306,
		Speaker = "勒瓦杜兰",
		Text = "……西西雅？",
	},
	[40030307] = {
		ID = 40030307,
		Text = "勒瓦杜兰猛地抬起头，整个人径直冲向教堂。",
	},
	[40030308] = {
		ID = 40030308,
		Speaker = "勒瓦杜兰",
		Text = "西西雅，你还好吗？",
	},
	[40030309] = {
		ID = 40030309,
		Text = "她抱着好几件毯子冲了出来，三两下就把西西雅裹成一颗圆滚滚的球。",
	},
	[40030310] = {
		ID = 40030310,
		Speaker = "西西雅",
		Text = "我只是打了个喷嚏，不是要冻死了。",
	},
	[40030311] = {
		ID = 40030311,
		Speaker = "西西雅",
		Text = "而且，有点热。",
	},
	[40030312] = {
		ID = 40030312,
		Speaker = "我",
		Text = "妳都被裹成球了还能这么冷静，这也是一种本事。",
	},
	[40030313] = {
		ID = 40030313,
		Speaker = "勒瓦杜兰",
		Text = "……着凉会很麻烦。",
	},
	[40030314] = {
		ID = 40030314,
		Speaker = "西西雅",
		Text = "麻烦的是，我现在看起来像一颗会说话的丸子。",
	},
	[40030315] = {
		ID = 40030315,
		Speaker = "我",
		Text = "一颗很毒舌的丸子。",
	},
	[40030316] = {
		ID = 40030316,
		Speaker = "西西雅",
		Text = "……反正，随便你们怎么说。",
	},
	[40030317] = {
		ID = 40030317,
		Speaker = "勒瓦杜兰",
		Text = "……嗯。",
	},
	[40030318] = {
		ID = 40030318,
		Speaker = "勒瓦杜兰",
		Text = "我只是……在想办法放松……",
	},
	[40030319] = {
		ID = 40030319,
		Speaker = "西西雅",
		Text = "如果这是放松，我很庆幸自己只是被裹成球，而不是被拿去修屋顶。",
	},
	[40030320] = {
		ID = 40030320,
		Speaker = "西西雅",
		Text = "我开始有点后悔打那个喷嚏了。",
	},
	[40030321] = {
		ID = 40030321,
		Speaker = "我",
		Text = "太迟了，妳已经是丸子了。",
	},
	[40030322] = {
		ID = 40030322,
		Speaker = "勒瓦杜兰",
		Text = "……",
	},
	[40030323] = {
		ID = 40030323,
		Speaker = "西西雅",
		Text = "好啦……我想想该怎么帮妳……",
	},
	[40030324] = {
		ID = 40030324,
	},
	[40030325] = {
		ID = 40030325,
	},
	[40030326] = {
		ID = 40030326,
		Text = "西西雅将身上的毯子全丢在摇椅上，一边把自己塞进沙发，顺手抽了一本旧书。",
	},
	[40030327] = {
		ID = 40030327,
		Text = "勒瓦杜兰站在门口没动，眼神在炉火跟书架之间来回打转。 ）",
	},
	[40030328] = {
		ID = 40030328,
		Text = "我随手从书架捞了一本童话故事集塞到她手里，指了指炉火旁的空凳子。",
	},
	[40030329] = {
		ID = 40030329,
		Text = "她盯着那本书看了两秒，才学着西西雅的样子慢吞吞坐下。",
	},
	[40030330] = {
		ID = 40030330,
		Speaker = "西西雅",
		Text = "你这样坐法，看书要看到脖子断掉。",
	},
	[40030331] = {
		ID = 40030331,
		Speaker = "勒瓦杜兰",
		Text = "……这样不好吗？本王以为端坐是基本的礼仪。",
	},
	[40030332] = {
		ID = 40030332,
		Speaker = "我",
		Text = "礼仪是给觐见用的，妳现在是来放假的，冰雪女王陛下。",
	},
	[40030333] = {
		ID = 40030333,
		Speaker = "西西雅",
		Text = "说起来，你怎么突然想到要来希望之丘？",
	},
	[40030334] = {
		ID = 40030334,
		Speaker = "勒瓦杜兰",
		Text = "……没什么特别的理由。只是——",
	},
	[40030335] = {
		ID = 40030335,
		Speaker = "勒瓦杜兰",
		Text = "那件事情过后，我常常会有种罪恶感。",
	},
	[40030336] = {
		ID = 40030336,
		Speaker = "勒瓦杜兰",
		Text = "在学习了人类的知识后，我心里不断冒出一个念头——",
	},
	[40030337] = {
		ID = 40030337,
		Speaker = "勒瓦杜兰",
		Text = "如果他们知道夺走太阳的人就是我，会怎样想。",
	},
	[40030338] = {
		ID = 40030338,
		Speaker = "西西雅",
		Text = "但照刚刚那些村民的反应来看，他们并不讨厌你喔。",
	},
	[40030339] = {
		ID = 40030339,
		Speaker = "勒瓦杜兰",
		Text = "那是因为她们看见的是「欧若拉」，而不是「勒瓦杜兰」。",
	},
	[40030340] = {
		ID = 40030340,
		Speaker = "西西雅",
		Text = "真要说罪魁祸首，那个人也不是你，是我。",
	},
	[40030341] = {
		ID = 40030341,
		Speaker = "勒瓦杜兰",
		Text = "如果他们恨我，或许还比较好过一些。至少那样，我就不用去猜他们心里到底在想什么。",
	},
	[40030342] = {
		ID = 40030342,
		Speaker = "我",
		Text = "所以妳宁愿先预设被讨厌，也不要冒一点『说不定他们愿意原谅』的风险？",
	},
	[40030343] = {
		ID = 40030343,
		Speaker = "勒瓦杜兰",
		Text = "……那不一样。恨是可以预期的，接纳不是。",
	},
	[40030344] = {
		ID = 40030344,
		Speaker = "勒瓦杜兰",
		Text = "我不知道……毕竟我不是人类……",
	},
	[40030345] = {
		ID = 40030345,
		Speaker = "西西雅",
		Text = "……算了，我懒得替整个村子回答妳。",
	},
	[40030346] = {
		ID = 40030346,
		Speaker = "我",
		Text = "那就先别猜，待几天自己看。",
	},
	[40030347] = {
		ID = 40030347,
		Speaker = "我",
		Text = "反正妳现在有大把时间留在这里练习。",
	},
	[40030348] = {
