		Speaker = "艾蕾娜",
		Text = "没事情可以做了。",
	},
	[40030612] = {
		ID = 40030612,
		Speaker = "我",
		Text = "那妳现在想做什么？",
	},
	[40030613] = {
		ID = 40030613,
		Speaker = "艾蕾娜",
		Text = "……什么都不想做。",
	},
	[40030614] = {
