	[40030619] = {
		ID = 40030619,
		Speaker = "艾蕾娜",
		Text = "我想要……回去希望之丘，可是这边……",
	},
	[40030620] = {
		ID = 40030620,
		Speaker = "我",
		Text = "交给雪人来管理就可以了，让他们来吧。",
	},
	[40030621] = {
		ID = 40030621,
		Text = "我朝旁边的雪人挥挥手，把剩下的收尾都交给他们。",
	},
	[40030622] = {
		ID = 40030622,
		Text = "我们一起走出冰雪城堡的大门，朝希望之丘的方向走去。",
