	[40030623] = {
		ID = 40030623,
	},
	[40030624] = {
		ID = 40030624,
	},
	[40030625] = {
		ID = 40030625,
		Speaker = "我",
		Text = "回去以后，我们也一起放空一下吧。",
	},
	[40030626] = {
		ID = 40030626,
		Speaker = "艾蕾娜",
		Text = "……好，如果船长在身边，我就试试看。",
	},
	[40030627] = {
		ID = 40030627,
		Speaker = "我",
		Text = "妳这样说，我还挺想立刻找个地方躺下的。",
	},
	[40030628] = {
		ID = 40030628,
	},
	[40030629] = {
		ID = 40030629,
	},
	[40030630] = {
		ID = 40030630,
		Text = "我和艾蕾娜走回希望之丘。",
	},
	[40030631] = {
		ID = 40030631,
		Text = "看见勒瓦杜兰站在盖到一半的木屋旁，井井有条地指挥着村民。",
	},
	[40030632] = {
		ID = 40030632,
		Speaker = "我",
		Text = "喔喔，妳怎么站在这边？",
	},
	[40030633] = {
		ID = 40030633,
		Speaker = "勒瓦杜兰",
		Text = "……你们回来了。",
	},
	[40030634] = {
		ID = 40030634,
		Speaker = "勒瓦杜兰",
		Text = "我的城堡还好吗？",
	},
	[40030635] = {
		ID = 40030635,
		Speaker = "艾蕾娜",
		Text = "没……没问题……",
	},
	[40030636] = {
		ID = 40030636,
		Speaker = "艾蕾娜",
		Text = "嗯！",
	},
	[40030637] = {
		ID = 40030637,
		Speaker = "我",
		Text = "这身架势有种奴役人类的感觉。",
	},
	[40030638] = {
		ID = 40030638,
		Speaker = "勒瓦杜兰",
		Text = "……奴役人类？哼！",
