	[40030639] = {
		ID = 40030639,
		Speaker = "勒瓦杜兰",
		Text = "雪人可比人类好用多了。",
	},
	[40030640] = {
		ID = 40030640,
		Speaker = "勒瓦杜兰",
		Text = "只要有雪，就能一直做出来，不用睡觉，也不用吃饭。",
	},
	[40030641] = {
		ID = 40030641,
		Speaker = "勒瓦杜兰",
		Text = "而且很好满足。一星期只要放三天假——",
	},
	[40030642] = {
		ID = 40030642,
		Speaker = "勒瓦杜兰",
		Text = "提供三餐加饭后点心、每天午休两个小时、还有住的地方……",
	},
	[40030643] = {
		ID = 40030643,
		Speaker = "勒瓦杜兰",
		Text = "雪人只要这样就满足了，天知道人类有多少要求？",
