	[40030644] = {
		ID = 40030644,
		Speaker = "艾蕾娜",
		Text = "……福利真好。",
	},
	[40030645] = {
		ID = 40030645,
		Speaker = "我",
		Text = "妳那边还缺雪人吗？",
	},
	[40030646] = {
		ID = 40030646,
		Speaker = "勒瓦杜兰",
		Text = "不了，我可不想看你力竭而亡，你有其他工作。",
	},
	[40030647] = {
		ID = 40030647,
		Speaker = "村民",
		Text = "欧若拉小姐，谢谢您的帮忙，这点心意请您收下！",
	},
	[40030648] = {
