	[40030652] = {
		ID = 40030652,
		Speaker = "村民",
		Text = "您就收下吧，村民们都很感谢。",
	},
	[40030653] = {
		ID = 40030653,
		Speaker = "村民",
		Text = "还有点灯人小姐，今天穿的衣服很好看。",
