	[40030678] = {
		ID = 40030678,
		Speaker = "勒瓦杜兰",
		Text = "……它应该听我命令！",
	},
	[40030679] = {
		ID = 40030679,
		Text = "勒瓦杜兰伸手想抓猫，猫弓起背炸毛窜开，尾巴扫过她的脸。",
