	[40030695] = {
		ID = 40030695,
	},
	[40030696] = {
		ID = 40030696,
	},
	[40030697] = {
		ID = 40030697,
		Text = "勒瓦杜兰稳稳落地，把还赖在怀里的猫轻轻放到石板路上。",
	},
	[40030698] = {
		ID = 40030698,
		Text = "猫咪不领情地甩了甩尾巴，一溜烟钻进巷子里。",
	},
	[40030699] = {
		ID = 40030699,
		Text = "艾蕾娜和我挤开围成一圈的村民，才看清楚全貌——",
