	[40030707] = {
		ID = 40030707,
		Speaker = "勒瓦杜兰",
		Text = "或者，更干脆一点也无妨——反正你们早就该恨我了。",
	},
	[40030708] = {
		ID = 40030708,
		Text = "没有人回答。几个孩子往后躲进大人身后，扯着衣角不敢再看她。",
	},
	[40030709] = {
		ID = 40030709,
		Speaker = "艾蕾娜",
		Text = "勒瓦杜兰……",
	},
	[40030710] = {
		ID = 40030710,
		Speaker = "勒瓦杜兰",
		Text = "妳不用担心，这是我一个人的事。",
	},
	[40030711] = {
		ID = 40030711,
		Speaker = "艾蕾娜",
		Text = "可是……",
	},
	[40030712] = {
		ID = 40030712,
		Speaker = "勒瓦杜兰",
		Text = "没有可是。",
	},
	[40030713] = {
		ID = 40030713,
		Text = "就在僵局快要撑不下去的时候，人群后方传来一阵急促的脚步声——",
	},
	[40030714] = {
		ID = 40030714,
		Text = "瑟蕾雅推开村民，快步挤到最前面。",
