	[40030715] = {
		ID = 40030715,
		Speaker = "瑟蕾雅",
		Text = "等、等一下，大家先别这样！",
	},
	[40030716] = {
		ID = 40030716,
		Speaker = "瑟蕾雅",
		Text = "咦……欧若拉小姐是——不对，勒瓦杜兰小姐才对……",
	},
	[40030717] = {
		ID = 40030717,
		Speaker = "瑟蕾雅",
		Text = "总、总之她真的不是坏人！",
	},
	[40030718] = {
		ID = 40030718,
		Speaker = "村民",
		Text = "可是瑟蕾雅小姐，她刚刚自己说的……",
	},
	[40030719] = {
		ID = 40030719,
		Speaker = "瑟蕾雅",
		Text = "呜……总、总之勒瓦杜兰小姐她真的不是坏人！",
	},
	[40030720] = {
		ID = 40030720,
		Speaker = "村民",
		Text = "可是永冬确实是她造成的吧？",
	},
	[40030721] = {
		ID = 40030721,
		Speaker = "瑟蕾雅",
		Text = "呜……",
	},
	[40030722] = {
		ID = 40030722,
		Speaker = "艾蕾娜",
		Text = "勒瓦杜兰小姐很努力想弥补错误……",
	},
	[40030723] = {
		ID = 40030723,
		Speaker = "艾蕾娜",
		Text = "还写了人类观察的笔记……",
	},
	[40030724] = {
		ID = 40030724,
		Speaker = "勒瓦杜兰",
		Text = "……！",
	},
	[40030725] = {
		ID = 40030725,
		Text = "有几个村民忍不住噗哧笑出声，方才凝结的气氛悄悄松动了一丝。",
	},
	[40030726] = {
		ID = 40030726,
		Speaker = "西西雅",
		Text = "蠢到让人生不起气。",
	},
	[40030727] = {
		ID = 40030727,
		Speaker = "勒瓦杜兰",
		Text = "够了。",
	},
	[40030728] = {
		ID = 40030728,
		Speaker = "勒瓦杜兰",
		Text = "没什么好说的。",
	},
	[40030729] = {
		ID = 40030729,
		Speaker = "勒瓦杜兰",
		Text = "我就是童话里那个反派——用永冬锁住整个世界的人。",
	},
	[40030730] = {
		ID = 40030730,
		Speaker = "勒瓦杜兰",
		Text = "这是事实，不需要谁替我辩解。",
