	[20170574] = {
		ID = 20170574,
		Speaker = "我",
		Text = "你所谓的奖励就是这种东西吗？",
	},
	[20170575] = {
		ID = 20170575,
		Speaker = "西西雅",
		Text = "才……才不是……唔……",
	},
	[20170576] = {
		ID = 20170576,
		Speaker = "西西雅",
		Text = "是听书上说的……",
