	[20170577] = {
		ID = 20170577,
		Speaker = "西西雅",
		Text = "书上说……运动能有效刺激……还会增加性欲……",
	},
	[20170578] = {
		ID = 20170578,
		Speaker = "西西雅",
		Text = "这都是船长大人的错喔……",
	},
	[20170579] = {
		ID = 20170579,
		Speaker = "西西雅",
		Text = "哈……哈啊……船……船长大人……",
	},
	[20170580] = {
		ID = 20170580,
		Speaker = "西西雅",
		Text = "带我出来运动……",
	},
	[20170581] = {
		ID = 20170581,
		Speaker = "西西雅",
		Text = "其实只是想要做爱吧……",
	},
	[20170582] = {
		ID = 20170582,
		Speaker = "我",
		Text = "你还敢说我，你知道飞船房间的隔音其实很差吗？",
