	[20170583] = {
		ID = 20170583,
		Speaker = "西西雅",
		Text = "呜咕……什么……意思……",
	},
	[20170584] = {
		ID = 20170584,
		Speaker = "我",
		Text = "每次半夜经过你的房间门口，都听得一清二楚喔。",
	},
	[20170585] = {
		ID = 20170585,
		Speaker = "西西雅",
		Text = "咿——！",
	},
	[20170586] = {
		ID = 20170586,
		Speaker = "我",
		Text = "跟平常安安静静的样子差很多喔。",
	},
	[20170587] = {
		ID = 20170587,
		Speaker = "西西雅",
		Text = "呜——我听不懂……你在说什么……",
	},
	[20170588] = {
		ID = 20170588,
		Speaker = "我",
		Text = "看你的房间就知道了吧，每天都自慰到早上才睡吧？",
	},
	[20170589] = {
		ID = 20170589,
		Speaker = "西西雅",
		Text = "呜……我……我不知道……",
	},
	[20170590] = {
		ID = 20170590,
		Speaker = "西西雅",
		Text = "那是……看书……念稿……的声音……",
