	[20170104] = {
		ID = 20170104,
		Text = "我终于放下遮着眼睛的手，视线小心避开床铺，改看向整个房间——",
	},
	[20170105] = {
		ID = 20170105,
		Text = "书堆得像小山，散落一地，连走道都快找不到。",
	},
	[20170106] = {
		ID = 20170106,
		Text = "垃圾桶里堆满稿纸和用过的卫生纸。",
	},
	[20170107] = {
		ID = 20170107,
		Speaker = "我",
		Text = "妳的房间也乱过头了吧，瑟蕾雅都没有管你吗？",
	},
	[20170108] = {
		ID = 20170108,
		Speaker = "西西雅",
		Text = "整理的话我反而会找不到东西。",
	},
	[20170109] = {
		ID = 20170109,
		Speaker = "西西雅",
		Text = "我称之为「乱中有序」。",
	},
	[20170110] = {
		ID = 20170110,
		Text = "不知道为何，西西雅露出了骄傲的笑脸。",
	},
	[20170111] = {
		ID = 20170111,
		Speaker = "我",
		Text = "没事，我来——妳的衣服呢，我帮妳拿。",
	},
	[20170112] = {
		ID = 20170112,
		Speaker = "西西雅",
		Text = "不用了，反正也没有衣服可拿。",
	},
	[20170113] = {
		ID = 20170113,
		Speaker = "我",
		Text = "咦？你平常穿的毛衣呢？",
	},
	[20170114] = {
		ID = 20170114,
		Speaker = "西西雅",
		Text = "瑟蕾雅 ，她说我的衣服堆积成灾，一次性全部抱去洗了。",
	},
	[20170115] = {
		ID = 20170115,
		Speaker = "西西雅",
		Text = "明明椅子上还有空间可以放的。",
	},
	[20170116] = {
		ID = 20170116,
		Speaker = "西西雅",
		Text = "剩下的只有这条毯子，还有一套她硬塞给我的运动服。",
	},
	[20170117] = {
		ID = 20170117,
		Speaker = "我",
		Text = "运动服？听起来不错啊？",
	},
	[20170118] = {
		ID = 20170118,
		Speaker = "我",
		Text = "医生不是也嘱托西西雅要多运动吗？整天待在床上不好喔。",
	},
	[20170119] = {
		ID = 20170119,
		Speaker = "我",
		Text = "瑟蕾雅也常常希望我多带妳出去走走。",
	},
	[20170120] = {
		ID = 20170120,
		Speaker = "西西雅",
		Text = "问题不在有没有衣服穿，是我根本不打算运动。",
	},
	[20170121] = {
		ID = 20170121,
		Text = "她说完，抱着毯子一头钻进堆满书的床铺深处，把自己裹得像只蓑衣虫，只露出一颗头。",
	},
	[20170122] = {
		ID = 20170122,
		Speaker = "西西雅",
		Text = "我又不运动，买运动服给我做什么，这是浪费布料。",
	},
	[20170123] = {
		ID = 20170123,
		Speaker = "我",
		Text = "既然衣服都准备好了，那就没有不运动的理由了——总会有办法的。",
	},
	[20170124] = {
		ID = 20170124,
		Speaker = "西西雅",
		Text = "有，理由是我不想。",
	},
	[20170125] = {
		ID = 20170125,
		Speaker = "我",
		Text = "妳这不叫理由，叫任性。",
	},
	[20170126] = {
		ID = 20170126,
		Speaker = "西西雅",
		Text = "任性也是一种理由喔。",
	},
	[20170127] = {
		ID = 20170127,
	},
	[20170128] = {
		ID = 20170128,
	},
	[20170129] = {
		ID = 20170129,
		Text = "我试着扯了一下毯角，西西雅立刻抱住床架，整个人连同被子缩成一团。",
	},
	[20170130] = {
		ID = 20170130,
		Text = "最后形成了一场毫无效率的拔河。",
	},
	[20170131] = {
		ID = 20170131,
		Speaker = "我",
		Text = "妳的手劲跟妳平时讲话的毒舌完全不成比例啊。",
	},
	[20170132] = {
		ID = 20170132,
		Speaker = "西西雅",
		Text = "面对生存的压迫，生物可是能爆发出不合理的力量的。",
	},
	[20170133] = {
		ID = 20170133,
		Speaker = "我",
		Text = "说真的，妳现在的力气拿去写稿肯定进度神速。",
	},
	[20170134] = {
		ID = 20170134,
		Speaker = "西西雅",
		Text = "我平常写的速度也很快的。",
	},
	[20170135] = {
		ID = 20170135,
		Speaker = "我",
		Text = "妳知道妳现在看起来就像被抓去体检的猫吗。",
	},
	[20170136] = {
		ID = 20170136,
		Speaker = "西西雅",
		Text = "那就放我回书堆，猫咪有拒绝体检的权利。",
	},
	[20170137] = {
		ID = 20170137,
		Speaker = "我",
		Text = "人类没有。",
	},
	[20170138] = {
		ID = 20170138,
		Speaker = "西西雅",
		Text = "我怀疑我现在的分类已经不算人类了。",
	},
	[20170139] = {
		ID = 20170139,
		Speaker = "我",
		Text = "医生都說妳现在可以开始做点缓和的运动了。",
	},
	[20170140] = {
		ID = 20170140,
		Speaker = "我",
		Text = "既然身体好一些，总不能一直躺回原本的生活吧。",
	},
	[20170141] = {
		ID = 20170141,
		Speaker = "西西雅",
		Text = "无所谓，反正躺着也能活到明天。",
	},
	[20170142] = {
		ID = 20170142,
		Speaker = "我",
		Text = "妳这是把「随便」两个字刻在骨子里了吧。",
	},
	[20170143] = {
		ID = 20170143,
		Speaker = "西西雅",
		Text = "刻上去比较省力，不用每次重新决定。",
	},
	[20170144] = {
		ID = 20170144,
		Speaker = "我",
		Text = "好吧，那我去跟瑟蕾雅说，妳宁愿继续蓑衣虫下去，也不想穿她特地买的运动服。",
	},
	[20170145] = {
		ID = 20170145,
		Speaker = "我",
		Text = "不知道瑟蕾雅会怎么想。",
	},
	[20170146] = {
		ID = 20170146,
		Speaker = "西西雅",
		Text = "唔！ ……你这招很卑鄙。",
	},
	[20170147] = {
		ID = 20170147,
		Speaker = "我",
		Text = "所以妳要去了吗？",
	},
	[20170148] = {
		ID = 20170148,
		Speaker = "西西雅",
		Text = "简直就像是大小的葛笼里面都放着干透的墨水一样。",
	},
	[20170149] = {
		ID = 20170149,
		Speaker = "西西雅",
		Text = "一眼望透，令人十分难受呢。",
	},
	[20170150] = {
		ID = 20170150,
		Speaker = "西西雅",
		Text = "嗯，这个不错，我得写下来才行。",
	},
	[20170151] = {
		ID = 20170151,
		Speaker = "我",
		Text = "先别写了，既然决定好了，就快走吧。",
	},
	[20170152] = {
		ID = 20170152,
		Speaker = "西西雅",
		Text = "哼，我只是不想让她失望。",
	},
	[20170153] = {
		ID = 20170153,
		Speaker = "西西雅",
		Text = "可别以为我就这么屈服了。",
	},
	[20170154] = {
		ID = 20170154,
		Speaker = "西西雅",
		Text = "如果第二讨厌的是船长大人，那第一肯定是运动了。",
	},
	[20170155] = {
		ID = 20170155,
		Text = "她一边碎念，一边还是慢吞吞地换上了那套运动服。",
	},
	[20170156] = {
		ID = 20170156,
		Speaker = "西西雅",
		Text = "这套衣服的布料……也太薄了吧？",
	},
	[20170157] = {
		ID = 20170157,
		Speaker = "西西雅",
		Text = "你不要一直盯着我看，我们到底是要去哪里运动？",
	},
	[20170158] = {
		ID = 20170158,
		Speaker = "西西雅",
		Text = "要下船的话我可不要喔。",
	},
	[20170159] = {
		ID = 20170159,
		Speaker = "我",
		Text = "放心吧，船上的设施可是意想不到的多呢。",
	},
	[20170160] = {
		ID = 20170160,
	},
	[20170161] = {
		ID = 20170161,
	},
	[20170162] = {
		ID = 20170162,
		Text = "我们穿过几条走廊，来到飞船内侧那块被妮芙拉整理过的运动场。",
	},
	[20170163] = {
		ID = 20170163,
		Speaker = "西西雅",
		Text = "没想到船上还有这种空间……",
	},
	[20170164] = {
		ID = 20170164,
		Speaker = "西西雅",
		Text = "真是讨厌呢。",
	},
	[20170165] = {
		ID = 20170165,
		Speaker = "我",
		Text = "先热身，伸展一下就好，不会太累。",
	},
	[20170166] = {
		ID = 20170166,
		Speaker = "西西雅",
		Text = "「不会太累」这句话，我从你嘴里听过很多次，没有一次是真的。",
	},
	[20170167] = {
		ID = 20170167,
		Speaker = "我",
		Text = "这次真的不一样，就转转手腕、压压腿。",
	},
	[20170168] = {
		ID = 20170168,
		Text = "我示范了几个简单的伸展动作，西西雅半信半疑地跟着做。",
	},
	[20170169] = {
		ID = 20170169,
		Text = "接着便听到西西雅的骨头传来僵硬的喀喀声。",
	},
	[20170170] = {
		ID = 20170170,
		Speaker = "西西雅",
		Text = "啊啊啊……骨折了。",
	},
	[20170171] = {
		ID = 20170171,
		Speaker = "西西雅",
		Text = "这个角度……肌肉在抗议。",
	},
	[20170172] = {
		ID = 20170172,
		Speaker = "我",
		Text = "才伸展而已，妳的肌肉抗议得也太快了。",
	},
	[20170173] = {
		ID = 20170173,
		Speaker = "我",
		Text = "倒不如说就是你整天坐在椅子上才会这样。",
	},
	[20170174] = {
		ID = 20170174,
		Speaker = "西西雅",
		Text = "我的身体可比我诚实多了。",
	},
	[20170175] = {
		ID = 20170175,
		Speaker = "我",
		Text = "把身体放轻松一点。",
	},
	[20170176] = {
		ID = 20170176,
		Speaker = "西西雅",
		Text = "你讲得好像很专业，别忘了平时的你也没认真运动过几次。",
	},
	[20170177] = {
		ID = 20170177,
		Speaker = "我",
		Text = "至少我不会热身完就趴下。",
	},
	[20170178] = {
		ID = 20170178,
		Speaker = "西西雅",
		Text = "不过就是热身而已，我的身体可没有那么脆弱。",
	},
	[20170179] = {
		ID = 20170179,
	},
	[20170180] = {
		ID = 20170180,
	},
	[20170181] = {
		ID = 20170181,
		Speaker = "西西雅",
		Text = "眼睛，我的眼睛！",
	},
	[20170182] = {
		ID = 20170182,
		Speaker = "西西雅",
		Text = "快关上灯，我病弱的身体要化为尘埃了。",
	},
	[20170183] = {
		ID = 20170183,
		Speaker = "我",
		Text = "太夸张了吧！我们船上可没有吸血鬼！",
	},
	[20170184] = {
		ID = 20170184,
		Speaker = "我",
		Text = "是还没有。",
	},
	[20170185] = {
		ID = 20170185,
		Speaker = "西西雅",
		Text = "那太好了，带上这本书去找你的吸血鬼吧，让我躺回我的窝里面。",
	},
	[20170186] = {
		ID = 20170186,
		Text = "西西雅用毯子盖住了脸。",
	},
	[20170187] = {
		ID = 20170187,
		Speaker = "我",
		Text = "妳知道妳现在看起来就像被抓去体检的猫吗。",
	},
