	[20170388] = {
		ID = 20170388,
		Speaker = "西西雅",
		Text = "反正也不是什么了不起的技能。",
	},
	[20170389] = {
		ID = 20170389,
		Speaker = "我",
		Text = "你脸上的得意都已经满出来了，简直就像是在等我夸奖你。",
	},
	[20170390] = {
		ID = 20170390,
		Speaker = "西西雅",
		Text = "才没有，谁需要你的肯定了。",
	},
	[20170391] = {
		ID = 20170391,
		Speaker = "我",
		Text = "行行行，妳没有，要不要先休息一下？",
