	[20170393] = {
		ID = 20170393,
		Speaker = "我",
		Text = "喔？",
	},
	[20170394] = {
		ID = 20170394,
		Speaker = "西西雅",
		Text = "嗯？",
	},
	[20170395] = {
		ID = 20170395,
		Speaker = "西西雅",
		Text = "干嘛露出那股恶心的笑脸……",
	},
	[20170396] = {
		ID = 20170396,
		Speaker = "我",
		Text = "嘿嘿嘿——",
	},
	[20170398] = {
		ID = 20170398,
		Speaker = "西西雅",
		Text = "咿！你你你你你——",
	},
	[20170399] = {
		ID = 20170399,
		Text = "在西西雅没反应过来前，我就用手托住了西西雅的身子。",
	},
	[20170400] = {
		ID = 20170400,
		Text = "将她公主抱了起来，慢慢的走到树下。",
	},
	[20170401] = {
		ID = 20170401,
		Speaker = "西西雅",
		Text = "你到底在做什么，又是性骚扰吗？",
	},
	[20170402] = {
		ID = 20170402,
		Speaker = "西西雅",
		Text = "这绝对是性骚扰吧？",
	},
	[20170403] = {
		ID = 20170403,
		Text = "我将西西雅放在树荫底下的长椅坐下。",
	},
	[20170404] = {
		ID = 20170404,
		Text = "她一坐下就没忍住喘了口气，肩膀微微垮下来。",
	},
	[20170407] = {
		ID = 20170407,
		Speaker = "我",
		Text = "什么？",
	},
	[20170408] = {
		ID = 20170408,
		Speaker = "西西雅",
		Text = "没——事——",
	},
	[20170409] = {
		ID = 20170409,
		Text = "风从树叶间筛下来，她闭着眼睛靠在椅背上，重重的叹了口气。",
	},
	[20170410] = {
		ID = 20170410,
		Speaker = "西西雅",
		Text = "说起来，我很久没有这样单纯散步了。",
	},
	[20170411] = {
		ID = 20170411,
		Text = "清凉的风迎面而来，要聊聊什么吗？",
	},
	[20170412] = {
		ID = 20170412,
	},
	[20170413] = {
		ID = 20170413,
	},
	[20170414] = {
		ID = 20170414,
		Speaker = "我",
		Text = "妳平常都在做什么？",
	},
	[20170415] = {
		ID = 20170415,
		Speaker = "西西雅",
		Text = "看书、躺着、被瑟蕾雅端东西进来。",
	},
	[20170418] = {
		ID = 20170418,
		Speaker = "我",
		Text = "妳跟瑟蕾雅认识很久了吧？",
	},
	[20170419] = {
		ID = 20170419,
		Speaker = "西西雅",
		Text = "从我还走不稳的时候就认识了。",
