	[20170422] = {
		ID = 20170422,
		Speaker = "西西雅",
		Text = "理所当然地帮我做着那些根本不应该做的事情。",
	},
	[20170423] = {
		ID = 20170423,
		Text = "她说这话的语气，比平常任何一句抱怨都要平静，平静到有点不像在讲自己的事。",
	},
	[20170424] = {
		ID = 20170424,
		Speaker = "我",
		Text = "妳講得这么轻松，我还以为妳在念别人的故事。",
	},
	[20170425] = {
		ID = 20170425,
		Speaker = "西西雅",
		Text = "反正都过去了，对我来说，能活到现在，每一天都像是故事一样。",
	},
	[20170426] = {
		ID = 20170426,
		Speaker = "我",
		Text = "一样的精彩吗？",
	},
	[20170427] = {
		ID = 20170427,
		Speaker = "西西雅",
		Text = "一样的没有意义。",
	},
	[20170428] = {
		ID = 20170428,
		Speaker = "我",
		Text = "……",
	},
	[20170429] = {
		ID = 20170429,
		Text = "我没有再追问，只是任由沉默留了一下，让风把话题轻轻带过去。",
	},
	[20170430] = {
		ID = 20170430,
		Speaker = "西西雅",
		Text = "……不过，能一直被照顾到现在，也不算太糟。",
