	[20170447] = {
		ID = 20170447,
		Speaker = "西西雅",
		Text = "讨厌喔，一点都不开心。",
	},
	[20170448] = {
		ID = 20170448,
		Speaker = "西西雅",
		Text = "我想想，船长大人的讨厌程度可以到第三名了呢。",
	},
	[20170450] = {
		ID = 20170450,
		Speaker = "我",
		Text = "那真是太好了呢。",
	},
	[20170451] = {
		ID = 20170451,
		Speaker = "西西雅",
		Text = "好什么？",
	},
	[20170452] = {
		ID = 20170452,
		Speaker = "我",
		Text = "只要继续努力，最讨厌的最后一名，就是最喜欢了吧。",
