	},
	[40020629] = {
		ID = 40020629,
		Text = "飞船深处的引擎震动一路传到脚底，可越靠近勒瓦杜兰的舱房，那点暖意就越薄。",
	},
	[40020001] = {
		ID = 40020001,
	},
	[40020002] = {
		ID = 40020002,
		Text = "总觉得四周有些奇怪。",
	},
	[40020003] = {
		ID = 40020003,
		Text = "准确来说，是温暖到不正常，我很确定自己前一夜还在冰雪星球上……",
	},
	[40020004] = {
		ID = 40020004,
		Text = "跟谁……喝了点酒？",
	},
	[40020005] = {
		ID = 40020005,
	},
	[40020006] = {
		ID = 40020006,
	},
	[40020007] = {
		ID = 40020007,
		Text = "我撑起身体四下张望——除了随风起伏的草浪跟蓝得发亮的天空，什么都没有。",
	},
	[40020008] = {
		ID = 40020008,
		Speaker = "我",
		Text = "……这是哪里啊？",
	},
	[40020009] = {
		ID = 40020009,
		Text = "就在我还在确认自己的心脏有有没有被挖掉时，远处传来一阵熟悉又极度不熟悉的笑声。",
	},
	[40020010] = {
		ID = 40020010,
		Text = "我抬头望去，看见西西雅抛下披肩，在花丛间连蹦带跳地追一只蝴蝶。",
	},
	[40020011] = {
		ID = 40020011,
		Text = "她笑得毫无防备，脸颊还带着红润的气色——那根本不是我认识的病弱系女子的西西雅。",
	},
	[40020012] = {
		ID = 40020012,
		Speaker = "我",
		Text = "……啊？西西雅？",
	},
	[40020013] = {
		ID = 40020013,
		Speaker = "西西雅",
		Text = "唔咕！",
	},
	[40020014] = {
		ID = 40020014,
		Text = "（她像被踩到尾巴一样僵住，指尖那只蝴蝶趁机飘走了。）",
	},
	[40020015] = {
		ID = 40020015,
		Speaker = "西西雅",
		Text = "咳，咳咳。",
	},
	[40020016] = {
		ID = 40020016,
		Speaker = "西西雅",
		Text = "你终于醒了，我以为你要睡到日落呢。",
	},
	[40020018] = {
		ID = 40020018,
		Speaker = "西西雅",
		Text = "别用那种眼神看我！你刚刚什么都没有看见！",
	},
	[40020020] = {
		ID = 40020020,
		Speaker = "西西雅",
		Text = "才没有。",
	},
	[40020021] = {
		ID = 40020021,
		Speaker = "西西雅",
		Text = "咳咳！重点是，你终于肯醒了。",
	},
	[40020022] = {
		ID = 40020022,
		Text = "她的声音又变回不抱希望那个的语气——只是眼底还残留着刚刚的兴奋未散去。",
	},
	[40020024] = {
		ID = 40020024,
		Speaker = "西西雅",
		Text = "不知道，我醒来的时候，你已经躺在这里了。",
	},
	[40020025] = {
		ID = 40020025,
		Speaker = "西西雅",
		Text = "话先说在前头，要我照顾你是不可能的喔，我已经准备好丢下船长先生了。",
	},
	[40020027] = {
		ID = 40020027,
		Speaker = "西西雅",
		Text = "草原，没有瞎的话应该是很明显的吧？",
	},
	[40020029] = {
		ID = 40020029,
		Speaker = "西西雅",
		Text = "因为答案就是不知道，没必要拖时间。",
	},
	[40020031] = {
		ID = 40020031,
		Speaker = "西西雅",
		Text = "我是在侦察地形！",
	},
	[40020032] = {
		ID = 40020032,
		Speaker = "西西雅",
		Text = "不要一直打乱我的节奏。",
	},
	[40020033] = {
		ID = 40020033,
		Speaker = "西西雅",
		Text = "总之，这里确实不对。天空太干净，风太温柔，连草的味道都甜得不像真的。",
	},
	[40020035] = {
		ID = 40020035,
		Speaker = "西西雅",
		Text = "因为这里本来就不是。",
	},
	[40020037] = {
		ID = 40020037,
		Speaker = "西西雅",
		Text = "只知道一件事——我醒来的时候，身体是舒服的。",
	},
	[40020038] = {
		ID = 40020038,
		Speaker = "西西雅",
		Text = "感觉不到心脏的绞痛，也不会有呼吸不顺的感觉。",
	},
	[40020039] = {
		ID = 40020039,
		Speaker = "西西雅",
		Text = "简直就像……我不知道，有一颗全新的心脏！",
	},
	[40020041] = {
		ID = 40020041,
		Speaker = "西西雅",
		Text = "好过头的事情，通常都要另外付出代价的。",
	},
	[40020043] = {
		ID = 40020043,
		Speaker = "西西雅",
		Text = "至少这样我还能确定我还是我自己，这样你也更放心吧。",
	},
	[40020046] = {
		ID = 40020046,
		Speaker = "西西雅",
		Text = "在你还没醒之前，我已经绕着这附近走了一圈。",
