	},
	[40020082] = {
		ID = 40020082,
		Speaker = "艾蕾娜",
		Text = "那里住着一位魔法师，据说她能实现任何愿望，就像是传说中的希望女神。",
	},
	[40020084] = {
		ID = 40020084,
		Speaker = "艾蕾娜",
		Text = "嗯？",
