	[40020588] = {
		ID = 40020588,
		Speaker = "西西雅",
		Text = "但是，是从什么时候开始，我为了活着而忘记了追逐蝴蝶，忘记了书写童话的快乐。",
	},
	[40020589] = {
		ID = 40020589,
		Speaker = "西西雅",
		Text = "没日没夜的恐惧死亡，恐惧明天的到来。",
	},
	[40020590] = {
		ID = 40020590,
		Speaker = "西西雅",
		Text = "除了苟活，我的生命早就失去了意义。",
	},
	[40020592] = {
		ID = 40020592,
		Speaker = "西西雅",
		Text = "童话里的愿望太方便了，方便到让人忍不住忘记，现实里根本没有这种好事。",
	},
	[40020593] = {
		ID = 40020593,
		Speaker = "西西雅",
		Text = "我的心脏不会因为说一句「拜托了」就突然变好，复健很痛，药很难吃，明天也不一定会比今天好。",
	},
	[40020594] = {
		ID = 40020594,
		Speaker = "西西雅",
		Text = "……可是那又怎样？至少明天还没来。在它来以前，我还有很多事情可以试。",
	},
	[40020595] = {
		ID = 40020595,
		Speaker = "瑟蕾雅",
		Text = "但如果一切都没有变好，你仍然死去了呢……？",
	},
	[40020596] = {
		ID = 40020596,
		Speaker = "西西雅",
		Text = "那我就从今天开始，抱着对明天的期待，那样不管完结在哪里，我都不会后悔",
	},
	[40020597] = {
		ID = 40020597,
		Speaker = "西西雅",
		Text = "请听我真正的愿望吧。",
	},
	[40020598] = {
		ID = 40020598,
		Text = "西西雅转向我，露出了笑意。",
	},
	[40020599] = {
		ID = 40020599,
		Speaker = "西西雅",
		Text = "我想回到，那个期待春天的自己。",
	},
	[40020600] = {
		ID = 40020600,
		Speaker = "西西雅",
		Text = "不论多么痛苦，都想要透过治疗变得健康的自己。",
	},
	[40020601] = {
		ID = 40020601,
		Speaker = "西西雅",
		Text = "无论明天会怎么样，都想要更努力一点翻遍所有书本的自己。",
	},
	[40020602] = {
		ID = 40020602,
		Speaker = "西西雅",
		Text = "我真正的愿望，是希望自己能永远维持那份「渴望追寻愿望的心」。",
	},
	[40020603] = {
		ID = 40020603,
		Speaker = "瑟蕾雅",
		Text = "渴望追寻愿望的心……",
	},
	[40020604] = {
		ID = 40020604,
		Speaker = "西西雅",
		Text = "没错，就算最后什么都没有变，我也不想变成一个不敢再许愿的人。",
	},
	[40020605] = {
		ID = 40020605,
		Speaker = "瑟蕾雅",
		Text = "西西……妳……",
	},
	[40020606] = {
		ID = 40020606,
		Speaker = "西西雅",
		Text = "我想要回家。",
	},
	[40020607] = {
		ID = 40020607,
		Speaker = "西西雅",
		Text = "然后靠着改变自己，让自己变得更健康——不是靠一句愿望，是靠我自己。",
	},
	[40020609] = {
		ID = 40020609,
		Speaker = "西西雅",
		Text = "与其让一句愿望，帮我把最痛的那一页撕掉，我宁可自己一页一页重新写。",
	},
	[40020610] = {
		ID = 40020610,
		Speaker = "西西雅",
		Text = "而且，你会陪我一起写的，不是吗？还有大家。",
	},
	[40020611] = {
		ID = 40020611,
		Speaker = "瑟蕾雅",
		Text = "西西，你……",
	},
	[40020612] = {
		ID = 40020612,
		Speaker = "瑟蕾雅",
		Text = "啊……我，我真的，不知道该说什么才好。",
	},
	[40020614] = {
		ID = 40020614,
		Speaker = "瑟蕾雅",
		Text = "咦咦咦？我的表情怎么了！",
	},
	[40020615] = {
		ID = 40020615,
		Speaker = "西西雅",
		Text = "妳现在的表情，大概是快要哭出来又不想承认的那种。",
	},
	[40020616] = {
		ID = 40020616,
		Text = "瑟蕾雅用手背抹了一下眼角，张开了手臂，一步一步走向西西雅，像是怕她会突然逃走一样，走得很慢，很小心。",
	},
	[40020617] = {
		ID = 40020617,
		Speaker = "瑟蕾雅",
		Text = "你真让我为你感到骄傲。",
	},
	[40020618] = {
		ID = 40020618,
		Speaker = "西西雅",
		Text = "喂……很难呼吸，妳抱太紧了。",
	},
	[40020619] = {
		ID = 40020619,
		Speaker = "瑟蕾雅",
		Text = "不要，再让我抱一下下就好。",
	},
	[40020621] = {
		ID = 40020621,
		Speaker = "西西雅",
		Text = "谁准你在这种时候讲废话了。",
	},
	[40020622] = {
		ID = 40020622,
		Speaker = "瑟蕾雅",
		Text = "好啦好啦——那么，西西，我都听清楚了。",
	},
	[40020623] = {
		ID = 40020623,
		Speaker = "瑟蕾雅",
		Text = "回家，然后靠自己变健康——这个愿望，不需要魔法，我只送你们一程就好。",
	},
	[40020625] = {
		ID = 40020625,
		Speaker = "瑟蕾雅",
		Text = "接下来啊……闭上眼睛，一下下就好。",
	},
	[40020626] = {
		ID = 40020626,
		Speaker = "瑟蕾雅",
		Text = "路上小心哟，晨星先生、西西。",
	},
	[40020627] = {
		ID = 40020627,
	},
	[40020628] = {
		ID = 40020628,
	},
	[40020630] = {
		ID = 40020630,
		Speaker = "勒瓦杜兰",
		Text = "进来。",
	},
	[40020659] = {
		ID = 40020659,
	},
	[20030401] = {
		ID = 20030401,
		Speaker = "赛诃希丝",
		Text = "我们各退一步好不好……",
	},
	[20030006] = {
		ID = 20030006,
		Text = "（赛诃希丝穿着小熊图案的棉睡衣，头上的角还套着一双毛线手套。）",
	},
	[20030050] = {
		ID = 20030050,
		Text = "（赛诃希丝穿着小熊图案的棉睡衣，头上的角还套着一双毛线手套。）",
	},
	[20030091] = {
		ID = 20030091,
		Text = "（赛诃希丝穿着小熊图案的棉睡衣，头上的角还套着一双毛线手套。）",
	},
	[20030148] = {
		ID = 20030148,
		Text = "（随后赛诃希丝恢复成平时的裸体。）",
	},
	[20030177] = {
		ID = 20030177,
		Text = "（随后赛诃希丝恢复成平时的裸体。）",
	},
	[20030380] = {
		ID = 20030380,
		Text = "（塞诃希丝压到我的身上。）",
	},
	[20030391] = {
		ID = 20030391,
		Speaker = "我",
		Text = "是你先低俗的，我只是以其人之道还治其人之身而已！",
	},
	[20030523] = {
		ID = 20030523,
		Speaker = "我",
		Text = "没想到你还有发出这种声音向我求饶的一天啊？",
	},
	[30160257] = {
		ID = 30160257,
		Speaker = "艾蕾娜",
		Text = "啊……啊啊……船长、船长、记不下来、太多了、根本记不下来",
	},
	[30160258] = {
		ID = 30160258,
		Speaker = "艾蕾娜",
		Text = "原来自己摸的时候不算数、原来要有船长才算数、每天都想要、每天每天都想要、上次也是、这次也是、下次也是、原来我想要的是船长！",
	},
	[30160259] = {
		ID = 30160259,
		Speaker = "艾蕾娜",
		Text = "船长、船长、不要停、不要停、再深一点、再用力一点、我自己摸绝对做不到这样、船长、再多一点……",
	},
	[30160260] = {
		ID = 30160260,
		Speaker = "艾蕾娜",
		Text = "！ ！ ！",
	},
	[20050368] = {
		ID = 20050368,
		Speaker = "黛莉亚",
		Text = "不是你说要喂机油的吗？不然应该喂什么？",
	},
	[40010784] = {
		ID = 40010784,
		Speaker = "我",
		Text = "在说什么，要求饶了吗？",
	},
	[10060217] = {
		ID = 10060217,
		Speaker = "首领",
		Text = "但这些从蒸气星球来的废物，吃我们的、喝我们的、抢我们的，",
	},
	[10060244] = {
		ID = 10060244,
		Speaker = "首领",
		Text = "劝你识相一点。这里不是蒸气星球！",
	},
	[10060378] = {
		ID = 10060378,
		Text = "喔？你该不会是曾经出现在蒸气星球的『会飞的暴露狂』？",
	},
	[20100556] = {
		ID = 20100556,
		Speaker = "耶珥",
		Text = "呜欧欧……居然还在变大。",
	},
	[20100561] = {
		ID = 20100561,
		Speaker = "耶珥",
		Text = "像这样在里面一抖一抖的，快一点……",
	},
	[30130061] = {
		ID = 30130061,
		Speaker = "伊丝娜",
		Text = "来，深呼吸一下，再忍耐一下……",
	},
	[20130228] = {
		ID = 20130228,
		Speaker = "伊丝娜",
		Text = "突然一夕之间就变成这个样子了。",
	},
	[40010218] = {
		ID = 40010218,
		Text = "（耶珥用一种奇怪的目光盯着我瞧，我顺着她的目光向下看去，才终于找到了异状的来源。）",
	},
	[40010228] = {
		ID = 40010228,
		Text = "我必须填这些字跑动画",
	},
	[40010229] = {
		ID = 40010229,
		Text = "我必须填这些字跑动画",
	},
	[40010448] = {
		ID = 40010448,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……那么，就让我好好招待两位贵宾吧。",
	},
	[40010583] = {
		ID = 40010583,
		Speaker = "我",
		Text = "好像是，把木头移开一点看看，你去。",
	},
	[40010732] = {
		ID = 40010732,
		Speaker = "耶珥",
		Text = "不过老实说啊，真的挺好玩的喔。",
	},
	[40010744] = {
		ID = 40010744,
		Speaker = "我",
		Text = "所以说，从头到尾真正在当反派的，其实另有其人啊。",
	},
	[40010001] = {
		ID = 40010001,
	},
	[40010002] = {
		ID = 40010002,
		Text = "（夏夜闷热，蝉鸣把周围围得密不透风。)",
	},
	[40010003] = {
		ID = 40010003,
		Text = "（离飞船不远的空地里，篝火把四周的树干映成暗橘色。四个人影围着火坐了下来——）",
	},
	[40010004] = {
		ID = 40010004,
		Speaker = "黛莉亚",
		Text = "从前，有个村庄，每到半夜都传来奇怪的声音！",
	},
	[40010005] = {
		ID = 40010005,
		Speaker = "黛莉亚",
		Text = "呻吟声、哀嚎声，所有人都不敢出门！",
	},
	[40010006] = {
		ID = 40010006,
		Speaker = "黛莉亚",
		Text = "后来有个勇者去追声音的源头——",
	},
	[40010007] = {
		ID = 40010007,
		Speaker = "黛莉亚",
		Text = "最后……当她到达了声音的尽头……他看见了——",
	},
	[40010008] = {
		ID = 40010008,
		Speaker = "黛莉亚",
		Text = "蒸汽锅炉密封胶老化！每到夜晚气温下降就热胀冷缩发出异响！",
	},
	[40010009] = {
		ID = 40010009,
		Speaker = "黛莉亚",
		Text = "他把锅炉修好了！村庄从此太平！感动吧！",
	},
	[40010010] = {
		ID = 40010010,
		Speaker = "秋比",
		Text = "哇！修好了！太棒了！",
	},
	[40010011] = {
		ID = 40010011,
	},
	[40010012] = {
		ID = 40010012,
		Text = "黛莉亚的身子站直，双手在空中不断挥舞，仿佛说的都是真实故事。",
	},
	[40010013] = {
		ID = 40010013,
		Text = "但显然除了秋比之外没有人对于黛莉亚的故事有所反应。",
	},
	[40010014] = {
		ID = 40010014,
		Speaker = "伊丝娜",
		Text = "黛莉亚，那个故事根本没有鬼啊！",
	},
	[40010015] = {
		ID = 40010015,
		Speaker = "我",
		Text = "我们到底为什么要坐在森林里面听鬼故事？",
	},
	[40010016] = {
		ID = 40010016,
		Speaker = "伊丝娜",
		Text = "后辈，我在测试你们的心理承受能力。",
	},
	[40010017] = {
		ID = 40010017,
		Speaker = "伊丝娜",
		Text = "别把它想成在玩乐，虽然……",
	},
	[40010018] = {
		ID = 40010018,
		Speaker = "伊丝娜",
		Text = "这样其实也挺有趣的嘛。",
	},
	[40010019] = {
		ID = 40010019,
		Speaker = "我",
		Text = "我看学姊也是乐在其中吧？",
	},
	[40010020] = {
		ID = 40010020,
		Speaker = "秋比",
		Text = "秋比知道一个很可怕的，就是那种砰～一声大家都吓到的！",
	},
	[40010021] = {
		ID = 40010021,
		Speaker = "我",
		Text = "从很多方面来说，那确实非常吓人……",
	},
	[40010022] = {
		ID = 40010022,
		Speaker = "我",
		Text = "但今天要的不是这种。",
	},
	[40010023] = {
		ID = 40010023,
		Speaker = "我",
		Text = "总之，还有谁有鬼故事吗？",
	},
	[40010024] = {
		ID = 40010024,
		Speaker = "黛莉亚",
		Text = "我！我还有一个！",
	},
	[40010025] = {
		ID = 40010025,
		Speaker = "伊丝娜",
		Text = "你已经说够多个了，换你了吧，学弟？",
	},
	[40010026] = {
		ID = 40010026,
		Text = "三双眼睛往我这边看过来。",
	},
	[40010027] = {
		ID = 40010027,
		Speaker = "我",
		Text = "好了，换我了，做好心理准备吧，因为——",
	},
	[40010028] = {
		ID = 40010028,
		Text = "（我把提灯移到脸前，把灯对准了自己的下巴。）",
	},
	[40010029] = {
		ID = 40010029,
		Speaker = "我",
		Text = "接下来我要说的是真实故事！",
	},
	[40010030] = {
		ID = 40010030,
		Speaker = "秋比",
		Text = "哇……脸好奇怪！",
	},
	[40010031] = {
		ID = 40010031,
		Speaker = "我",
		Text = "从前，有一片森林……",
	},
	[40010032] = {
		ID = 40010032,
	},
	[40010033] = {
		ID = 40010033,
	},
	[40010034] = {
		ID = 40010034,
		Speaker = "？ ？",
		Text = "看起来好像挺有趣的呢～",
	},
	[40010035] = {
		ID = 40010035,
		Speaker = "？ ？",
		Text = "让姊姊我也稍微参与一下吧，不过——",
	},
	[40010036] = {
		ID = 40010036,
		Speaker = "？ ？",
		Text = "——果然还是得要有一些更有趣的事情发生才行呢～",
	},
	[40010037] = {
		ID = 40010037,
	},
	[40010038] = {
		ID = 40010038,
	},
	[40010039] = {
		ID = 40010039,
		Text = "（鬼故事才说到一半，我抬起头——才注意到篝火光芒边缘有什么东西在飘。）",
	},
	[40010040] = {
		ID = 40010040,
		Text = "（淡绿色的光点像是鳞粉一样撒下，顺着源头看去，一个带着尖帽的影子隐藏在枝桠间。）",
	},
	[40010041] = {
		ID = 40010041,
		Speaker = "秋比",
		Text = "秋比……好困……",
	},
	[40010042] = {
		ID = 40010042,
		Speaker = "黛莉亚",
		Text = "舰长你的故事……太无聊了啦……",
	},
	[40010043] = {
		ID = 40010043,
		Text = "（一种说不出的怪异感弥漫在周围，但又像是被遮蔽，无法说出口。）",
	},
	[40010044] = {
		ID = 40010044,
		Text = "（意识开始像泡在温水里，慢慢变得模糊。篝火的形状扭曲了，树木变高变暗。）",
	},
	[40010045] = {
		ID = 40010045,
		Text = "（最后只见到一个绿色的人影走到身前。）",
	},
	[40010046] = {
		ID = 40010046,
		Speaker = "？ ？",
		Text = "真可爱的睡脸呢。",
	},
	[40010047] = {
		ID = 40010047,
		Speaker = "？ ？",
		Text = "哎呀，你也在呢，那你也一起来吧，呵呵～",
	},
	[40010048] = {
		ID = 40010048,
		Text = "（之后一切便消失在黑暗里。）",
	},
	[40010049] = {
		ID = 40010049,
	},
	[40010050] = {
		ID = 40010050,
	},
	[40010051] = {
		ID = 40010051,
	},
	[40010052] = {
		ID = 40010052,
		Speaker = "我",
		Text = "不对劲。",
	},
	[40010053] = {
		ID = 40010053,
		Speaker = "我",
		Text = "我是什么时候来到这个地方的？",
	},
	[40010054] = {
		ID = 40010054,
		Speaker = "我",
		Text = "喂？伊丝娜？黛莉亚？秋比？ ……任何人都行。",
	},
	[40010055] = {
		ID = 40010055,
		Speaker = "我",
		Text = "……不对。刚才不是还在一起的吗？",
	},
	[40010056] = {
		ID = 40010056,
		Speaker = "？ ？",
		Text = "呵呵……啊啦，少年也在这里啊？",
	},
	[40010057] = {
		ID = 40010057,
		Text = "（我靠着手中唯一的光源勉强辨认自己在一间洋馆内。）",
	},
	[40010058] = {
		ID = 40010058,
		Text = "（只是我不记得原先外面下着这么大的雷雨。）",
	},
	[40010059] = {
		ID = 40010059,
		Text = "（熟悉的声音从斜上方传来，带着一贯的悠闲。）",
	},
	[40010060] = {
		ID = 40010060,
		Speaker = "我",
		Text = "！ ？",
	},
	[40010061] = {
		ID = 40010061,
		Speaker = "我",
		Text = "你是——耶珥？ ？",
	},
	[40010062] = {
		ID = 40010062,
		Text = "我将提灯的光源照往声音的来源。",
	},
	[40010063] = {
		ID = 40010063,
		Text = "耶珥像是已经久候多时一般，慵懒的在沙发上回应。",
	},
	[40010064] = {
		ID = 40010064,
		Speaker = "耶珥",
		Text = "哎呀，直接照脸，少年可真没礼貌。",
	},
	[40010065] = {
		ID = 40010065,
		Speaker = "我",
		Text = "你在这里干什么！",
	},
	[40010066] = {
		ID = 40010066,
		Speaker = "耶珥",
		Text = "面对淑女居然用如此粗暴的方式提问吗？",
	},
	[40010067] = {
		ID = 40010067,
		Speaker = "耶珥",
		Text = "少年你期望从妾身身上得到什么答案呢？",
	},
	[40010068] = {
		ID = 40010068,
		Speaker = "我",
		Text = "先告诉我这里是哪里？",
	},
	[40010069] = {
		ID = 40010069,
		Speaker = "耶珥",
		Text = "嗯～好问题呢，这个妾身也没办法准确回答。",
	},
	[40010070] = {
		ID = 40010070,
		Speaker = "我",
		Text = "你确定这一切真的不是你搞的鬼吗？",
	},
	[40010071] = {
		ID = 40010071,
		Speaker = "耶珥",
		Text = "哦？少年挺敏锐的，看来成长了许多呢。",
	},
	[40010072] = {
		ID = 40010072,
		Speaker = "耶珥",
		Text = "好吧，这次妾身就破例的多说一点点吧。",
	},
	[40010073] = {
		ID = 40010073,
		Speaker = "耶珥",
		Text = "妾身确实「本来」是在树上偷看你们。",
	},
	[40010074] = {
		ID = 40010074,
		Speaker = "耶珥",
		Text = "觉得很有意思，打算找点乐子捉弄少年。",
	},
	[40010075] = {
		ID = 40010075,
		Speaker = "我",
		Text = "……",
	},
	[40010076] = {
		ID = 40010076,
		Speaker = "耶珥",
		Text = "但那是一开始的计画，妾身真的只是刚好路过，这点少年绝对可以相信。",
	},
	[40010077] = {
		ID = 40010077,
		Speaker = "耶珥",
		Text = "妾身吹了点助眠的粉末——让你们能做个带点惊吓感的梦。",
	},
	[40010078] = {
		ID = 40010078,
		Speaker = "我",
		Text = "助眠的粉末！ ？",
	},
	[40010079] = {
		ID = 40010079,
		Speaker = "耶珥",
		Text = "不要这么惊讶，原本很简单的。",
	},
	[40010080] = {
		ID = 40010080,
		Speaker = "耶珥",
		Text = "你们睡着，吓得人仰马翻，妾身在旁边偷笑。",
	},
	[40010081] = {
		ID = 40010081,
		Speaker = "耶珥",
		Text = "然后你们醒来，什么事都没发生。",
