	[40010082] = {
		ID = 40010082,
		Speaker = "耶珥",
		Text = "很有趣对吧？",
	},
	[40010083] = {
		ID = 40010083,
		Speaker = "我",
		Text = "这哪叫「什么事都没有」，你这根本就是恶作剧找麻烦！",
	},
	[40010084] = {
		ID = 40010084,
		Speaker = "耶珥",
		Text = "啊啦，少年的反应比妾身预期的激烈呢。",
	},
	[40010085] = {
		ID = 40010085,
		Speaker = "我",
		Text = "重点不是这个！那这个地方是怎么回事？",
	},
	[40010086] = {
		ID = 40010086,
		Speaker = "耶珥",
		Text = "这正是问题所在。",
	},
	[40010087] = {
		ID = 40010087,
		Speaker = "耶珥",
		Text = "妾身也没料到，会有个奇怪的力量介入。不是妾身的——是某个说不清楚的东西，把我们卷进这里来的。",
	},
	[40010088] = {
		ID = 40010088,
		Speaker = "我",
		Text = "「奇怪的力量」……这种说法太模糊了。",
	},
	[40010089] = {
		ID = 40010089,
		Speaker = "耶珥",
		Text = "妾身也只能这样说，因为妾身也看不清楚那是什么。只知道，那个东西不属于这片森林，也不属于妾身。",
	},
	[40010090] = {
		ID = 40010090,
		Speaker = "我",
		Text = "不属于这片森林……你的意思是，这里不是正常的森林？",
	},
	[40010091] = {
		ID = 40010091,
		Speaker = "耶珥",
		Text = "少年走了这么久，还没感觉到吗？",
	},
	[40010092] = {
		ID = 40010092,
		Speaker = "我",
		Text = "……说起来，这里的空气好像跟刚才不一样。",
	},
	[40010093] = {
		ID = 40010093,
		Speaker = "耶珥",
		Text = "呵呵，说得对。",
	},
	[40010094] = {
		ID = 40010094,
		Speaker = "我",
		Text = "你不能跟之前一样用魔法什么的带我们出去吗？",
	},
	[40010095] = {
		ID = 40010095,
		Speaker = "耶珥",
		Text = "呵呵……这正是妾身需要告诉少年的事。",
	},
	[40010096] = {
		ID = 40010096,
		Speaker = "耶珥",
		Text = "在这个空间里，妾身没有任何力量，顶多打个小小的光源喔。",
	},
	[40010097] = {
		ID = 40010097,
		Speaker = "我",
		Text = "……什么？",
	},
	[40010098] = {
		ID = 40010098,
		Speaker = "耶珥",
		Text = "就是字面上的意思。在这里，妾身不过是个弱女子而已。",
	},
	[40010099] = {
		ID = 40010099,
		Speaker = "我",
		Text = "你说这种话，你觉得我会信？",
	},
	[40010100] = {
		ID = 40010100,
		Text = "（耶珥凑到我的耳边。）",
	},
	[40010101] = {
		ID = 40010101,
		Speaker = "耶珥",
		Text = "少年可以试试，现在不管对姊姊我做任何事情，妾身大概都反抗不了的喔～",
	},
	[40010102] = {
		ID = 40010102,
		Text = "（耶珥胸部几乎贴到我的手臂上，在这种距离下才看得更清楚。）",
	},
	[40010103] = {
		ID = 40010103,
		Text = "（这个人平时就穿成这个样子到处走吗？）",
	},
	[40010104] = {
		ID = 40010104,
		Speaker = "我",
		Text = "咳……好……好吧，我就姑且相信你吧……",
	},
	[40010105] = {
		ID = 40010105,
		Speaker = "我",
		Text = "但在我们找到离开的方法之前，你可别动什么歪脑筋。",
	},
	[40010106] = {
		ID = 40010106,
		Speaker = "耶珥",
		Text = "呵呵～真是太好了，少年你可要对妾身这个弱女子温柔一点喔～",
	},
	[40010107] = {
		ID = 40010107,
	},
	[40010108] = {
		ID = 40010108,
	},
	[40010109] = {
		ID = 40010109,
		Text = "（我仔细端详着室内的所有摆设。）",
	},
	[40010110] = {
		ID = 40010110,
		Text = "（我和耶珥两人四处探索，走到了洋馆的大厅。）",
	},
	[40010111] = {
		ID = 40010111,
		Text = "（壁炉中还燃着温暖的火，桌上什至摆了一壶还冒着热雾的茶。）",
	},
	[40010112] = {
		ID = 40010112,
		Speaker = "耶珥",
		Text = "嗯？少年，看桌上？",
	},
	[40010113] = {
		ID = 40010113,
		Speaker = "我",
		Text = "……这里感觉才刚有人住过欸。",
	},
	[40010114] = {
		ID = 40010114,
		Speaker = "耶珥",
		Text = "呵呵，少年也注意到了呢——那杯茶。",
	},
	[40010115] = {
		ID = 40010115,
		Speaker = "我",
		Text = "让我再确认一次，这真的不是你设计的吧？别跟我說妳连茶点都能无中生有。",
	},
	[40010116] = {
		ID = 40010116,
		Speaker = "耶珥",
		Text = "哎呀，妾身可没那么闲。这些东西，妾身一进来的时候就摆在这了，跟妾身没有半点关系。",
	},
	[40010117] = {
		ID = 40010117,
		Speaker = "耶珥",
		Text = "到现在还不愿意相信妾身吗？",
	},
	[40010118] = {
		ID = 40010118,
		Speaker = "我",
		Text = "怀疑你感觉是目前最容易的做法……",
	},
	[40010119] = {
		ID = 40010119,
		Speaker = "耶珥",
		Text = "少年，互相怀疑没有意义，妾身有什么理由这么做呢？",
	},
	[40010120] = {
		ID = 40010120,
		Speaker = "耶珥",
		Text = "可别忘了我们现在是同一片叶子上的蚂蚁喔。",
	},
	[40010121] = {
		ID = 40010121,
		Speaker = "耶珥",
		Text = "啊啦，少年不是自己也看见了吗？妾身何必为这种小事说谎。",
	},
	[40010122] = {
		ID = 40010122,
		Text = "（我又看了一圈——挂画端正、窗帘垂得笔直、地毯上连一个脚印都没有。）",
	},
	[40010123] = {
		ID = 40010123,
		Speaker = "我",
		Text = "所以到底是有人住，还是说这房子专门备好一切，等不速之客上门？",
	},
	[40010124] = {
		ID = 40010124,
		Speaker = "耶珥",
		Text = "你觉得呢？",
	},
	[40010125] = {
		ID = 40010125,
		Speaker = "我",
		Text = "我怎么知道，我又不是活了几千年的老怪物。",
	},
	[40010126] = {
		ID = 40010126,
		Speaker = "耶珥",
		Text = "呵呵，这句话，妾身就当作没听到好了。",
	},
	[40010127] = {
		ID = 40010127,
		Text = "（我的视线滑过茶几，停在一个瓷杯底下——边角压着一张信纸，折得整整齐齐，像是特地留给人发现的。）",
	},
	[40010128] = {
		ID = 40010128,
		Speaker = "我",
		Text = "那是什么？",
	},
	[40010129] = {
		ID = 40010129,
		Speaker = "耶珥",
		Text = "哦？看起来，少年一下子就找到今晚的重点了呢。",
	},
	[40010130] = {
		ID = 40010130,
		Text = "（信纸上的字迹工整得诡异，一笔一画都像是刻意写得漂亮，故意留给人细看。）",
	},
	[40010131] = {
		ID = 40010131,
		Speaker = "我",
		Text = "「邀请阁下与同伴，共同参加一场游戏。」",
	},
	[40010132] = {
		ID = 40010132,
		Speaker = "我",
		Text = "「游戏规则很简单——在午夜十二点以前，找出散落在这栋洋房里，几位伙伴的玩偶。」",
	},
	[40010133] = {
		ID = 40010133,
		Speaker = "我",
		Text = "「找不到的话，他们的灵魂……就会永远留在这里！？」",
	},
	[40010134] = {
		ID = 40010134,
		Text = "（念完最后一个字，手上那张薄薄的纸，突然变得很重。）",
	},
	[40010135] = {
		ID = 40010135,
		Speaker = "我",
		Text = "……这什么烂游戏，玩偶是指谁的玩偶？",
	},
	[40010136] = {
		ID = 40010136,
		Speaker = "耶珥",
		Text = "呵呵，少年要不要自己猜猜看？",
	},
	[40010137] = {
		ID = 40010137,
		Speaker = "我",
		Text = "别跟我来这套，我现在真的没空陪妳玩猜谜。",
	},
	[40010138] = {
		ID = 40010138,
		Speaker = "我",
		Text = "……算了，先不管妳信不信的问题。",
	},
	[40010139] = {
		ID = 40010139,
		Speaker = "我",
		Text = "『几位伙伴』——这栋房子里不会只有我们两个人吧。",
	},
	[40010140] = {
		ID = 40010140,
		Speaker = "我",
		Text = "该不会……",
	},
	[40010141] = {
		ID = 40010141,
		Speaker = "我",
		Text = "是学姊她们！ ？",
	},
	[40010142] = {
		ID = 40010142,
	},
	[40010143] = {
		ID = 40010143,
	},
	[40010144] = {
		ID = 40010144,
		Speaker = "我",
		Text = "「灵魂永远留在这里」……这什么恐怖片等级的措辞啊。",
	},
	[40010145] = {
		ID = 40010145,
		Speaker = "我",
		Text = "喂，耶珥。妳說妳现在什么力量都没有，对吧——",
	},
	[40010146] = {
		ID = 40010146,
		Speaker = "我",
		Text = "那好歹借我妳那颗聪明的脑袋用用。",
	},
	[40010147] = {
		ID = 40010147,
		Speaker = "我",
		Text = "信里写的这个游戏，我需要你帮助我。",
	},
	[40010148] = {
		ID = 40010148,
		Speaker = "耶珥",
		Text = "呵呵……少年，这是不是代表你终于——",
	},
	[40010149] = {
		ID = 40010149,
		Speaker = "耶珥",
		Text = "——愿意相信妾身了呢？",
	},
	[40010150] = {
		ID = 40010150,
		Speaker = "我",
		Text = "别得意得太早，这只是暂时同盟。",
	},
	[40010151] = {
		ID = 40010151,
		Speaker = "我",
		Text = "这栋房子里现在能商量事情的，也就只剩妳一个了。",
	},
	[40010152] = {
		ID = 40010152,
		Speaker = "耶珥",
		Text = "啊啦，这样的说法还真是伤人。不过——",
	},
	[40010153] = {
		ID = 40010153,
		Speaker = "耶珥",
		Text = "——妾身喜欢这种被需要的感觉。",
	},
	[40010154] = {
		ID = 40010154,
		Speaker = "我",
		Text = "听起来你是同意了喔？",
	},
	[40010155] = {
		ID = 40010155,
		Speaker = "耶珥",
		Text = "少年都亲口拜托了，妾身要是拒绝，那也太不解风情了吧？",
	},
	[40010156] = {
		ID = 40010156,
		Speaker = "我",
		Text = "妳看过信上写的规则吧——午夜十二点前找不到玩偶，大家的灵魂就永远关在这栋房子里。",
	},
	[40010157] = {
		ID = 40010157,
		Speaker = "耶珥",
		Text = "妾身当然看到了。不过少年，你有没有想过——",
	},
	[40010158] = {
		ID = 40010158,
		Speaker = "耶珥",
		Text = "会出这种题目的家伙，八成也不是什么讲道理的角色。",
	},
	[40010159] = {
		ID = 40010159,
		Speaker = "我",
		Text = "所以妳的意思是，我们只能乖乖照规则玩，还是说其实有办法作弊？",
	},
	[40010160] = {
		ID = 40010160,
		Speaker = "耶珥",
		Text = "呵呵，作弊这种事妾身最喜欢了——",
	},
	[40010161] = {
		ID = 40010161,
		Speaker = "耶珥",
		Text = "可惜现在一点力量都使不出来，也就只能老老实实陪你动脑。",
	},
	[40010162] = {
		ID = 40010162,
		Speaker = "耶珥",
		Text = "你的话肯定会比妾身更了解吧，用最古老的方式思考的话，那就是——",
	},
	[40010163] = {
		ID = 40010163,
		Speaker = "耶珥",
		Text = "如果你是她们的玩偶的话，你会在哪里？",
	},
	[40010164] = {
		ID = 40010164,
		Speaker = "我",
		Text = "这样真的有用吗？说不定出题的人根本就不会这样安排。",
	},
	[40010165] = {
		ID = 40010165,
		Speaker = "耶珥",
		Text = "如果那真的是跟灵魂有关的东西，那妾身认为这样做的可能性是更大的喔。",
	},
	[40010166] = {
		ID = 40010166,
		Text = "（我闭上眼，把飞船上那几张脸一个个摊开在脑海里——）",
	},
	[40010167] = {
		ID = 40010167,
		Speaker = "我",
		Text = "……如果要藏学姊的玩偶，换成是我，大概会放在办公室之类的地方吧。",
	},
	[40010168] = {
		ID = 40010168,
		Speaker = "耶珥",
		Text = "喔？少年这么快就抓到诀窍了？",
	},
	[40010169] = {
		ID = 40010169,
		Speaker = "我",
		Text = "没什么诀窍，就只是……她太适合待在那种一尘不染、规规矩矩的地方了，不觉得吗？",
	},
	[40010170] = {
		ID = 40010170,
		Speaker = "耶珥",
		Text = "呵呵，看来少年比自己以为的还要了解她们呢。",
	},
	[40010171] = {
		ID = 40010171,
		Speaker = "我",
		Text = "废话少说，先找办公室吧——反正也是要一间一间房间翻，时间不等人。",
	},
	[40010172] = {
		ID = 40010172,
		Speaker = "耶珥",
		Text = "遵命，我的少年侦探。",
	},
	[40010173] = {
		ID = 40010173,
	},
	[40010174] = {
		ID = 40010174,
	},
	[40010175] = {
		ID = 40010175,
		Speaker = "耶珥",
		Text = "呵呵，这间什么都没有呢。少年，你打算把整条走廊都走完吗？",
	},
	[40010176] = {
		ID = 40010176,
		Speaker = "我",
		Text = "不然呢，总不能站在这边祈祷玩偶自己蹦出来吧。",
	},
	[40010177] = {
		ID = 40010177,
		Text = "（我打开另一扇门，天花板上倒挂着几十个没有脸的布偶，随着开门灌入的风轻轻摇晃。）",
	},
	[40010178] = {
		ID = 40010178,
		Speaker = "我",
		Text = "……好的，这间我们就当作没看到。",
	},
	[40010179] = {
		ID = 40010179,
		Speaker = "耶珥",
		Text = "哎呀，少年也有会怕的东西呢，妾身还以为你天不怕地不怕。",
	},
	[40010180] = {
		ID = 40010180,
		Speaker = "我",
		Text = "怕是不怕，只是不想跟一堆没脸的娃娃大眼瞪小眼。",
	},
	[40010181] = {
		ID = 40010181,
		Text = "（第三扇门后是间浴室，浴缸里积着暗红色的水，水面飘着一层油光，散发出令人不安的甜腻气味。）",
	},
	[40010182] = {
		ID = 40010182,
		Speaker = "我",
		Text = "……这洋房的装潢品味还真是与众不同。",
	},
	[40010183] = {
		ID = 40010183,
		Speaker = "耶珥",
		Text = "呵呵，说不定这才是这栋房子里最正常的房间呢。",
	},
	[40010184] = {
		ID = 40010184,
		Speaker = "我",
		Text = "妳的正常，跟我的正常好像不太一样。",
	},
	[40010185] = {
		ID = 40010185,
		Speaker = "耶珥",
		Text = "少年会不会其实比想像中还胆小啊？",
	},
	[40010186] = {
		ID = 40010186,
		Speaker = "我",
		Text = "胆小的人不会两天内就跟一个自称魔女的家伙组队。",
	},
	[40010187] = {
		ID = 40010187,
		Speaker = "耶珥",
		Text = "呵呵～",
	},
	[40010188] = {
		ID = 40010188,
		Speaker = "我",
		Text = "随便妳怎么想。",
	},
	[40010189] = {
		ID = 40010189,
		Text = "（我推开第四扇门——空的，只有满地碎裂的木片和一张电椅。）",
	},
	[40010190] = {
		ID = 40010190,
		Speaker = "我",
		Text = "又是空的。",
	},
	[40010191] = {
		ID = 40010191,
		Speaker = "耶珥",
		Text = "少年不会开始怀疑自己的猜测是不是搞错了吧？",
	},
	[40010192] = {
		ID = 40010192,
		Speaker = "我",
		Text = "有意见就直说，别拐弯抹角。",
	},
	[40010193] = {
		ID = 40010193,
		Speaker = "耶珥",
		Text = "呵呵，妾身可没说什么呀。只是觉得，少年的直觉其实一直都不差。",
	},
	[40010194] = {
		ID = 40010194,
		Speaker = "我",
		Text = "那还真是谢谢妳的信任。",
	},
	[40010195] = {
		ID = 40010195,
		Speaker = "耶珥",
		Text = "少年可不像是会轻易放弃的人呢。",
	},
	[40010196] = {
		ID = 40010196,
		Speaker = "我",
		Text = "总会有办法的。",
	},
	[40010197] = {
		ID = 40010197,
		Speaker = "耶珥",
		Text = "呵呵，这句话少年是不是说了不止一次了？",
	},
	[40010198] = {
		ID = 40010198,
		Text = "（我再次打开下一扇门，这次——）",
	},
	[40010199] = {
		ID = 40010199,
		Text = "（门后是一间办公室——桌椅虽然斑驳，但摆设整齐，正中央的木桌上，端端正正坐着一只伊丝娜的布偶。）",
	},
	[40010200] = {
		ID = 40010200,
		Speaker = "我",
		Text = "找到了！",
	},
	[40010201] = {
		ID = 40010201,
		Speaker = "耶珥",
		Text = "……等等，少年！",
	},
	[40010202] = {
		ID = 40010202,
		Speaker = "我",
		Text = "怎么了？找到东西不是好事吗？",
	},
	[40010203] = {
		ID = 40010203,
		Speaker = "耶珥",
		Text = "看看脚下！",
	},
	[40010204] = {
		ID = 40010204,
		Text = "（我的指尖碰到布偶的瞬间，背后传来一声沉重的闷响——办公室的门被重重地锁上。）",
	},
	[40010205] = {
		ID = 40010205,
		Text = "而我的脚下出现了六芒星，散发出血红诡异的光芒。",
	},
	[40010206] = {
		ID = 40010206,
		Speaker = "耶珥",
		Text = "妾身就说了。少年就是不听人讲话。",
	},
	[40010207] = {
		ID = 40010207,
		Text = "（我手上的伊丝娜玩偶发出了尖锐的笑声，不断的震动，头在我面前扭转了一圈。）",
	},
	[40010208] = {
		ID = 40010208,
		Speaker = "耶珥",
		Text = "少年，把它丢掉！",
	},
	[40010209] = {
		ID = 40010209,
		Speaker = "我",
		Text = "这东西黏在我手上！",
	},
	[40010210] = {
		ID = 40010210,
		Text = "（我还来不及搞清楚发生什么事情。）",
	},
	[40010211] = {
		ID = 40010211,
		Text = "（一道半透明的影子窜出，穿过我的身体。）",
	},
	[40010212] = {
		ID = 40010212,
	},
	[40010213] = {
		ID = 40010213,
	},
	[40010214] = {
		ID = 40010214,
		Speaker = "耶珥",
		Text = "少年，你还好吗？",
	},
	[40010215] = {
		ID = 40010215,
		Text = "（我只感觉一阵头晕目眩，跌跌撞撞的摔到一旁的沙发上。）",
	},
	[40010216] = {
		ID = 40010216,
		Speaker = "我",
		Text = "总感觉不太对，但又有种莫名的熟悉感？",
	},
	[40010217] = {
		ID = 40010217,
		Speaker = "耶珥",
		Text = "熟悉？少年你……莫不是在开玩笑吧？",
	},
	[40010219] = {
		ID = 40010219,
		Speaker = "我",
		Text = "啊！ ？",
	},
	[40010220] = {
		ID = 40010220,
		Text = "（我一低头，只看见自己的下体以惊人的气势雄起，甚至比平时更夸张。）",
	},
	[40010221] = {
		ID = 40010221,
		Text = "（怪不得会头晕目眩。）",
	},
	[40010222] = {
		ID = 40010222,
		Speaker = "耶珥",
		Text = "啊啦……妾身更多的是从心里感到佩服。",
	},
	[40010223] = {
		ID = 40010223,
		Speaker = "耶珥",
		Text = "即使在这种情况下，还能够有如此雄伟的反应吗？",
	},
	[40010224] = {
		ID = 40010224,
		Speaker = "我",
		Text = "这不能怪我，要怪魔法什么的。",
	},
	[40010225] = {
		ID = 40010225,
		Speaker = "耶珥",
		Text = "少年你接下来该不会要说自己涨的很难受希望妾身帮忙处理吧？",
	},
	[40010226] = {
		ID = 40010226,
		Speaker = "我",
		Text = "如果可以的话……？",
	},
	[40010227] = {
		ID = 40010227,
		Speaker = "耶珥",
		Text = "呵呵呵……真是直言不讳呢。",
	},
	[40010230] = {
		ID = 40010230,
		Speaker = "耶珥",
		Text = "呵呵……真是惊人的气势。",
	},
	[40010231] = {
		ID = 40010231,
		Speaker = "耶珥",
		Text = "感觉比妾身上次看到的还要更雄伟呢。",
	},
	[40010232] = {
		ID = 40010232,
		Text = "耶珥的脸贴近我的肉棒。",
	},
	[40010233] = {
		ID = 40010233,
		Text = "兴奋的鼻息不断的吹在我的龟头上。",
	},
	[40010234] = {
		ID = 40010234,
		Text = "丝绸的手套沾上不断流出来的液体，缓缓的顺着我的血管挑逗。",
	},
	[40010235] = {
		ID = 40010235,
		Speaker = "耶珥",
		Text = "这样子一跳一跳的，真是可爱呢。",
	},
	[40010236] = {
		ID = 40010236,
		Speaker = "耶珥",
		Text = "看起来已经迫不及待想要更多的刺激了呢。",
	},
	[40010237] = {
		ID = 40010237,
		Text = "温热的舌头夹带着温热的唾液，贴上了我的肉棒。",
	},
	[40010238] = {
		ID = 40010238,
		Text = "一股暖意顺着前端一路滑向下，在肉沟中来回舔拭。",
	},
	[40010239] = {
		ID = 40010239,
		Speaker = "我",
		Text = "耶珥……快……快一点……",
	},
	[40010240] = {
		ID = 40010240,
		Speaker = "耶珥",
		Text = "呵呵……妾身知道的呦。",
	},
	[40010241] = {
		ID = 40010241,
		Speaker = "耶珥",
		Text = "只是这样子的刺激，浇熄不了少年心中的欲火吧？",
	},
	[40010242] = {
		ID = 40010242,
		Speaker = "耶珥",
		Text = "只是少年这个样子，不就让妾身更想要好好欺负一番了吗？",
	},
	[40010243] = {
		ID = 40010243,
		Text = "耶珥的身子向前倾，小巧的嘴将我的肉棒前端含下。",
	},
	[40010244] = {
		ID = 40010244,
		Text = "对我施以一个邪魅的微笑，随后直接将整根肉棒吞入嘴中。",
	},
	[40010245] = {
		ID = 40010245,
		Text = "房间中只剩下耶珥的喉咙抽送肉棒的声音。",
	},
	[40010246] = {
		ID = 40010246,
		Text = "以及耶珥的手自慰的水声。",
	},
	[40010247] = {
		ID = 40010247,
		Speaker = "我",
		Text = "耶……耶珥……快要……",
	},
	[40010248] = {
		ID = 40010248,
		Text = "在即将到达临界点前，耶珥的头抬起，将肉棒吐了出来。",
	},
	[40010249] = {
		ID = 40010249,
		Speaker = "耶珥",
		Text = "这样就不行了吗？还不可以喔。",
	},
	[40010250] = {
		ID = 40010250,
		Speaker = "耶珥",
		Text = "这么快就射了的话，要怎么满足其他人呢？",
	},
	[40010251] = {
		ID = 40010251,
		Speaker = "耶珥",
		Text = "还得要接受更多的……磨练，才可以喔。",
	},
	[40010252] = {
		ID = 40010252,
		Text = "耶珥继续用缓慢持续的速度舔拭着肉棒。",
	},
	[40010253] = {
		ID = 40010253,
		Text = "时不时送入嘴中，但总是在要射精的前一刻松口，露出得逞的笑脸。",
	},
	[40010254] = {
		ID = 40010254,
		Speaker = "耶珥",
		Text = "少年，快要忍不住了吗？",
	},
	[40010255] = {
		ID = 40010255,
		Speaker = "耶珥",
		Text = "想要射精了吗？",
	},
	[40010256] = {
		ID = 40010256,
		Speaker = "耶珥",
		Text = "还不可以喔，至少还要再撑个五分钟才及格。",
	},
	[40010257] = {
		ID = 40010257,
		Speaker = "我",
		Text = "五……五分钟？",
	},
	[40010258] = {
		ID = 40010258,
		Text = "耶珥再次将我的肉棒含入口中。",
	},
	[40010259] = {
		ID = 40010259,
		Speaker = "我",
		Text = "对……对不起了，耶珥。",
	},
	[40010260] = {
		ID = 40010260,
		Speaker = "耶珥",
		Text = "唔？唔呜呜呜！ ！",
	},
	[40010261] = {
		ID = 40010261,
		Text = "我的手扶住了耶珥的后脑，并向下压。",
	},
	[40010262] = {
		ID = 40010262,
		Text = "耶珥瞪大眼，发出挣扎的呜呜声，只能任由肉棒在自己的喉咙来回抽送。",
	},
	[40010263] = {
		ID = 40010263,
		Speaker = "耶珥",
		Text = "唔呜呜呜！呜呜！",
	},
	[40010264] = {
		ID = 40010264,
		Speaker = "我",
		Text = "再一下，再一下就好了……要射了……",
	},
	[40010265] = {
		ID = 40010265,
		Text = "一股热流直接在耶珥的喉咙喷出，耶珥的手用力的掐了一下我的大腿。",
	},
	[40010266] = {
		ID = 40010266,
		Speaker = "耶珥",
		Text = "唔呜呜呜呜呜！咳咳！",
	},
	[40010267] = {
		ID = 40010267,
		Text = "耶珥的头抬起，忍耐已久的大量精液喷洒在耶珥的脸和身上。",
	},
	[40010268] = {
		ID = 40010268,
		Speaker = "耶珥",
		Text = "咳咳咳……虽然妾身是故意的……但少年……",
	},
	[40010269] = {
		ID = 40010269,
		Speaker = "耶珥",
		Text = "也太粗暴了吧？",
	},
	[40010270] = {
		ID = 40010270,
		Speaker = "我",
		Text = "我很抱歉，有点失去理智了……",
	},
	[40010271] = {
		ID = 40010271,
		Speaker = "耶珥",
		Text = "呵呵……这样的也不讨厌就是了，但……对待其他女孩们可要温柔一点喔。",
	},
	[40010272] = {
		ID = 40010272,
		Text = "耶珥伸出舌头，将我龟头上的精液舔拭干净。",
	},
	[40010273] = {
		ID = 40010273,
	},
	[40010274] = {
		ID = 40010274,
	},
	[40010275] = {
		ID = 40010275,
		Text = "（办公室内部残留着刚才那阵闹剧的痕迹——",
	},
	[40010276] = {
		ID = 40010276,
		Text = "（耶珥脸上还沾着几抹液体，我把怀里不再挣扎的伊丝娜玩偶抱稳，它不再有动作，软绵绵地垂着。）",
	},
	[40010277] = {
		ID = 40010277,
		Speaker = "耶珥",
		Text = "呵呵……看来妾身这身行头，是彻底报销了呢。",
	},
	[40010278] = {
		ID = 40010278,
		Text = "耶珥的上半身也同样沾满了精液。",
	},
	[40010279] = {
		ID = 40010279,
		Speaker = "我",
		Text = "呃……那个，抱歉。",
	},
	[40010280] = {
		ID = 40010280,
		Speaker = "耶珥",
		Text = "算了吧，毕竟妾身自己也乐在其中呢。",
	},
	[40010281] = {
		ID = 40010281,
		Text = "（她说着，指尖轻轻一弹，一圈淡淡的绿光从脚边窜起，顺着身体往上淌过。）",
	},
	[40010282] = {
		ID = 40010282,
		Text = "（转眼间裙摆重新挺立，连刚才沾上的精液都像没出现过一样——只留下空气里一丝若有似无的甜香。）",
	},
	[40010283] = {
		ID = 40010283,
		Speaker = "我",
		Text = "……你到底还剩下多少能力？",
	},
	[40010284] = {
		ID = 40010284,
		Speaker = "耶珥",
		Text = "足够弱小了喔～要再试一次看看吗？",
	},
	[40010285] = {
		ID = 40010285,
		Speaker = "我",
		Text = "……算了，我不该问。",
	},
	[40010286] = {
		ID = 40010286,
		Speaker = "我",
		Text = "话说回来——",
	},
	[40010287] = {
		ID = 40010287,
		Speaker = "我",
		Text = "找到伊丝娜的玩偶，接下来就是黛莉亚的了吧。",
	},
	[40010288] = {
		ID = 40010288,
		Speaker = "耶珥",
		Text = "少年心里已经有底了?",
	},
	[40010289] = {
		ID = 40010289,
		Speaker = "我",
		Text = "黛莉亚那家伙，一看到会动的机关就走不动路。",
	},
	[40010290] = {
		ID = 40010290,
		Speaker = "我",
		Text = "如果这座洋房底下真的藏着什么机关，她的玩偶肯定被扔在最像她的地方——锅炉室。",
	},
	[40010291] = {
		ID = 40010291,
		Speaker = "耶珥",
		Text = "喔？这么笃定？",
	},
	[40010292] = {
		ID = 40010292,
		Speaker = "我",
		Text = "烧得轰隆作响的锅炉、一堆齿轮管线——根本就是黛莉亚的主场。",
	},
	[40010293] = {
		ID = 40010293,
		Speaker = "我",
		Text = "倒不如说我想不到她不在那里的可能性。",
	},
	[40010294] = {
		ID = 40010294,
		Speaker = "耶珥",
		Text = "呵呵，少年偶尔也是会动脑筋的呢。",
	},
	[40010295] = {
		ID = 40010295,
		Speaker = "我",
		Text = "妳这句话怎么听都不像称赞。",
	},
	[40010296] = {
		ID = 40010296,
		Text = "（我和耶珥向洋房深处走去，终于找到了通往地下室的楼梯。）",
	},
	[40010297] = {
		ID = 40010297,
		Text = "（提灯向下照去，光柱却感觉被黑暗给吸收，完全看不见底。）",
	},
	[40010298] = {
		ID = 40010298,
		Speaker = "耶珥",
		Text = "少年，你确定要走下去吗？",
	},
	[40010299] = {
		ID = 40010299,
		Speaker = "耶珥",
		Text = "如果会害怕的话姐姐的手可以借你握喔，呵呵～",
	},
	[40010300] = {
		ID = 40010300,
		Speaker = "我",
		Text = "黛莉亚还等着我们去救呢。",
	},
	[40010301] = {
		ID = 40010301,
		Speaker = "耶珥",
		Text = "真是充满男子气概呢。",
	},
	[40010302] = {
		ID = 40010302,
		Text = "（越往下走，空气就越是闷热，墙上的水痕渐渐变成一层薄薄的锈迹。",
	},
	[40010303] = {
		ID = 40010303,
		Text = "（就在转过某个弯角时，一阵金属的怪声从更深处回荡传来——。）",
	},
	[40010304] = {
		ID = 40010304,
		Speaker = "我",
		Text = "……妳有听到吗？",
	},
	[40010305] = {
		ID = 40010305,
		Speaker = "耶珥",
		Text = "妾身的耳朵好得很呢，少年。",
	},
	[40010306] = {
		ID = 40010306,
		Speaker = "我",
		Text = "你觉得那是什么？",
	},
	[40010307] = {
		ID = 40010307,
		Speaker = "耶珥",
		Text = "说出答案的话，不就不好玩了吗？",
	},
	[40010308] = {
		ID = 40010308,
		Speaker = "我",
		Text = "那代表你知道吧？",
	},
	[40010309] = {
		ID = 40010309,
		Speaker = "耶珥",
		Text = "知道又如何，先走走看不就清楚了。",
	},
	[40010310] = {
		ID = 40010310,
		Text = "（我和耶珥两人一前一后的往地下室走去，持续且沉重的金属声仍不断在黑暗中回荡。）",
	},
	[40010311] = {
		ID = 40010311,
		Speaker = "耶珥",
		Text = "少年，声音越来越近了喔。",
	},
	[40010312] = {
		ID = 40010312,
		Speaker = "我",
		Text = "我有注意到这件事情……",
	},
	[40010313] = {
		ID = 40010313,
		Speaker = "耶珥",
		Text = "要好好保护柔弱的妾身喔～呵呵～",
	},
	[40010314] = {
		ID = 40010314,
		Text = "（脚下的地板终于由楼梯变为平地，而另一道金属声音也随之出现。）",
	},
	[40010315] = {
		ID = 40010315,
		Text = "（光扫过去的瞬间，我看见了它——一副浑身锈迹的全身铠甲，正一步一步地朝我们走来）",
	},
	[40010316] = {
		ID = 40010316,
		Text = "（关节处发出生锈金属彼此摩擦的呻吟，头盔底下空得像是根本没有脸。）",
	},
	[40010317] = {
		ID = 40010317,
	},
	[40010318] = {
		ID = 40010318,
	},
	[40010319] = {
		ID = 40010319,
		Text = "（光扫过去的瞬间，我看见了它——一副浑身锈迹的全身铠甲，正一步一步地朝我们走来）",
	},
	[40010320] = {
		ID = 40010320,
		Text = "（关节处发出生锈金属彼此摩擦的呻吟，头盔底下空得像是根本没有脸。）",
	},
	[40010321] = {
		ID = 40010321,
		Speaker = "我",
		Text = "……！ ？",
	},
	[40010322] = {
		ID = 40010322,
		Text = "（铠甲的头猛地转向我们，下一秒整具沉重的躯体就朝这里直冲过来。）",
	},
	[40010323] = {
		ID = 40010323,
		Text = "（速度快得完全不像那身锈迹斑斑的模样该有的样子。）",
	},
	[40010324] = {
		ID = 40010324,
		Text = "（耶珥一把抓住我的手腕往旁边拽，一把大剑径直镶进我刚才站的地板。）",
	},
	[40010325] = {
		ID = 40010325,
		Speaker = "耶珥",
		Text = "站在原地是想变成两半吗？少年？",
	},
	[40010326] = {
		ID = 40010326,
		Speaker = "我",
		Text = "谢了，不过，我现在真的需要你提出一个好点子。",
	},
	[40010327] = {
		ID = 40010327,
		Speaker = "耶珥",
		Text = "那是你应该考虑的问题喔，妾身现在只是一名弱女子罢了。",
	},
	[40010328] = {
		ID = 40010328,
		Text = "（两人跑过一个转角，耶珥打开金属置物柜的门。）",
	},
	[40010329] = {
		ID = 40010329,
		Text = "（我几乎是被塞进去的，两个人挤在同一格铁柜里。）",
	},
	[40010330] = {
		ID = 40010330,
		Text = "（门板阖上的瞬间，光线彻底消失，只剩下彼此的呼吸声贴得极近）",
	},
	[40010331] = {
		ID = 40010331,
		Text = "（铠甲沉重的脚步声在外头来回踱步，一下、一下，敲得我心脏跟着发抖。）",
	},
	[40010332] = {
		ID = 40010332,
		Speaker = "我",
		Text = "……它走了吗？",
	},
	[40010333] = {
		ID = 40010333,
		Speaker = "耶珥",
		Text = "呵呵，应该吧？妾身也不敢打包票。",
	},
	[40010334] = {
		ID = 40010334,
		Text = "（即使被塞在窄小的铁柜里，耶珥那股气定神闲一点都没少。）",
	},
	[40010335] = {
		ID = 40010335,
		Speaker = "我",
		Text = "妳这种保证，跟没保证有什么两样。",
	},
	[40010336] = {
		ID = 40010336,
		Text = "（又等了一段像是永远那么长的时间，外头的脚步声终于彻底消失。）",
	},
	[40010337] = {
		ID = 40010337,
		Text = "（我才敢把铁柜的门推开一条缝，探头确认四下无人。）",
	},
	[40010338] = {
		ID = 40010338,
		Speaker = "我",
		Text = "差点喘不过气，你的胸部几乎占了八成的空间。",
	},
	[40010339] = {
		ID = 40010339,
		Speaker = "耶珥",
		Text = "少年在揉的时候意见可没有现在那么多呢。",
	},
	[40010340] = {
		ID = 40010340,
		Speaker = "我",
		Text = "得想个办法，不然我们就是一直躲一直躲，躲到天荒地老，况且还没有找到娃娃。",
	},
	[40010341] = {
		ID = 40010341,
		Speaker = "我",
		Text = "你有什么好点子吗？",
	},
	[40010342] = {
		ID = 40010342,
		Speaker = "耶珥",
		Text = "很高兴少年你问了喔～呵呵～",
	},
	[40010343] = {
		ID = 40010343,
		Speaker = "耶珥",
		Text = "妾身当然早有计画了。",
	},
	[40010344] = {
		ID = 40010344,
		Speaker = "我",
		Text = "每当我看到你这个表情，我都很后悔向你提问……",
	},
	[40010345] = {
		ID = 40010345,
		Text = "转场用",
	},
	[40010346] = {
		ID = 40010346,
		Text = "转场用",
	},
	[40010347] = {
		ID = 40010347,
		Speaker = "我",
		Text = "你最好确定这是一个好主意！",
	},
	[40010348] = {
		ID = 40010348,
		Speaker = "耶珥",
		Text = "不觉得这很有趣吗～？",
	},
	[40010349] = {
		ID = 40010349,
		Speaker = "我",
		Text = "这不是我想得到的答案！",
	},
	[40010350] = {
		ID = 40010350,
		Text = "（我深吸一口气，故意把脚步踩得又重又响，往走道另一端走去，把自己变成最显眼的靶子。）",
	},
	[40010351] = {
		ID = 40010351,
		Speaker = "我",
		Text = "喂，大铁罐，这边啦！",
	},
	[40010352] = {
		ID = 40010352,
		Text = "（铠甲猛地转向这里，发出金属碰撞般的咆哮冲了过来，速度比想像中还快——）",
	},
	[40010353] = {
		ID = 40010353,
		Text = "（我拔腿狂奔，身后的脚步声重得像整条走道都在震动。）",
	},
	[40010354] = {
		ID = 40010354,
		Speaker = "耶珥",
		Text = "少年，再快一点，要被追到了喔！",
	},
	[40010355] = {
		ID = 40010355,
		Speaker = "我",
		Text = "这种事情不用你说我也知道！",
	},
	[40010356] = {
		ID = 40010356,
		Text = "（我飞快地冲过耶珥的身旁，铠甲也紧随其后，耶珥看准时机，将地上的铁链拉紧。",
	},
	[40010357] = {
		ID = 40010357,
		Text = "（就在那道横拉在地面的绳子绷直的瞬间，铠甲整条腿被死死绊住）",
	},
	[40010358] = {
		ID = 40010358,
		Text = "（庞大的身躯失去平衡，轰的一声重重摔倒在地，头盔应声脱飞，滚得老远。）",
	},
	[40010359] = {
		ID = 40010359,
		Speaker = "我",
		Text = "……成功了？",
	},
	[40010360] = {
		ID = 40010360,
		Speaker = "耶珥",
		Text = "呵呵，看吧，妾身说得没错。",
	},
	[40010361] = {
		ID = 40010361,
		Text = "（铠甲却没有就此不动——它撑着地面缓缓坐起身，胸甲和头盔之间没有头颅，而是——。）",
	},
	[40010362] = {
		ID = 40010362,
		Text = "（——那该是头的位置上，稳稳坐着一个熟悉的东西——黛莉亚的娃娃。）",
	},
	[40010363] = {
		ID = 40010363,
		Speaker = "黛莉亚娃娃铠甲？",
		Text = "（愤怒的金属混合嘎吱声。）",
	},
	[40010364] = {
		ID = 40010364,
		Text = "那铠甲举起了不知从何而来的巨大扳手，再次向我们奔来……",
	},
	[40010365] = {
		ID = 40010365,
	},
	[40010366] = {
		ID = 40010366,
	},
	[40010367] = {
		ID = 40010367,
		Speaker = "耶珥",
		Text = "呵呵，看样子它还没打算让少年回家呢。",
	},
	[40010368] = {
		ID = 40010368,
		Speaker = "我",
		Text = "……我还以为铠甲头一掉，它就该知难而退了。",
	},
	[40010369] = {
		ID = 40010369,
		Text = "（铠甲甩开黏在关节缝隙里的碎石，举起那支巨大的扳手朝两人逼近，脚步又急又重。）",
	},
	[40010370] = {
		ID = 40010370,
		Text = "（我什么都来不及多想，抓着耶珥拔腿就没入了地下室更深处的通道。）",
	},
	[40010371] = {
		ID = 40010371,
		Speaker = "耶珥",
		Text = "少年，妾身希望你有b计画。",
	},
	[40010372] = {
		ID = 40010372,
		Speaker = "我",
		Text = "我还在想，在那之前继续跑。",
	},
	[40010373] = {
		ID = 40010373,
		Text = "（我的脑子里疯狂打转——正面硬拼绝对不是办法，总得找点什么才行。）",
	},
	[40010374] = {
		ID = 40010374,
		Text = "（就在这时，某个规律的敲击声从侧边一扇贴着锈迹斑斑「锅炉室」铁牌的门后传了出来。）",
	},
	[40010375] = {
		ID = 40010375,
		Text = "（沉闷得像是有什么东西还在里头运转着，怎么听都不像是废弃多年该有的动静。）",
	},
	[40010376] = {
		ID = 40010376,
		Speaker = "我",
		Text = "慢着，你还记得黛莉亚说过的鬼故事吗？",
	},
	[40010377] = {
		ID = 40010377,
		Speaker = "耶珥",
		Text = "哪一个呢？",
	},
	[40010378] = {
		ID = 40010378,
		Speaker = "我",
		Text = "很烂的那个。",
	},
	[40010379] = {
		ID = 40010379,
		Speaker = "耶珥",
		Text = "这并没有让范围缩小喔，少年。",
	},
	[40010380] = {
		ID = 40010380,
		Speaker = "我",
		Text = "就是那个啦！",
	},
	[40010381] = {
		ID = 40010381,
	},
	[40010382] = {
		ID = 40010382,
		Speaker = "黛莉亚",
		Text = "从前，有个村庄，每到半夜都传来奇怪的声音！",
	},
	[40010383] = {
		ID = 40010383,
		Speaker = "黛莉亚",
		Text = "呻吟声、哀嚎声，所有人都不敢出门！",
	},
	[40010384] = {
		ID = 40010384,
		Speaker = "黛莉亚",
		Text = "后来有个勇者去追声音的源头——",
	},
	[40010385] = {
		ID = 40010385,
		Speaker = "黛莉亚",
		Text = "最后……当她到达了声音的尽头……他看见了——",
	},
	[40010386] = {
		ID = 40010386,
		Speaker = "黛莉亚",
		Text = "蒸汽锅炉密封胶老化！每到夜晚气温下降就热胀冷缩发出异响！",
	},
	[40010387] = {
		ID = 40010387,
		Speaker = "黛莉亚",
		Text = "他把锅炉修好了！村庄从此太平！感动吧！",
	},
	[40010388] = {
		ID = 40010388,
	},
	[40010389] = {
		ID = 40010389,
		Speaker = "我",
		Text = "耶珥，我有个烂主意——听起来很蠢，但赌一把。",
	},
	[40010390] = {
		ID = 40010390,
		Speaker = "耶珥",
		Text = "呵呵，少年的烂主意，妾身向来捧场。",
	},
	[40010391] = {
		ID = 40010391,
		Text = "（我和耶珥冲进锅炉室，将厚重的金属大门关上。）",
	},
	[40010392] = {
		ID = 40010392,
		Speaker = "耶珥",
		Text = "少年，妾身挡住门，你快点。",
	},
	[40010393] = {
		ID = 40010393,
		Speaker = "我",
		Text = "我已经在加速了！",
	},
	[40010394] = {
		ID = 40010394,
		Text = "（锅炉前的封口早就裂开一道缝，黑褐色的密封胶干硬得像块石头，边缘还泛着焦黑的痕迹。）",
	},
	[40010395] = {
		ID = 40010395,
		Text = "（我蹲下来，呆愣地看着锅炉——别说修，我连这玩意儿该从哪里下手都看不出来，满脑子只剩下「完了」两个字打转。）",
	},
	[40010396] = {
		ID = 40010396,
		Speaker = "我",
		Text = "早知道就多留意黛莉亚平常在鼓捣什么了……",
	},
	[40010397] = {
		ID = 40010397,
		Speaker = "我",
		Text = "我拿起一旁印着黄色大字的蓝色喷雾罐朝着密封胶猛喷。",
	},
	[40010398] = {
		ID = 40010398,
		Speaker = "耶珥",
		Text = "少年，小心！",
	},
	[40010399] = {
		ID = 40010399,
		Text = "（铠甲亡灵将铁门撞开，黛莉亚布偶的眼睛直勾勾的看着我。）",
	},
	[40010400] = {
		ID = 40010400,
		Text = "（冰冷的铁壳扑面而来的瞬间，耶珥的腿抬起，将我踹向一旁。）",
	},
	[40010401] = {
		ID = 40010401,
		Text = "（耶珥则轻盈的跳向一旁，像斗牛士闪过牛角那样把它整个送进了锅炉敞开的炉口。）",
	},
	[40010402] = {
		ID = 40010402,
		Text = "（沉重的铁壳撞进炉膛，发出一声闷重的回响，火星子喷溅出来，烫得她赶紧往后退了一步。）",
	},
	[40010403] = {
		ID = 40010403,
		Speaker = "我",
		Text = "呼……结论上来说，至少结束了。",
	},
	[40010404] = {
		ID = 40010404,
		Speaker = "耶珥",
		Text = "呵呵，看来少年也不是只有一张嘴呢。",
	},
	[40010405] = {
		ID = 40010405,
		Text = "（耶珥慢悠悠地走近，抱着手臂，又恢复了那副事不关己的悠闲模样。）",
	},
	[40010406] = {
		ID = 40010406,
		Text = "（呼吸渐渐平复下来，我这才猛然想起——玩偶呢？）",
	},
	[40010407] = {
		ID = 40010407,
		Speaker = "我",
		Text = "等等，黛莉亚的玩偶呢？该不会也跟着——",
	},
	[40010408] = {
		ID = 40010408,
		Text = "（耶珥慢条斯理地从尖帽中摸出一团脏兮兮的布偶，举到脸旁晃了晃——）",
	},
	[40010409] = {
		ID = 40010409,
		Text = "（正是那张熟悉的、有些丑萌的脸，除了沾满煤灰，倒是连一根线头都没少。）",
	},
	[40010410] = {
		ID = 40010410,
		Speaker = "耶珥",
		Text = "少年在找的，是这个吗？",
	},
	[40010411] = {
		ID = 40010411,
	},
	[40010412] = {
		ID = 40010412,
	},
	[40010413] = {
		ID = 40010413,
		Speaker = "我",
		Text = "两只到手，只剩秋比的还没找到。",
	},
	[40010414] = {
		ID = 40010414,
		Speaker = "耶珥",
		Text = "说得也是啊……不过那孩子平时就飘在半空中，玩偶会藏在哪，妾身也毫无头绪。",
	},
	[40010415] = {
		ID = 40010415,
		Speaker = "我",
		Text = "如果是秋比的风格，大概不会乖乖待在办公室或锅炉室这种地方吧。",
	},
	[40010416] = {
		ID = 40010416,
		Speaker = "耶珥",
		Text = "哎呀，你倒是很了解她嘛。",
	},
	[40010417] = {
		ID = 40010417,
		Speaker = "我",
		Text = "只是在想，如果我是颗气球，会想飘到哪去而已。",
	},
	[40010418] = {
		ID = 40010418,
		Text = "（话音刚落，锅炉室的灯光毫无预兆地暗了一瞬，管线深处传来一声闷响。）",
	},
	[40010419] = {
		ID = 40010419,
		Speaker = "我",
		Text = "……刚才那是什么？",
	},
	[40010420] = {
		ID = 40010420,
		Speaker = "耶珥",
		Text = "啊啦，听起来是有意外的访客呢？",
	},
	[40010421] = {
		ID = 40010421,
		Text = "（黑暗里先传来笑声——嘻嘻嘻嘻——像是刻意拖长，享受着两人绷紧神经的模样。）",
	},
	[40010422] = {
		ID = 40010422,
		Text = "（地下室的屋顶被直接扯开，天空变成了奇异的扭曲空间。）",
	},
	[40010423] = {
		ID = 40010423,
		Text = "（阴影里浮出一道被放大数百倍的身影，白发与金色烙印在扭曲的背景前显得格外刺眼。）",
	},
	[40010424] = {
		ID = 40010424,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……忍不住想探头出来打个招呼了。",
	},
	[40010425] = {
		ID = 40010425,
		Speaker = "我",
		Text = "你是……飞天暴露狂？ ——这次连自我介绍都不打算要吗？",
	},
