	[40010606] = {
		ID = 40010606,
		Speaker = "耶珥",
		Text = "虽然因果欠佳，但确实挺有可能的呢。",
	},
	[40010607] = {
		ID = 40010607,
		Speaker = "我",
		Text = "那我们上去把她弄醒吧。",
	},
	[40010608] = {
		ID = 40010608,
		Speaker = "耶珥",
		Text = "少年想怎么做呢？",
	},
	[40010609] = {
		ID = 40010609,
		Text = "（我跑出掩体，对着上面的巨大秋比大喊。）",
	},
	[40010610] = {
		ID = 40010610,
		Speaker = "我",
		Text = "秋比！醒醒啊！妳在做梦啦！",
	},
	[40010611] = {
		ID = 40010611,
		Speaker = "巨大秋比",
		Text = "哇，是大玩偶，好小！",
