	[40010613] = {
		ID = 40010613,
		Text = "（秋比的巨掌却连顿一下都没有，随着一阵欢快的晃动震落满地枯叶——）",
	},
	[40010614] = {
		ID = 40010614,
		Speaker = "赛诃希丝",
		Text = "喂——这样真的会，会吐出来的啊——",
	},
	[40010615] = {
		ID = 40010615,
		Speaker = "耶珥",
		Text = "哎呀，堂堂的邪神大人，居然会怕晕车呢。",
	},
	[40010616] = {
		ID = 40010616,
		Speaker = "赛诃希丝",
		Text = "嘻——嘻嘻……本座才不会怕这种小事，只是懒得，懒得跟这种蠢东西计较而已！",
	},
	[40010617] = {
		ID = 40010617,
		Text = "（没等我喊出口，那只巨掌已经先一步松开——赛诃希丝画出一道抛物线，重重摔进不远处的一丛蕨草里。）",
	},
	[40010618] = {
		ID = 40010618,
		Speaker = "赛诃希丝",
		Text = "……看吧，我只要……想下来……我就能……下来……",
	},
	[40010619] = {
		ID = 40010619,
		Speaker = "耶珥",
		Text = "呵呵，摔得这么漂亮，一定是特意练过的吧。",
	},
	[40010620] = {
		ID = 40010620,
		Speaker = "我",
		Text = "先别管那些了——这是机会，快走！",
	},
	[40010621] = {
		ID = 40010621,
		Text = "（三人压低身子钻进更深的林间，而巨大的秋比在后方刨开路径上所有树木。）",
	},
	[40010622] = {
		ID = 40010622,
		Speaker = "巨大秋比",
		Text = "不要跑！",
