	[40010627] = {
		ID = 40010627,
	},
	[40010628] = {
		ID = 40010628,
	},
	[40010629] = {
		ID = 40010629,
		Text = "（秋比的手掌又一次从高处压下来，拍得大地轰鸣作响。）",
	},
	[40010630] = {
		ID = 40010630,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……看来这只气球怪物挺喜欢你嘛。",
	},
	[40010631] = {
		ID = 40010631,
		Speaker = "我",
		Text = "妳倒是轻松，要不要帮我分担一半？让妳照顾一天？",
	},
	[40010632] = {
		ID = 40010632,
		Speaker = "赛诃希丝",
		Text = "啊啊啊！手过来了！你牺牲一下！你给她抓！",
	},
	[40010633] = {
		ID = 40010633,
		Speaker = "我",
		Text = "不要扯我！专心逃你的！",
	},
	[40010634] = {
		ID = 40010634,
		Speaker = "赛诃希丝",
		Text = "就算要死我也要拖你一起下水！",
	},
	[40010635] = {
		ID = 40010635,
		Text = "（两人的手劲谁都不肯先松开，巨大的手指却已经接近——下一秒，我们两个就一起被扣进了掌心，同时离地。）",
	},
	[40010636] = {
