		Speaker = "巨大秋比",
		Text = "嘿嘿～要一起玩喔～",
	},
	[40010637] = {
		ID = 40010637,
		Speaker = "赛诃希丝",
		Text = "啊啊啊！又被抓上来了，都是你害的！",
	},
	[40010638] = {
		ID = 40010638,
		Speaker = "赛诃希丝",
		Text = "早知道就不跟你们同流合污了。",
	},
	[40010639] = {
		ID = 40010639,
		Speaker = "我",
		Text = "现在说这个有点晚了吧？",
	},
	[40010640] = {
		ID = 40010640,
		Text = "（我低头一看，耶珥正站在树根旁，仰头望着我们，脸上竟然还带着笑。）",
	},
	[40010641] = {
		ID = 40010641,
		Speaker = "耶珥",
		Text = "少年，接着。",
	},
	[40010642] = {
