	[40010661] = {
		ID = 40010661,
		Text = "（巨大的手掌松开我们两人，只是高度是在几百公尺的高空中。）",
	},
	[40010662] = {
		ID = 40010662,
		Text = "（下一秒，秋比整个人仰面栽进池塘里，溅起的水花像是海啸一般。）",
	},
	[40010663] = {
		ID = 40010663,
		Speaker = "赛诃希丝",
		Text = "哇啊——！",
	},
	[40010664] = {
		ID = 40010664,
		Speaker = "我",
		Text = "抓稳了！",
	},
	[40010665] = {
		ID = 40010665,
		Text = "（我们两个一起摔在落叶堆上，跌得七荤八素。）",
	},
	[40010666] = {
		ID = 40010666,
		Text = "（尘土落定后我才看清楚，那是一个缩小到不成比例的秋比布偶，静静躺在地上，一动也不动。）",
	},
	[40010667] = {
		ID = 40010667,
		Speaker = "耶珥",
		Text = "呵呵，看来用来吓人的幽灵还挺有用的呢。",
	},
	[40010668] = {
		ID = 40010668,
		Speaker = "我",
		Text = "谢了，差点以为要变成秋比的晚餐了。",
	},
	[40010669] = {
		ID = 40010669,
		Text = "（四周终于安静下来，只剩水滴从树叶间断断续续落下的声音。）",
	},
	[40010670] = {
		ID = 40010670,
		Text = "（紧接着又是一声闷响——某个比拳头大不了多少的东西也跟着砸落在旁边。）",
	},
	[40010671] = {
		ID = 40010671,
		Text = "（赛诃希丝的眼神盯着布偶，露出了不怀好意的笑容。）",
	},
	[40010672] = {
		ID = 40010672,
	},
	[40010673] = {
		ID = 40010673,
	},
	[40010674] = {
		ID = 40010674,
		Text = "（我一头撞在松软的地面上，满嘴都是碎叶的味道，那跟屋子一样高的秋比，消散得比喷嚏还快——）",
	},
	[40010675] = {
		ID = 40010675,
		Text = "（好像刚才什么都没发生过。秋比娃娃弹了两下，安静地躺在不远处的草丛里。）",
	},
	[40010676] = {
		ID = 40010676,
		Speaker = "我",
		Text = "……结束了？",
	},
	[40010677] = {
		ID = 40010677,
		Speaker = "耶珥",
		Text = "呵呵，看来是呢。少年这次的反应，倒是比妾身想像中机灵。",
	},
	[40010678] = {
		ID = 40010678,
		Speaker = "我",
		Text = "反正只是恶梦，至少我希望是吧……",
	},
	[40010679] = {
		ID = 40010679,
		Text = "（赛诃希丝从落叶堆里爬起来，视线直勾勾钉在草丛里那个娃娃上，像是饿了三天的野兽看见猎物。）",
	},
	[40010680] = {
		ID = 40010680,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……",
	},
	[40010681] = {
		ID = 40010681,
		Text = "（她连滚带爬地扑过去，把秋比娃娃整个搂进怀里。）",
	},
	[40010682] = {
		ID = 40010682,
		Text = "（赛诃希丝抱住秋比玩偶的瞬间，紫色触手窜出，缠上耶珥腰间的袋子。）",
	},
	[40010683] = {
		ID = 40010683,
		Text = "（袋口自行松开，其余玩偶接连飞向她，身上的金色烙印也逐一亮起。）",
	},
	[40010684] = {
		ID = 40010684,
		Speaker = "赛诃希丝",
		Text = "这孩子被踩成这样还真是可怜呢——不过没关系！",
	},
	[40010685] = {
		ID = 40010685,
		Speaker = "我",
		Text = "妳在打什么主意。",
	},
	[40010686] = {
		ID = 40010686,
		Speaker = "赛诃希丝",
		Text = "有了这些，我的力量……终于要回来了！这不是天大的好消息吗？",
	},
	[40010687] = {
		ID = 40010687,
		Speaker = "耶珥",
		Text = "哎呀，妾身怎么记得有人前不久还在哀嚎自己什么都做不了？",
	},
	[40010688] = {
		ID = 40010688,
		Speaker = "赛诃希丝",
		Text = "少啰嗦，魔女。妳懂什么——看看你的腰间吧，你的娃娃，现在都是我的了！",
	},
	[40010689] = {
		ID = 40010689,
		Speaker = "赛诃希丝",
		Text = "这样子，剧本又回到正轨了，哈哈哈！",
	},
	[40010690] = {
		ID = 40010690,
		Text = "（她话音落下的瞬间，身上的金色烙印一齐亮起。）",
	},
	[40010691] = {
		ID = 40010691,
		Speaker = "我",
		Text = "喂——",
	},
	[40010692] = {
		ID = 40010692,
		Speaker = "赛诃希丝",
		Text = "难道不该让你们也尝尝，被玩具耍得团团转是什么感觉吗？",
	},
	[40010693] = {
		ID = 40010693,
		Speaker = "赛诃希丝",
		Text = "从现在开始，我填满你们身上的每一处——不管你们怎么求饶都没用。",
	},
	[40010694] = {
		ID = 40010694,
		Text = "（她身后探出几条紫黑色的触手，带着黏液缓缓蠕动。）",
	},
	[40010695] = {
		ID = 40010695,
		Speaker = "我",
		Text = "没事，我来。",
	},
	[40010696] = {
		ID = 40010696,
		Speaker = "耶珥",
		Text = "哎呀，少年还挺有骨气的嘛。",
	},
	[40010697] = {
		ID = 40010697,
		Speaker = "赛诃希丝",
		Text = "妳们两个少在那边打情骂俏——这不是理所当然的事吗？反抗只会让折磨的时间拉得更长。",
	},
	[40010698] = {
		ID = 40010698,
		Speaker = "我",
		Text = "谁跟妳打情骂俏了。",
	},
	[40010699] = {
		ID = 40010699,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻……嘴硬到最后一刻，我最喜欢了——越挣扎越精彩。",
	},
	[40010700] = {
		ID = 40010700,
		Speaker = "耶珥",
		Text = "啊啦，妾身倒想看看，这场戏能演到哪里。",
	},
	[40010701] = {
		ID = 40010701,
		Speaker = "赛诃希丝",
		Text = "妳最好别分心太久，魔女——接下来，妳也是主角之一。",
	},
	[40010702] = {
		ID = 40010702,
		Text = "（她抬起手，指尖划出一道弧线，周围的空气像被扯开了一角。）",
	},
	[40010703] = {
		ID = 40010703,
		Speaker = "赛诃希丝",
		Text = "来吧，让我看看，你们两个能撑到什么时候——这才是这场游戏真正的延长赛。",
	},
	[40010704] = {
		ID = 40010704,
		Speaker = "我",
		Text = "……妳最好祈祷这场延长赛，妳不会后悔。",
	},
	[40010705] = {
		ID = 40010705,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻，那，就开始吧——",
	},
	[40010706] = {
		ID = 40010706,
		Speaker = "耶珥",
		Text = "……呵呵。",
	},
	[40010707] = {
		ID = 40010707,
		Speaker = "赛诃希丝",
		Text = "妳笑什么？",
	},
	[40010708] = {
		ID = 40010708,
		Speaker = "耶珥",
		Text = "啊啦，妾身什么都没说呀——难道妳没发现吗？",
	},
	[40010709] = {
		ID = 40010709,
		Text = "（赛诃希丝身上的触手胡乱地扭动，像是连她自己都感觉到了什么不对。）",
	},
	[40010710] = {
		ID = 40010710,
		Speaker = "赛诃希丝",
		Text = "……哼，少在那边装神秘，想动摇我的节奏没那么容易。",
	},
	[40010711] = {
		ID = 40010711,
		Speaker = "耶珥",
		Text = "真是可惜呢，看来，今天只能玩到这边了。",
	},
	[40010712] = {
		ID = 40010712,
		Speaker = "赛诃希丝",
		Text = "欸？",
	},
	[40010713] = {
		ID = 40010713,
		Speaker = "耶珥",
		Text = "很有趣喔，不过，到此为止了。",
	},
	[40010714] = {
		ID = 40010714,
		Text = "（耶珥伸出手，做出施法的动作，淡淡的光点出现在她的身旁。）",
	},
	[40010715] = {
		ID = 40010715,
	},
	[40010716] = {
		ID = 40010716,
	},
	[40010717] = {
		ID = 40010717,
		Text = "（那阵窜过脊椎的寒意才刚过去。）",
	},
	[40010718] = {
		ID = 40010718,
		Text = "（触手在她身后重新张开，恢复成那副居高临下的姿态。）",
	},
	[40010719] = {
		ID = 40010719,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……妳这副气定神闲的样子，未免也装得太过头了吧？",
	},
	[40010720] = {
		ID = 40010720,
		Speaker = "赛诃希丝",
		Text = "都到了这个地步，还想维持那张从容的脸——这不是虚张声势，还能是什么呢？",
	},
	[40010721] = {
		ID = 40010721,
		Speaker = "赛诃希丝",
		Text = "还有你，可恶的虫子，也给我乖乖站在那里看戏——。",
	},
	[40010722] = {
		ID = 40010722,
		Speaker = "我",
		Text = "喂，妳刚才不是才抖了一下吗，现在装镇定会不会太晚了点。",
	},
	[40010723] = {
		ID = 40010723,
		Speaker = "赛诃希丝",
		Text = "嘻嘻，飞虫这种时候还是闭嘴比较好。",
	},
	[40010724] = {
		ID = 40010724,
		Speaker = "耶珥",
		Text = "呵呵……啊啦，妳这么激动做什么呢——明明才刚拿回力量而已。",
	},
	[40010725] = {
		ID = 40010725,
		Speaker = "赛诃希丝",
		Text = "少在那装模作样！让妳好好见识一下——什么才叫真正的绝望！",
	},
	[40010726] = {
		ID = 40010726,
		Text = "（话音未落，她身后的触手伸长，带着黏液的前端如鞭子般朝耶珥抽了过去。）",
	},
	[40010727] = {
		ID = 40010727,
		Speaker = "我",
		Text = "耶珥小心！",
	},
	[40010728] = {
		ID = 40010728,
		Text = "（触手击中的瞬间却只发出一声闷响——耶珥连手都没抬起来。）",
	},
	[40010729] = {
		ID = 40010729,
		Text = "（那条触手就像撞上了什么看不见的墙，硬生生停在她面前寸许的地方）",
	},
	[40010730] = {
		ID = 40010730,
		Speaker = "赛诃希丝",
		Text = "……咦？",
	},
	[40010731] = {
		ID = 40010731,
		Speaker = "耶珥",
		Text = "唉呀……真是有点可惜呢——这样一来，这出戏也演不下去了。",
	},
	[40010733] = {
		ID = 40010733,
		Speaker = "赛诃希丝",
		Text = "妳……妳到底在说什么？封印呢？妳的力量不是应该——",
	},
	[40010734] = {
		ID = 40010734,
		Speaker = "耶珥",
		Text = "封印？呵呵，妳猜猜看——妾身从头到尾，就没有被封印过喔。",
	},
	[40010735] = {
		ID = 40010735,
		Text = "（我脑中一片空白——如果她从一开始就没被封印，那这一路上所有的惊险，究竟算是什么？）",
	},
	[40010736] = {
		ID = 40010736,
		Speaker = "我",
		Text = "……妳說没被封印，那这整个试胆大会的鬼故事、洋房、铠甲亡灵——通通都是妳安排的？",
	},
	[40010737] = {
		ID = 40010737,
		Speaker = "耶珥",
		Text = "啊啦，少年反应真快呢——不过，真正的魔女可是不会说太清楚的喔。",
	},
	[40010738] = {
		ID = 40010738,
		Speaker = "耶珥",
		Text = "——从头到尾，一切都好好地捏在妾身的手心里呢。",
	},
	[40010739] = {
		ID = 40010739,
		Speaker = "耶珥",
		Text = "包含你也是唷，触手女孩。",
	},
	[40010740] = {
		ID = 40010740,
		Speaker = "耶珥",
		Text = "妾身精心准备、想让少年好好享受的一个夏天呢。",
	},
	[40010741] = {
		ID = 40010741,
		Speaker = "赛诃希丝",
		Text = "怎、怎么可能……结界明明是我亲手设下的！",
	},
	[40010742] = {
		ID = 40010742,
		Speaker = "赛诃希丝",
		Text = "这片森林也是依照我的意志创造出来的，我不可能弄错！",
	},
	[40010743] = {
		ID = 40010743,
		Speaker = "耶珥",
		Text = "那是～妾身让你做的喔。",
	},
	[40010745] = {
		ID = 40010745,
		Text = "（赛诃希丝的嘴角僵在半空，那张总是游刃有余的脸，第一次找不到任何话可以接。）",
	},
	[40010746] = {
		ID = 40010746,
		Speaker = "我",
		Text = "所以说，从头到尾真正在当反派的，其实另有其人啊。",
	},
	[40010747] = {
		ID = 40010747,
		Speaker = "耶珥",
		Text = "呵呵，少年，你这语气——听起来不太像在生气呢。",
	},
	[40010748] = {
		ID = 40010748,
		Text = "（赛诃希丝 这时候才像是回过神来，想要往后退——）",
	},
	[40010749] = {
		ID = 40010749,
		Text = "（触手却不听使唤似地，自顾自缠上了她自己的手腕。）",
	},
	[40010750] = {
		ID = 40010750,
		Speaker = "赛诃希丝",
		Text = "等、等一下，这是怎么回事！为什么我的触手——",
	},
	[40010751] = {
		ID = 40010751,
		Speaker = "耶珥",
		Text = "随便拿劣质的把戏来吓唬妾身在意的人——这种事，妾身可不会就这么算了。",
	},
	[40010752] = {
		ID = 40010752,
		Speaker = "赛诃希丝",
		Text = "等、等等，我不是那个意思，只是想让场面热闹一点而已嘛——",
	},
	[40010753] = {
		ID = 40010753,
		Speaker = "耶珥",
		Text = "呵呵，既然妳这么喜欢玩触手，那就好好体会一下，被自己的东西五花大绑是什么滋味吧。",
	},
	[40010754] = {
		ID = 40010754,
		Text = "（话音刚落，赛诃希丝背后的触手竟像是被无形的手牵引着。）",
	},
	[40010755] = {
		ID = 40010755,
		Text = "（一圈圈缠上了她自己的四肢，把她五花大绑成一团，重重摔坐在地上。）",
	},
	[40010756] = {
		ID = 40010756,
		Speaker = "赛诃希丝",
		Text = "不、不要啊，这什么下流的惩罚——快放开我啦！",
	},
	[40010757] = {
		ID = 40010757,
		Text = "（方才那副高高在上的邪神架子已经荡然无存。）",
	},
	[40010758] = {
		ID = 40010758,
		Text = "（取而代之的是拼命想挣脱、却越挣越紧的窘迫模样。）",
	},
	[40010759] = {
		ID = 40010759,
		Speaker = "我",
		Text = "话说回来，这画面好像比妳平常吓人的时候还精彩不少。",
	},
	[40010760] = {
		ID = 40010760,
		Speaker = "赛诃希丝",
		Text = "闭、闭嘴啦！飞虫没资格说这种话！",
	},
	[40010761] = {
		ID = 40010761,
		Speaker = "耶珥",
		Text = "呵呵，少年，别逗她了——被自己的触手绑住，也算是一种因果报应吧。",
	},
	[40010762] = {
		ID = 40010762,
		Speaker = "我",
		Text = "所以，现在这个被绑起来的家伙，妳打算怎么处理？",
	},
	[40010763] = {
		ID = 40010763,
		Speaker = "耶珥",
		Text = "呵呵——这个嘛，少年，你觉得呢？",
	},
	[40010764] = {
		ID = 40010764,
		Speaker = "赛诃希丝",
		Text = "咦？你们在说什么？",
	},
	[40010765] = {
		ID = 40010765,
		Speaker = "赛诃希丝",
		Text = "为什么你在脱裤子！ ？等等！",
	},
	[40010766] = {
		ID = 40010766,
	},
	[40010767] = {
		ID = 40010767,
	},
	[40010768] = {
		ID = 40010768,
		Text = "（触手将赛诃希丝的双手绑住，躺在地板上扭动。）",
	},
	[40010769] = {
		ID = 40010769,
		Speaker = "赛诃希丝",
		Text = "为什么你在脱裤子！ ？等等！",
	},
	[40010770] = {
		ID = 40010770,
		Speaker = "赛诃希丝",
		Text = "你是不又想要趁机占我便宜了？",
	},
	[40010771] = {
		ID = 40010771,
		Speaker = "我",
		Text = "你不是很喜欢这样吗？每次看到我就一副想把我吸干的样子。",
	},
	[40010772] = {
		ID = 40010772,
		Speaker = "赛诃希丝",
		Text = "确实是没错，但我想要看到的是你求饶的样子！",
	},
	[40010773] = {
		ID = 40010773,
		Speaker = "我",
		Text = "现在不一样，该你求饶了喔。",
	},
	[40010774] = {
		ID = 40010774,
	},
	[40010775] = {
		ID = 40010775,
	},
	[40010776] = {
		ID = 40010776,
		Speaker = "赛诃希丝",
		Text = "呜啊！咕呜呜呜……",
	},
	[40010777] = {
		ID = 40010777,
		Speaker = "赛诃希丝",
		Text = "可恶啊，居然用这种粗暴的姿势。",
	},
	[40010778] = {
		ID = 40010778,
		Speaker = "赛诃希丝",
		Text = "简直就像是把我当成泄欲的道具。",
	},
	[40010779] = {
