	[30140186] = {
		ID = 30140186,
		Speaker = "我",
		Text = "观众越多，游戏才好玩啊～",
	},
	[30140188] = {
		ID = 30140188,
		Speaker = "我",
		Text = "对……所以不能让观众失望，我要加速了喔～",
	},
	[30140204] = {
		ID = 30140204,
		Speaker = "我",
		Text = "惩罚结束～看妳还敢不敢说我弄的东西难吃。",
	},
	[30140212] = {
		ID = 30140212,
		Speaker = "我",
		Text = "（呵呵，这次就放妳一马吧……祝好梦～）",
	},
	[30160044] = {
		ID = 30160044,
		Speaker = "我",
		Text = "……你这个解释充满了个人风格呢。",
	},
	[30160049] = {
		ID = 30160049,
		Speaker = "我",
		Text = "呜……！",
	},
	[30160052] = {
		ID = 30160052,
		Speaker = "艾蕾娜",
		Text = "船长先生的肉棒，在手心里一跳一跳的……",
	},
	[30160053] = {
		ID = 30160053,
		Speaker = "我",
		Text = "艾蕾娜……你再继续这样动的话……",
	},
	[30160054] = {
		ID = 30160054,
		Speaker = "艾蕾娜",
		Text = "没关系喔……就这样射出来吧……全部都发泄在我的身上也可以喔……",
	},
	[30160055] = {
		ID = 30160055,
		Speaker = "我",
		Text = "等等，艾蕾娜……不行，忍……忍不住了。",
	},
	[30160056] = {
		ID = 30160056,
		Speaker = "艾蕾娜",
		Text = "呜！好多……",
	},
	[30160057] = {
		ID = 30160057,
		Speaker = "我",
		Text = "抱……抱歉……弄到你的斗篷上全部都是……",
	},
	[30160058] = {
		ID = 30160058,
		Speaker = "艾蕾娜",
		Text = "船长的……船长的气味……",
	},
	[30160059] = {
		ID = 30160059,
		Speaker = "艾蕾娜",
		Text = "好浓厚……全部都是……大脑好晕……",
	},
	[30160060] = {
		ID = 30160060,
		Speaker = "我",
		Text = "艾蕾娜……你没事吧？",
	},
	[30160061] = {
		ID = 30160061,
		Speaker = "艾蕾娜",
		Text = "嗯，没事的。",
	},
	[30160062] = {
		ID = 30160062,
		Speaker = "艾蕾娜",
		Text = "为了帮船长恢复体温，这些都是必要的……",
	},
	[30160063] = {
