	[20151004] = {
		ID = 20151004,
		Speaker = "爱诗塔",
		Text = "左边的路有人维护过，在地下城里，这种程度的打理不会是自然形成的，也许是某种魔法。",
	},
	[20151008] = {
		ID = 20151008,
		Speaker = "爱诗塔",
		Text = "中间那条没有任何可以解读的资讯，正因如此，是三条路里最难判断的一条。",
	},
	[20151014] = {
		ID = 20151014,
		Text = "（史莱姆们的动静慢慢平息了，一个接一个向黑暗深处蠕动。）",
	},
	[20151015] = {
		ID = 20151015,
		Text = "（留下几道在火把光下闪着光泽的黏液痕迹，就这样消失进走廊尽头的阴影里，它们看起来非常满足。）",
	},
	[20151016] = {
		ID = 20151016,
		Text = "（我往地上看了一眼，爱诗塔的薄纱还有身上所有大大小小的布料——已经全不见了。）",
