	[20050750] = {
		ID = 20050750,
		Text = "（清晨，我仍蜷在大床铺上，毯子滑到腰际，窗缝里透着稀薄的光，天色刚亮。）",
	},
	[20150010] = {
		ID = 20150010,
		Speaker = "我",
		Text = "还有一件事，你觉得左边那条路为什么这么亮？",
	},
	[20150022] = {
		ID = 20150022,
		Speaker = "我",
		Text = "嗯，最危险的路的感觉。",
	},
	[20150027] = {
		ID = 20150027,
		Speaker = "爱诗塔",
		Text = "前面三步，石板的颜色不对，从左边墙缝绕过去。",
	},
	[20150035] = {
		ID = 20150035,
		Text = "（后方的石板一块接一块地崩落，往黑暗中消失，脚跟刚离地，踩着的那块就不见了。）",
	},
	[20150057] = {
		ID = 20150057,
		Speaker = "爱诗塔",
		Text = "没有问题，只是——我以为你会选比较危险的那条。",
	},
	[20150067] = {
		ID = 20150067,
		Speaker = "我",
		Text = "没错，整洁的地面、通风明亮的道路——全都是招人入坑的讯号。",
	},
	[20150083] = {
		ID = 20150083,
		Speaker = "我",
		Text = "嗯，还没到尽头。",
	},
	[20150088] = {
		ID = 20150088,
		Text = "（通道继续延伸，脚步声一左一右，回响在静得过分的石壁之间。）",
	},
	[20150094] = {
		ID = 20150094,
		Text = "（通道尽头是一个稍大的空间，中央摆着一个色彩鲜艳的宝箱。）",
	},
	[20150120] = {
		ID = 20150120,
		Speaker = "爱诗塔",
		Text = "确认完毕，这条路不通，换下一条。",
	},
	[20150133] = {
		ID = 20150133,
		Speaker = "爱诗塔",
		Text = "这只是在确认我的预测是否正确，准备好了吗。",
	},
	[20150135] = {
		ID = 20150135,
		Speaker = "我",
		Text = "啊，真的过不去，不对！卡住了！",
	},
	[20150149] = {
		ID = 20150149,
		Text = "（一道轰鸣打破了宁静的地下城，整面石壁碎裂，灰烬和碎石向前爆散——）",
	},
	[20150160] = {
		ID = 20150160,
		Speaker = "爱诗塔",
		Text = "锁孔的设计不寻常，这扇门不是随意安置的。",
	},
	[20150163] = {
		ID = 20150163,
		Text = "（爱诗塔的眉头轻轻皱了一下，像是在犹豫。）",
	},
	[20150175] = {
		ID = 20150175,
		Speaker = "爱诗塔",
		Text = "这扇门存在，是因为某人在此设置了一道关卡，那道关卡本身是一种意图。",
	},
	[20150206] = {
		ID = 20150206,
		Speaker = "爱诗塔",
		Text = "设计者既然希望钥匙能被找到，就不会让它完全无迹可寻，应该有某种线索。",
	},
	[20150213] = {
		ID = 20150213,
		Speaker = "爱诗塔",
		Text = "锁孔的设计不寻常，这扇门不是随意安置的。",
	},
	[20150257] = {
		ID = 20150257,
		Speaker = "爱诗塔",
		Text = "……确实，那扇门挡着我了。",
	},
	[20150265] = {
		ID = 20150265,
		Text = "（爱诗塔依旧鼓着脸颊看着我，为了避免被砍，我连忙拍手。）",
	},
	[20150276] = {
		ID = 20150276,
		Speaker = "爱诗塔",
		Text = "锁孔的设计不寻常，这扇门不是随意安置的。",
	},
	[20150279] = {
		ID = 20150279,
		Speaker = "我",
		Text = "还没找到钥匙，代表一定有哪条路是我还没走到的，回头补完再说。",
	},
	[20150288] = {
		ID = 20150288,
		Speaker = "我",
		Text = "就是继续往前走的进度，往地下城更深处推进的进度。",
	},
	[20150307] = {
		ID = 20150307,
		Speaker = "我",
		Text = "好，那我们继续走，把剩下的路都补完再说吧。",
	},
	[20150323] = {
		ID = 20150323,
		Speaker = "我",
		Text = "好，算了，那宝石？闪亮亮那种。",
	},
	[20150324] = {
		ID = 20150324,
		Speaker = "爱诗塔",
		Text = "宝石的价值依用途而异——装饰用、货币用、记录用，若仅论外观，我没有特别需求。",
	},
	[20150343] = {
		ID = 20150343,
		Text = "（眼神直直落在我身上，说不清是在等待还是在担忧。）",
	},
	[20150356] = {
		ID = 20150356,
		Speaker = "我",
		Text = "妳是我重要的人，爱诗塔，不是工具，不是骑士——是人。",
	},
	[20150384] = {
		ID = 20150384,
		Speaker = "爱诗塔",
		Text = "原来如此，你说的是使命以外的时间。",
	},
	[20150420] = {
		ID = 20150420,
		Text = "（前方的通道稍微开阔了一些，脚步声也沉了一点，爱诗塔稍稍停顿了一下。）",
	},
	[20150453] = {
		ID = 20150453,
		Text = "（继续往深处翻，灰尘也越厚，就在我快要放弃这个角落的时候。）",
	},
	[20150462] = {
		ID = 20150462,
		Speaker = "爱诗塔",
		Text = "原来如此，封存技术相当不错，能保存这么长的时间。",
	},
	[20150475] = {
		ID = 20150475,
		Text = "（爱诗塔接过陶罐，低头看了一眼，然后闭起眼睛，慢慢把罐口往脸靠近。）",
	},
	[20150481] = {
		ID = 20150481,
		Text = "（然后她就吃了。速度快得我完全没反应过来，等我回过神。）",
	},
	[20150490] = {
		ID = 20150490,
		Text = "（爱诗塔终于抬起头，神情回到平时的冷静，只是陶罐依然在她手上。）",
	},
	[20150509] = {
		ID = 20150509,
		Speaker = "我",
		Text = "喔？但就看看封面嘛，又没打开。",
	},
	[20150519] = {
		ID = 20150519,
		Text = "（书页在我指间自行翻动起来，纸面散出一种暗绿色的光，然后唰的一声，某个东西破开了。）",
	},
	[20150522] = {
		ID = 20150522,
		Text = "（它们没有理会我，直奔爱诗塔的方向，眨眼间就把她缠得严严实实。）",
	},
	[20150529] = {
		ID = 20150529,
		Text = "（我往旁边跳开了一步。）",
	},
	[20150530] = {
		ID = 20150530,
		Text = "（剑光一闪，我几乎没有看清楚爱诗塔是怎么把剑抽出来的，只看见紫色的弧光扫过。）",
	},
	[20150531] = {
		ID = 20150531,
		Text = "（黏液四溅，触手一条接着一条从根部断落，蠕动了几下，粉碎成墨水，地上全是液体。）",
	},
	[20150561] = {
		ID = 20150561,
		Text = "（几块宝石从缝隙里折射出碎碎的光，整个房间像是有人把一座金库直接倒进来了。）",
	},
	[20150565] = {
		ID = 20150565,
		Speaker = "爱诗塔",
		Text = "没有护卫，也没有陷阱的痕迹。",
	},
	[20150571] = {
		ID = 20150571,
		Speaker = "我",
		Text = "你看，连酒杯都是金制的，这个前任主人品味不错。",
	},
	[20150572] = {
		ID = 20150572,
		Text = "（我往里头多走了几步，每一脚都踩在金币堆上，金属碰撞的细碎声从脚底散开。）",
	},
	[20150601] = {
		ID = 20150601,
		Speaker = "我",
		Text = "一枚就够了，冒险纪念嘛。",
	},
	[20150613] = {
		ID = 20150613,
		Text = "（我走出石门，踏回走道，脚底下传来的感触和来时完全不一样——）",
	},
	[20150631] = {
		ID = 20150631,
		Speaker = "爱诗塔",
		Text = "没见过，封蜡完整，应该没开封过。",
	},
	[20150636] = {
		ID = 20150636,
		Text = "（我用舌尖浅尝，液体在口腔中散开，带甜，却是有些灼烫的。）",
	},
	[20150643] = {
		ID = 20150643,
		Speaker = "我",
		Text = "当然认真，不过爱诗塔没问题吗？",
	},
	[20150658] = {
		ID = 20150658,
		Speaker = "我",
		Text = "好好，不说了，但是你那时候其实挺……",
	},
	[20150662] = {
		ID = 20150662,
		Speaker = "爱诗塔",
		Text = "那件事……从现在起不再提起，永远。",
	},
	[20150666] = {
		ID = 20150666,
		Speaker = "我",
		Text = "没有，是你想多了，好了，我们走吧。",
	},
	[20150675] = {
		ID = 20150675,
		Text = "（话音刚落，脚下传来滑腻的声响，爱诗塔的脚步骤然停住——）",
	},
	[20150676] = {
		ID = 20150676,
		Text = "（湿漉漉的史莱姆群从四面八方挤进来，两人转眼间已被数十只包围在走廊正中央。）",
	},
	[20150683] = {
		ID = 20150683,
		Text = "（却在下一秒，那六瓣各自缓缓收缩、重新聚合，恢复成完整的球体。）",
	},
	[20150687] = {
		ID = 20150687,
		Speaker = "爱诗塔",
		Text = "砍一只变两只，文献里没有记载过这种习性。",
	},
	[20150693] = {
		ID = 20150693,
		Speaker = "爱诗塔",
		Text = "后方也有，退路堵死了。",
	},
	[20150697] = {
		ID = 20150697,
		Text = "（下一瞬，几十颗半透明球体腾空而起，全数朝爱诗塔扑去，连番黏附在她的护甲与衣物上。）",
	},
	[20150699] = {
		ID = 20150699,
		Text = "（仔细一看，史莱姆并不试图伤害爱诗塔的身体——）",
	},
	[20000915] = {
		ID = 20000915,
		Speaker = "瑟蕾雅",
		Text = "因为……因为是我滑下去的嘛，如果我早一点注意到的话……",
	},
	[20080017] = {
		ID = 20080017,
		Speaker = "我",
		Text = "那就行了，今天当作练习，下次换超大只的。",
	},
	[20080064] = {
		ID = 20080064,
		Speaker = "我",
		Text = "那就行了，今天当作练习，下次换超大只的。",
	},
	[20080143] = {
		ID = 20080143,
		Speaker = "我",
		Text = "理论上可以，挖个坑，上面铺树枝盖住，再用雪伪装，放诱饵在正中间，野猪闻着味道走进来，就掉下去了。",
	},
	[20080145] = {
		ID = 20080145,
		Speaker = "我",
		Text = "因为没放诱饵，有诱饵就不一样。",
	},
	[20080147] = {
		ID = 20080147,
		Speaker = "我",
		Text = "放它最想要的东西在正中间，它就会忘记其他的，要不要试试看？",
	},
	[20080150] = {
		ID = 20080150,
		Speaker = "我",
		Text = "野猪对食物的气味很敏感，你带吃的了对吧。",
	},
	[20080487] = {
		ID = 20080487,
		Speaker = "我",
		Text = "哈提追月亮，斯库尔追太阳，它们从世界诞生那天就开始跑，一路追，从来没有停过。",
	},
	[20080505] = {
		ID = 20080505,
		Speaker = "我",
		Text = "好，那大狼把太阳和月亮都吞进肚子里之后——世界就开始崩了。",
	},
	[20080511] = {
		ID = 20080511,
		Speaker = "我",
		Text = "全部，大地沉进了海，火把剩下的烧掉，什么都没有了。",
	},
	[20080515] = {
		ID = 20080515,
		Speaker = "我",
		Text = "等一下，还没结束，沉默了很久很久之后——大地从海里升起来了。",
	},
	[20080516] = {
		ID = 20080516,
		Speaker = "我",
		Text = "全新的大地，什么都是新的，草长出来，水流清了，瀑布从高山落下去。",
	},
	[20080519] = {
		ID = 20080519,
		Speaker = "我",
		Text = "新的太阳升起来了，旧太阳留下了一个女儿，她继承了母亲的位子，从此照耀新的世界。",
	},
	[20080521] = {
		ID = 20080521,
		Speaker = "我",
		Text = "活下来的那些人，在新的土地上重新开始，故事就这样了。",
	},
	[20080535] = {
		ID = 20080535,
		Speaker = "我",
		Text = "对，就像你那件一样，大家都叫她小红帽，但她是人类。",
	},
	[20080546] = {
		ID = 20080546,
		Speaker = "我",
		Text = "对，森林里有一头大灰狼，它闻到面包的香味了，也想吃了小红帽。",
	},
	[20140172] = {
		ID = 20140172,
		Speaker = "我",
		Text = "确实，那我们要在哪里画？",
	},
	[20140300] = {
		ID = 20140300,
		Speaker = "我",
		Text = "找个合适的零件，把轮子换掉，这里什么都有，应该找得到。",
	},
	[20140482] = {
		ID = 20140482,
		Speaker = "我",
		Text = "再怎么无知，也不像是真的有恶意，这点倒是放心了。",
	},
	[20140513] = {
		ID = 20140513,
		Speaker = "我",
		Text = "放心，今晚先睡吧。",
	},
	[20140536] = {
		ID = 20140536,
		Speaker = "我",
		Text = "没有人知道长什么样子，因为被带走的小孩……都没有回来过。",
	},
	[20140598] = {
		ID = 20140598,
		Speaker = "我",
		Text = "这个问题很有趣，要不要边走边想？",
	},
	[20140601] = {
		ID = 20140601,
		Speaker = "我",
		Text = "说不定吧，今天那些来找你修理的机器人，看起来很像有自己的想法。",
	},
	[20140720] = {
		ID = 20140720,
		Speaker = "我",
		Text = "好，市集，出发前让我整理一——",
	},
	[20140736] = {
		ID = 20140736,
		Speaker = "我",
		Text = "……你能当没听见吗，话说，秋比你想吃什么？",
	},
	[40000290] = {
		ID = 40000290,
		Speaker = "伊丝娜",
		Text = "沐光节就是这么回事——女孩送一朵花给身边的人，感谢光明，感谢对方，是惯例。",
	},
	[20080025] = {
		ID = 20080025,
		Speaker = "伊尔瓦",
		Text = "嗯——这个不对，不是普通的气味。",
	},
	[20140023] = {
		ID = 20140023,
		Text = "（秋比继续往前走，两只破旧的泰迪熊晃荡在她怀里。）",
	},
	[20080028] = {
		ID = 20080028,
		Text = "（我走过去蹲下来，雪里压着一个坑洞，比我的手掌大将近两倍，坑底能看见清晰的蹄型轮廓。）",
	},
	[20080032] = {
		ID = 20080032,
		Speaker = "伊尔瓦",
		Text = "是野猪，但不只是野猪。",
	},
	[20080043] = {
		ID = 20080043,
		Speaker = "伊尔瓦",
		Text = "试过，很多次。",
	},
	[20080052] = {
		ID = 20080052,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦相信，小公鸡的脑袋一定没问题，所以说说看——有什么计画吗？",
	},
	[20080072] = {
		ID = 20080072,
		Speaker = "伊尔瓦",
		Text = "嗯——这个不对，不是普通的气味。",
	},
	[20080075] = {
		ID = 20080075,
		Text = "（我走过去蹲下来，雪里压着一个坑洞，比我的手掌大将近两倍，坑底能看见清晰的蹄型轮廓。）",
	},
	[20080079] = {
		ID = 20080079,
		Speaker = "伊尔瓦",
		Text = "是野猪，但不只是野猪。",
	},
	[20080090] = {
		ID = 20080090,
		Speaker = "伊尔瓦",
		Text = "试过，很多次。",
	},
	[20080099] = {
		ID = 20080099,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦相信，小公鸡的脑袋一定没问题，所以说说看——有什么计画吗？",
	},
	[20080113] = {
		ID = 20080113,
		Speaker = "伊尔瓦",
		Text = "嗯——这个不对，不是普通的气味。",
	},
	[20080116] = {
		ID = 20080116,
		Text = "（我走过去蹲下来，雪里压着一个坑洞，比我的手掌大将近两倍，坑底能看见清晰的蹄型轮廓。）",
	},
	[20080120] = {
		ID = 20080120,
		Speaker = "伊尔瓦",
		Text = "是野猪，但不只是野猪。",
	},
	[20080131] = {
		ID = 20080131,
		Speaker = "伊尔瓦",
		Text = "试过，很多次。",
	},
	[20080140] = {
		ID = 20080140,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦相信，小公鸡的脑袋一定没问题，所以说说看——有什么计画吗？",
	},
	[20080144] = {
		ID = 20080144,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦试过挖坑，野猪之王跳过去了。",
	},
	[20080153] = {
		ID = 20080153,
		Text = "（伊尔瓦沉默了一下，然后深吸一口气。）",
	},
	[20080170] = {
		ID = 20080170,
		Text = "（突然树林深处传来一声闷响，野猪之王从雪堆里直接冲出来，四蹄踩上陷阱盖——）",
	},
	[20080222] = {
		ID = 20080222,
		Speaker = "伊尔瓦",
		Text = "你看，耳朵是真的，长在这里的。",
	},
	[20080225] = {
		ID = 20080225,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦是狼养大的，所以有一部分是狼。",
	},
	[20080229] = {
		ID = 20080229,
		Speaker = "伊尔瓦",
		Text = "嗯，现在也闻得到远处的面包香味。",
	},
	[20080260] = {
		ID = 20080260,
		Speaker = "伊尔瓦",
		Text = "你看，耳朵是真的，长在这里的。",
	},
	[20080263] = {
		ID = 20080263,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦是狼养大的，所以有一部分是狼。",
	},
	[20080267] = {
		ID = 20080267,
		Speaker = "伊尔瓦",
		Text = "嗯，现在也闻得到远处的面包香味。",
	},
	[20080298] = {
		ID = 20080298,
		Speaker = "伊尔瓦",
		Text = "你看，耳朵是真的，长在这里的。",
	},
	[20080301] = {
		ID = 20080301,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦是狼养大的，所以有一部分是狼。",
	},
	[20080305] = {
		ID = 20080305,
		Speaker = "伊尔瓦",
		Text = "嗯，现在也闻得到远处的面包香味。",
	},
	[20080494] = {
		ID = 20080494,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦吞太阳不是让世界死掉，是让旧世界睡着，让新的早晨出生。",
	},
	[20080500] = {
		ID = 20080500,
		Speaker = "伊尔瓦",
		Text = "雪球和木炭也是伊尔瓦带大的幼狼，雪球喜欢追月亮的影子，木炭喜欢对着太阳叫。",
	},
	[20080520] = {
		ID = 20080520,
		Text = "（雪洞里沉默了，伊尔瓦没有打断，也没有问问题，连底下扇风的窸窣声都停了。）",
	},
	[20080624] = {
		ID = 20080624,
		Text = "（两个人一起滚进了雪堆，等世界终于停止旋转，才意识到自己半埋在雪里。）",
	},
	[20080661] = {
		ID = 20080661,
		Speaker = "伊尔瓦",
		Text = "上次的故事还没说完，继续说。",
	},
	[20140067] = {
		ID = 20140067,
		Text = "（秋比继续往前走，两只破旧的泰迪熊晃荡在她怀里。）",
	},
	[20140130] = {
		ID = 20140130,
		Text = "（秋比继续往前走，两只破旧的泰迪熊晃荡在她怀里。）",
	},
	[20140181] = {
		ID = 20140181,
		Text = "（秋比不等我说完，已经冲向铜像底座，对着薇拉的裙摆大力一喷，鲜红的弧线在铜绿表面炸开。）",
	},
	[20140338] = {
		ID = 20140338,
		Text = "（咚，那颗摇摇欲坠的轮子终于坚持不住，从机器人身上滚了下来。）",
	},
	[20140380] = {
		ID = 20140380,
		Text = "（咚，那颗摇摇欲坠的轮子终于坚持不住，从机器人身上滚了下来。）",
	},
	[20140423] = {
		ID = 20140423,
		Text = "（咚，那颗摇摇欲坠的轮子终于坚持不住，从机器人身上滚了下来。）",
	},
	[20140470] = {
		ID = 20140470,
		Text = "（深夜，遗忘之都的街道空空荡荡的，齿轮声平稳的回荡在街道上，仅有微弱的月光和路灯的光芒。）",
	},
	[20140565] = {
		ID = 20140565,
		Text = "（两台机器人各自把头顶的东西轻轻放到地上，随后倒入热水。）",
	},
	[20140642] = {
		ID = 20140642,
		Text = "（被拉着转进旁边的小巷，暗巷里只有头上一盏忽明忽暗的灯。）",
	},
	[20140649] = {
		ID = 20140649,
		Speaker = "秋比",
		Text = "就说嘛，大玩偶就是会跑的，所以要站在旁边才可以。",
	},
	[20140703] = {
		ID = 20140703,
		Text = "有什么东西在弹，有节奏地上窜下跳、让床板震动。",
	},
	[20140781] = {
		ID = 20140781,
		Text = "（一串彩色气球跟在她身后飘，在空荡荡的夜街里显得荒唐而鲜艳，我叹了一口气，跟上去。）",
	},
	[30040155] = {
		ID = 30040155,
		Speaker = "我",
		Text = "看吧，身体比嘴诚实，一捏奶头，里面就收得更紧了。",
	},
	[30050108] = {
		ID = 30050108,
		Speaker = "我",
		Text = "那个，黛莉亚，身为一个忙碌的旅人，我平常的事情还挺多的。",
	},
	[30070141] = {
		ID = 30070141,
		Speaker = "我",
		Text = "……抱歉，女王陛下，没忍住。",
	},
	[30080086] = {
		ID = 30080086,
		Text = "希望之丘的仓库，深夜，某个不知轻重的狼群之主，正在做一件非常不明智的事情。",
	},
	[30080109] = {
		ID = 30080109,
		Speaker = "伊尔瓦",
		Text = "……哼，就这样？",
	},
	[30080113] = {
		ID = 30080113,
		Speaker = "伊尔瓦",
		Text = "……嗯，完全没感觉。",
	},
	[30080120] = {
		ID = 30080120,
		Speaker = "伊尔瓦",
		Text = "……哼，小意思。",
	},
	[30080125] = {
		ID = 30080125,
		Speaker = "伊尔瓦",
		Text = "……没事，继续。",
	},
	[30090088] = {
		ID = 30090088,
		Speaker = "葛蕾香",
		Text = "呵……你看出来了，龙族的待客之道，从来不会敷衍。",
	},
	[30140094] = {
		ID = 30140094,
		Speaker = "秋比",
		Text = "呼……绑住那种地方……就真的是谋杀了吧……",
	},
	[30170003] = {
		ID = 30170003,
		Speaker = "西西雅",
		Text = "贫血，新的心脏还没适应这副破烂身体。",
	},
	[30170004] = {
		ID = 30170004,
		Speaker = "我",
		Text = "我帮你找医生。",
	},
	[30170005] = {
		ID = 30170005,
		Speaker = "西西雅",
		Text = "不用，我需要你的色欲能量。",
	},
	[30170074] = {
		ID = 30170074,
		Speaker = "西西雅",
		Text = "作家的本能，至少还能享受写作的快感。",
	},
	[30170104] = {
		ID = 30170104,
		Speaker = "西西雅",
		Text = "……我要把你写死，下一本男主是反派，结局惨死。",
	},
	[30170111] = {
		ID = 30170111,
		Speaker = "西西雅",
		Text = "现实版本比我写的还要过分，写了也没办法超越。",
	},
	[30170113] = {
		ID = 30170113,
		Speaker = "西西雅",
		Text = "是称赞，文学意义上的称赞。",
	},
	[10012390] = {
		ID = 10012390,
		Speaker = "西西雅",
		Text = "你理解得很快，我们是这么怀疑的。",
	},
	[10012439] = {
		ID = 10012439,
		Speaker = "我",
		Text = "真可靠，也真可怕。",
	},
	[10012468] = {
		ID = 10012468,
		Speaker = "我",
		Text = "北方，就是飞船迫降的地方",
	},
	[10012477] = {
		ID = 10012477,
		Speaker = "艾蕾娜",
		Text = "北门封锁，孩子们也都回到屋内。",
	},
	[10012488] = {
		ID = 10012488,
		Speaker = "瑟蕾雅",
		Text = "只是去确认一件遗失的东西，请大家留在屋内。",
	},
	[10012493] = {
		ID = 10012493,
		Speaker = "艾蕾娜",
		Text = "出发，风雪正在变强。",
	},
	[10012617] = {
		ID = 10012617,
		Speaker = "伊尔瓦",
		Text = "不能，名字是被咬出来的。",
	},
	[10012621] = {
		ID = 10012621,
		Speaker = "伊尔瓦",
		Text = "像心脏，又不像心脏，像太阳被关在笼子里，还很不服气。",
	},
	[10012623] = {
		ID = 10012623,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦‧芬里西亚，雪林的红帽，雪球和木炭的妈妈。",
	},
	[10012628] = {
		ID = 10012628,
		Speaker = "我",
		Text = "吞噬日月，芬布尔之冬，妳就是那个芬布尔传说！",
	},
	[10012632] = {
		ID = 10012632,
		Speaker = "伊尔瓦",
		Text = "但现在的冬天很臭，不是我的味道。",
	},
	[10012642] = {
		ID = 10012642,
		Speaker = "伊尔瓦",
		Text = "她以前会许愿，会哭，会抱着别人的愿望发抖，现在她只剩下一座很冷的城。",
	},
	[10012665] = {
		ID = 10012665,
		Speaker = "伊尔瓦",
		Text = "走吧，再慢一点，森林就要把你们的名字吃掉了。",
	},
	[10012682] = {
		ID = 10012682,
		Speaker = "我",
		Text = "墨水还没干，她离开不久。",
	},
	[10012686] = {
		ID = 10012686,
		Speaker = "我",
		Text = "这里少了一页，撕痕很新。",
	},
	[10012689] = {
		ID = 10012689,
		Speaker = "艾蕾娜",
		Text = "不是看见，是灯记得。",
	},
	[10012694] = {
		ID = 10012694,
		Speaker = "我",
		Text = "我知道，所以我们更不能用慌张替她送第二次危险。",
	},
	[10012697] = {
		ID = 10012697,
		Speaker = "瑟蕾雅",
		Text = "每次重要的人离开，大家都这么说，可是留下来的人，还是会一直想是不是自己不够好。",
	},
	[10012700] = {
		ID = 10012700,
		Speaker = "瑟蕾雅",
		Text = "对不起，我会冷静。",
	},
	[10012705] = {
		ID = 10012705,
		Speaker = "我",
		Text = "『勒瓦杜兰』 她是谁？",
	},
	[10012711] = {
		ID = 10012711,
		Speaker = "瑟蕾雅",
		Text = "它不是普通灯，她也不是普通提灯者。",
	},
	[10012712] = {
		ID = 10012712,
		Speaker = "艾蕾娜",
		Text = "我不知道自己是不是普通，别人需要我照亮路，我就照亮。",
	},
	[10012717] = {
		ID = 10012717,
		Speaker = "西西雅的笔记",
		Text = "「瑟蕾雅如果看到这里，先不要哭，妳哭起来会把字弄湿。」",
	},
	[10012719] = {
		ID = 10012719,
		Speaker = "西西雅的笔记",
		Text = "「我去雪之深处确认一件事，但等不及你们回来，就当我是病人任性。」",
	},
	[10012724] = {
		ID = 10012724,
		Speaker = "我",
		Text = "会，当一个愿望太痛，连许愿的人都不敢承认它时。",
	},
	[10012727] = {
		ID = 10012727,
		Speaker = "瑟蕾雅",
		Text = "「瑟蕾雅，不要跟来，妳来了，我就会想回头。」",
	},
	[10012729] = {
		ID = 10012729,
		Speaker = "黛莉亚",
		Text = "从脚印方向来看，她往裂谷走，那里是前往雪之深处的旧路。",
	},
	[10012734] = {
		ID = 10012734,
		Speaker = "我",
		Text = "两个都要，但如果只能选一个，我选妳。",
	},
	[10012735] = {
		ID = 10012735,
		Speaker = "瑟蕾雅",
		Text = "西西一定很害怕，可是她还是去了。",
	},
	[10012738] = {
		ID = 10012738,
		Speaker = "艾蕾娜",
		Text = "风变了，现在出发，还追得上脚印。",
	},
	[10012739] = {
		ID = 10012739,
		Speaker = "我",
		Text = "那就走吧，去把毒舌的病人从世界尽头带回来。",
	},
	[10012740] = {
		ID = 10012740,
		Speaker = "瑟蕾雅",
		Text = "不是带回来，是一起回来。",
	},
	[10012751] = {
		ID = 10012751,
		Speaker = "伊尔瓦",
		Text = "是被新的雪覆盖了，风向刚好从北边吹来。",
	},
	[10012755] = {
		ID = 10012755,
		Speaker = "艾蕾娜",
		Text = "我会引路，这是我会做的事。",
	},
	[10012758] = {
		ID = 10012758,
		Speaker = "我",
		Text = "差很多，前者是工具，后者是妳有多特别。",
	},
	[10012763] = {
		ID = 10012763,
		Speaker = "瑟蕾雅",
		Text = "会，我会把她带回来。",
	},
	[10012765] = {
		ID = 10012765,
		Speaker = "瑟蕾雅",
		Text = "……会，这次，我也会回来。",
	},
	[10012771] = {
		ID = 10012771,
		Speaker = "我",
		Text = "所以人才会想保护它，太大的东西，反而不容易让人心疼。",
	},
	[10012783] = {
		ID = 10012783,
		Speaker = "瑟蕾雅",
		Text = "前面有裂谷，地图上标记为「旧雪道」。",
	},
	[10012835] = {
		ID = 10012835,
		Speaker = "艾蕾娜",
		Text = "我没有不舒服，我只是……不想靠近门。",
	},
	[10012869] = {
		ID = 10012869,
		Text = "雪下的世界忽然静了，瑟蕾雅红着脸紧闭双眼，艾蕾娜的灯火轻轻颤动。",
	},
	[10012892] = {
		ID = 10012892,
		Speaker = "我",
		Text = "是管理档案，像在记录许愿妖精的执行历程。",
	},
	[10012928] = {
		ID = 10012928,
		Speaker = "我",
		Text = "没错，这次轮到我们找到她。",
	},
	[10012940] = {
		ID = 10012940,
		Speaker = "我",
		Text = "对，还有伊尔瓦，这点无法忽略。",
	},
	[10013423] = {
		ID = 10013423,
		Speaker = "西西雅",
		Text = "别得意，我仍然认为你非常可疑。",
	},
	[10013428] = {
		ID = 10013428,
		Speaker = "我",
		Text = "我会记得的，小红帽小姐，以后改吃面包，不吃太阳了吧？",
	},
	[10012864] = {
		ID = 10012864,
		Speaker = "瑟蕾雅",
		Text = "我希望西西不要再为我逞强，可是我更害怕……如果她不为我逞强，我就不知道自己还值不值得被留下。",
	},
	[40000006] = {
		ID = 40000006,
		Text = "（像是整片大地瞻仰着阳光，脚踩上去是松软的草地，空气是甜的。是我没见过的地方，连想像都到不了的那种。）",
	},
	[40000016] = {
		ID = 40000016,
		Text = "（在风里轻轻飘动，它们看起来像是蒲公英长了眼睛跟嘴巴。）",
	},
	[40000035] = {
		ID = 40000035,
		Text = "（就在这时，毛球群动了，每只身上都带着由各种野花和细草编织而成的花圈，不知是从哪变出来的。）",
	},
	[40000051] = {
		ID = 40000051,
		Text = "（沐光节的摊位比预想的密集许多，毛球居民站在各自的摊位前，用圆滚滚的身体招呼着来往的毛球。）",
	},
	[40000059] = {
		ID = 40000059,
		Text = "（伊丝娜僵在原地，低头看着手里的黄色小花，毛球还在原地等，眼睛亮得像小灯泡。）",
	},
	[40000091] = {
		ID = 40000091,
		Text = "（毛球们不需要任何进一步的邀请，更多的同伴从四面涌来，一圈一圈绕着伊丝娜围下去。）",
	},
	[40000116] = {
		ID = 40000116,
		Text = "（傍晚的光线把花朵星球染成金橘色，节庆的喧嚷声并没有因此安静下来，我在飞船的舱口——）",
	},
	[40000158] = {
		ID = 40000158,
		Speaker = "我",
		Text = "嗯，先问一件事——李奥纳多头上那卷卫生纸是什么情况？",
	},
	[40000172] = {
		ID = 40000172,
		Speaker = "黛莉亚",
		Text = "好……好，谢谢舰长先生。",
	},
	[40000174] = {
		ID = 40000174,
		Text = "（杯子上系着一朵小花，毛球把茶推到黛莉亚面前，仰起圆脸，一副等着被谢谢的模样。）",
	},
	[40000187] = {
		ID = 40000187,
		Speaker = "我",
		Text = "这样，戴上看看。",
	},
	[40000203] = {
		ID = 40000203,
		Speaker = "薇拉",
		Text = "并非，只是顺带说明，这是人类行为学：聊天的一部份。",
	},
	[40000204] = {
		ID = 40000204,
		Speaker = "薇拉",
		Text = "这边是蜜罐花，花心液体含高浓度糖分，是沐光节最常见的赠礼品种，本地毛球以此作为主要食物来源之一。",
	},
	[40000224] = {
		ID = 40000224,
		Text = "（我转过头，看了她几秒，她也看着我，没有笑、没有皱眉，什么都没有。）",
	},
	[40000253] = {
		ID = 40000253,
		Speaker = "秋比",
		Text = "对喔，它们一直在讲这个故事。",
	},
	[40000255] = {
		ID = 40000255,
		Speaker = "秋比",
		Text = "好呀，秋比帮妳翻，等等我！",
	},
	[40000260] = {
		ID = 40000260,
		Speaker = "秋比",
		Text = "然后一个女神来了，带来光，让花长出来，让毛球们有了家。",
	},
	[40000265] = {
		ID = 40000265,
		Speaker = "伊丝娜",
		Text = "感谢身边的人，倒是个有温度的习俗。",
	},
	[40000269] = {
		ID = 40000269,
		Speaker = "秋比",
		Text = "送花给喜欢的人，它说，很灵的。",
	},
	[40000306] = {
		ID = 40000306,
		Speaker = "伊丝娜",
		Text = "啊——等一下，那边角落那朵，那朵向日葵，小的那朵。",
	},
	[40000324] = {
		ID = 40000324,
		Speaker = "伊丝娜",
		Text = "好，走过去，把花递出去，就这样。",
	},
	[40000344] = {
		ID = 40000344,
		Speaker = "伊丝娜",
		Text = "我说没有就是没有！你眼花了，现在可以放开我了吗！",
	},
	[40000351] = {
