	},
	[20060577] = {
		ID = 20060577,
		Text = "（掌心还残留着那一瞬间的触感，大衣里面什么都没穿——）",
	},
	[20060578] = {
		ID = 20060578,
		Speaker = "我",
		Text = "薇拉，妳这样走在外面……是认真的吗。",
	},
	[20100005] = {
		ID = 20100005,
		Speaker = "耶珥",
		Text = "呵呵……放轻松，少年，这片林子有什么值得妾身特地设局的？",
	},
	[20100033] = {
		ID = 20100033,
		Speaker = "耶珥",
		Text = "呵呵……放轻松，少年，这片林子有什么值得妾身特地设局的？",
	},
	[20100062] = {
		ID = 20100062,
		Speaker = "耶珥",
		Text = "呵呵……放轻松，少年，这片林子有什么值得妾身特地设局的？",
	},
	[20100086] = {
		ID = 20100086,
		Text = "（我在林子里绕了一圈，五片叶子的确实不少，我找了几株看起来最像的，折回去。）",
	},
	[20100109] = {
		ID = 20100109,
		Speaker = "耶珥",
		Text = "不算毒，只是汁液接触皮肤会发热，然后起疹子，最后心脏就会停止。",
	},
	[20100147] = {
		ID = 20100147,
		Speaker = "耶珥",
		Text = "不算毒，只是汁液接触皮肤会发热，然后起疹子，最后心脏就会停止。",
	},
	[20100186] = {
		ID = 20100186,
		Speaker = "耶珥",
		Text = "不算毒，只是汁液接触皮肤会发热，然后起疹子，最后心脏就会停止。",
	},
	[20100348] = {
		ID = 20100348,
		Speaker = "我",
		Text = "跑步草一直往前冲，前面是峭壁地形，把它逼到角落，它就没有退路了。",
	},
	[20100353] = {
		ID = 20100353,
		Speaker = "耶珥",
		Text = "别说话，少年，你看。",
	},
	[20100363] = {
		ID = 20100363,
		Speaker = "我",
		Text = "我这不是顾全你的采药大计吗，白追了多可惜。",
	},
	[20100386] = {
		ID = 20100386,
		Speaker = "我",
		Text = "跑步草一直往前冲，右前方是河流地形，把它逼到河边，它就没有退路了。",
	},
	[20100391] = {
		ID = 20100391,
		Speaker = "耶珥",
		Text = "别说话，少年，你看。",
	},
	[20100401] = {
		ID = 20100401,
		Speaker = "我",
		Text = "我这不是顾全你的采药大计吗，白追了多可惜。",
	},
	[20100416] = {
		ID = 20100416,
		Speaker = "耶珥",
		Text = "不需要知道的事就别问，省事多了。",
	},
	[20100417] = {
		ID = 20100417,
		Speaker = "耶珥",
		Text = "针线也有，少年，接着。",
	},
	[20100423] = {
		ID = 20100423,
		Speaker = "耶珥",
		Text = "穿着缝不方便，少年你平时做事都这么瞻前顾后的吗。",
	},
	[20100426] = {
		ID = 20100426,
		Text = "（我接过递来的裙装，布料比看起来更轻薄丝滑，耶珥在野餐垫上坐了下来，把茶杯端在手上。）",
	},
	[20100576] = {
		ID = 20100576,
		Text = "（只有踩枯叶的声音和偶尔的鸟鸣，没有什么特定目标——）",
	},
	[20100595] = {
		ID = 20100595,
		Speaker = "耶珥",
		Text = "哎，少年把妾身想得太复杂了，今天就只是出来采点药，没有别的意思——对吧？",
	},
	[20100598] = {
		ID = 20100598,
		Text = "（阳光穿过树冠筛落，在脚边洒出不规则的金斑，我把最后一口水咽下去——靠着树干坐着。）",
	},
	[20100604] = {
		ID = 20100604,
		Speaker = "耶珥",
		Text = "勉勉强强，好了，休息够了——正事开始。",
	},
	[20100607] = {
		ID = 20100607,
		Speaker = "我",
		Text = "原来如此，所以「偶遇」是演的？",
	},
	[20100610] = {
		ID = 20100610,
		Speaker = "耶珥",
		Text = "呵呵……好，妾身就直说了，有一种药草，妾身自己采不到，需要少年你出马。",
	},
	[20100614] = {
		ID = 20100614,
		Speaker = "耶珥",
		Text = "嗯，两条，跑起来非常的快呦。",
	},
	[20100616] = {
		ID = 20100616,
		Speaker = "耶珥",
		Text = "它叫做跑步草，顾名思义，是会移动的植物。而且对魔力极度敏感。",
	},
	[20100618] = {
		ID = 20100618,
		Speaker = "耶珥",
		Text = "妾身一靠近，它立刻拔腿就跑，每一次都是。",
	},
	[20100627] = {
		ID = 20100627,
		Text = "（我跟在耶珥身后往更深的树荫走去，脚底下的苔藓越来越厚，传来啪达啪达的脚步声。）",
	},
	[20100629] = {
		ID = 20100629,
		Speaker = "耶珥",
		Text = "次数不重要，妾身只是每次都被跑走了，跑多了就把路记住了。",
	},
	[20100632] = {
		ID = 20100632,
		Speaker = "我",
		Text = "谢谢夸奖，如果它睡醒了跑起来，我可以追吗？",
	},
	[20100633] = {
		ID = 20100633,
		Speaker = "耶珥",
		Text = "可以追——妾身只是追不上而已，少年你若有把握，妾身倒很想看看。",
	},
	[20130030] = {
		ID = 20130030,
		Speaker = "伊丝娜",
		Text = "不对吧，差很多好吗！",
	},
	[20130041] = {
		ID = 20130041,
		Text = "（她的动作顿了一下，手指抬起来碰了碰浏海，又放下——）",
	},
	[20130053] = {
		ID = 20130053,
		Speaker = "伊丝娜",
		Text = "甜的，你应该喝得惯，比你说的那什么便宜啤酒好喝一百倍。",
	},
	[20130061] = {
		ID = 20130061,
		Speaker = "我",
		Text = "就那支，看起来最贵的那个。",
	},
	[20130065] = {
		ID = 20130065,
		Speaker = "我",
		Text = "总之，酒听起来很不得了，那就它了，学姊。",
	},
	[20130074] = {
		ID = 20130074,
		Text = "（我喝了一口，入喉的瞬间像有什么东西在舌根点了一把火，沿着喉咙一路烫到胸口。）",
	},
	[20130075] = {
		ID = 20130075,
		Speaker = "我",
		Text = "……嗯，有点，难以入口。",
	},
	[20130077] = {
		ID = 20130077,
		Speaker = "我",
		Text = "嗯，很烈，而且辣。",
	},
	[20130079] = {
		ID = 20130079,
		Text = "（伊丝娜的表情在那一瞬间凝住了，嘴角微微动了一下，视线缓缓飘向远方。）",
	},
	[20130085] = {
		ID = 20130085,
		Speaker = "我",
		Text = "刚才说的「通常只有行家才会点」。",
	},
	[20130086] = {
		ID = 20130086,
		Speaker = "伊丝娜",
		Text = "……好，算了，这支先放一边，不然我们换点比较甜的，我帮你调一杯。",
	},
	[20130094] = {
		ID = 20130094,
		Speaker = "伊丝娜",
		Text = "甜的，你应该喝得惯，连这点都喝不下去的话，我们就只有牛奶了。",
	},
	[20130101] = {
		ID = 20130101,
		Speaker = "我",
		Text = "我不太懂这些，妳帮我挑一个好了。",
	},
	[20130110] = {
		ID = 20130110,
		Speaker = "我",
		Text = "好喝就多喝，难喝就停下来，大概这样？",
	},
	[20130114] = {
		ID = 20130114,
		Speaker = "我",
		Text = "学姊帮我调一杯嘛，学姊自己设计的那种。",
	},
	[20130121] = {
		ID = 20130121,
		Speaker = "我",
		Text = "学姊特制调酒，开始期待了。",
	},
	[20130126] = {
		ID = 20130126,
		Speaker = "伊丝娜",
		Text = "甜的，你应该喝得惯，连这点都喝不下去的话，我们就只有牛奶了。",
	},
	[20130187] = {
		ID = 20130187,
		Speaker = "我",
		Text = "对了——学姊来这艘船也一段时间了吧，习惯了吗？",
	},
	[20130191] = {
		ID = 20130191,
		Speaker = "伊丝娜",
		Text = "不对吧，习惯像是针对「不可以改变的事情」说的。",
	},
	[20130193] = {
		ID = 20130193,
		Speaker = "伊丝娜",
		Text = "比如说行政系统根本一塌糊涂，文件格式没有统一，报告提交窗口不固定，整艘船上都是疯子！",
	},
	[20130197] = {
		ID = 20130197,
		Speaker = "伊丝娜",
		Text = "……没有别的办法，对吧，东西摆在那里乱着，放着不管才是真的有问题。",
	},
	[20130198] = {
		ID = 20130198,
		Text = "（她喝得比我想像中快，我瞥了一眼那个杯子，没说什么。）",
	},
	[20130200] = {
		ID = 20130200,
		Speaker = "伊丝娜",
		Text = "生活上……不习惯的地方很多，早餐没有固定时间，作息跟我以前完全不一样。",
	},
	[20130207] = {
		ID = 20130207,
		Speaker = "伊丝娜",
		Text = "我说了，不习惯不是重点，重点是这些东西可以解决，所以就解决掉。",
	},
	[20130221] = {
		ID = 20130221,
		Text = "（我往前倾了一点，仔细看了一眼，耳根到脸颊，有一层淡淡的红——）",
	},
	[20130238] = {
		ID = 20130238,
		Speaker = "伊丝娜",
		Text = "生活上……不习惯的地方很多，早餐没有固定时间，作息跟我以前完全不一样。",
