	[20130471] = {
		ID = 20130471,
		Speaker = "我",
		Text = "好好好，是真的，那不如我们先回去睡觉，明天再继续吧。",
	},
	[20130474] = {
		ID = 20130474,
		Speaker = "我",
		Text = "学姊，妳刚才把我的饮料当妳的喝掉了，整杯。",
	},
	[20130479] = {
		ID = 20130479,
		Text = "（伊丝娜一把甩开了我伸过去的手，她站起来，摇晃了一下——）",
	},
	[20130512] = {
		ID = 20130512,
		Speaker = "我",
		Text = "好好好，是真的，那不如我们先回去睡觉，明天再继续吧。",
	},
	[20130515] = {
		ID = 20130515,
		Speaker = "我",
		Text = "学姊，妳刚才把我的饮料当妳的喝掉了，整杯。",
	},
	[20130686] = {
		ID = 20130686,
		Text = "（走廊的灯光昏黄，按学姊说的方向走，那扇有红色小灯的门在转角。）",
	},
	[20130693] = {
		ID = 20130693,
		Text = "（与平时不同，学姊的身上穿着的是一套头黑色兔女郎装——把她平日那股行政官的冷淡线条全数打散，手边排了几只空酒杯，表情非常刻意地维持镇定，但那半截结巴已经把底牌亮了一半。）",
	},
	[20130701] = {
		ID = 20130701,
		Text = "（酒吧的灯光昏黄，全裸的伊丝娜坐在吧台后，手边空杯子排了一列。）",
	},
	[10010270] = {
		ID = 10010270,
		Text = "飞船落地，扬起尘雾，飞船走下来一名男子，若无其事地拍了拍身上的灰。",
	},
	[20000008] = {
		ID = 20000008,
		Text = "（我蹲下来，把线沉进冰洞里，洞口冒着一丝寒气。）",
	},
	[20000010] = {
		ID = 20000010,
		Speaker = "我",
		Text = "管他的，就当是拿着鱼竿发呆好了，这样等人好像比较不无聊。",
	},
	[20000032] = {
		ID = 20000032,
		Speaker = "我",
		Text = "不管怎么说，你终于来了，雪橇带了吗？",
	},
	[20000043] = {
		ID = 20000043,
		Text = "（我弯腰靠近，往里面看了一眼，不大，但能避风。）",
	},
	[20000046] = {
		ID = 20000046,
		Text = "（我把身子压低，钻了进去，里面比想像中大。）",
	},
	[20000054] = {
		ID = 20000054,
		Speaker = "我",
		Text = "嗯，发现了一座，就钻进来了，要进来吗？",
	},
	[20000075] = {
		ID = 20000075,
		Text = "（像是谁把整座丘陵都裹上了一层糖衣，我站在坡底，仰着头往上看。）",
	},
	[20000086] = {
		ID = 20000086,
		Text = "（我几步冲了下去，在雪堆旁蹲下来，那团雪球缓缓动了一下，露出了银色的长发和一双粉紫色的眼睛。）",
	},
	[20000091] = {
		ID = 20000091,
		Speaker = "瑟蕾雅",
		Text = "没有受伤！完全没事的，像这样的事情在希望之丘到处都看的到……我已经很习惯了。",
	},
	[20000097] = {
		ID = 20000097,
		Speaker = "瑟蕾雅",
		Text = "我自己也不太懂怎么发生的，就是走着走着，然后就趴在地上了。",
	},
	[20000104] = {
		ID = 20000104,
		Speaker = "我",
		Text = "不算很久，虽然你出场方式有点……出乎预料。",
	},
	[20000108] = {
		ID = 20000108,
		Speaker = "我",
		Text = "还是有点微妙的差距的，吓到是反射，震惊是佩服。",
	},
	[20000189] = {
		ID = 20000189,
		Speaker = "我",
		Text = "没问题的，就试一下嘛，不舒服的话马上起来就好。",
	},
	[20000190] = {
		ID = 20000190,
		Speaker = "瑟蕾雅",
		Text = "那个……好、好吧，晨星先生先示范一下吗？",
	},
	[20000194] = {
		ID = 20000194,
		Speaker = "我",
		Text = "没事没事，来，你也躺下来。",
	},
	[20000196] = {
		ID = 20000196,
		Speaker = "瑟蕾雅",
		Text = "……哇，天空好大。",
	},
	[20000197] = {
		ID = 20000197,
		Speaker = "我",
		Text = "好，现在张开手脚，像这样——用力往雪里压，然后慢慢上下挥动。",
	},
	[20000199] = {
		ID = 20000199,
		Speaker = "我",
		Text = "雪天使，你没听过吗？",
	},
	[20000202] = {
		ID = 20000202,
		Speaker = "我",
		Text = "就是这样躺着，手脚慢慢动，起来之后地上会留下一个轮廓，像天使展开翅膀的形状。",
	},
	[20000207] = {
		ID = 20000207,
		Speaker = "我",
		Text = "雪地里的仰泳，也不是不行，就是有点冷而已。",
	},
	[20000209] = {
		ID = 20000209,
		Speaker = "我",
		Text = "等你站起来就知道了，有人在旁边看才好玩，自己做自己看少了点什么。",
	},
	[20000211] = {
		ID = 20000211,
		Speaker = "我",
		Text = "那今天就长见识了，跟对人出门还是有差的。",
	},
	[20000230] = {
		ID = 20000230,
		Text = "（短暂的沉默，他这才意识到她还没起身，两人距离近得能看清彼此呼出的白雾。）",
	},
	[20000233] = {
		ID = 20000233,
		Speaker = "我",
		Text = "先别急，雪里面可能有坑，先确认脚没扭到再动。",
	},
	[20000256] = {
		ID = 20000256,
		Speaker = "瑟蕾雅",
		Text = "……好，我在听，我在这里。",
	},
	[20000261] = {
		ID = 20000261,
		Speaker = "我",
		Text = "还有……告诉大家，我走得很安详，雪很冷，但……挺舒服的。",
	},
	[20000279] = {
		ID = 20000279,
		Text = "经历了刚才的小插曲，两人终于做到了心心念念的雪橇上。",
	},
	[20000280] = {
		ID = 20000280,
		Text = "两列并排的脚步在白色大地中画出一条歪曲的线。",
	},
	[20000319] = {
