		ID = 10050007,
		Speaker = "伊丝娜",
		Text = "我快渴死了，你在跟我说风景。",
	},
	[10050008] = {
		ID = 10050008,
		Speaker = "我",
		Text = "那边有条河。",
	},
	[10050009] = {
		ID = 10050009,
		Text = "伊丝娜眼睛一亮，快步走过去，蹲下来看。",
	},
	[10050010] = {
		ID = 10050010,
		Speaker = "伊丝娜",
		Text = "……这是水吗？这是泥巴吧！",
	},
	[10050011] = {
		ID = 10050011,
		Text = "河床里流着混浊的褐色液体，沙尘在水面上结成一层薄薄的壳，闻起来有股说不清楚的腥味。",
	},
	[10050012] = {
		ID = 10050012,
		Speaker = "伊丝娜",
		Text = "这到底是什么鬼星球？ ？ ？",
	},
	[10050013] = {
		ID = 10050013,
		Speaker = "伊丝娜",
		Text = "我为什么不学秋比黛莉亚在飞船上睡觉就好？ ？",
	},
	[10050014] = {
		ID = 10050014,
		Speaker = "我",
		Text = "面对现实吧，抽签可是很无情的，学姊。",
	},
	[10050015] = {
		ID = 10050015,
		Speaker = "我",
		Text = "刚才那条也不行，再往前看看吧。",
	},
	[10050016] = {
		ID = 10050016,
		Text = "两人继续在荒原上走。远处的地平线上，沙尘暴的边缘像一道移动的墙，缓缓往这个方向滚来。",
	},
	[10050017] = {
		ID = 10050017,
		Speaker = "伊丝娜",
		Text = "我们迷路了吗？",
	},
	[10050018] = {
		ID = 10050018,
		Speaker = "我",
		Text = "没有。",
	},
	[10050019] = {
		ID = 10050019,
		Speaker = "伊丝娜",
		Text = "那聚落在哪里？",
	},
	[10050020] = {
		ID = 10050020,
		Speaker = "我",
		Text = "……再往前一点。",
	},
	[10050021] = {
		ID = 10050021,
		Speaker = "伊丝娜",
		Text = "我们已经「再往前一点」，六次了！",
	},
	[10050022] = {
		ID = 10050022,
		Speaker = "我",
		Text = "第七次会到的。",
	},
	[10050023] = {
		ID = 10050023,
		Speaker = "我",
		Text = "我通常是开船的，地面不算我的强项。",
	},
	[10050024] = {
		ID = 10050024,
		Speaker = "伊丝娜",
		Text = "我到底为什么要跟你下船……",
	},
	[10050025] = {
		ID = 10050025,
		Text = "就在这个时候，远处传来一声枪响，清脆而干净，在荒原上滚出很远的回声。",
	},
	[10050026] = {
		ID = 10050026,
		Speaker = "伊丝娜",
		Text = "枪声！",
	},
	[10050027] = {
		ID = 10050027,
		Speaker = "我",
		Text = "有人的地方就有水。",
	},
	[10050028] = {
		ID = 10050028,
		Speaker = "伊丝娜",
		Text = "有人的地方也有子弹！",
	},
	[10050029] = {
		ID = 10050029,
		Text = "转场",
	},
	[10050030] = {
		ID = 10050030,
		Text = "转场",
	},
	[10050031] = {
		ID = 10050031,
		Text = "两人循着枪声的方向，终于在一片低矮的土墙后面看见了聚落的轮廓。",
	},
	[10050032] = {
		ID = 10050032,
		Text = "镇口聚集着一大群人，神情紧张，全都往街道中央看去。",
	},
	[10050033] = {
		ID = 10050033,
		Text = "沿着人群外围，拖着大包小包的『难民们』疲惫不堪、眼神空洞地坐在地上。",
	},
	[10050034] = {
		ID = 10050034,
		Text = "人群中央，一个肩上扛着步枪，另一手持左轮手枪的女人——",
	},
	[10050035] = {
		ID = 10050035,
		Text = "正站在街道正中间，对着前方五个拿着武器的大汉。",
	},
	[10050036] = {
		ID = 10050036,
		Text = "女人姿势懒散，但那双眼睛却冷得像准星。",
	},
	[10050037] = {
		ID = 10050037,
		Speaker = "女人",
		Text = "老子数到三，把上周抢走的水票还来，老子就当什么都没发生。",
	},
	[10050038] = {
		ID = 10050038,
		Speaker = "恶霸手下A",
		Text = "你……你知道你在对付谁吗？这条街是……",
	},
	[10050039] = {
		ID = 10050039,
		Speaker = "女人",
		Text = "一。",
	},
	[10050040] = {
		ID = 10050040,
		Speaker = "恶霸手下A",
		Text = "你疯了吗！我们有五个人！",
	},
	[10050041] = {
		ID = 10050041,
		Speaker = "女人",
		Text = "二。",
	},
	[10050042] = {
		ID = 10050042,
		Text = "只见女人手缓缓扣下击锤，恶霸手下知道这场对决无法逃避了。",
	},
	[10050043] = {
		ID = 10050043,
		Text = "五个大汉与女人相隔几十步，目光对峙。",
	},
	[10050044] = {
		ID = 10050044,
		Text = "四周安静得可怕，瞬间抽干了所有声音。",
	},
	[10050045] = {
		ID = 10050045,
		Speaker = "女人",
		Text = "三！",
	},
	[10050046] = {
		ID = 10050046,
		Text = "连续的枪响，撕裂了整条街的死寂。",
	},
	[10050047] = {
		ID = 10050047,
		Text = "硝烟自枪口袅袅升起，只见四名恶霸直接倒下，最后一名恶霸的手抖个不停，枪被射击掉落在地面。",
	},
	[10050048] = {
		ID = 10050048,
		Text = "女人熟练地转动枪轮，将发烫的手枪插回腰间的皮套。",
	},
	[10050049] = {
		ID = 10050049,
		Speaker = "凯伊",
		Text = "哼，差了一点。",
	},
	[10050050] = {
		ID = 10050050,
		Speaker = "恶霸手下",
		Text = "水票给你……这罐水也给你……",
	},
	[10050051] = {
		ID = 10050051,
		Speaker = "恶霸手下",
		Text = "拜托放过我……",
	},
	[10050052] = {
		ID = 10050052,
		Text = "凯伊从恶霸手中取回一叠水票，还有几瓶密封完好的干净水。",
	},
	[10050053] = {
		ID = 10050053,
		Text = "她把一瓶收起来，剩下的水瓶全数丢给了旁边眼神空洞的难民们。",
	},
	[10050054] = {
		ID = 10050054,
		Speaker = "凯伊",
		Text = "拿去吧，老子还不渴。",
	},
	[10050055] = {
		ID = 10050055,
		Text = "难民们为了几瓶水，竟抢成一团。",
	},
	[10050056] = {
		ID = 10050056,
		Speaker = "我",
		Text = "这地方的水，要靠打架才能拿到？",
	},
	[10050057] = {
		ID = 10050057,
		Speaker = "伊丝娜",
		Text = "看起来是这样。",
