	[10050058] = {
		ID = 10050058,
		Speaker = "我",
		Text = "那刚好。",
	},
	[10050059] = {
		ID = 10050059,
		Text = "我大步走上前，挡在凯伊面前。",
	},
	[10050060] = {
		ID = 10050060,
		Speaker = "我",
		Text = "决斗。",
