	[10050068] = {
		ID = 10050068,
		Speaker = "我",
		Text = "你数到三，我也可以。",
	},
	[10050069] = {
		ID = 10050069,
		Text = "凯伊脸色一沉，周围的人群往后退了一步，自动空出一条通道。",
	},
	[10050071] = {
		ID = 10050071,
		Text = "一个侧身，扬起地面的沙尘，同时一个转身压低凯伊的枪管，那一枪打进了地里。",
	},
	[10050072] = {
