		Speaker = "我",
		Text = "硬把我拉进这个充满雌性龙族贺尔蒙的古堡……",
	},
	[10050274] = {
		ID = 10050274,
		Speaker = "我",
		Text = "……还是说这才是你的目的？",
	},
	[10050275] = {
		ID = 10050275,
		Speaker = "葛蕾香",
		Text = "你的逻辑思维，令本人印象深刻。",
	},
	[10050276] = {
		ID = 10050276,
		Speaker = "我",
		Text = "谢谢。",
	},
	[10050277] = {
		ID = 10050277,
		Speaker = "葛蕾香",
		Text = "这不是夸奖。",
	},
	[10050278] = {
		ID = 10050278,
		Speaker = "我",
		Text = "我知道。不过你现在这个反应，让我想起一个人。",
	},
	[10050279] = {
		ID = 10050279,
		Speaker = "葛蕾香",
		Text = "……谁。",
	},
	[10050281] = {
		ID = 10050281,
		Speaker = "葛蕾香",
		Text = "谁？",
	},
	[10050282] = {
		ID = 10050282,
		Speaker = "我",
		Text = "原初女神。",
	},
	[10050283] = {
		ID = 10050283,
		Text = "葛蕾香的视线没有移开，但某个细微的东西在她眼神里动了一下。",
	},
	[10050284] = {
		ID = 10050284,
		Text = "最后葛蕾香松开她紧抓我脖子的手。",
	},
	[10050285] = {
		ID = 10050285,
		Speaker = "葛蕾香",
		Text = "……你跟主上见过面。",
	},
	[10050286] = {
		ID = 10050286,
		Speaker = "我",
		Text = "咳咳……不然呢？我们的关系比这深远多了。",
	},
	[10050287] = {
		ID = 10050287,
		Speaker = "葛蕾香",
		Text = "哼。",
	},
	[10050288] = {
		ID = 10050288,
		Speaker = "我",
		Text = "我有必要在一个随时能杀我的龙族面前说谎吗？",
	},
	[10050289] = {
		ID = 10050289,
		Text = "葛蕾香没有立刻回答。",
	},
	[10050290] = {
		ID = 10050290,
		Text = "她盯着我，试图从他脸上找到破绽。",
	},
	[10050291] = {
		ID = 10050291,
		Speaker = "葛蕾香",
		Text = "主上……为什么通缉你，难道你也是这样对她？",
	},
	[10050292] = {
		ID = 10050292,
		Text = "葛蕾香的尾巴缠绕住裤裆的隆起，像是随时都能绞碎我的部位。",
	},
	[10050293] = {
		ID = 10050293,
		Speaker = "我",
		Text = "（她为什么想知道？）",
	},
	[10050294] = {
		ID = 10050294,
		Speaker = "我",
		Text = "比起这个，你不好奇为什么我下面的隆起都没有消退吗？",
	},
	[10050295] = {
		ID = 10050295,
		Speaker = "葛蕾香",
		Text = "……无耻之徒。",
	},
	[10050296] = {
		ID = 10050296,
		Speaker = "我",
		Text = "说不定这就是原初女神通缉我的原因喔？葛蕾香……",
	},
	[10050297] = {
		ID = 10050297,
		Speaker = "葛蕾香",
		Text = "住嘴，斗胆直呼我名讳。",
	},
	[10050298] = {
		ID = 10050298,
		Speaker = "我",
		Text = "不然能叫你什么？",
	},
	[10050300] = {
		ID = 10050300,
		Speaker = "我",
		Text = "你如果想知道我跟原初女神之间的……秘密，我们做个交易吧？",
	},
	[10050301] = {
		ID = 10050301,
		Speaker = "葛蕾香",
		Text = "哼，何必跟将死之人做交易？",
	},
	[10050302] = {
		ID = 10050302,
		Speaker = "我",
		Text = "你有什么损失吗？给我足够带回飞船的水，我就告诉你关于她的事。",
	},
	[10050303] = {
		ID = 10050303,
		Speaker = "我",
		Text = "很好奇吧？高高在上的女神的真实个性到底为何？",
	},
	[10050304] = {
		ID = 10050304,
		Speaker = "我",
		Text = "以你的阶级，我想也未必能接触她吧？",
	},
	[10050305] = {
		ID = 10050305,
		Speaker = "葛蕾香",
		Text = "本人自有办法。",
	},
	[10050306] = {
		ID = 10050306,
		Speaker = "我",
		Text = "你也可以杀了我，什么都问不到。",
	},
	[10050307] = {
		ID = 10050307,
		Text = "葛蕾香沉默片刻。",
	},
	[10050308] = {
		ID = 10050308,
		Speaker = "葛蕾香",
		Text = "水可以给你。但你要跟本人走，亲自向主上赔罪。",
	},
	[10050309] = {
		ID = 10050309,
		Speaker = "我",
		Text = "不行。",
	},
	[10050310] = {
		ID = 10050310,
		Speaker = "葛蕾香",
		Text = "那就别想拿到水。",
	},
	[10050311] = {
		ID = 10050311,
		Speaker = "我",
		Text = "我有另一个提议。",
	},
	[10050312] = {
		ID = 10050312,
		Speaker = "葛蕾香",
		Text = "本人不感兴趣。",
	},
	[10050313] = {
		ID = 10050313,
		Speaker = "我",
		Text = "你现在的状态，古堡里又只有你一个龙族……",
	},
	[10050314] = {
		ID = 10050314,
		Speaker = "我",
		Text = "你要怎么宣泄自己的欲望？",
	},
	[10050315] = {
		ID = 10050315,
		Speaker = "葛蕾香",
		Text = "……你最好想清楚接下来要说的话。",
	},
	[10050316] = {
		ID = 10050316,
		Speaker = "我",
		Text = "我可是连原初女神都忌惮的对象。",
	},
	[10050317] = {
		ID = 10050317,
		Speaker = "我",
		Text = "你不好奇，她当初为什么忌惮我吗？",
	},
	[10050318] = {
		ID = 10050318,
		Text = "葛蕾香没有说话。",
	},
	[10050319] = {
		ID = 10050319,
		Text = "她转过头，背对着我。",
	},
	[10050320] = {
		ID = 10050320,
		Speaker = "我",
		Text = "（她犹豫了。）",
	},
	[10050321] = {
		ID = 10050321,
		Text = "只见葛蕾香盯着不远处挂在墙上的一把断剑，若有所思。",
	},
	[10050322] = {
		ID = 10050322,
		Text = "转场",
	},
	[10050323] = {
		ID = 10050323,
		Text = "转场",
	},
	[10050324] = {
		ID = 10050324,
		Text = "聚落首领的住所，比外面任何地方都干净，桌上什至摆着一瓶透明的水。",
	},
	[10050325] = {
		ID = 10050325,
		Text = "伊丝娜与凯伊坐在人类首领对面，神情各异。",
	},
	[10050326] = {
		ID = 10050326,
		Speaker = "伊丝娜",
		Text = "感谢你们的救援，不然被她这样一挥，我的身体早就散了……",
	},
	[10050327] = {
		ID = 10050327,
		Text = "（不晓得后辈怎么样了……）",
	},
	[10050328] = {
		ID = 10050328,
		Speaker = "首领",
		Text = "两位面对龙族，能活下来，实属幸运。",
	},
	[10050329] = {
		ID = 10050329,
		Speaker = "凯伊",
		Text = "是老子闪得快，不是幸运。",
	},
	[10050330] = {
		ID = 10050330,
		Speaker = "首领",
		Text = "凯伊小姐每次都是被打飞出去的，这不一样。",
	},
	[10050331] = {
		ID = 10050331,
		Speaker = "凯伊",
		Text = "……",
	},
	[10050332] = {
		ID = 10050332,
		Speaker = "首领",
		Text = "龙族在这颗星球上的时间，已经太久。她带来诅咒，带来沙尘暴，带来灾难。",
	},
	[10050334] = {
		ID = 10050334,
		Speaker = "伊丝娜",
		Text = "龙族死前的诅咒？",
	},
	[10050335] = {
		ID = 10050335,
		Speaker = "首领",
		Text = "百年前，龙族曾经跟人类为了争夺水源地，演变成一场种族的全面战争。",
	},
	[10050336] = {
		ID = 10050336,
		Speaker = "首领",
		Text = "最后我们的先祖，几乎歼灭了龙族。",
	},
	[10050337] = {
		ID = 10050337,
		Speaker = "首领",
		Text = "相传龙族长老死前下了最狠毒的诅咒，自此我们的水源每日都会遭到沙尘暴侵袭……",
	},
	[10050338] = {
		ID = 10050338,
		Speaker = "伊丝娜",
		Text = "所以你们想杀掉她？化解诅咒？",
	},
	[10050339] = {
		ID = 10050339,
		Speaker = "首领",
		Text = "不是想。是必须。",
	},
	[10050340] = {
		ID = 10050340,
		Text = "首领诚恳地转向凯伊。",
	},
	[10050341] = {
		ID = 10050341,
		Speaker = "首领",
		Text = "凯伊小姐，你是这颗星球最好的枪手。这件事，非你莫属。",
	},
	[10050342] = {
		ID = 10050342,
		Speaker = "凯伊",
		Text = "……你要老子暗杀她？",
	},
	[10050343] = {
		ID = 10050343,
		Speaker = "首领",
		Text = "悄悄解决，对大家都好……",
	},
	[10050344] = {
		ID = 10050344,
		Speaker = "凯伊",
		Text = "不可能。",
	},
	[10050345] = {
		ID = 10050345,
		Speaker = "首领",
		Text = "凯伊小姐？",
	},
	[10050346] = {
		ID = 10050346,
		Speaker = "首领",
		Text = "我们会提供星球最高的赏金给你",
	},
	[10050347] = {
		ID = 10050347,
		Speaker = "凯伊",
		Text = "正面对决，不搞阴招。这是老子的规矩！",
	},
	[10050348] = {
		ID = 10050348,
		Speaker = "首领",
		Text = "正面对决，她能够防御人类的子弹……",
	},
	[10050349] = {
		ID = 10050349,
		Speaker = "凯伊",
		Text = "那你们就想办法找到有效的子弹。",
	},
	[10050350] = {
		ID = 10050350,
		Speaker = "首领",
		Text = "你能不能不要事不关己的态度？难道你不想拯救其他没有水喝的同胞吗？",
	},
	[10050351] = {
		ID = 10050351,
		Speaker = "凯伊",
		Text = "老子……是独行侠。",
	},
	[10050352] = {
		ID = 10050352,
		Speaker = "凯伊",
		Text = "你们想要什么，就自己去抢！",
	},
	[10050353] = {
		ID = 10050353,
		Text = "首领看着凯伊，沉默片刻，没有继续追问。",
	},
	[10050354] = {
		ID = 10050354,
		Text = "就在这时，门开了。",
	},
	[10050355] = {
		ID = 10050355,
		Text = "我走进来，拍了拍身上的沙尘，神情自若。",
	},
	[10050356] = {
		ID = 10050356,
		Speaker = "我",
		Text = "我找了好久，终于听说你们被送到这。",
	},
	[10050357] = {
		ID = 10050357,
		Text = "伊丝娜与凯伊惊讶万分。",
	},
	[10050358] = {
		ID = 10050358,
		Speaker = "伊丝娜",
		Text = "后辈！ ！你怎么出来的！ ？",
