	[10050359] = {
		ID = 10050359,
		Speaker = "凯伊",
		Text = "从古堡走出来的人类……老子还真是活久见！",
	},
	[10050360] = {
		ID = 10050360,
		Speaker = "我",
		Text = "没什么，大概是我长得还算可爱，她就把我放了。",
	},
	[10050361] = {
		ID = 10050361,
		Speaker = "伊丝娜",
		Text = "……什么？",
	},
	[10050362] = {
		ID = 10050362,
		Speaker = "我",
		Text = "龙族也是会审美的。",
