	[10050377] = {
		ID = 10050377,
		Speaker = "凯伊",
		Text = "老子只是还在考虑，你这么快就找其他人，",
	},
	[10050378] = {
		ID = 10050378,
		Speaker = "凯伊",
		Text = "这样是不给老子面子！",
	},
	[10050379] = {
		ID = 10050379,
		Speaker = "首领",
		Text = "…….",
