	[10050388] = {
		ID = 10050388,
		Speaker = "伊丝娜",
		Text = "那是人。",
	},
	[10050389] = {
		ID = 10050389,
		Speaker = "首领",
		Text = "那是机械。",
	},
	[10050390] = {
		ID = 10050390,
		Speaker = "伊丝娜",
		Text = "我说，那是人！",
	},
	[10050391] = {
		ID = 10050391,
		Text = "凯伊眼神黯淡，别过头去，很显然她也无力阻止这个状况。",
	},
	[10050392] = {
		ID = 10050392,
		Text = "伊丝娜转向首领，眼神从来没这么冷过。",
	},
	[10050393] = {
		ID = 10050393,
		Speaker = "伊丝娜",
		Text = "停止这件事。善待机械难民。这是我的条件。",
