	[10050394] = {
		ID = 10050394,
		Speaker = "伊丝娜",
		Text = "你是人类方的首领，你办得到吧！ ！ ！ ！",
	},
	[10050395] = {
		ID = 10050395,
		Text = "伊丝娜气到全身颤抖，我拍拍她的背，表示理解。",
	},
	[10050396] = {
		ID = 10050396,
		Speaker = "我",
		Text = "你听到我学姊说的，",
