		Text = "伊丝娜还没说话，我先开口了。",
	},
	[10050403] = {
		ID = 10050403,
		Speaker = "我",
		Text = "他在说谎。",
	},
	[10050404] = {
		ID = 10050404,
		Speaker = "伊丝娜",
		Text = "我知道。",
	},
	[10050405] = {
		ID = 10050405,
		Speaker = "我",
		Text = "那你还……",
