	[10050406] = {
		ID = 10050406,
		Speaker = "伊丝娜",
		Text = "我知道他在说谎。",
	},
	[10050407] = {
		ID = 10050407,
		Text = "伊丝娜停下脚步，看着那片空地的方向。",
	},
	[10050408] = {
