	[10050410] = {
		ID = 10050410,
		Text = "远处，沙尘暴的边缘又往这个方向靠近了一些。",
	},
	[10050411] = {
		ID = 10050411,
		Text = "转场",
	},
	[10050412] = {
		ID = 10050412,
		Text = "转场",
	},
	[10050413] = {
		ID = 10050413,
		Text = "聚落外围，一条通往水源地的小路。",
	},
	[10050415] = {
		ID = 10050415,
		Speaker = "凯伊",
		Text = "在老子想到办法之前，老子不会对龙族婆娘出招。",
	},
	[10050416] = {
		ID = 10050416,
		Speaker = "凯伊",
		Text = "这是神枪手的原则。",
	},
	[10050417] = {
		ID = 10050417,
		Speaker = "我",
		Text = "喔？所以你还是想拿赏金的嘛。",
	},
	[10050418] = {
		ID = 10050418,
		Speaker = "凯伊",
		Text = "没有理由不拿。",
	},
	[10050419] = {
		ID = 10050419,
		Speaker = "我",
		Text = "是吗？",
	},
	[10050420] = {
		ID = 10050420,
		Speaker = "我",
		Text = "其实你也是想帮忙改变现状的吧？",
	},
	[10050421] = {
		ID = 10050421,
		Text = "凯伊装傻假装没听到。",
	},
	[10050422] = {
		ID = 10050422,
		Speaker = "我",
		Text = "……口是心非的家伙。",
	},
	[10050423] = {
		ID = 10050423,
		Text = "两人沿着石壁走，快接近水源地的时候，前方突然传来动静。",
	},
	[10050424] = {
		ID = 10050424,
		Text = "突然来了七八个人，堵在路口。",
	},
	[10050425] = {
		ID = 10050425,
		Speaker = "手下A",
		Text = "凯伊，你如果不出手，就手上的步枪留下来给我们用。",
	},
	[10050426] = {
		ID = 10050426,
		Speaker = "凯伊",
		Text = "哦？",
	},
	[10050427] = {
		ID = 10050427,
		Speaker = "手下A",
		Text = "你不帮忙，就是龙族同路人。",
	},
	[10050428] = {
		ID = 10050428,
		Speaker = "我",
		Text = "神枪手，你不辩解吗？",
	},
	[10050429] = {
		ID = 10050429,
		Speaker = "凯伊",
		Text = "想要什么，就自己来抢。",
	},
	[10050430] = {
		ID = 10050430,
		Text = "凯伊拔出步枪，对方也同时拔枪。",
	},
	[10050431] = {
		ID = 10050431,
		Text = "人数悬殊，但凯伊脸上没有半点慌张。",
	},
	[10050432] = {
		ID = 10050432,
		Speaker = "我",
		Text = "几个人你有把握？",
	},
	[10050433] = {
		ID = 10050433,
		Speaker = "凯伊",
		Text = "全部。",
	},
	[10050434] = {
		ID = 10050434,
		Speaker = "我",
		Text = "那我在旁边看。",
	},
	[10050435] = {
		ID = 10050435,
		Speaker = "凯伊",
		Text = "老子不需要你。",
	},
	[10050436] = {
		ID = 10050436,
		Text = "枪声大作，凯伊闪身躲过第一波攻击，反手击倒两个人。",
	},
	[10050437] = {
		ID = 10050437,
		Text = "她继续推进，动作干净俐落，一个接一个地把手下逼退。",
	},
	[10050438] = {
		ID = 10050438,
		Text = "眼看就要突破，",
	},
	[10050439] = {
		ID = 10050439,
		Text = "一阵异响从远处滚来。",
	},
	[10050440] = {
		ID = 10050440,
		Text = "低沉的、震动空气的声音。",
	},
	[10050441] = {
		ID = 10050441,
		Speaker = "我",
		Text = "凯伊！ ！ ！",
	},
	[10050442] = {
		ID = 10050442,
		Text = "沙尘暴的前锋像一道墙，瞬间吞没了整条路。",
	},
	[10050443] = {
		ID = 10050443,
		Text = "黄沙横扫，视线归零，所有人被冲击气流打得站不稳。",
	},
	[10050444] = {
		ID = 10050444,
		Text = "凯伊被卷起来，整个人撞进石壁，重重落地。",
	},
	[10050445] = {
		ID = 10050445,
		Speaker = "凯伊",
		Text = "……惨了。",
	},
	[10050446] = {
		ID = 10050446,
		Text = "她想站起来，腿却不听使唤。",
	},
	[10050447] = {
		ID = 10050447,
		Text = "手下们也被打散，但已经有人重新举起了枪。",
	},
	[10050448] = {
		ID = 10050448,
		Speaker = "手下A",
		Text = "找到她了！干掉她！",
	},
	[10050449] = {
		ID = 10050449,
		Text = "凯伊闭上眼睛。",
	},
	[10050450] = {
		ID = 10050450,
		Text = "枪声没有响。",
	},
	[10050451] = {
		ID = 10050451,
		Text = "取而代之的，是另一道声音，低沉的、带着某种古老重量的声音，像是某样东西睁开了眼。",
	},
	[10050452] = {
		ID = 10050452,
		Text = "所有手下的枪，同时飞了出去。",
	},
	[10050453] = {
		ID = 10050453,
		Text = "沙尘中，一个身影站在凯伊面前。",
	},
	[10050454] = {
		ID = 10050454,
		Speaker = "葛蕾香",
		Text = "一群乌合之众。",
	},
	[10050455] = {
		ID = 10050455,
		Text = "葛蕾香低头看了凯伊一眼，然后转身，准备离开。",
	},
	[10050456] = {
		ID = 10050456,
		Speaker = "凯伊",
		Text = "……喂。",
	},
	[10050457] = {
		ID = 10050457,
		Speaker = "葛蕾香",
		Text = "什么事。",
	},
	[10050458] = {
		ID = 10050458,
		Speaker = "凯伊",
		Text = "你为什么救老子？",
	},
	[10050459] = {
		ID = 10050459,
		Speaker = "葛蕾香",
		Text = "本人没有救你。",
	},
	[10050460] = {
		ID = 10050460,
		Speaker = "凯伊",
		Text = "你刚才明明……",
	},
	[10050461] = {
		ID = 10050461,
		Speaker = "葛蕾香",
		Text = "本人只是刚好路过，顺手处理了几个碍眼的东西。",
	},
	[10050462] = {
		ID = 10050462,
		Speaker = "葛蕾香",
		Text = "你刚好在里面，跟本人无关。",
	},
	[10050463] = {
		ID = 10050463,
		Text = "她没有再说话，走进沙尘里，消失了。",
	},
	[10050464] = {
		ID = 10050464,
		Speaker = "凯伊",
		Text = "……",
	},
	[10050465] = {
		ID = 10050465,
		Speaker = "我",
		Text = "能站吗？",
	},
	[10050466] = {
		ID = 10050466,
		Speaker = "凯伊",
		Text = "老子自己来。",
	},
	[10050467] = {
		ID = 10050467,
		Speaker = "我",
		Text = "好。",
	},
	[10050468] = {
		ID = 10050468,
		Speaker = "凯伊",
		Text = "……她为什么要救老子。",
	},
	[10050469] = {
		ID = 10050469,
		Speaker = "我",
		Text = "她说没有救你。",
	},
	[10050470] = {
		ID = 10050470,
		Text = "凯伊不甘愿被救，竟直接冲向葛蕾香离去的方向。",
	},
	[10050471] = {
		ID = 10050471,
		Text = "我跟伊丝娜不解对看，只好也跟了上去。",
	},
	[10050472] = {
		ID = 10050472,
		Text = "转场",
	},
	[10050473] = {
		ID = 10050473,
		Text = "转场",
	},
	[10050474] = {
		ID = 10050474,
		Text = "葛蕾香来到某处废墟，手上光芒大作，一挥手就把不远处的大石头炸飞。",
	},
	[10050475] = {
		ID = 10050475,
		Text = "尘埃落定后，葛蕾香随即在被炸开的地面找到一块金属碎片。",
	},
	[10050476] = {
		ID = 10050476,
		Text = "凯伊跟过来，不禁好奇葛蕾香找到什么。",
	},
	[10050477] = {
		ID = 10050477,
		Text = "葛蕾香一个人蹲在地上。",
	},
	[10050478] = {
		ID = 10050478,
		Text = "她手里捧着一块金属碎片，剑刃的一截，边缘已经生锈。",
	},
	[10050479] = {
		ID = 10050479,
		Text = "她的手指轻轻描着上面的纹路，像在摸一样很珍贵的东西。",
	},
	[10050480] = {
		ID = 10050480,
		Speaker = "葛蕾香",
		Text = "……终于找到你。",
	},
	[10050481] = {
		ID = 10050481,
		Speaker = "葛蕾香",
		Text = "你当年是什么样的人呢。",
	},
	[10050482] = {
		ID = 10050482,
		Speaker = "葛蕾香",
		Text = "本人一次都没有见过你。",
	},
	[10050483] = {
		ID = 10050483,
		Speaker = "葛蕾香",
		Text = "但他们都说你是个蠢透了的人类……",
	},
	[10050484] = {
		ID = 10050484,
		Text = "她停了一下。",
	},
	[10050485] = {
		ID = 10050485,
		Speaker = "葛蕾香",
		Text = "本人觉得，你没做错。",
	},
	[10050487] = {
		ID = 10050487,
		Text = "风吹过废墟，扬起一点沙尘。",
	},
	[10050488] = {
		ID = 10050488,
		Text = "葛蕾香把碎片贴近胸口，低着头感受，一动也不动。",
	},
	[10050489] = {
		ID = 10050489,
		Text = "凯伊靠在墙上，看着这一幕，没有出声。",
	},
	[10050490] = {
		ID = 10050490,
		Speaker = "凯伊",
		Text = "（她是在怀念谁？）",
	},
	[10050491] = {
		ID = 10050491,
		Text = "不知道过了多久，葛蕾香从怀里拿出本来挂在古堡上的断剑，放置在地上，跟剑刃摆在一起",
	},
	[10050492] = {
		ID = 10050492,
		Text = "看起来就像是一把完好如初的宝剑。",
	},
	[10050493] = {
		ID = 10050493,
		Text = "凯伊看到这里，不禁张大了嘴巴。",
	},
	[10050494] = {
		ID = 10050494,
		Speaker = "葛蕾香",
		Text = "爸爸，你还需要这把长剑的另一半。",
	},
	[10050495] = {
		ID = 10050495,
		Speaker = "葛蕾香",
		Text = "本人找了数十年，只找回这把长剑。",
	},
	[10050496] = {
		ID = 10050496,
		Speaker = "葛蕾香",
		Text = "短剑应该还在某人手上。",
	},
	[10050497] = {
		ID = 10050497,
		Text = "葛蕾香收走剑，走进暗下来的荒原里，消失了。",
	},
	[10050498] = {
		ID = 10050498,
		Text = "凯伊坐在原地，腿软无力，喃喃自语道",
	},
	[10050499] = {
		ID = 10050499,
		Speaker = "凯伊",
		Text = "龙族婆娘怎么会有长剑『孤行』……",
	},
	[10050500] = {
		ID = 10050500,
		Speaker = "凯伊",
		Text = "老子找了这么久，居然是在她手上……",
	},
	[10050501] = {
		ID = 10050501,
		Text = "凯伊站起来，快步往回走。",
	},
	[10050502] = {
		ID = 10050502,
		Text = "她没有注意到，墙角另一边，我跟伊丝娜也站在那里。",
	},
	[10050503] = {
		ID = 10050503,
		Text = "我目送凯伊离去，低头想了想。",
	},
	[10050504] = {
		ID = 10050504,
		Speaker = "伊丝娜",
		Text = "那把长剑是什么来头？",
	},
	[10050505] = {
		ID = 10050505,
		Speaker = "伊丝娜",
		Text = "怎么凯伊看到这么崩溃？",
	},
	[10050506] = {
		ID = 10050506,
		Speaker = "我",
		Text = "学姊，知道我怎么离开古堡的吗？",
	},
	[10050508] = {
		ID = 10050508,
		Speaker = "伊丝娜",
		Text = "为什么？",
	},
	[10050509] = {
		ID = 10050509,
		Text = "我的思绪飘回数小时前，",
	},
	[10050510] = {
		ID = 10050510,
	},
	[10050511] = {
		ID = 10050511,
		Text = "在古堡内，葛蕾香突然拿起墙上的断剑给我看",
	},
	[10050512] = {
		ID = 10050512,
		Speaker = "葛蕾香",
		Text = "这个剑柄的样式，你要牢记在心。",
	},
	[10050513] = {
		ID = 10050513,
		Speaker = "葛蕾香",
		Text = "本来是一对双剑，这是长剑『孤行』，还有一把短剑『静默』。",
	},
	[10050514] = {
		ID = 10050514,
		Speaker = "我",
		Text = "你需要我帮忙找短剑？",
	},
	[10050515] = {
		ID = 10050515,
		Speaker = "我",
		Text = "呵呵，不怕我直接逃走吗？",
	},
	[10050516] = {
		ID = 10050516,
		Speaker = "葛蕾香",
		Text = "本人方才已在你身上种下印记，去哪里我都知道。",
	},
	[10050517] = {
		ID = 10050517,
		Speaker = "葛蕾香",
		Text = "我放你走，人类会视你为英雄。",
	},
	[10050518] = {
		ID = 10050518,
		Speaker = "葛蕾香",
		Text = "帮我留意有没有人知道这把短剑的下落。",
	},
	[10050519] = {
		ID = 10050519,
		Speaker = "我",
		Text = "你为什么不直接问，拿水源交换情报？",
	},
	[10050520] = {
		ID = 10050520,
		Speaker = "我",
		Text = "我相信他们挤破头也会想办法找到。",
	},
	[10050521] = {
		ID = 10050521,
		Speaker = "葛蕾香",
		Text = "本人有不做这事的理由。",
	},
	[10050522] = {
		ID = 10050522,
		Text = "回忆结束，伊丝娜理解来龙去脉后，好奇我的想法。",
	},
	[10050523] = {
		ID = 10050523,
		Speaker = "伊丝娜",
		Text = "那你现在算什么？双面间谍吗？",
	},
	[10050524] = {
		ID = 10050524,
		Speaker = "我",
		Text = "三面间谍。",
	},
	[10050525] = {
		ID = 10050525,
		Speaker = "我",
		Text = "我要同时兼顾龙族、人类、机械公民的利益。",
	},
	[10050526] = {
		ID = 10050526,
		Speaker = "我",
		Text = "容易吗我？我不过想好好喝口纯净的水！ ！ ！",
	},
	[10050527] = {
		ID = 10050527,
		Speaker = "我",
		Text = "怎么这么麻烦！ ！ ！",
	},
	[10050528] = {
		ID = 10050528,
		Speaker = "伊丝娜",
		Text = "后辈，不管怎么样，你一定要解决我们机械公民的处境。",
	},
	[10050529] = {
		ID = 10050529,
		Speaker = "伊丝娜",
		Text = "我相信你办得到！",
	},
	[10050530] = {
		ID = 10050530,
		Speaker = "我",
		Text = "谢谢你，不过说到底，水都是被你们三个女人喝完的。",
	},
	[10050531] = {
		ID = 10050531,
		Text = "为什么是我要解决问题？",
	},
	[10050532] = {
		ID = 10050532,
		Speaker = "伊丝娜",
		Text = "你好意思说？还不是你一直在船上跟我……那个，然后又跟黛莉亚那个，还跟秋比那个……",
	},
	[10050535] = {
		ID = 10050535,
		Speaker = "我",
		Text = "啊……好吧，是我的问题。",
	},
	[10050536] = {
		ID = 10050536,
		Text = "转场",
	},
	[10050537] = {
		ID = 10050537,
		Text = "转场",
	},
	[10050538] = {
		ID = 10050538,
		Text = "聚落边缘，凯伊推开一扇旧木门，走进一间小屋。",
	},
	[10050539] = {
		ID = 10050539,
		Text = "我跟在后面，没有被邀请，也没有被阻止。",
	},
	[10050540] = {
		ID = 10050540,
		Text = "小屋里很简单，一张桌，一把椅，墙上挂着几幅地图。",
	},
	[10050541] = {
		ID = 10050541,
		Text = "凯伊走到桌边，打开一个旧木盒，从里面取出一把短剑，握在手里。",
	},
	[10050543] = {
		ID = 10050543,
		Speaker = "凯伊",
		Text = "你跟过来干嘛？",
	},
	[10050544] = {
		ID = 10050544,
		Speaker = "我",
		Text = "葛蕾香要找的，就是这把？",
	},
	[10050546] = {
		ID = 10050546,
		Speaker = "我",
		Text = "歹势，刚好路过，刚好听到，然后就刚好跟过来。",
	},
	[10050547] = {
		ID = 10050547,
		Speaker = "凯伊",
		Text = "哼。",
	},
	[10050548] = {
		ID = 10050548,
		Text = "凯伊把短剑握紧，放回木盒，木盒推到桌子最深处。",
	},
	[10050549] = {
		ID = 10050549,
		Speaker = "我",
		Text = "这把剑，拿去跟她换水源，不就解决了？",
	},
	[10050550] = {
		ID = 10050550,
		Speaker = "凯伊",
		Text = "不行。",
	},
	[10050551] = {
		ID = 10050551,
		Speaker = "我",
		Text = "为什么？",
	},
	[10050552] = {
		ID = 10050552,
		Speaker = "凯伊",
		Text = "这是老子先祖亲手打造的武器。不是拿来交换的东西。",
	},
	[10050553] = {
		ID = 10050553,
		Speaker = "我",
		Text = "你先祖是铸剑师？",
	},
	[10050554] = {
		ID = 10050554,
		Speaker = "凯伊",
		Text = "对，死在人龙大战里。这把剑是他留下来唯一的东西。",
