		ID = 10050696,
		Speaker = "我",
		Text = "我猜，是她的力量离开了水源，诅咒才会反扑。",
	},
	[10050697] = {
		ID = 10050697,
		Speaker = "凯伊",
		Text = "……",
	},
	[10050698] = {
		ID = 10050698,
		Speaker = "伊丝娜",
		Text = "那现在怎么办？",
	},
	[10050699] = {
		ID = 10050699,
		Speaker = "我",
		Text = "不知道……",
	},
	[10050700] = {
		ID = 10050700,
		Speaker = "凯伊",
		Text = "……老子拿先祖的遗物，换来的居然是一堆沙子……",
	},
	[10050701] = {
		ID = 10050701,
		Text = "远处，葛蕾香还是低着头，攥着那把短剑。",
	},
	[10050702] = {
		ID = 10050702,
		Speaker = "葛蕾香",
		Text = "现在，愿意相信本人了吗？",
	},
	[10050703] = {
		ID = 10050703,
		Text = "转场",
	},
	[10060001] = {
		ID = 10060001,
		Text = "转场",
	},
	[10060002] = {
		ID = 10060002,
		Text = "荒野星球，人类聚落的最后一处水源地，闸口早已被沙尘暴摧残，浑浊的褐色液体混着泥沙，散发着腥臭。",
	},
	[10060003] = {
		ID = 10060003,
		Text = "难民与居民聚集在水源周围，神情绝望。有人手里还捧着亲人的遗物，无声地哭泣。",
	},
	[10060004] = {
		ID = 10060004,
		Text = "葛蕾香一人站上高台，居高临下俯视底下所有人，神情比平常更加紧绷。",
	},
	[10060005] = {
		ID = 10060005,
		Speaker = "葛蕾香",
		Text = "本人知道，你们此刻恨透了本人。",
	},
	[10060006] = {
		ID = 10060006,
		Speaker = "葛蕾香",
		Text = "但这片水源，本人必须继续集中管理。",
	},
	[10060007] = {
		ID = 10060007,
		Speaker = "首领",
		Text = "说穿了，不就是垄断水源的借口？",
	},
	[10060008] = {
		ID = 10060008,
		Speaker = "葛蕾香",
		Text = "这不是借口。",
	},
	[10060009] = {
		ID = 10060009,
		Speaker = "首领",
		Text = "不然是什么？凭什么是你决定谁能喝水、谁不能？",
	},
	[10060010] = {
		ID = 10060010,
		Speaker = "葛蕾香",
		Text = "凭本人愿意扛下这个责任，而你们办不到！",
	},
	[10060011] = {
		ID = 10060011,
		Text = "葛蕾香一气之下拔出短剑静默，划开自己的手腕，鲜红的血滴落水面。",
	},
	[10060012] = {
		ID = 10060012,
		Speaker = "凯伊",
		Text = "你在做什么？",
	},
	[10060013] = {
		ID = 10060013,
		Speaker = "我",
		Text = "咦？",
	},
	[10060014] = {
		ID = 10060014,
		Text = "（这把剑？）",
	},
	[10060015] = {
		ID = 10060015,
		Text = "众人屏息看着，染黄的沙水在龙血触及的瞬间，",
	},
	[10060016] = {
		ID = 10060016,
		Text = "竟一圈一圈地澄澈起来，浑浊褪去，化作清透的净水。",
	},
	[10060017] = {
		ID = 10060017,
		Speaker = "难民甲",
		Text = "……水变干净了？",
	},
	[10060018] = {
		ID = 10060018,
		Speaker = "难民乙",
		Text = "虽然只有一部份变清澈，但这到底是什么妖术？",
	},
	[10060019] = {
		ID = 10060019,
		Speaker = "我",
		Text = "原来如此． ． ．",
	},
	[10060020] = {
		ID = 10060020,
		Speaker = "葛蕾香",
		Text = "本人的血，能暂时压制诅咒。",
	},
	[10060021] = {
		ID = 10060021,
		Speaker = "葛蕾香",
		Text = "龙族长老临终前留下的诅咒是，『所有人类的水源，终将遭沙尘暴侵袭。 』",
	},
	[10060022] = {
		ID = 10060022,
		Speaker = "葛蕾香",
		Text = "所以本人集中管理这最后一处水源，不是为了独占。",
	},
	[10060023] = {
		ID = 10060023,
		Speaker = "葛蕾香",
		Text = "是为了不让它，也步上其他水源的后尘！",
	},
	[10060024] = {
		ID = 10060024,
		Speaker = "凯伊",
		Text = "……只要人类不拥有，反而能永久使用？",
	},
	[10060025] = {
		ID = 10060025,
		Speaker = "我",
		Text = "也太辛苦了吧。居然一个人默默背负这么多……",
	},
	[10060026] = {
		ID = 10060026,
		Text = "人群一阵骚动，有人开始动摇，望向葛蕾香的眼神多了一丝迟疑。",
	},
	[10060027] = {
		ID = 10060027,
		Speaker = "难民甲",
		Text = "如果她说的是真的呢……",
	},
	[10060028] = {
		ID = 10060028,
		Speaker = "首领",
		Text = "别被她骗了！沙尘暴就是她招来的！",
	},
	[10060029] = {
		ID = 10060029,
		Speaker = "首领",
		Text = "谁能证实龙族说的话？",
	},
	[10060030] = {
		ID = 10060030,
		Speaker = "葛蕾香",
		Text = "本人没有必要骗你们。",
	},
	[10060031] = {
		ID = 10060031,
		Speaker = "首领",
		Text = "那你这么厉害，怎么不去净化其他水源？",
	},
	[10060032] = {
		ID = 10060032,
		Speaker = "葛蕾香",
		Text = "本人有什么理由如此牺牲？",
	},
	[10060033] = {
		ID = 10060033,
		Speaker = "首领",
		Text = "就凭整个星球被你们龙族搞得民不聊生！",
	},
	[10060034] = {
		ID = 10060034,
		Speaker = "难民乙",
		Text = "妳就该赎罪！",
	},
	[10060035] = {
		ID = 10060035,
		Speaker = "难民甲",
		Text = "对！滴几滴血算什么？",
	},
	[10060036] = {
		ID = 10060036,
		Speaker = "难民妇人",
		Text = "我儿子刚刚死在沙尘暴中央……",
	},
	[10060037] = {
		ID = 10060037,
		Speaker = "难民妇人",
		Text = "就是你害的！",
	},
	[10060038] = {
		ID = 10060038,
		Speaker = "葛蕾香",
		Text = "……很遗憾，与本人无关。",
	},
	[10060039] = {
		ID = 10060039,
		Speaker = "难民妇人",
		Text = "遗憾？你一句遗憾，就能把我儿子还给我吗！",
	},
	[10060040] = {
		ID = 10060040,
		Text = "妇人的哭喊点燃了整片人群压抑已久的悲痛与愤怒，越来越多人站起身，朝高台涌去。",
	},
	[10060041] = {
		ID = 10060041,
		Speaker = "难民男子",
		Text = "杀了她！为死去的人报仇！",
	},
	[10060042] = {
		ID = 10060042,
		Speaker = "伊丝娜",
		Text = "等等，先听她把话说完！",
	},
	[10060043] = {
		ID = 10060043,
		Speaker = "首领",
		Text = "诸位，现在不动手，更待何时！",
	},
	[10060044] = {
		ID = 10060044,
		Speaker = "首领",
		Text = "反正现在水源也毁了，不需要再看她脸色！",
	},
	[10060045] = {
		ID = 10060045,
		Text = "人群一拥而上，石块、木棍朝葛蕾香砸去。她怔在原地，没有闪避，也没有回击。",
	},
	[10060046] = {
		ID = 10060046,
		Speaker = "凯伊",
		Text = "……她怎么不躲？",
	},
	[10060047] = {
		ID = 10060047,
		Speaker = "我",
		Text = "她大概没想过会被这样对待。",
	},
	[10060048] = {
		ID = 10060048,
		Speaker = "伊丝娜",
		Text = "住手！她刚才是想帮你们！",
	},
	[10060049] = {
		ID = 10060049,
		Text = "没有人听得进去。葛蕾香被一块石头击中肩头，踉跄后退了一步，眼神里第一次流露出真切的茫然。",
	},
	[10060050] = {
		ID = 10060050,
		Speaker = "葛蕾香",
		Text = "……本人明明。",
	},
	[10060051] = {
		ID = 10060051,
		Speaker = "葛蕾香",
		Text = "本人明明，依照父亲的遗愿，一直都在守着这里……",
	},
	[10060052] = {
		ID = 10060052,
		Text = "她低头看着自己滴血的手腕，",
	},
	[10060053] = {
		ID = 10060053,
		Text = "又看向底下那些愤怒、悲痛、完全听不进任何解释的面孔。",
	},
	[10060054] = {
		ID = 10060054,
		Text = "某种东西在她眼底碎裂了，她握紧短剑，转身头也不回地冲下高台，",
	},
	[10060055] = {
		ID = 10060055,
		Text = "消失在通往古堡的方向。",
	},
	[10060056] = {
		ID = 10060056,
		Speaker = "我",
		Text = "公主殿下！",
	},
	[10060057] = {
		ID = 10060057,
		Text = "我想追上去，却被瞬间涌上的人群挡住去路。",
	},
	[10060058] = {
		ID = 10060058,
		Speaker = "难民乙",
		Text = "别让她跑了！",
	},
	[10060059] = {
		ID = 10060059,
		Speaker = "我",
		Text = "都给我让开！",
	},
	[10060060] = {
		ID = 10060060,
		Text = "人群被我的气势一震，迟疑地让出一条缝，但葛蕾香早已不见踪影。",
	},
	[10060061] = {
		ID = 10060061,
		Text = "首领走到我面前，脸色铁青。",
	},
	[10060062] = {
		ID = 10060062,
		Speaker = "首领",
		Text = "这星球唯一的水源，刚才毁了。",
	},
	[10060063] = {
		ID = 10060063,
		Speaker = "我",
		Text = "很明显，她警告过你。",
	},
	[10060064] = {
		ID = 10060064,
		Speaker = "首领",
		Text = "你相信她的话？",
	},
	[10060067] = {
		ID = 10060067,
		Speaker = "我",
		Text = "所以我是龙族同路人，是吗？",
	},
	[10060068] = {
		ID = 10060068,
		Speaker = "首领",
		Text = "外来者，你们要小心了！",
	},
	[10060069] = {
		ID = 10060069,
		Text = "首领撂下这句话，转身离开，留下满地狼藉与绝望的人群。",
	},
	[10060070] = {
		ID = 10060070,
		Speaker = "凯伊",
		Text = "……老子有种不好的预感。",
	},
	[10060071] = {
		ID = 10060071,
		Text = "我望着葛蕾香消失的方向，又看了一眼满目疮痍的水源地，沉默了片刻，转头叫住凯伊。",
	},
	[10060072] = {
		ID = 10060072,
		Speaker = "我",
		Text = "凯伊。",
	},
	[10060073] = {
		ID = 10060073,
		Speaker = "凯伊",
		Text = "……干嘛。",
	},
	[10060074] = {
		ID = 10060074,
		Speaker = "我",
		Text = "我有话想问你。",
	},
	[10060075] = {
		ID = 10060075,
		Text = "两人并肩走向聚落边缘，身影渐渐远去。",
	},
	[10060076] = {
		ID = 10060076,
		Text = "另一边，伊丝娜神情凝重，悄悄转身走向另一条巷弄。",
	},
	[10060077] = {
		ID = 10060077,
		Speaker = "伊丝娜",
		Text = "首领这句『外来者』让人发寒……",
	},
	[10060078] = {
		ID = 10060078,
		Speaker = "伊丝娜",
		Text = "他是不是想做什么？",
	},
	[10060079] = {
		ID = 10060079,
		Text = "伊丝娜快步离去，没有告诉任何人自己接下来的打算。",
	},
	[10060080] = {
		ID = 10060080,
		Text = "转场",
	},
	[10060082] = {
		ID = 10060082,
		Text = "古堡外，沙尘刚刚平息，天色染上一层诡异的橘红。",
	},
	[10060083] = {
		ID = 10060083,
		Text = "一道身影踩着虚浮轻巧的步伐，穿过崩塌的石墙，径自走进庭院。",
	},
	[10060084] = {
		ID = 10060084,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……大人，您这座古堡，还真是……别有一番「颓废」的风味呢。",
	},
	[10060086] = {
		ID = 10060086,
		Text = "葛蕾香狼狈逃回古堡、浑身沾满沙尘与唾骂痕迹的背影。",
	},
	[10060087] = {
		ID = 10060087,
		Text = "她掩嘴，笑意加深了几分，却没有说破，只是静静等葛蕾香转过身来。",
	},
	[10060088] = {
		ID = 10060088,
		Text = "葛蕾香听见动静，猛然转身。",
	},
	[10060089] = {
		ID = 10060089,
		Text = "她迅速抹去脸上残留的狼狈，摆出一贯居高临下的姿态。",
	},
	[10060090] = {
		ID = 10060090,
		Speaker = "葛蕾香",
		Text = "受缚者……擅自闯入本人的居所，你好大的胆子。",
	},
	[10060091] = {
		ID = 10060091,
		Speaker = "赛诃希丝",
		Text = "属下哪敢擅自，是奉命而来呢。",
	},
	[10060092] = {
		ID = 10060092,
		Speaker = "赛诃希丝",
		Text = "主上先前不是亲自上报，说抓到那只死不了的虫子吗？属下是奉命来把人带走的呀。",
	},
	[10060093] = {
		ID = 10060093,
		Speaker = "葛蕾香",
		Text = "……人不在这里。",
	},
	[10060094] = {
		ID = 10060094,
		Speaker = "赛诃希丝",
		Text = "诶？不在这里？",
	},
	[10060095] = {
		ID = 10060095,
		Speaker = "赛诃希丝",
		Text = "主上亲自上报的猎物，怎么一转眼，又不在了呢？",
	},
	[10060096] = {
		ID = 10060096,
		Speaker = "葛蕾香",
		Text = "本人没有义务，向你解释行踪。",
	},
	[10060097] = {
		ID = 10060097,
		Speaker = "赛诃希丝",
		Text = "属下不敢多问，只是好奇，主上今天，似乎特别……忙碌呢。",
	},
	[10060098] = {
		ID = 10060098,
		Text = "她的视线似有若无地扫过葛蕾香肩头尚未拍净的尘土，又若无其事地移开。",
	},
	[10060099] = {
		ID = 10060099,
		Speaker = "赛诃希丝",
		Text = "刚才路过水源地的时候，属下好像看见一群人类，对着主上丢石头？",
	},
	[10060100] = {
		ID = 10060100,
		Speaker = "赛诃希丝",
		Text = "嘻嘻，大概是属下眼花了吧。像大人这样尊贵的仕女，怎么可能被区区凡人这样对待呢。",
	},
	[10060101] = {
		ID = 10060101,
		Text = "葛蕾香的指尖微微一颤，但她面上分毫不露，依旧维持着居高临下的神情。",
	},
	[10060102] = {
		ID = 10060102,
		Speaker = "葛蕾香",
		Text = "你的眼睛，确实该看医生了。",
	},
	[10060103] = {
		ID = 10060103,
		Speaker = "赛诃希丝",
		Text = "是吗？那真是属下失礼了。",
	},
	[10060104] = {
		ID = 10060104,
		Speaker = "赛诃希丝",
		Text = "不过，主上放心，属下这张嘴，一向牢靠得很。今天看见的事，绝对不会多说一句。",
	},
	[10060105] = {
		ID = 10060105,
		Text = "这句话表面恭顺，语气里却藏着一丝若有似无的得意。",
	},
	[10060106] = {
		ID = 10060106,
		Speaker = "葛蕾香",
		Text = "……你到底想说什么。",
	},
	[10060107] = {
		ID = 10060107,
		Speaker = "赛诃希丝",
		Text = "属下什么都没想说呀。属下只是奉命办事的下人，哪敢对主上有什么想法。",
	},
	[10060108] = {
		ID = 10060108,
		Text = "赛诃希丝说完，又是一串轻笑，笑声里带着一种让人不快的余韵。",
	},
	[10060109] = {
		ID = 10060109,
		Speaker = "葛蕾香",
		Text = "既然人不在，你就先回去。",
	},
	[10060110] = {
		ID = 10060110,
		Speaker = "赛诃希丝",
		Text = "那属下要怎么跟上面覆命呢？总不能空手而回吧。",
	},
	[10060111] = {
		ID = 10060111,
		Speaker = "葛蕾香",
		Text = "告诉上面，猎物已经到手，只是还需要一点时间收网。",
	},
	[10060112] = {
		ID = 10060112,
		Speaker = "赛诃希丝",
		Text = "收网……主上这话说得，可真是，充满自信呢。",
	},
	[10060113] = {
		ID = 10060113,
		Text = "她的视线又一次扫过葛蕾香身上的尘土痕迹，笑意里的挑衅几乎压不住了。",
	},
	[10060114] = {
		ID = 10060114,
		Speaker = "赛诃希丝",
		Text = "毕竟连几个手无寸铁的凡人，主上都能……应付得如此「精彩」呢。",
	},
	[10060115] = {
		ID = 10060115,
		Text = "葛蕾香眼底闪过一丝杀意，一巴掌狠狠甩了过去。",
	},
	[10060116] = {
		ID = 10060116,
		Text = "清脆的声响在空旷的庭院里格外响亮。",
	},
	[10060117] = {
		ID = 10060117,
		Text = "赛诃希丝捂着脸颊，脸上闪过一丝极深的错愕与怨毒。",
	},
	[10060118] = {
		ID = 10060118,
		Speaker = "赛诃希丝",
		Text = "……主上，这是何必呢。",
	},
	[10060119] = {
		ID = 10060119,
		Speaker = "葛蕾香",
		Text = "你的嘴，该学着放干净一点。",
	},
	[10060120] = {
		ID = 10060120,
		Text = "赛诃希丝低下头，笑容重新爬回脸上，却怎么看都透着一股阴森。",
	},
	[10060121] = {
		ID = 10060121,
		Speaker = "赛诃希丝",
		Text = "属下知错了。是属下失言，请主上恕罪。",
	},
	[10060122] = {
		ID = 10060122,
		Speaker = "赛诃希丝",
		Text = "那属下先告退，静候主上的好消息。",
	},
	[10060123] = {
		ID = 10060123,
		Text = "她躬身行礼，姿态恭顺，转身时，嘴角那抹笑却丝毫没有褪去。",
	},
	[10060124] = {
		ID = 10060124,
		Text = "赛诃希丝的身影渐渐消失在沙尘弥漫的荒原尽头。",
	},
	[10060125] = {
		ID = 10060125,
		Text = "庭院里只剩葛蕾香一人，她维持的姿态，终于在此刻松懈下来。",
	},
	[10060126] = {
		ID = 10060126,
		Speaker = "葛蕾香",
		Text = "……可恶的东西。",
	},
	[10060127] = {
		ID = 10060127,
		Text = "她缓缓松开紧握的拳头，低头看向自己手腕上尚未愈合的伤口。",
	},
	[10060128] = {
		ID = 10060128,
		Speaker = "葛蕾香",
		Text = "……刚才。",
	},
	[10060129] = {
		ID = 10060129,
		Text = "她抬手，从腰间取下短剑静默，凝视着剑身上的血迹。",
	},
	[10060130] = {
		ID = 10060130,
		Speaker = "葛蕾香",
		Text = "伤口居然这么深……",
	},
	[10060131] = {
		ID = 10060131,
		Text = "她的眼神渐渐凝重起来，像是意识到什么不对劲的事。",
	},
	[10060132] = {
		ID = 10060132,
		Speaker = "葛蕾香",
		Text = "静默，是父亲留下的遗物。是……人类打造的剑。",
	},
	[10060133] = {
		ID = 10060133,
		Speaker = "葛蕾香",
		Text = "龙族的鳞与皮肉十分强固，寻常兵刃只能伤其分毫……",
	},
	[10060134] = {
		ID = 10060134,
		Speaker = "葛蕾香",
		Text = "那为何…….",
	},
	[10060135] = {
		ID = 10060135,
		Text = "葛蕾香紧紧握住短剑，指节泛白，眼神里第一次浮现出一种近乎恐惧的茫然。",
	},
	[10060136] = {
		ID = 10060136,
		Text = "转场",
	},
	[10060137] = {
		ID = 10060137,
		Text = "转场",
	},
	[10060138] = {
		ID = 10060138,
		Text = "聚落边缘，一处半塌的土墙后方。周围没有人经过，只剩风沙刮过墙角的声音。",
	},
	[10060139] = {
		ID = 10060139,
		Speaker = "我",
		Text = "所以你有用静默砍过任何东西吗？",
	},
	[10060140] = {
		ID = 10060140,
		Speaker = "凯伊",
		Text = "老子是枪手，不是剑客！",
	},
	[10060141] = {
		ID = 10060141,
		Speaker = "我",
		Text = "那你有没有想过，为什么葛蕾香拿静默割自己手腕，血流得跟普通人一样？",
	},
	[10060142] = {
		ID = 10060142,
		Speaker = "我",
		Text = "一般的兵器无法造成他们重伤害。",
	},
	[10060143] = {
		ID = 10060143,
		Text = "凯伊的脸色从原先的愤怒逐渐转为凝重，嘴巴张着却迟迟挤不出话。",
	},
	[10060144] = {
		ID = 10060144,
		Speaker = "凯伊",
		Text = "老子刚刚还真没想到这件事……",
	},
	[10060145] = {
		ID = 10060145,
		Speaker = "我",
		Text = "我曾在其他星球见过龙族，",
	},
	[10060146] = {
		ID = 10060146,
		Speaker = "我",
		Text = "能真正伤害他们的材料，只有一种。",
	},
	[10060147] = {
		ID = 10060147,
		Speaker = "我",
		Text = "就是他们自己的骨头，龙骨！",
	},
	[10060148] = {
		ID = 10060148,
		Speaker = "凯伊",
		Text = "……你是说，老子先祖用龙的骨头铸了这对剑？",
	},
	[10060149] = {
		ID = 10060149,
		Speaker = "我",
		Text = "人龙大战初期，战场上一定留下了龙族的遗骸。你先祖是当时最好的铸剑师。",
	},
	[10060150] = {
		ID = 10060150,
		Speaker = "凯伊",
		Text = "老子一直以为……那只是一把先祖手艺好、所以特别锋利的剑。",
	},
	[10060151] = {
		ID = 10060151,
		Speaker = "我",
		Text = "而且，人类正面打不赢龙族，就算有龙骨剑也一样。近身挥剑的机会根本不存在。",
	},
	[10060152] = {
		ID = 10060152,
		Speaker = "我",
		Text = "那为什么还要铸？",
	},
	[10060153] = {
		ID = 10060153,
		Text = "凯伊沉默了很久，随后一拳用力打在桌面上。",
	},
	[10060154] = {
		ID = 10060154,
		Speaker = "凯伊",
		Text = "暗杀，只有耍阴招才有机会杀龙族长老。",
	},
	[10060155] = {
		ID = 10060155,
		Speaker = "我",
		Text = "你知道这个执行计画的人是谁吗？",
	},
	[10060156] = {
		ID = 10060156,
		Speaker = "凯伊",
		Text = "老子的老子曾经说过，",
	},
	[10060157] = {
		ID = 10060157,
		Speaker = "凯伊",
		Text = "那个执行任务的，是先祖从小一起长大的好友。",
	},
	[10060158] = {
		ID = 10060158,
		Speaker = "凯伊",
		Text = "先祖临终前一直在念一句话:",
	},
	[10060159] = {
		ID = 10060159,
		Speaker = "凯伊",
		Text = "「如果老子没有铸那对剑，他就不会死。」",
	},
	[10060160] = {
		ID = 10060160,
		Speaker = "我",
		Text = "我再问你一件事。",
	},
	[10060161] = {
		ID = 10060161,
		Speaker = "我",
		Text = "你先祖的好友，被选中去暗杀龙族长老。",
	},
	[10060162] = {
		ID = 10060162,
		Speaker = "我",
		Text = "而龙骨剑是人类铸造的暗杀兵器，最后却出现在葛蕾香父亲手上。",
	},
	[10060163] = {
		ID = 10060163,
		Speaker = "我",
		Text = "这代表什么？",
	},
	[10060164] = {
		ID = 10060164,
		Speaker = "我",
		Text = "如果他们是同一人呢？",
	},
	[10060165] = {
		ID = 10060165,
		Text = "凯伊的脸色一点一点变了。",
	},
	[10060166] = {
		ID = 10060166,
		Speaker = "凯伊",
		Text = "等等……葛蕾香是龙族。她爸也是龙族……",
	},
	[10060167] = {
		ID = 10060167,
		Speaker = "凯伊",
		Text = "不对。如果她爸是先祖的好友，先祖是人类……",
	},
	[10060168] = {
		ID = 10060168,
		Speaker = "凯伊",
		Text = "她爸是人类？",
	},
	[10060169] = {
		ID = 10060169,
		Speaker = "我",
		Text = "一个人类，跟龙族在一起，生下了葛蕾香。",
	},
	[10060170] = {
		ID = 10060170,
		Speaker = "我",
		Text = "然后人类方把龙骨剑交到他手上，叫他去杀自己爱人的族人。",
	},
	[10060171] = {
		ID = 10060171,
		Text = "凯伊感到不可置信。",
	},
	[10060172] = {
		ID = 10060172,
		Speaker = "凯伊",
		Text = "你从一把剑就能推测出这些东西？",
	},
	[10060173] = {
		ID = 10060173,
		Speaker = "我",
		Text = "这样就能解释，为什么葛蕾香要帮你们这些人类保住水源？",
	},
	[10060174] = {
		ID = 10060174,
		Speaker = "我",
		Text = "她肯定是继承了，她父母的遗志。",
	},
	[10060175] = {
		ID = 10060175,
		Speaker = "我",
		Text = "我猜，他父亲最后是……",
	},
	[10060176] = {
		ID = 10060176,
		Speaker = "凯伊",
		Text = "成功刺杀，不然龙族怎么会被人类歼灭。",
	},
	[10060177] = {
		ID = 10060177,
		Speaker = "我",
		Text = "不，我认为是失败，他甚至没有动手，我猜。",
	},
	[10060178] = {
		ID = 10060178,
		Speaker = "我",
		Text = "不然葛蕾香的父亲会被作为整个星球的英雄而传颂！",
	},
	[10060179] = {
		ID = 10060179,
		Speaker = "我",
		Text = "但显然你们没有人知道他是谁。",
	},
	[10060180] = {
		ID = 10060180,
		Speaker = "凯伊",
		Text = "先祖说的「如果老子没有铸那对剑」……",
	},
	[10060181] = {
		ID = 10060181,
		Speaker = "凯伊",
		Text = "他不是在说好友死在战场上。",
	},
	[10060182] = {
		ID = 10060182,
		Speaker = "凯伊",
		Text = "而是……",
	},
	[10060183] = {
		ID = 10060183,
		Speaker = "我",
		Text = "你先祖的悔恨，是因为他觉得自己「为了大义」，把好友推进了死局。",
	},
	[10060184] = {
		ID = 10060184,
		Speaker = "凯伊",
		Text = "难怪老子的老子都叫老子什么事都不要管……",
	},
	[10060185] = {
		ID = 10060185,
		Speaker = "凯伊",
		Text = "做个独行侠就好！",
	},
	[10060186] = {
		ID = 10060186,
		Speaker = "我",
		Text = "但你抢水票分给难民，还替机械公民出头……",
	},
	[10060187] = {
		ID = 10060187,
		Speaker = "凯伊",
		Text = "那不一样。老子高兴，老子想做，跟什么大义无关！",
	},
	[10060188] = {
		ID = 10060188,
		Speaker = "我",
		Text = "葛蕾香何尝不是？",
	},
	[10060189] = {
		ID = 10060189,
		Speaker = "我",
		Text = "守住人类唯一的水源，肯定是自己喝水喝到饱，",
	},
	[10060190] = {
		ID = 10060190,
		Speaker = "我",
		Text = "绝对不是为了人类着想对吧？",
	},
	[10060191] = {
		ID = 10060191,
		Text = "凯伊没有正面回应。",
	},
	[10060192] = {
		ID = 10060192,
		Speaker = "凯伊",
		Text = "你搞得老子的脑很乱！",
	},
	[10060193] = {
		ID = 10060193,
		Speaker = "凯伊",
		Text = "老子警告你，如果你在盘算什么，最好别把老子当棋子。",
	},
	[10060194] = {
		ID = 10060194,
		Speaker = "我",
		Text = "我不会。",
	},
	[10060195] = {
		ID = 10060195,
		Speaker = "凯伊",
		Text = "你最好是。",
	},
	[10060196] = {
		ID = 10060196,
		Speaker = "我",
		Text = "我只是要提醒你",
	},
	[10060197] = {
		ID = 10060197,
		Speaker = "我",
		Text = "这颗星球的命运掌握在你们自己手里。",
	},
	[10060198] = {
		ID = 10060198,
		Text = "凯伊没有继续回话。他看向古堡的方向，目光沉静。",
	},
	[10060199] = {
		ID = 10060199,
		Text = "转场",
	},
	[10060200] = {
		ID = 10060200,
		Text = "转场",
	},
	[10060201] = {
		ID = 10060201,
		Text = "聚落里的酒吧，大门敞开，里面空无一人。",
	},
	[10060202] = {
		ID = 10060202,
		Text = "椅子东倒西歪，桌上的酒杯还没收，有几杯打翻在地，琥珀色的液体沿着地面蔓延。",
	},
	[10060203] = {
		ID = 10060203,
		Speaker = "伊丝娜",
		Text = "……怎么一个人都没有？",
	},
	[10060204] = {
		ID = 10060204,
		Text = "伊丝娜推开吧台后方的门，储藏室也是空的。",
	},
	[10060205] = {
		ID = 10060205,
		Speaker = "伊丝娜",
		Text = "平常这个时间，这里不是应该挤满人吗……",
	},
	[10060206] = {
		ID = 10060206,
		Text = "她走回门口，低头看见地面上密密麻麻的脚印，全往同一个方向汇聚。",
	},
	[10060207] = {
		ID = 10060207,
		Speaker = "伊丝娜",
		Text = "所有人都往广场去了？",
	},
	[10060208] = {
		ID = 10060208,
		Text = "她心里浮起一股极不舒服的预感，加快脚步，顺着足迹一路跑过去。",
	},
	[10060209] = {
		ID = 10060209,
	},
	[10060210] = {
		ID = 10060210,
	},
	[10060211] = {
		ID = 10060211,
		Text = "广场上，黑压压的一片人头，所有居民跟难民都挤在这里，脸上带着一种狂热而扭曲的亢奋。",
	},
	[10060212] = {
		ID = 10060212,
		Text = "广场中央，几名机械公民被锁链捆绑在木柱上，身上已经有明显被殴打的痕迹。",
	},
	[10060213] = {
		ID = 10060213,
		Text = "首领站在高台上，双手背在身后，居高临下地俯视着被捆绑的机械公民。",
	},
	[10060214] = {
		ID = 10060214,
		Speaker = "首领",
		Text = "诸位！水源毁了，粮食见底，这一切是谁害的？",
	},
	[10060215] = {
		ID = 10060215,
		Speaker = "群众",
		Text = "龙族！外来者！",
	},
	[10060216] = {
		ID = 10060216,
		Speaker = "首领",
		Text = "龙族躲在古堡里，我们奈何不了她。",
	},
	[10060219] = {
		ID = 10060219,
		Speaker = "难民甲",
		Text = "本来水就不够了，还要分给一堆铁罐头！",
	},
	[10060220] = {
		ID = 10060220,
		Text = "伊丝娜挤到人群边缘，看清了广场中央的景象，整个人如遭雷击。",
	},
	[10060221] = {
		ID = 10060221,
		Speaker = "伊丝娜",
		Text = "不……不会吧……",
	},
	[10060222] = {
		ID = 10060222,
		Text = "首领缓步走到被捆绑的机械公民面前，蹲下身，语气平静得近乎冷酷。",
	},
	[10060223] = {
		ID = 10060223,
		Speaker = "首领",
		Text = "机械人，有什么遗言吗？",
	},
	[10060224] = {
		ID = 10060224,
		Speaker = "机械难民",
		Text = "……我想回去。",
	},
	[10060225] = {
		ID = 10060225,
		Speaker = "首领",
		Text = "回哪里？",
	},
	[10060226] = {
		ID = 10060226,
		Speaker = "机械难民",
		Text = "回蒸气星球……那里才是我的家……",
	},
	[10060227] = {
		ID = 10060227,
		Speaker = "机械难民",
		Text = "我不想待在这里……拜托……让我回家……",
	},
	[10060228] = {
		ID = 10060228,
		Text = "广场上安静了一瞬，随即被更大的鼓噪声淹没。",
	},
	[10060229] = {
		ID = 10060229,
		Text = "伊丝娜的眼泪瞬间涌了出来。她没有犹豫，直接从人群中冲了出去。",
	},
	[10060230] = {
		ID = 10060230,
		Speaker = "伊丝娜",
		Text = "住手！ ！ ！",
	},
	[10060231] = {
		ID = 10060231,
		Text = "她撞开挡在前面的几个人，跌跌撞撞地冲到机械公民面前，张开双臂挡在他们身前。",
	},
	[10060232] = {
		ID = 10060232,
		Speaker = "伊丝娜",
		Text = "他们不是废物！他们是人！他们跟你们一样会痛、会害怕！",
	},
	[10060233] = {
		ID = 10060233,
		Speaker = "首领",
		Text = "又是你。",
	},
	[10060234] = {
		ID = 10060234,
		Speaker = "伊丝娜",
		Text = "你答应过我的！你说过会善待他们！",
	},
	[10060235] = {
		ID = 10060235,
		Speaker = "首领",
		Text = "那是水源还在的时候。现在水没了，承诺自然也没了。",
	},
	[10060236] = {
		ID = 10060236,
		Speaker = "伊丝娜",
		Text = "你……！",
	},
	[10060237] = {
		ID = 10060237,
		Speaker = "首领",
		Text = "把她拉开。",
	},
	[10060238] = {
		ID = 10060238,
		Text = "几个人冲上来拉扯伊丝娜，她死命抓着捆绑机械公民的木柱不放，指甲都断了。",
	},
	[10060239] = {
		ID = 10060239,
		Speaker = "伊丝娜",
		Text = "我不走！你们要杀他们，就先杀我！",
	},
	[10060240] = {
		ID = 10060240,
		Speaker = "难民甲",
		Text = "疯女人，你一个外来的凭什么管我们的事！",
	},
	[10060242] = {
		ID = 10060242,
		Text = "一个人从背后推了伊丝娜一把，她重重摔在地上，额角磕在石头上，渗出血来。",
	},
	[10060243] = {
		ID = 10060243,
		Speaker = "伊丝娜",
		Text = "啊——！",
	},
	[10060245] = {
		ID = 10060245,
		Text = "伊丝娜趴在地上，抬头看着首领，眼泪混着血迹糊了满脸，却死也不肯让开。",
	},
	[10060246] = {
		ID = 10060246,
		Speaker = "伊丝娜",
		Text = "就算……就算只有我一个人在意……我也不会让开……",
	},
	[10060247] = {
		ID = 10060247,
		Speaker = "首领",
		Text = "行刑。",
	},
	[10060248] = {
		ID = 10060248,
		Text = "就在刽子手举起武器的瞬间，",
	},
	[10060249] = {
		ID = 10060249,
		Text = "一发子弹从远处呼啸而来，精准地击中捆绑机械公民的锁链，铁链应声断裂。",
	},
	[10060250] = {
		ID = 10060250,
		Text = "所有人回头。",
	},
	[10060251] = {
		ID = 10060251,
		Text = "凯伊站在广场入口，枪口还在冒烟，我站在她旁边，面无表情。",
	},
	[10060252] = {
		ID = 10060252,
		Speaker = "凯伊",
		Text = "你们一群人欺负弱小，丢不丢脸啊",
	},
	[10060253] = {
		ID = 10060253,
		Speaker = "首领",
		Text = "凯伊，这不关你的事。",
	},
	[10060254] = {
		ID = 10060254,
		Speaker = "凯伊",
		Text = "老子看不下去！",
	},
	[10060255] = {
		ID = 10060255,
		Text = "凯伊拿起步枪连开数枪，子弹精准地扫过刽子手脚边的地面，",
	},
	[10060256] = {
		ID = 10060256,
		Text = "扬起一排尘土，没伤到任何人，却让所有人都吓得后退了好几步。",
	},
	[10060257] = {
		ID = 10060257,
		Speaker = "凯伊",
		Text = "老子的枪，从来不打第二次警告。听懂了就给老子滚！",
	},
	[10060258] = {
		ID = 10060258,
		Text = "刽子手丢下武器，滚进人群里。",
	},
	[10060259] = {
		ID = 10060259,
		Text = "我快步走到伊丝娜身边，扶起她。",
	},
	[10060260] = {
		ID = 10060260,
		Speaker = "我",
		Text = "学姊，还好吗？",
	},
	[10060261] = {
		ID = 10060261,
		Speaker = "伊丝娜",
		Text = "我没事……他们呢？机械公民呢？",
	},
	[10060262] = {
		ID = 10060262,
		Speaker = "我",
		Text = "锁链断了，先别动。",
	},
	[10060263] = {
		ID = 10060263,
		Text = "我站起身，环视广场上所有人。群众的狂热因为凯伊的枪声暂时被压下，但眼里的愤怒跟绝望还没有消退。",
	},
	[10060264] = {
		ID = 10060264,
		Speaker = "首领",
		Text = "外来者，你又想干什么？上次你出的主意，害我们连最后的水源都没了。",
	},
	[10060265] = {
		ID = 10060265,
		Speaker = "首领",
		Text = "这次你还有什么资格站在这里说话？",
	},
	[10060266] = {
		ID = 10060266,
		Speaker = "我",
		Text = "我有办法让所有人，都有干净的水喝。",
	},
	[10060267] = {
		ID = 10060267,
		Text = "广场安静了一瞬。",
	},
	[10060268] = {
		ID = 10060268,
		Speaker = "首领",
		Text = "又是你的空话？",
	},
	[10060269] = {
		ID = 10060269,
		Speaker = "我",
		Text = "你们都亲眼看见了，龙族的血，能净化被诅咒的水源。",
	},
	[10060270] = {
		ID = 10060270,
		Speaker = "难民甲",
		Text = "看见了又怎样？龙女又不会帮我们！",
	},
	[10060271] = {
		ID = 10060271,
		Speaker = "我",
		Text = "所以我说……抓住她。",
	},
	[10060272] = {
		ID = 10060272,
		Text = "人群骚动了起来。",
	},
	[10060273] = {
		ID = 10060273,
		Speaker = "我",
		Text = "葛蕾香现在躲在古堡里，只要把她抓住，用她的血持续净化水源，这颗星球的诅咒就能被压制。",
	},
	[10060274] = {
		ID = 10060274,
		Speaker = "难民乙",
		Text = "她是龙族！怎么抓？",
	},
	[10060275] = {
		ID = 10060275,
		Speaker = "我",
		Text = "这件事，只有一个人做得到。",
	},
	[10060276] = {
		ID = 10060276,
		Text = "我转头，看向凯伊。所有人的视线都跟着他，齐刷刷落在凯伊身上。",
	},
	[10060277] = {
		ID = 10060277,
		Speaker = "凯伊",
		Text = "……你在看老子干嘛？",
	},
	[10060278] = {
		ID = 10060278,
		Speaker = "我",
		Text = "你是这颗星球上最强的枪手。",
	},
	[10060279] = {
		ID = 10060279,
		Text = "而且你已经研发能杀害龙族的子弹！",
	},
	[10060280] = {
		ID = 10060280,
		Speaker = "凯伊",
		Text = "等等等等等，老子什么时候研发出来了？ ？ ？",
	},
	[10060281] = {
		ID = 10060281,
		Speaker = "难民甲",
		Text = "凯伊！你不是一直想跟她对决吗！",
	},
	[10060282] = {
		ID = 10060282,
		Speaker = "难民乙",
		Text = "现在是你为大家出头的时候了！",
	},
	[10060283] = {
		ID = 10060283,
		Text = "群众的目光从绝望转成期待，一道道灼热的视线压在凯伊身上。",
	},
	[10060284] = {
		ID = 10060284,
		Speaker = "凯伊",
		Text = "……",
	},
	[10060285] = {
		ID = 10060285,
		Speaker = "首领",
		Text = "凯伊小姐。",
	},
	[10060286] = {
		ID = 10060286,
		Speaker = "首领",
		Text = "我知道你跟这个外来者，都很在乎那些机械公民。",
	},
	[10060287] = {
		ID = 10060287,
		Speaker = "凯伊",
		Text = "……你想说什么。",
	},
	[10060288] = {
		ID = 10060288,
		Speaker = "首领",
		Text = "很简单。你去对付龙女，机械公民的事，我可以既往不咎。",
	},
	[10060289] = {
		ID = 10060289,
		Speaker = "首领",
		Text = "你如果做不到嘛……",
	},
	[10060290] = {
		ID = 10060290,
		Speaker = "首领",
		Text = "大家都没有水喝，要死，总得有人先死吧？",
	},
	[10060291] = {
		ID = 10060291,
		Speaker = "首领",
		Text = "你觉得，民众会先拿谁开刀？",
	},
	[10060292] = {
		ID = 10060292,
		Text = "他的视线瞥向伊丝娜怀里几个瑟缩发抖的机械公民，意思再明显不过。",
	},
	[10060293] = {
		ID = 10060293,
		Speaker = "伊丝娜",
		Text = "你这是威胁！",
	},
	[10060294] = {
		ID = 10060294,
		Speaker = "首领",
		Text = "我只是在陈述事实。",
	},
	[10060295] = {
		ID = 10060295,
		Text = "凯伊盯着首领，又看了一眼被伊丝娜护在身后的机械公民，再看向我。",
	},
	[10060296] = {
		ID = 10060296,
		Text = "我没有任何表情，也没有替她回答。",
	},
	[10060297] = {
		ID = 10060297,
		Speaker = "凯伊",
		Text = "不要逼我！",
	},
	[10060298] = {
		ID = 10060298,
		Text = "她转身，头也不回地走出广场。",
	},
	[10060299] = {
		ID = 10060299,
		Text = "群众面面相觑，首领的脸色阴沉了下来。",
	},
	[10060300] = {
		ID = 10060300,
		Text = "我看着凯伊离去的背影，眼底闪过一丝不易察觉的神情，像是预料之中，又像是某种歉意。",
	},
	[10060301] = {
		ID = 10060301,
		Speaker = "伊丝娜",
		Text = "后辈……你刚才那番话，是认真的吗？",
	},
	[10060302] = {
		ID = 10060302,
		Speaker = "我",
		Text = "……",
	},
	[10060303] = {
		ID = 10060303,
		Speaker = "伊丝娜",
		Text = "你真的要让凯伊去抓葛蕾香？",
	},
	[10060304] = {
		ID = 10060304,
		Speaker = "我",
		Text = "学姊，你先带机械公民离开这里。",
	},
	[10060305] = {
		ID = 10060305,
		Speaker = "伊丝娜",
		Text = "你没有回答我的问题。",
	},
	[10060306] = {
		ID = 10060306,
		Speaker = "我",
		Text = "我会处理。",
	},
	[10060307] = {
		ID = 10060307,
		Speaker = "伊丝娜",
		Text = "……我相信你！",
	},
	[10060308] = {
		ID = 10060308,
		Text = "伊丝娜带着机械公民离开广场，一瘸一拐，额头上的血还在流。",
	},
	[10060309] = {
		ID = 10060309,
		Text = "我独自站在原地，望着凯伊消失的方向，又望了一眼古堡的方向。",
	},
	[10060310] = {
		ID = 10060310,
		Text = "两个女人，两个方向，他夹在正中间。",
	},
	[10060311] = {
		ID = 10060311,
		Text = "转场",
	},
	[10060312] = {
		ID = 10060312,
		Text = "转场",
	},
	[10060313] = {
		ID = 10060313,
		Text = "聚落边缘，废弃建筑的后方。凯伊一脚踹开木板门，直直走向我。",
	},
	[10060314] = {
		ID = 10060314,
		Text = "黑压压的枪口抵在我脑门前，近的连膛线都看得一清二楚。",
	},
	[10060315] = {
		ID = 10060315,
		Speaker = "凯伊",
		Text = "你又来了。",
	},
	[10060316] = {
		ID = 10060316,
		Speaker = "凯伊",
		Text = "老子上次就警告过你，别把老子当棋子。",
	},
	[10060317] = {
		ID = 10060317,
		Speaker = "凯伊",
		Text = "结果你转头就在广场上，当着全部人的面，把老子架上去！",
	},
	[10060318] = {
		ID = 10060318,
		Speaker = "我",
		Text = "我有指名你吗？",
	},
	[10060319] = {
		ID = 10060319,
		Speaker = "凯伊",
		Text = "你看着老子说「只有一个人做得到」，全场都听懂了，你还装！",
	},
	[10060320] = {
		ID = 10060320,
		Speaker = "我",
		Text = "那你答应了吗？",
	},
	[10060321] = {
		ID = 10060321,
		Speaker = "凯伊",
		Text = "……老子没答应。",
	},
	[10060322] = {
		ID = 10060322,
		Speaker = "我",
		Text = "对，你没答应。因为你可以选择。",
	},
	[10060323] = {
		ID = 10060323,
		Speaker = "我",
		Text = "我把选项摆在你面前，但我没有替你做决定。",
	},
	[10060324] = {
		ID = 10060324,
		Speaker = "凯伊",
		Text = "你这张嘴，比你的拳头更让人想揍。",
	},
	[10060325] = {
		ID = 10060325,
		Speaker = "我",
		Text = "谢谢夸奖。跟我来，有东西给你看。",
	},
	[10060326] = {
		ID = 10060326,
		Speaker = "凯伊",
		Text = "老子不想看。",
	},
	[10060327] = {
		ID = 10060327,
		Speaker = "我",
		Text = "你会想看的。",
	},
	[10060328] = {
		ID = 10060328,
		Text = "我没有多说，转身就走。凯伊骂了一声，还是跟了上去。",
	},
	[10060329] = {
		ID = 10060329,
	},
	[10060330] = {
		ID = 10060330,
	},
	[10060331] = {
		ID = 10060331,
		Text = "废弃建筑内部，那座古老的铸造炉前，黛莉亚正蹲在地上擦着手上的油渍，满脸得意。",
	},
	[10060332] = {
		ID = 10060332,
		Text = "炉体已经被重新拼装完毕，炉口泛着暗红色的余温，像一头刚苏醒的野兽。",
	},
	[10060333] = {
		ID = 10060333,
		Speaker = "黛莉亚",
		Text = "搞定了！完美！连排气结构都给它优化过了！",
	},
	[10060334] = {
		ID = 10060334,
		Speaker = "我",
		Text = "辛苦了。",
	},
	[10060335] = {
		ID = 10060335,
		Speaker = "黛莉亚",
		Text = "辛苦什么！这个炉子的构造超有趣的，用了至少三种我没见过的导热机制！",
	},
	[10060336] = {
		ID = 10060336,
		Speaker = "黛莉亚",
		Text = "修的时候差点舍不得装回去，想拆一块带回船上研究……",
	},
	[10060337] = {
		ID = 10060337,
		Speaker = "凯伊",
		Text = "等等。",
	},
	[10060338] = {
		ID = 10060338,
		Speaker = "凯伊",
		Text = "这个炉子……你修好了？",
	},
	[10060339] = {
		ID = 10060339,
		Speaker = "黛莉亚",
		Text = "对啊，怎么了？",
	},
	[10060340] = {
		ID = 10060340,
		Speaker = "凯伊",
		Text = "老子找遍整个星球，铁匠、工匠、机械师，没有一个人知道怎么修这座炉！",
	},
	[10060341] = {
		ID = 10060341,
		Speaker = "凯伊",
		Text = "这东西坏了几十年了，你几天就搞定？",
	},
	[10060342] = {
		ID = 10060342,
		Speaker = "黛莉亚",
		Text = "嗯……大概是因为我看得懂它的结构？",
	},
	[10060343] = {
		ID = 10060343,
		Speaker = "凯伊",
		Text = "你也太屌了吧！",
	},
	[10060344] = {
		ID = 10060344,
		Speaker = "黛莉亚",
		Text = "嘿嘿，被这样直接夸奖，还蛮爽的。",
	},
	[10060345] = {
		ID = 10060345,
		Speaker = "我",
		Text = "凯伊，你知道这座炉子能做什么吧？",
	},
	[10060346] = {
		ID = 10060346,
		Text = "凯伊看着炉口的暗红色余温，表情渐渐凝重起来。",
	},
	[10060347] = {
		ID = 10060347,
		Speaker = "凯伊",
		Text = "……知道。",
	},
	[10060348] = {
		ID = 10060348,
		Speaker = "凯伊",
		Text = "这是老子先祖当年铸造双剑用的炉。",
	},
	[10060349] = {
		ID = 10060349,
		Speaker = "凯伊",
		Text = "有了这座炉，只要有材料，就能铸造跟双剑一样的……杀龙兵器。",
	},
	[10060350] = {
		ID = 10060350,
		Speaker = "我",
		Text = "不需要铸剑。只需要铸子弹。",
	},
	[10060351] = {
		ID = 10060351,
		Speaker = "凯伊",
		Text = "子弹……",
	},
	[10060352] = {
		ID = 10060352,
		Speaker = "我",
		Text = "龙骨子弹。装进你的枪里，你就有了真正能伤到龙族的武器。",
	},
	[10060353] = {
		ID = 10060353,
		Text = "凯伊沉默了很长一段时间，盯着那座炉。",
	},
	[10060354] = {
		ID = 10060354,
		Speaker = "凯伊",
		Text = "……龙骨呢？",
	},
	[10060355] = {
		ID = 10060355,
		Speaker = "我",
		Text = "我去找。",
	},
	[10060356] = {
		ID = 10060356,
		Speaker = "凯伊",
		Text = "你去哪找？这颗星球上的龙族只剩那个婆娘一个，你总不能把她的骨头拆下来吧？",
	},
	[10060357] = {
		ID = 10060357,
		Speaker = "我",
		Text = "活着的龙族只剩一个。但死去的龙族，不止一个。",
	},
	[10060358] = {
		ID = 10060358,
		Speaker = "凯伊",
		Text = "……你是说。",
	},
	[10060359] = {
		ID = 10060359,
		Speaker = "我",
		Text = "人龙大战，龙族几乎灭族。这颗星球上，一定有龙族的墓地。",
	},
	[10060360] = {
		ID = 10060360,
		Speaker = "凯伊",
		Text = "你要去挖龙族的坟？",
	},
	[10060361] = {
		ID = 10060361,
		Speaker = "我",
		Text = "不要讲这么难听，是借！",
	},
	[10060362] = {
		ID = 10060362,
		Speaker = "我",
		Text = "你知道龙族墓地在哪对吗？",
	},
	[10060363] = {
		ID = 10060363,
		Speaker = "凯伊",
		Text = "……啧。",
	},
	[10060364] = {
		ID = 10060364,
	},
	[10060365] = {
		ID = 10060365,
	},
	[10060366] = {
		ID = 10060366,
		Text = "荒原深处，一片被风沙半掩的石碑群。龙族的墓地比想像中简朴，没有雕饰，",
	},
	[10060367] = {
		ID = 10060367,
		Text = "只有一块块粗糙的石板，上面刻着看不懂的龙文。",
	},
	[10060368] = {
		ID = 10060368,
		Text = "我独自站在墓碑前，微微低头。",
	},
	[10060369] = {
		ID = 10060369,
		Speaker = "我",
		Text = "抱歉，打扰了。",
	},
	[10060370] = {
		ID = 10060370,
		Speaker = "我",
		Text = "我知道这对你们是不敬。但你们族里最后一个活着的人，现在需要这些东西。",
	},
	[10060371] = {
		ID = 10060371,
		Speaker = "我",
		Text = "借用你们的骨头一用。事成之后……抱歉你们也得不到好处。",
	},
	[10060374] = {
		ID = 10060374,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……挖人家的坟，还先道歉，你倒是挺有礼貌的呢。",
	},
	[10060375] = {
		ID = 10060375,
		Text = "我的手一顿，缓缓站起身。",
	},
	[10060376] = {
		ID = 10060376,
		Text = "赛诃希丝不知何时已经靠在不远处的石碑上，抱着手臂，饶有兴味地打量着他。",
	},
	[10060377] = {
		ID = 10060377,
		Speaker = "我",
		Text = "……你是谁？",
	},
	[10060379] = {
		ID = 10060379,
		Speaker = "赛诃希丝",
		Text = "好难听的词。嘻嘻，这下我可以带你回去覆命了！",
	},
	[10060380] = {
		ID = 10060380,
		Speaker = "我",
		Text = "你要带我走？",
	},
	[10060381] = {
		ID = 10060381,
		Speaker = "赛诃希丝",
		Text = "把死不了的虫子，带回主上面前。",
	},
	[10060382] = {
		ID = 10060382,
		Speaker = "赛诃希丝",
		Text = "不过嘛……",
	},
	[10060383] = {
		ID = 10060383,
		Text = "赛诃希丝往前踏了一步，空气中开始弥漫一种浓烈而暧昧的气息，像是花蜜融在雾里。",
	},
	[10060384] = {
		ID = 10060384,
		Speaker = "赛诃希丝",
		Text = "在带你回去之前，我倒是很好奇……让主上念念不忘的男人，到底有什么特别的呢？",
	},
	[10060385] = {
		ID = 10060385,
		Speaker = "我",
		Text = "……你身上这股气息。",
	},
	[10060386] = {
		ID = 10060386,
		Speaker = "赛诃希丝",
		Text = "喜欢吗？这是我的一点小天赋。任何雄性生物，只要靠近属下……",
	},
	[10060387] = {
		ID = 10060387,
		Speaker = "我",
		Text = "又来了。",
	},
	[10060389] = {
		ID = 10060389,
		Speaker = "我",
		Text = "……跟在古堡里一模一样。",
	},
	[10060390] = {
		ID = 10060390,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻，好诚实的身体。不愧是让最高通缉的男子。",
	},
	[10060391] = {
		ID = 10060391,
		Speaker = "赛诃希丝",
		Text = "不如我先帮你……「检查」一下？",
	},
	[10060392] = {
		ID = 10060392,
		Speaker = "我",
		Text = "不用了，谢谢。",
	},
	[10060393] = {
		ID = 10060393,
		Text = "我趁赛诃希丝笑得正欢，猛然转身拔腿就跑，脚下扬起一片沙尘。",
	},
	[10060394] = {
		ID = 10060394,
		Speaker = "赛诃希丝",
		Text = "诶？你跑什么！",
	},
	[10060395] = {
		ID = 10060395,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻，跑得还挺快呢！",
	},
	[10060396] = {
		ID = 10060396,
		Text = "我拼命往聚落方向跑，身后赛诃希丝的笑声越来越近，",
	},
	[10060397] = {
		ID = 10060397,
		Text = "然后，毫无预兆地，一道沉重的冲击从侧面轰来。",
	},
	[10060398] = {
		ID = 10060398,
		Text = "我被打飞出去，重重撞在石壁上，胸口传来剧烈的疼痛，嘴角溢出鲜血。",
	},
	[10060399] = {
		ID = 10060399,
		Text = "葛蕾香站在那里，右手还维持着挥击的姿势，龙族魔力的余波在空气中扭曲。",
	},
	[10060400] = {
		ID = 10060400,
		Speaker = "葛蕾香",
		Text = "罪人。本人说过，你哪里都不准去。",
	},
	[10060401] = {
		ID = 10060401,
		Speaker = "赛诃希丝",
		Text = "喔喔！主上好帅！一击就把他打趴了呢！",
	},
	[10060402] = {
		ID = 10060402,
		Speaker = "葛蕾香",
		Text = "……你又在这里做什么。",
	},
	[10060403] = {
		ID = 10060403,
		Speaker = "赛诃希丝",
		Text = "属下只是在执行任务呀。是这只虫子自己跑出来的，不关属下的事。",
	},
	[10060404] = {
		ID = 10060404,
		Speaker = "葛蕾香",
		Text = "带走他的事，由本人处理。你退下。",
	},
	[10060405] = {
		ID = 10060405,
		Speaker = "赛诃希丝",
		Text = "嘻嘻，不让我参与吗？那属下就先走啰。",
	},
	[10060406] = {
		ID = 10060406,
		Text = "赛诃希丝轻飘飘地离开，笑声在风里回荡了好一阵才散去。",
	},
	[10060407] = {
		ID = 10060407,
		Text = "我靠在石壁上，胸口的伤让他几乎说不出话，每一次呼吸都带着血腥味。",
	},
	[10060408] = {
		ID = 10060408,
		Speaker = "葛蕾香",
		Text = "你的命，是本人想收就收的东西。记住这一点。",
	},
	[10060409] = {
		ID = 10060409,
		Speaker = "我",
		Text = "……咳，你打人之前，好歹听我说一句话",
	},
	[10060410] = {
		ID = 10060410,
		Speaker = "葛蕾香",
		Text = "将死之言。",
	},
	[10060411] = {
		ID = 10060411,
		Speaker = "我",
		Text = "对，就是遗言。",
	},
	[10060412] = {
		ID = 10060412,
		Text = "我费力地抬起手，示意葛蕾香靠近。葛蕾香犹豫了一瞬，蹲下身，将耳朵凑近。",
	},
	[10060413] = {
		ID = 10060413,
		Text = "我的声音极低极轻，像是怕被谁听见。",
	},
	[10060414] = {
		ID = 10060414,
		Speaker = "我",
		Text = "一人『孤行』，『静默』地背负使命。",
	},
	[10060415] = {
		ID = 10060415,
		Speaker = "我",
		Text = "这又何尝，不是你的写照？",
	},
	[10060416] = {
		ID = 10060416,
		Text = "葛蕾香整个人僵住了。",
	},
	[10060417] = {
		ID = 10060417,
		Text = "她蹲在原地，没有动，也没有说话。",
	},
	[10060418] = {
		ID = 10060418,
		Text = "转场",
	},
	[10060419] = {
		ID = 10060419,
		Text = "转场",
	},
	[10060420] = {
		ID = 10060420,
		Text = "废弃建筑内部，铸造炉的火光映在墙壁上，摇曳不定。",
	},
	[10060421] = {
		ID = 10060421,
		Text = "黛莉亚把最后一颗子弹从模具里取出，用布仔细擦拭，摆在另外两颗旁边。",
	},
	[10060422] = {
		ID = 10060422,
		Text = "三颗泛着暗灰色光泽的子弹，静静躺在铁盘上，看起来跟普通子弹没什么两样，",
	},
	[10060423] = {
		ID = 10060423,
		Text = "但表面有一层极细的纹路，像骨骼的纤维。",
	},
	[10060424] = {
		ID = 10060424,
		Speaker = "黛莉亚",
		Text = "好了，三颗，全部完成。",
	},
	[10060425] = {
		ID = 10060425,
		Speaker = "凯伊",
		Text = "就三颗？",
	},
	[10060426] = {
		ID = 10060426,
		Speaker = "黛莉亚",
		Text = "材料就这么多嘛，龙骨的密度太高，一小块只能铸三颗。",
	},
	[10060427] = {
		ID = 10060427,
		Speaker = "黛莉亚",
		Text = "而且这座炉的温控很极端，再多铸几颗，炉膛可能会裂开，我刚修好的欸，不想让它坏掉。",
	},
	[10060428] = {
		ID = 10060428,
		Speaker = "凯伊",
		Text = "……三颗。",
	},
	[10060429] = {
		ID = 10060429,
		Text = "凯伊把子弹放在掌心，感受着重量，比普通子弹沉了不少。",
	},
	[10060430] = {
		ID = 10060430,
		Speaker = "凯伊",
		Text = "够了。",
	},
	[10060431] = {
		ID = 10060431,
		Speaker = "凯伊",
		Text = "老子打五个人只用五颗子弹。三颗打一个龙族婆娘，绰绰有余。",
	},
	[10060432] = {
		ID = 10060432,
		Speaker = "黛莉亚",
		Text = "好帅……可是对方是龙族欸？",
	},
	[10060433] = {
		ID = 10060433,
		Speaker = "凯伊",
		Text = "那就更不能浪费。每一颗都要打在要害上。",
	},
	[10060434] = {
		ID = 10060434,
		Text = "（这三颗子弹，就是老子的孤行与静默……）",
	},
	[10060435] = {
		ID = 10060435,
		Text = "凯伊把三颗子弹小心翼翼地收进腰间的弹匣袋，拍了拍。",
	},
	[10060436] = {
		ID = 10060436,
		Speaker = "凯伊",
		Text = "你们船长呢？",
	},
	[10060437] = {
		ID = 10060437,
		Speaker = "黛莉亚",
		Text = "他把龙族遗骨交给我之后就不知道跑去哪了。",
	},
	[10060438] = {
		ID = 10060438,
		Speaker = "凯伊",
		Text = "又是这样。每次要找他的时候就消失。",
	},
	[10060439] = {
		ID = 10060439,
		Speaker = "黛莉亚",
		Text = "他一直都这样啦，习惯就好。",
	},
	[10060440] = {
		ID = 10060440,
		Speaker = "凯伊",
		Text = "习惯个鬼。",
	},
	[10060441] = {
		ID = 10060441,
		Text = "凯伊转身准备离开，在门口差点撞上走进来的伊丝娜。",
	},
	[10060442] = {
		ID = 10060442,
		Text = "伊丝娜额头缠着绷带，走路还有些一瘸一拐，但精神看起来比之前好了一些。",
	},
	[10060443] = {
		ID = 10060443,
		Speaker = "伊丝娜",
		Text = "凯伊，我听黛莉亚说子弹铸好了？",
	},
	[10060444] = {
		ID = 10060444,
		Speaker = "凯伊",
		Text = "嗯。三颗。",
	},
	[10060445] = {
		ID = 10060445,
		Speaker = "伊丝娜",
		Text = "……你真的要去？",
	},
	[10060446] = {
		ID = 10060446,
		Speaker = "凯伊",
		Text = "还没决定。",
	},
	[10060447] = {
		ID = 10060447,
		Speaker = "伊丝娜",
		Text = "那你站在这里收子弹是在做什么？",
	},
	[10060448] = {
		ID = 10060448,
		Speaker = "凯伊",
		Text = "……闭嘴。",
	},
	[10060449] = {
		ID = 10060449,
		Text = "黛莉亚识相地往后退了几步，蹲回炉边假装检查零件。",
	},
	[10060450] = {
		ID = 10060450,
		Text = "伊丝娜靠在门框上，看着凯伊。沉默了一会儿，她先开口了。",
	},
	[10060451] = {
		ID = 10060451,
		Speaker = "伊丝娜",
		Text = "我一直想问你。",
	},
	[10060452] = {
		ID = 10060452,
		Speaker = "伊丝娜",
		Text = "……你有没有想过，葛蕾香父亲当年的处境？",
	},
	[10060453] = {
		ID = 10060453,
		Speaker = "凯伊",
		Text = "……想过。",
	},
	[10060454] = {
		ID = 10060454,
		Speaker = "凯伊",
		Text = "老子想过很多次。",
	},
	[10060455] = {
		ID = 10060455,
		Speaker = "凯伊",
		Text = "他是人类，却爱上龙族。然后人类方把龙骨剑交到他手上，叫他去暗杀龙族长老。",
	},
	[10060456] = {
		ID = 10060456,
		Speaker = "凯伊",
		Text = "你让一个人，拿着武器，去杀爱人的家人……这怎么下得了手？",
	},
	[10060457] = {
		ID = 10060457,
		Speaker = "伊丝娜",
		Text = "人类方之所以选上他，是因为他跟龙族长老之间有信任吧。",
	},
	[10060458] = {
		ID = 10060458,
		Speaker = "伊丝娜",
		Text = "只有被信任的人，才能靠近到足以暗杀的距离。",
	},
	[10060459] = {
		ID = 10060459,
		Speaker = "凯伊",
		Text = "……对。人类方看上的，就是那份信任。",
	},
	[10060460] = {
		ID = 10060460,
		Speaker = "凯伊",
		Text = "最恶心的就是这里。他们把信任当成武器，比龙骨剑还恶毒。",
	},
	[10060461] = {
		ID = 10060461,
		Text = "凯伊低下头，握着拳，指节发白。",
	},
	[10060462] = {
		ID = 10060462,
		Speaker = "凯伊",
		Text = "老子的先祖也一样。",
	},
	[10060463] = {
		ID = 10060463,
		Speaker = "伊丝娜",
		Text = "什么意思？",
	},
	[10060464] = {
		ID = 10060464,
		Speaker = "凯伊",
		Text = "他铸了那对剑。他以为自己是在为人类造武器、赢得战争。",
	},
	[10060465] = {
		ID = 10060465,
		Speaker = "凯伊",
		Text = "结果他的剑，害了自己最好的朋友。",
	},
	[10060466] = {
		ID = 10060466,
		Speaker = "凯伊",
		Text = "如果他没有发明龙骨剑，或许根本不会有人拿这种东西去逼迫葛蕾香的父亲。",
	},
	[10060467] = {
		ID = 10060467,
		Speaker = "凯伊",
		Text = "老子的先祖，是含恨死的。不是死在战场上，是死在愧疚里。",
	},
	[10060468] = {
		ID = 10060468,
		Speaker = "伊丝娜",
		Text = "……原来如此。",
	},
	[10060469] = {
		ID = 10060469,
		Speaker = "伊丝娜",
		Text = "难怪你把双剑当成信物而不是武器。你继承的不是剑，是你先祖的悔恨。",
	},
	[10060470] = {
		ID = 10060470,
		Speaker = "凯伊",
		Text = "……",
	},
	[10060471] = {
		ID = 10060471,
		Text = "炉火噼啪作响，黛莉亚在角落里安静地听着，手里的扳手早就忘了转。",
	},
	[10060472] = {
		ID = 10060472,
		Speaker = "伊丝娜",
		Text = "凯伊，你不一定要去。",
	},
	[10060473] = {
		ID = 10060473,
		Speaker = "凯伊",
		Text = "……老子知道。",
	},
	[10060474] = {
		ID = 10060474,
		Speaker = "伊丝娜",
		Text = "没有人有权利逼你重蹈你先祖的覆辙。",
	},
	[10060475] = {
		ID = 10060475,
		Speaker = "凯伊",
		Text = "老子说了，老子知道。",
	},
	[10060476] = {
		ID = 10060476,
		Text = "凯伊闭上眼睛，深深吸了一口气，又缓缓吐出来。",
	},
	[10060477] = {
		ID = 10060477,
		Speaker = "凯伊",
		Text = "老子不想杀她。",
	},
	[10060478] = {
		ID = 10060478,
		Speaker = "凯伊",
		Text = "老子先祖的好友的女儿，老子不想杀她。",
	},
	[10060479] = {
		ID = 10060479,
		Speaker = "凯伊",
		Text = "可是老子想破头，也想不出怎么两全其美。",
	},
	[10060480] = {
		ID = 10060480,
		Speaker = "伊丝娜",
		Text = "那就不要去。",
	},
	[10060481] = {
		ID = 10060481,
		Speaker = "凯伊",
		Text = "不去，就没有水。没有水，所有人都会死。包括你的机械公民。",
	},
	[10060482] = {
		ID = 10060482,
		Speaker = "伊丝娜",
		Text = "……",
	},
	[10060483] = {
		ID = 10060483,
		Text = "凯伊睁开眼，眼神跟之前不一样了。不是冲动，不是愤怒，是一种咬着牙、把所有退路烧掉之后的决绝。",
	},
	[10060484] = {
		ID = 10060484,
		Speaker = "凯伊",
		Text = "老子这辈子就信一件事。",
	},
	[10060485] = {
		ID = 10060485,
		Speaker = "凯伊",
		Text = "想要什么，就去抢。",
	},
	[10060486] = {
		ID = 10060486,
		Speaker = "伊丝娜",
		Text = "凯伊……",
	},
	[10060487] = {
		ID = 10060487,
		Speaker = "凯伊",
		Text = "老子想喝水。",
	},
	[10060488] = {
		ID = 10060488,
		Speaker = "凯伊",
		Text = "所以老子要去抢。",
	},
	[10060489] = {
		ID = 10060489,
		Speaker = "凯伊",
		Text = "老子要让龙族的血，洒在那片水源地上。",
	},
	[10060490] = {
		ID = 10060490,
		Text = "凯伊把手按在腰间的弹匣袋上，转身大步走出废弃建筑。",
	},
	[10060491] = {
		ID = 10060491,
		Text = "伊丝娜望着她的背影，张了张嘴，最终什么也没说出来。",
	},
	[10060492] = {
		ID = 10060492,
		Speaker = "黛莉亚",
		Text = "……她会没事吗？",
	},
	[10060493] = {
		ID = 10060493,
		Speaker = "伊丝娜",
		Text = "我不知道。",
	},
	[10060494] = {
		ID = 10060494,
		Speaker = "伊丝娜",
		Text = "但如果后辈真的在盘算什么……拜托，不要让她白白牺牲。",
	},
	[10060495] = {
		ID = 10060495,
		Text = "转场",
	},
	[10060496] = {
		ID = 10060496,
		Text = "转场",
	},
	[10060497] = {
		ID = 10060497,
		Text = "水源地外，夕阳把整片荒原染成血红色。",
	},
	[10060498] = {
		ID = 10060498,
		Text = "葛蕾香早已站在高台上，双手环胸，俯视着底下逐渐聚集的人群。",
	},
	[10060499] = {
		ID = 10060499,
		Text = "她一语不发，像一尊石雕，等待着什么。",
	},
	[10060500] = {
		ID = 10060500,
		Text = "聚落里几乎所有人都来了。难民、居民、机械公民，连孩童都被大人扛在肩上，挤在最外围。",
	},
	[10060501] = {
		ID = 10060501,
		Text = "远处，一个身影缓缓走来。",
	},
	[10060502] = {
		ID = 10060502,
		Text = "凯伊一步一步穿过人群，目光从始至终没有离开高台上的葛蕾香。",
	},
	[10060503] = {
		ID = 10060503,
		Text = "周围的人自动让出一条路，没有人说话，只有风沙刮过地面的声音。",
	},
	[10060504] = {
		ID = 10060504,
		Text = "我从侧面快步走上前，拦在凯伊面前。",
	},
	[10060505] = {
		ID = 10060505,
		Speaker = "我",
		Text = "等一下。",
	},
	[10060506] = {
		ID = 10060506,
		Speaker = "凯伊",
		Text = "……",
	},
	[10060507] = {
		ID = 10060507,
		Speaker = "我",
		Text = "让我确认一下子弹。",
	},
	[10060509] = {
		ID = 10060509,
		Text = "我打开弹轮，逐一检查三颗龙骨子弹的位置，确认无误后，合上弹轮，把枪交回凯伊手中。",
	},
	[10060510] = {
		ID = 10060510,
		Speaker = "我",
		Text = "……保重。",
	},
	[10060512] = {
		ID = 10060512,
		Text = "她大步走向水源地中央，踩在干裂的地面上，发出沉闷的声响。",
	},
	[10060513] = {
		ID = 10060513,
		Text = "高台上，葛蕾香终于动了。",
	},
	[10060514] = {
		ID = 10060514,
		Text = "她低头看了凯伊一眼，语气轻淡。",
	},
	[10060515] = {
		ID = 10060515,
		Speaker = "葛蕾香",
		Text = "来了。",
	},
	[10060516] = {
		ID = 10060516,
		Text = "葛蕾香从高台跃下，落地的瞬间，冲击波向四面八方炸开，地面龟裂，沙尘冲天。",
	},
	[10060517] = {
		ID = 10060517,
		Text = "最前排的观众被气浪扫得踉跄后退，有人直接被掀翻在地。",
	},
	[10060518] = {
		ID = 10060518,
		Speaker = "黛莉亚",
		Text = "好强的冲击力！",
	},
	[10060519] = {
		ID = 10060519,
		Speaker = "伊丝娜",
		Text = "所有人往后退！",
	},
	[10060520] = {
		ID = 10060520,
		Text = "沙尘落定，葛蕾香与凯伊相隔三十步，正面对峙。",
	},
	[10060521] = {
		ID = 10060521,
		Text = "葛蕾香的周身，龙族魔力的光晕隐隐流转，空气都在扭曲。",
	},
	[10060522] = {
		ID = 10060522,
		Text = "凯伊把帽檐压低，右手握枪，垂在腰侧。",
	},
	[10060524] = {
		ID = 10060524,
		Speaker = "凯伊",
		Text = "废话少说。",
	},
	[10060525] = {
		ID = 10060525,
		Text = "葛蕾香抬手，毫无保留地轰出第一道冲击波，空气炸裂的声响震得所有人耳鸣。",
	},
	[10060526] = {
		ID = 10060526,
		Text = "凯伊侧身一闪，冲击波擦着她的肩膀掠过，身后的石墙直接碎成粉末。",
	},
	[10060527] = {
		ID = 10060527,
		Text = "第二道冲击波紧接而来，凯伊往右翻滚，地面被轰出一个深坑。",
	},
	[10060528] = {
		ID = 10060528,
		Text = "凯伊没有急着开枪，她不断移动，左闪右避，脚步带起越来越多的尘沙。",
	},
	[10060529] = {
		ID = 10060529,
		Text = "第三道、第四道冲击波接连轰来，每一击都精准覆盖凯伊的位置，但她总是在最后一刻消失在沙尘里。",
	},
	[10060530] = {
		ID = 10060530,
		Speaker = "首领",
		Text = "她在做什么？为什么不开枪？",
	},
	[10060531] = {
		ID = 10060531,
		Speaker = "我",
		Text = "（她在等。）",
	},
	[10060532] = {
		ID = 10060532,
		Text = "沙尘越来越浓，漫天黄沙像一面移动的墙，凯伊的身影在其中时隐时现。",
	},
	[10060533] = {
		ID = 10060533,
		Text = "葛蕾香的眼神锐利地扫过沙尘，试图锁定凯伊的位置，但沙幕太厚，视线被完全遮蔽。",
	},
	[10060534] = {
		ID = 10060534,
		Speaker = "葛蕾香",
		Text = "……聪明。",
	},
	[10060535] = {
		ID = 10060535,
		Text = "第一声​​枪响。",
	},
	[10060536] = {
		ID = 10060536,
		Text = "子弹从沙尘中射出，速度快得几乎不可见，精准命中葛蕾香的右肩。",
	},
	[10060537] = {
		ID = 10060537,
		Text = "龙血喷涌而出，比人类的血更浓稠，带着一丝金属般的光泽。",
	},
	[10060538] = {
		ID = 10060538,
		Speaker = "葛蕾香",
		Text = "呜……",
	},
	[10060539] = {
		ID = 10060539,
		Text = "群众爆发出一阵欢呼，震耳欲聋。",
	},
	[10060540] = {
		ID = 10060540,
		Speaker = "难民甲",
		Text = "中了！打中了！",
	},
	[10060541] = {
		ID = 10060541,
		Speaker = "难民乙",
		Text = "龙族受伤了！她也会喷血！",
	},
	[10060542] = {
		ID = 10060542,
		Speaker = "伊丝娜",
		Text = "第一颗。",
	},
	[10060543] = {
		ID = 10060543,
		Text = "葛蕾香按住右肩的伤口，鲜血从指缝间渗出。她抬起头，朝沙尘中凯伊隐匿的方向，猛然轰出一道更强的冲击波。",
	},
	[10060544] = {
		ID = 10060544,
		Text = "沙幕被撕开一个缺口，凯伊的身影暴露了一瞬。",
	},
	[10060545] = {
		ID = 10060545,
		Text = "凯伊没有躲，她趁着缺口，举枪，第二声枪响。",
	},
	[10060546] = {
		ID = 10060546,
		Text = "子弹命中葛蕾香的左脚，她整个人踉跄跪地，龙血溅在干裂的土壤上，渗出一片暗金色的痕迹。",
	},
	[10060547] = {
		ID = 10060547,
		Text = "群众再次欢呼，比第一次更疯狂。",
	},
	[10060548] = {
		ID = 10060548,
		Speaker = "群众",
		Text = "凯伊！凯伊！凯伊！",
	},
	[10060549] = {
		ID = 10060549,
		Speaker = "黛莉亚",
		Text = "还剩一颗……",
	},
	[10060550] = {
		ID = 10060550,
		Text = "葛蕾香单膝跪地，抬起头，眼神里看不出痛楚，只有一种冰冷的专注。",
	},
	[10060551] = {
		ID = 10060551,
		Text = "她猛然挥出右臂，一道冲击波的轨迹不再是直线，而是弧形包抄。",
	},
	[10060552] = {
		ID = 10060552,
		Text = "凯伊来不及闪避，冲击波正面命中她的右手臂。",
	},
	[10060553] = {
		ID = 10060553,
		Text = "骨头碎裂的声音清晰可闻。",
	},
	[10060554] = {
		ID = 10060554,
		Speaker = "凯伊",
		Text = "呜——！",
	},
	[10060555] = {
		ID = 10060555,
		Text = "凯伊的右手臂软塌下来，手枪从手中脱落，砸在地上。",
	},
	[10060556] = {
		ID = 10060556,
		Text = "群众的欢呼戛然而止，所有人屏住呼吸。",
	},
	[10060557] = {
		ID = 10060557,
		Speaker = "首领",
		Text = "完了……她的手……",
	},
	[10060558] = {
		ID = 10060558,
		Speaker = "伊丝娜",
		Text = "凯伊！",
	},
	[10060559] = {
		ID = 10060559,
		Speaker = "首领",
		Text = "惯用手废了……结束了……",
	},
	[10060560] = {
		ID = 10060560,
		Text = "葛蕾香撑着受伤的左脚，缓缓站起，一跃飞回高台顶端。",
	},
	[10060561] = {
		ID = 10060561,
		Text = "她居高临下俯视着底下单膝跪地、右臂无力垂挂的凯伊，抬起右手，龙族魔力在掌心凝聚，光芒越来越刺眼。",
	},
	[10060563] = {
		ID = 10060563,
		Text = "葛蕾香从高台俯冲而下，带着足以震碎地面的力道，直扑凯伊。",
	},
	[10060564] = {
		ID = 10060564,
		Text = "所有人都以为结束了。",
	},
	[10060565] = {
		ID = 10060565,
		Text = "凯伊跪在原地，右手废了，身上全是擦伤跟沙尘。",
	},
	[10060566] = {
		ID = 10060566,
		Text = "她低着头，左手，缓缓捡起地上的手枪。",
	},
	[10060567] = {
		ID = 10060567,
		Speaker = "凯伊",
		Text = "……老子说过。",
	},
	[10060568] = {
		ID = 10060568,
		Speaker = "凯伊",
		Text = "三颗就够了。",
	},
	[10060569] = {
		ID = 10060569,
		Text = "她抬头，左手举枪，对准从高空俯冲而来的葛蕾香，第三声枪响。",
	},
	[10060570] = {
		ID = 10060570,
		Text = "子弹划破空气，精准命中葛蕾香的额头。",
	},
	[10060571] = {
		ID = 10060571,
		Text = "葛蕾香的身体在半空中猛然一顿，龙族魔力的光芒瞬间熄灭。",
	},
	[10060572] = {
		ID = 10060572,
		Speaker = "凯伊",
		Text = "（咦？）",
	},
	[10060573] = {
		ID = 10060573,
		Text = "她的身体失去支撑，直直坠入水源地，水花冲天而起。",
	},
	[10060574] = {
		ID = 10060574,
		Text = "龙血从水中散开，像金色的墨水，一圈一圈向外蔓延。",
	},
	[10060575] = {
		ID = 10060575,
		Text = "浑浊的水面，在所有人眼前，缓缓变得澄澈透明。",
	},
	[10060576] = {
		ID = 10060576,
		Text = "整个水源地，像被施了一场奇迹，重新变回了干净的水。",
	},
	[10060577] = {
		ID = 10060577,
		Text = "广场上，死一般地安静。",
	},
	[10060578] = {
		ID = 10060578,
		Text = "然后，欢呼声如海啸般爆发。",
	},
	[10060579] = {
		ID = 10060579,
		Speaker = "群众",
		Text = "水！干净的水！",
	},
	[10060580] = {
		ID = 10060580,
		Speaker = "难民妇人",
		Text = "终于……终于有水了……",
	},
	[10060581] = {
		ID = 10060581,
		Text = "我没有加入欢呼。他快步走到凯伊身边，一把扶起她，带着她登上高台。",
	},
	[10060582] = {
		ID = 10060582,
		Speaker = "我",
		Text = "站上去。",
	},
	[10060583] = {
		ID = 10060583,
		Speaker = "凯伊",
		Text = "……什么？",
	},
	[10060584] = {
		ID = 10060584,
		Speaker = "我",
		Text = "诸位！决斗已经结束！",
	},
	[10060585] = {
		ID = 10060585,
		Speaker = "我",
		Text = "凯伊是胜利者！",
	},
	[10060586] = {
		ID = 10060586,
		Text = "群众的欢呼更加震耳。",
	},
	[10060587] = {
		ID = 10060587,
		Speaker = "我",
		Text = "他现在是……这颗星球的新领袖！",
	},
	[10060588] = {
		ID = 10060588,
		Text = "凯伊又愣住了，转头瞪着我，嘴巴张开又合上。",
	},
	[10060589] = {
		ID = 10060589,
		Speaker = "凯伊",
		Text = "……你又来。",
	},
	[10060590] = {
		ID = 10060590,
		Speaker = "我",
		Text = "你可以拒绝。",
	},
	[10060591] = {
		ID = 10060591,
		Text = "凯伊看着底下那些欢呼的脸、哭泣的脸、满怀期待看着她的脸。",
	},
	[10060592] = {
		ID = 10060592,
		Text = "她深吸一口气。",
	},
	[10060593] = {
		ID = 10060593,
		Speaker = "凯伊",
		Text = "好！老子接了！",
	},
	[10060594] = {
		ID = 10060594,
		Text = "群众再次欢呼。",
	},
	[10060595] = {
		ID = 10060595,
		Speaker = "凯伊",
		Text = "新首领的第一个法令！",
	},
	[10060596] = {
		ID = 10060596,
		Text = "凯伊抬起还能动的左手，指向人群中的机械公民。",
	},
	[10060597] = {
		ID = 10060597,
		Speaker = "凯伊",
		Text = "从今天起，机械公民跟人类，同等地位！",
	},
	[10060598] = {
		ID = 10060598,
		Speaker = "凯伊",
		Text = "谁敢再欺负他们，就来跟老子的枪说话！",
	},
	[10060599] = {
		ID = 10060599,
		Text = "群众愣了一瞬，随即被胜利的狂热淹没，欢呼声盖过了一切异议。",
	},
	[10060600] = {
		ID = 10060600,
		Text = "伊丝娜在人群角落里，眼泪无声地流下来。",
	},
	[10060601] = {
		ID = 10060601,
		Text = "机械公民们瑟缩着抬起头，第一次在这颗星球上，听见有人替他们说话。",
	},
	[10060602] = {
		ID = 10060602,
		Text = "唯有首领，站在台下，脸色铁青，双拳握得指节泛白。",
	},
	[10060603] = {
		ID = 10060603,
		Text = "凯伊转头看了一下水源，始终没看到葛蕾香的尸体飘上来。",
	},
	[10060604] = {
		ID = 10060604,
		Speaker = "凯伊",
		Text = "（总觉得最后击中的感觉不太对……是我的错觉吗？）",
	},
	[10060605] = {
		ID = 10060605,
		Text = "转场",
	},
	[10060606] = {
		ID = 10060606,
		Text = "转场",
	},
	[10060607] = {
		ID = 10060607,
		Text = "水源地，夜幕降临，群众已经散去。",
	},
	[10060608] = {
		ID = 10060608,
		Text = "我独自走到水源地边缘，朝水面低声开口。",
	},
	[10060609] = {
		ID = 10060609,
		Speaker = "我",
		Text = "可以起来了。",
	},
	[10060610] = {
		ID = 10060610,
		Text = "水面晃动，葛蕾香缓缓从水中站起，浑身湿透，额头上有一道被钝击造成的瘀伤，但没有贯穿的弹孔。",
	},
	[10060611] = {
		ID = 10060611,
		Speaker = "葛蕾香",
		Text = "……本人在水底趴了快一个时辰。",
	},
	[10060612] = {
		ID = 10060612,
		Speaker = "我",
		Text = "辛苦了。",
	},
	[10060613] = {
		ID = 10060613,
		Speaker = "葛蕾香",
		Text = "哼。",
	},
	[10060614] = {
		ID = 10060614,
		Speaker = "我",
		Text = "决斗之前，我替凯伊检查弹轮的时候。第三颗换成了普通子弹。",
	},
	[10060615] = {
		ID = 10060615,
		Speaker = "葛蕾香",
		Text = "所以她最后那一枪，打中本人额头的，只是普通金属。",
	},
	[10060616] = {
		ID = 10060616,
		Speaker = "我",
		Text = "对。冲击力足够让你倒下，但不会贯穿龙族的头骨。",
	},
	[10060617] = {
		ID = 10060617,
		Speaker = "我",
		Text = "前两枪是真的龙骨子弹。肩膀跟脚，还好吗？",
	},
	[10060618] = {
		ID = 10060618,
		Speaker = "葛蕾香",
		Text = "龙族的自愈能力，几天就会长好。不需要你操心。",
	},
	[10060619] = {
		ID = 10060619,
		Speaker = "我",
		Text = "那就好。",
	},
	[10060620] = {
		ID = 10060620,
		Text = "说真的，我也没想过真的能说服骄傲的公主殿下能够配合演出阿！",
	},
	[10060621] = {
		ID = 10060621,
		Text = "我的思绪飘回数小时前——龙族墓地，沙尘弥漫的黄昏。",
	},
	[10060622] = {
		ID = 10060622,
	},
	[10060623] = {
		ID = 10060623,
		Text = "龙族墓地，葛蕾香把受伤的我拖到墓碑群旁。她没有把他关起来，而是跟他并肩站在龙族长老的墓碑前。",
	},
	[10060624] = {
		ID = 10060624,
		Speaker = "葛蕾香",
		Text = "你刚才说的那句话……再说一次。",
	},
	[10060625] = {
		ID = 10060625,
		Speaker = "我",
		Text = "一人孤行，静默地背负使命。",
	},
	[10060626] = {
		ID = 10060626,
		Speaker = "葛蕾香",
		Text = "……然后呢。",
	},
	[10060627] = {
		ID = 10060627,
		Speaker = "我",
		Text = "我问你一个问题。",
	},
	[10060628] = {
		ID = 10060628,
		Speaker = "我",
		Text = "人类，论力量、论魔力、论寿命，没有一项比得上龙族。",
	},
	[10060629] = {
		ID = 10060629,
		Speaker = "我",
		Text = "这样的种族，怎么可能被人类歼灭？",
	},
	[10060630] = {
		ID = 10060630,
		Text = "葛蕾香僵住了。",
	},
	[10060631] = {
		ID = 10060631,
		Speaker = "我",
		Text = "你想过这个问题吧。",
	},
	[10060632] = {
		ID = 10060632,
		Speaker = "葛蕾香",
		Text = "……本人想过。想了很多年。",
	},
	[10060633] = {
		ID = 10060633,
		Speaker = "我",
		Text = "答案是什么？",
	},
	[10060634] = {
		ID = 10060634,
		Speaker = "葛蕾香",
		Text = "本人找不到答案。",
	},
	[10060635] = {
		ID = 10060635,
		Speaker = "葛蕾香",
		Text = "人类的武器不可能重创龙族。就算有龙骨剑，也只有两把，杀不了一整个族群。",
	},
	[10060636] = {
		ID = 10060636,
		Speaker = "葛蕾香",
		Text = "除非……",
	},
	[10060637] = {
		ID = 10060637,
		Speaker = "我",
		Text = "除非有神明一般的存在，在背后帮忙。",
	},
	[10060638] = {
		ID = 10060638,
		Speaker = "葛蕾香",
		Text = "你是说……女神方？",
	},
	[10060639] = {
		ID = 10060639,
		Speaker = "我",
		Text = "我没有证据。但你心里清楚，人类单靠自己，办不到那种程度的屠杀。",
	},
	[10060640] = {
		ID = 10060640,
		Speaker = "葛蕾香",
		Text = "……本人是女神的仕女。你要本人怀疑自己效忠的对象？",
	},
	[10060641] = {
		ID = 10060641,
		Speaker = "我",
		Text = "我要你问自己一个问题。",
	},
	[10060642] = {
		ID = 10060642,
		Speaker = "我",
		Text = "你守护这片水源、管理这颗星球、效忠女神组织，这些事，有哪一件是你自己选的？",
	},
	[10060643] = {
		ID = 10060643,
		Speaker = "我",
		Text = "还是全部都是「父亲会希望你这么做」？",
	},
	[10060644] = {
		ID = 10060644,
		Text = "葛蕾香沉默了很久。风沙从墓碑间穿过。",
	},
	[10060645] = {
		ID = 10060645,
		Speaker = "葛蕾香",
		Text = "……如果本人想知道真相，就必须离开这里。",
	},
	[10060646] = {
		ID = 10060646,
		Speaker = "葛蕾香",
		Text = "但女神组织不会允许本人擅离职守。赛诃希丝已经在盯着了。",
	},
	[10060647] = {
		ID = 10060647,
		Speaker = "我",
		Text = "所以你需要死一次。",
	},
	[10060648] = {
		ID = 10060648,
		Speaker = "葛蕾香",
		Text = "……什么意思。",
	},
	[10060649] = {
		ID = 10060649,
		Speaker = "我",
		Text = "在所有人面前死一次。在女神方面前死一次。",
	},
	[10060650] = {
		ID = 10060650,
		Speaker = "我",
		Text = "死掉的葛蕾香，没有人会追查。活着的葛蕾香，才能去找真相。",
	},
	[10060651] = {
		ID = 10060651,
		Speaker = "葛蕾香",
		Text = "你要让凯伊杀本人？",
	},
	[10060652] = {
		ID = 10060652,
		Speaker = "我",
		Text = "凯伊手上有龙骨子弹。她会来找你决斗。这是最好的机会。",
	},
	[10060654] = {
		ID = 10060654,
		Text = "水源地旁，月光照在两人身上。",
	},
	[10060655] = {
		ID = 10060655,
		Speaker = "我",
		Text = "不过公主殿下的演技真是出乎意料的好！",
	},
	[10060656] = {
		ID = 10060656,
		Speaker = "葛蕾香",
		Text = "哼。",
	},
	[10060657] = {
		ID = 10060657,
		Text = "远处，一道脚步声正在接近，轻巧、虚浮，带着熟悉的嘻笑。",
	},
	[10060658] = {
		ID = 10060658,
		Speaker = "赛诃希丝",
		Text = "嘻嘻嘻嘻……龙女大人的尸体呢？属下想来瞻仰一下遗容。",
	},
	[10060659] = {
		ID = 10060659,
		Text = "赛诃希丝的身影绕过石壁，直直朝水源地走来。",
	},
	[10060661] = {
		ID = 10060661,
		Text = "赛诃希丝的目光扫过来，越来越近，再走三步，就会直接看见葛蕾香。",
	},
	[10060662] = {
		ID = 10060662,
		Text = "两步。",
	},
	[10060663] = {
		ID = 10060663,
		Text = "一步。",
	},
	[10060664] = {
		ID = 10060664,
		Text = "然后，空气变了。",
	},
	[10060665] = {
		ID = 10060665,
		Text = "没有声音，没有光芒，只是周围的一切突然像被薄纱覆盖，轮廓开始微微溶解。",
	},
	[10060666] = {
		ID = 10060666,
		Text = "赛诃希丝的视线掠过葛蕾香站立的位置，却什么都没看见。只有空荡荡的水岸跟月光下的石壁。",
	},
	[10060667] = {
		ID = 10060667,
		Speaker = "赛诃希丝",
		Text = "嗯？",
	},
	[10060668] = {
		ID = 10060668,
		Text = "她皱了皱眉，又看了一遍，确认那里什么都没有。",
	},
	[10060669] = {
		ID = 10060669,
		Speaker = "赛诃希丝",
		Text = "尸体沉下去了吗……真扫兴。",
	},
	[10060670] = {
		ID = 10060670,
		Text = "她转头打量我，嘴角还挂着笑，但眼底突然闪过一丝警觉。",
	},
	[10060671] = {
		ID = 10060671,
		Speaker = "赛诃希丝",
		Text = "……奇怪。",
	},
	[10060672] = {
		ID = 10060672,
		Speaker = "我",
		Text = "怎么了？",
	},
	[10060673] = {
		ID = 10060673,
		Speaker = "赛诃希丝",
		Text = "这附近……有一股很异常的魔力。",
	},
	[10060674] = {
		ID = 10060674,
		Speaker = "赛诃希丝",
		Text = "非常强。强到我完全无法辨识来源。",
	},
	[10060675] = {
		ID = 10060675,
		Text = "她的视线快速扫过四周，找不到任何异状，但那股压迫感却清晰得无法忽视。",
	},
	[10060676] = {
		ID = 10060676,
		Speaker = "赛诃希丝",
		Text = "……不是龙族的。也不是人类的。",
	},
	[10060677] = {
		ID = 10060677,
		Speaker = "赛诃希丝",
		Text = "这种等级的魔力，属下从来没有感受过。",
	},
	[10060678] = {
		ID = 10060678,
		Speaker = "我",
		Text = "妳就没想过是我的魔力吗？",
	},
	[10060679] = {
		ID = 10060679,
		Text = "她的笑容第一次出现了苦笑。",
	},
	[10060680] = {
		ID = 10060680,
		Speaker = "赛诃希丝",
		Text = "嘻嘻……看来这颗星球上，藏着的东西比我想的还要多呢。",
	},
	[10060681] = {
		ID = 10060681,
		Speaker = "赛诃希丝",
		Text = "罢了，今天就先到这里。",
	},
	[10060682] = {
		ID = 10060682,
		Speaker = "赛诃希丝",
		Text = "虫子，你迟早会落到我手上的。下次见。",
	},
	[10060683] = {
		ID = 10060683,
		Text = "赛诃希丝转身离去，步伐比来时快了几分，笑声也比平常短了一些。",
	},
	[10060684] = {
		ID = 10060684,
		Text = "等她的气息彻底消失，我才发现自己的后背已经全是冷汗。",
	},
	[10060685] = {
		ID = 10060685,
		Speaker = "我",
		Text = "……好险。",
	},
	[10060686] = {
		ID = 10060686,
		Text = "他转身，葛蕾香依然站在原地，但她身旁多了一个女人，蒙着兜帽的身影，无声无息，像从阴影中长出来的。",
	},
	[10060687] = {
		ID = 10060687,
		Speaker = "我",
		Text = "……是你。当初帮我逃出追杀的那个魔法师姐姐？",
	},
	[10060688] = {
		ID = 10060688,
		Text = "尖帽下的人微微点了一下头。",
	},
	[10060689] = {
		ID = 10060689,
		Speaker = "耶珥",
		Text = "…………",
	},
	[10060690] = {
		ID = 10060690,
		Speaker = "葛蕾香",
		Text = "她叫耶珥。本人小时候，她就在了。一直藏在这颗星球的某处，暗中照看本人长大。",
	},
	[10060691] = {
		ID = 10060691,
		Text = "也是耶珥告诉我，维护人类，是父亲的遗愿。",
	},
	[10060692] = {
		ID = 10060692,
		Speaker = "我",
		Text = "耶珥为什么要保护葛蕾香？",
	},
	[10060693] = {
		ID = 10060693,
		Text = "上次来不及问你，你是反抗女神的势力吗？",
	},
	[10060694] = {
		ID = 10060694,
		Speaker = "耶珥",
		Text = "呵，我只是一个爱管闲事的魔女罢了。",
	},
	[10060695] = {
		ID = 10060695,
		Speaker = "我",
		Text = "……耶珥，谢谢你。当初救了我，今天又救了她。",
	},
	[10060696] = {
		ID = 10060696,
		Text = "耶珥轻轻摇了摇头。",
	},
	[10060697] = {
		ID = 10060697,
		Speaker = "耶珥",
		Text = "我需要你活着，活越久越好。",
	},
	[10060698] = {
		ID = 10060698,
		Speaker = "我",
		Text = "那你可要多救我几次才行啊！魔法师姐姐！",
	},
	[10060699] = {
		ID = 10060699,
		Speaker = "葛蕾香",
		Text = "罪人。",
	},
	[10060700] = {
		ID = 10060700,
		Text = "葛蕾香从腰间取下一个皮囊，递给我。皮囊沉甸甸的，里面装着液体。",
	},
	[10060701] = {
		ID = 10060701,
		Speaker = "葛蕾香",
		Text = "本人的血。足够你用一段时间。",
	},
	[10060702] = {
		ID = 10060702,
		Speaker = "我",
		Text = "凯伊那边……",
	},
	[10060703] = {
		ID = 10060703,
		Speaker = "葛蕾香",
		Text = "你自己去交代。本人没有义务替你善后。",
	},
	[10060704] = {
		ID = 10060704,
		Speaker = "我",
		Text = "她会揍我。",
	},
	[10060705] = {
		ID = 10060705,
		Speaker = "葛蕾香",
		Text = "你活该。",
	},
	[10060706] = {
		ID = 10060706,
		Speaker = "我",
		Text = "那水源呢？",
	},
	[10060707] = {
		ID = 10060707,
		Speaker = "葛蕾香",
		Text = "龙血能暂时压制诅咒。这一袋用完之前，本人会回来补。",
	},
	[10060708] = {
		ID = 10060708,
		Speaker = "葛蕾香",
		Text = "固定时间，不要担心。",
	},
	[10060709] = {
		ID = 10060709,
		Speaker = "我",
		Text = "你会回来？",
	},
	[10060710] = {
		ID = 10060710,
		Speaker = "葛蕾香",
		Text = "本人选择守护这片水源，不是为了赎罪，是因为这里需要水。",
	},
	[10060711] = {
		ID = 10060711,
		Speaker = "葛蕾香",
		Text = "但本人不会再为任何人的剧本活着。包括父亲的，包括女神的。",
	},
	[10060712] = {
		ID = 10060712,
		Speaker = "葛蕾香",
		Text = "本人回来，是因为本人自己决定要回来。",
	},
	[10060713] = {
		ID = 10060713,
		Text = "葛蕾香转身，走向耶珥。",
	},
	[10060714] = {
		ID = 10060714,
		Speaker = "葛蕾香",
		Text = "罪人。下次见面，本人要听你说清楚，你跟主上之间到底发生了什么。",
	},
	[10060715] = {
		ID = 10060715,
		Speaker = "葛蕾香",
		Text = "不准再敷衍本人。",
	},
	[10060716] = {
		ID = 10060716,
		Speaker = "我",
		Text = "好，一言为定。",
	},
	[10060717] = {
		ID = 10060717,
		Text = "两个身影走入荒原深处的夜色中，消失在沙丘的另一边。",
	},
	[10060718] = {
		ID = 10060718,
		Text = "过了一会儿，伊丝娜跟黛莉亚走了过来。",
	},
	[10060719] = {
		ID = 10060719,
		Speaker = "伊丝娜",
		Text = "后辈，你一个人在这里干嘛？",
	},
	[10060720] = {
		ID = 10060720,
		Speaker = "我",
		Text = "等你们。先喝水吧。",
	},
	[10060721] = {
		ID = 10060721,
		Text = "三人蹲在水源地旁，伊丝娜捧了一口水喝下去。",
	},
	[10060722] = {
		ID = 10060722,
		Speaker = "伊丝娜",
		Text = "……没有泥巴味了。",
	},
	[10060723] = {
		ID = 10060723,
		Speaker = "黛莉亚",
		Text = "好好喝！",
	},
	[10060724] = {
		ID = 10060724,
		Speaker = "伊丝娜",
		Text = "泥巴啤酒再见",
	},
	[10060725] = {
		ID = 10060725,
		Text = "三人坐在水源地旁，月光照在干净的水面上，波光粼粼。",
	},
	[10060726] = {
		ID = 10060726,
		Text = "不远处，人类跟机械公民把凯伊丢到空中狂欢着。",
	},
	[10060727] = {
		ID = 10060727,
		Speaker = "我",
		Text = "黛莉亚，你先去启动飞船吧！",
	},
	[10060728] = {
		ID = 10060728,
		Speaker = "黛莉亚",
		Text = "怎么了？",
	},
	[10060729] = {
		ID = 10060729,
		Speaker = "伊丝娜",
		Text = "方便后辈逃跑。",
	},
	[10060730] = {
		ID = 10060730,
		Speaker = "我",
		Text = "没错，我要拿着这一袋龙血去跟她解释整个状况。",
	},
	[10060731] = {
		ID = 10060731,
		Speaker = "黛莉亚",
		Text = "哇啊～～她一定会拿枪扫射你！",
	},
	[10060732] = {
		ID = 10060732,
		Speaker = "我",
		Text = "所以，这个水，我们再多喝几口吧！",
	},
	[10060733] = {
		ID = 10060733,
		Speaker = "我",
		Text = "这辈子没喝过这么『昂贵』的水！",
	},
	[10060734] = {
		ID = 10060734,
		Speaker = "我",
		Text = "你们知道吗，在其他星球，打开水龙头就有干净的水。",
	},
	[10060735] = {
		ID = 10060735,
		Speaker = "伊丝娜",
		Text = "别说了，听了更心酸。",
	},
	[10060736] = {
		ID = 10060736,
		Speaker = "黛莉亚",
		Text = "欸，那我们下一颗星球能不能去一个有很多水的地方？",
	},
	[10060737] = {
		ID = 10060737,
		Speaker = "我",
		Text = "上一颗是冰，这一颗是沙。照这个规律，下一颗搞不好是火山。",
	},
	[10060738] = {
		ID = 10060738,
		Speaker = "伊丝娜",
		Text = "拜托不要。",
	},
	[10060739] = {
		ID = 10060739,
		Text = "风沙比往日平静了一些，远处的沙尘暴没有再靠近。",
	},
	[10060740] = {
		ID = 10060740,
		Text = "我捧了一口水喝下去，然后躺在地上，长长地叹了一口气。",
	},
	[10060741] = {
		ID = 10060741,
		Speaker = "我",
		Text = "……这口水，得来还真不容易。",
	},
	[10060742] = {
		ID = 10060742,
		Text = "三人安静地坐着，谁也没有急着站起来。",
	},
	[10060743] = {
		ID = 10060743,
		Text = "荒野星球的夜空，第一次看起来没那么荒凉了。",
	},
	[10060744] = {
		ID = 10060744,
	},
	[10060745] = {
		ID = 10060745,
	},
	[10060746] = {
		ID = 10060746,
	},
	[20080105] = {
		ID = 20080105,
		Speaker = "我",
		Text = "那……所以今天要抓鹿吗？",
	},
	[20080164] = {
		ID = 20080164,
		Speaker = "我",
		Text = "……",
	},
	[20080178] = {
		ID = 20080178,
		Speaker = "我",
		Text = "上……？等、等等等等——！ ！",
	},
	[20080211] = {
		ID = 20080211,
		Speaker = "我",
		Text = "……",
	},
	[20080232] = {
		ID = 20080232,
		Speaker = "我",
		Text = "那……伊尔瓦为什么没有尾巴？",
	},
	[20080235] = {
