		Speaker = "我",
		Text = "你还好吗？",
	},
	[20050513] = {
		ID = 20050513,
		Speaker = "黛莉亚",
		Text = "哇啊啊……身上都是泥土跟鸟味。",
	},
	[20050514] = {
		ID = 20050514,
		Speaker = "我",
		Text = "你的衣服……",
	},
	[20050515] = {
		ID = 20050515,
		Speaker = "黛莉亚",
		Text = "先别管衣服了吧？小鸟呢？",
	},
	[20050516] = {
		ID = 20050516,
		Speaker = "黛莉亚",
		Text = "小鸟都没事吧？",
	},
	[20050517] = {
		ID = 20050517,
		Text = "（黛莉雅急忙地把头凑到窝旁。）",
	},
	[20050518] = {
