	[30150123] = {
		ID = 30150123,
		Speaker = "我",
		Text = "譬如说称赞大家很色又很可爱什么的……",
	},
	[10013299] = {
		ID = 10013299,
		Speaker = "我",
		Text = "你这家伙，果然深藏不露啊！",
