		Text = "唔哇啊！",
	},
	[40000483] = {
		ID = 40000483,
		Speaker = "我",
		Text = "唔哇啊！学姊！你冷静一点啊！",
	},
	[10010383] = {
		ID = 10010383,
		Speaker = "伊丝娜",
		Text = "啊～～～",
	},
	[10010385] = {
		ID = 10010385,
		Speaker = "黛莉亚",
		Text = "啊，是刚刚说要整个大翻修的地方。",
	},
	[10010516] = {
		ID = 10010516,
		Speaker = "黛莉亚",
		Text = "伊丝娜小姐怎么脸这么红啊？",
