	},
	[20080188] = {
		ID = 20080188,
		Text = "（一根枯木往我们这边直直飞过来。）",
	},
	[20080189] = {
		ID = 20080189,
		Text = "（伊尔瓦两脚一蹬跳起，落到巨木时轻盈的再次跳起。）",
	},
	[20080190] = {
		ID = 20080190,
		Text = "（落回雪地的瞬间我只感受到了跨下传来的冲击跟越来越快的速度。）",
	},
	[20080192] = {
		ID = 20080192,
		Speaker = "伊尔瓦",
		Text = "抓胸部吧！小公鸡不是很喜欢胸部吗？",
	},
	[20080194] = {
		ID = 20080194,
		Speaker = "伊尔瓦",
		Text = "欸？抓哪里都好，就是不要抓伊尔瓦的耳朵！",
	},
	[20080196] = {
		ID = 20080196,
		Text = "（这时我的脑子里闪过一件事——）",
	},
	[20080197] = {
		ID = 20080197,
		Text = "（当初发现伊尔瓦的尾巴是假的以后，就一直非常的好奇。）",
	},
	[20080199] = {
		ID = 20080199,
		Speaker = "伊尔瓦",
		Text = "小公鸡！你想干什么！ ？",
	},
	[20080200] = {
		ID = 20080200,
		Speaker = "伊尔瓦",
		Text = "你不准——！",
	},
	[20080201] = {
		ID = 20080201,
		Text = "（我伸手摸上去的瞬间，感觉到温热、柔软，还有一种细微的颤动。）",
	},
	[20080202] = {
		ID = 20080202,
		Text = "（这触感绝对不是装饰品，而是真实的、有血液在里面流动的耳朵。）",
	},
	[20080203] = {
		ID = 20080203,
		Speaker = "伊尔瓦",
		Text = "咿咿咿咿咿——！",
	},
	[20080204] = {
		ID = 20080204,
		Text = "（我的手指往耳朵内侧摸去，手指被温暖舒服的绒毛包裹住。）",
	},
	[20080205] = {
		ID = 20080205,
		Speaker = "伊尔瓦",
		Text = "唔喔喔喔喔——！不要——呜！",
	},
	[20080206] = {
		ID = 20080206,
		Text = "伊尔瓦的惊叫声和失去方向的脚步几乎同时发生。",
	},
	[20080207] = {
		ID = 20080207,
		Text = "我从伊尔瓦的背上直接被甩下来，接着伊尔瓦整个人压到了我身上。",
	},
	[20080208] = {
		ID = 20080208,
		Text = "两人在雪地上滑行了好一阵子，直到两人撞进了雪堆中才停下。",
	},
	[20080212] = {
