	},
	[20080214] = {
		ID = 20080214,
		Text = "（伊尔瓦的双眼顿时亮了——连两只耳朵都竖了起来。）",
	},
	[20080215] = {
		ID = 20080215,
		Speaker = "伊尔瓦",
		Text = "咸奶油？喔喔！太阳人的面包！",
	},
	[20080220] = {
		ID = 20080220,
		Speaker = "伊尔瓦",
		Text = "……行！伊尔瓦说。",
	},
	[20080221] = {
		ID = 20080221,
		Text = "（伊尔瓦低下头，指了指帽子上两个洞。）",
	},
	[20080224] = {
		ID = 20080224,
		Speaker = "伊尔瓦",
		Text = "小公鸡见识太少了。",
	},
	[20080227] = {
		ID = 20080227,
		Speaker = "伊尔瓦",
		Text = "这对耳朵能听到三座山以外的脚步声。",
	},
	[20080231] = {
		ID = 20080231,
		Speaker = "伊尔瓦",
		Text = "恩～我闻到了，是菠萝面包！",
	},
	[20080233] = {
		ID = 20080233,
		Speaker = "伊尔瓦",
		Text = "这个伊尔瓦也不知道，不过我看大家都有尾巴。",
	},
	[20080234] = {
		ID = 20080234,
		Speaker = "伊尔瓦",
		Text = "所以伊尔瓦做了这个，塞在差不多的位置。",
	},
	[20080237] = {
		ID = 20080237,
		Speaker = "伊尔瓦",
		Text = "感觉就像是刚吃了两颗太阳一样！眼前都是白的，还有好大声的声音！",
	},
	[20080238] = {
		ID = 20080238,
		Speaker = "伊尔瓦",
		Text = "狼族里，只有信任的伙伴才可以碰耳朵！",
	},
	[20080240] = {
		ID = 20080240,
		Speaker = "伊尔瓦",
		Text = "小公鸡！",
	},
	[20080241] = {
		ID = 20080241,
		Speaker = "伊尔瓦",
		Text = "是说！伊尔瓦听说人类有和我很像的故事！",
	},
	[20080242] = {
		ID = 20080242,
		Speaker = "伊尔瓦",
