	},
	[20080562] = {
		ID = 20080562,
		Speaker = "伊尔瓦",
		Text = "终于又有力气了吗？",
	},
	[20080564] = {
		ID = 20080564,
		Speaker = "伊尔瓦",
		Text = "嗯？小公鸡，你的手在干嘛？",
	},
	[20080566] = {
		ID = 20080566,
		Speaker = "伊尔瓦",
		Text = "小公鸡，为什么你在揉伊尔瓦的屁股？",
	},
	[20080567] = {
		ID = 20080567,
		Speaker = "伊尔瓦",
		Text = "外面在干什么？",
	},
	[20080569] = {
