	[20080586] = {
		ID = 20080586,
		Speaker = "伊尔瓦",
		Text = "……呜……你故意的对不对……",
	},
	[20080593] = {
		ID = 20080593,
		Speaker = "伊尔瓦",
		Text = "呜啊啊啊……！",
	},
	[20080594] = {
		ID = 20080594,
		Speaker = "伊尔瓦",
		Text = "哈……哈啊……",
	},
	[20080597] = {
		ID = 20080597,
		Text = "（伴随着射精，伊尔瓦的尾巴整个被拔了出来。）",
	},
	[20080598] = {
		ID = 20080598,
		Text = "（插在雪地里的伊尔瓦全身剧烈的抖动。）",
	},
	[20080600] = {
		ID = 20080600,
		Text = "（趁着伊尔瓦全身瘫软，我用力的抓住伊尔瓦的腰一拔——）",
	},
	[20080601] = {
		ID = 20080601,
		Text = "（翻着白眼、全身抽搐的伊尔瓦躺在雪地上，舌头还露在外面。）",
	},
	[20080604] = {
		ID = 20080604,
		Text = "（看来只能等他自己醒来了。）",
	},
	[20080605] = {
		ID = 20080605,
	},
	[20080606] = {
		ID = 20080606,
		Text = "（太阳高挂在希望之丘的郊外，即使日照如此强烈，地上还是覆盖了厚厚一层雪。）",
	},
	[20080607] = {
		ID = 20080607,
		Text = "（我吐出一口白雾，紧跟在伊尔瓦后方。）",
	},
	[20080608] = {
		ID = 20080608,
		Speaker = "伊尔瓦",
		Text = "虽然小公鸡说今天要陪伊尔瓦，但是伊尔瓦有个疑问——",
	},
	[20080609] = {
		ID = 20080609,
		Speaker = "伊尔瓦",
		Text = "小公鸡从来没有狩猎过吗？",
	},
	[20080611] = {
		ID = 20080611,
		Speaker = "伊尔瓦",
		Text = "不可能，连狼宝宝都要学会的狩猎，小公鸡怎么可能不会？",
	},
	[20080612] = {
		ID = 20080612,
		Speaker = "伊尔瓦",
		Text = "那你怎么活下来的？",
	},
	[20080614] = {
		ID = 20080614,
		Speaker = "伊尔瓦",
		Text = "那太奇怪了，人类都这样吗？",
	},
	[20080616] = {
		ID = 20080616,
		Speaker = "伊尔瓦",
		Text = "面包是交换来的，不一样，伊尔瓦的面包是狩猎的一部份。",
	},
	[20080617] = {
		ID = 20080617,
		Speaker = "伊尔瓦",
		Text = "既然是第一次，今天伊尔瓦要教小公鸡狩猎。",
	},
	[20080619] = {
		ID = 20080619,
		Speaker = "伊尔瓦",
		Text = "小公鸡也想学对吧！",
	},
	[20080621] = {
		ID = 20080621,
		Speaker = "伊尔瓦",
		Text = "要从什么体型的开始？超大型？大型？",
	},
	[20080622] = {
		ID = 20080622,
		Text = "（伊尔瓦无视我的话，在我身旁蹦跳。）",
	},
	[20080623] = {
		ID = 20080623,
	},
	[20080625] = {
		ID = 20080625,
		Text = "（几步之外，伊尔瓦也坐在雪地上，黄色辫子贴在脸上，样子说不上是生气还是傻了。）",
