	[20140122] = {
		ID = 20140122,
	},
	[20140123] = {
		ID = 20140123,
		Text = "（早餐后，秋比走在我前头，偶尔转个半圈回望，确认我有没有跟上。）",
	},
	[20140124] = {
		ID = 20140124,
		Speaker = "秋比",
		Text = "好好吃！松饼真的好好吃！",
	},
	[20140125] = {
		ID = 20140125,
		Text = "（秋比捧着脸原地转了一圈，头顶的气球跟着摇摇摆摆。）",
	},
	[20140126] = {
		ID = 20140126,
		Speaker = "秋比",
		Text = "有奶油！有草莓！还有好甜好甜的蜂蜜味！",
	},
	[20140128] = {
		ID = 20140128,
		Speaker = "秋比",
		Text = "那当然！三明治是什么嘛，只会让人觉得肚子很混乱！",
	},
	[20140131] = {
		ID = 20140131,
		Text = "（路边的机器人往我们这边看了一眼，随后慌张地跑开。）",
	},
	[20140133] = {
		ID = 20140133,
		Speaker = "秋比",
		Text = "欸欸？平常？",
	},
	[20140134] = {
		ID = 20140134,
		Speaker = "秋比",
		Text = "嗯……有时候会画画！",
	},
	[20140136] = {
		ID = 20140136,
		Speaker = "秋比",
		Text = "对啊！把看到的东西画下来！",
	},
	[20140137] = {
		ID = 20140137,
		Speaker = "秋比",
		Text = "好多好多！整面墙都是！",
	},
	[20140139] = {
		ID = 20140139,
		Speaker = "秋比",
		Text = "会有机器人来帮忙清理呀！",
	},
	[20140141] = {
		ID = 20140141,
		Speaker = "秋比",
		Text = "还有……放烟火！",
	},
	[20140143] = {
		ID = 20140143,
		Speaker = "秋比",
		Text = "对！就在广场上放，声音好大！颜色好漂亮！",
	},
	[20140145] = {
		ID = 20140145,
		Speaker = "秋比",
		Text = "会呀！",
	},
	[20140147] = {
		ID = 20140147,
		Speaker = "秋比",
		Text = "然后它们也一起看烟火！",
	},
	[20140149] = {
		ID = 20140149,
		Speaker = "秋比",
		Text = "不知道！但它们都站在那边不动了！",
	},
	[20140151] = {
		ID = 20140151,
		Speaker = "秋比",
		Text = "那不一样！当机是坏掉，看烟火是一起玩！",
	},
	[20140153] = {
		ID = 20140153,
		Speaker = "秋比",
		Text = "对吧对吧！ ！",
	},
	[20140154] = {
		ID = 20140154,
		Speaker = "秋比",
		Text = "大玩偶选一个吧！",
	},
	[20140155] = {
		ID = 20140155,
		Speaker = "秋比",
		Text = "大玩偶选哪个，我们今天就去玩哪个吧！",
	},
	[20140156] = {
		ID = 20140156,
	},
	[20140157] = {
		ID = 20140157,
		Speaker = "秋比",
		Text = "太好了！大玩偶选了画画！",
	},
	[20140158] = {
		ID = 20140158,
		Text = "（秋比立刻跳了起来，双臂举高，原地转了一圈。）",
	},
	[20140160] = {
		ID = 20140160,
		Speaker = "秋比",
		Text = "走走走！我知道最棒的地方！",
	},
	[20140162] = {
		ID = 20140162,
		Speaker = "秋比",
		Text = "跟着我就对了！大玩偶不用想那么多！",
