		Speaker = "薇拉",
		Text = "我可是满怀着心意在进行演出练习的。",
	},
	[30060027] = {
		ID = 30060027,
		Speaker = "薇拉",
		Text = "就连你说的，要适度地排出汗液，表现出现场的热情与温度这点，我都也有办到。",
	},
	[30060028] = {
		ID = 30060028,
		Speaker = "薇拉",
		Text = "请听……",
	},
	[30060029] = {
		ID = 30060029,
		Speaker = "薇拉",
		Text = "广阔宇宙中的孤独星光～你可否听到我在歌唱～",
	},
	[30060030] = {
		ID = 30060030,
		Speaker = "我",
		Text = "啊啊……",
