	[10012324] = {
		ID = 10012324,
		Speaker = "瑟蕾雅",
		Text = "小时候真的有人这样说过喔。",
	},
	[10012325] = {
		ID = 10012325,
		Speaker = "瑟蕾雅",
		Text = "有个男孩子把愿望写成十七页，还用线绑起来。",
