	[10012333] = {
		ID = 10012333,
		Speaker = "我",
		Text = "因为真正珍贵的东西，大多不能长久保存。",
	},
	[10012334] = {
		ID = 10012334,
		Text = "西西雅抬眼看了他一瞬，像是听出某种不属于玩笑的重量。",
	},
	[10012335] = {
		ID = 10012335,
		Speaker = "西西雅",
