	[10012587] = {
		ID = 10012587,
		Text = "秋比在口袋掏到什么就往黑暗乱丢",
	},
	[10012588] = {
		ID = 10012588,
		Speaker = "我",
		Text = "你丢面包干嘛？",
	},
	[10012589] = {
		ID = 10012589,
		Text = "自从秋比丢出面包后，黑暗中的攻击停止了。",
	},
	[10012590] = {
		ID = 10012590,
		Text = "取而代之，冲出两只迷你生物。",
	},
	[10012591] = {
		ID = 10012591,
		Speaker = "秋比",
		Text = "狗狗！",
	},
	[10012592] = {
		ID = 10012592,
		Text = "两颗毛茸茸的小球从树后滚出来，一白一黑，像被雪和炭灰揉成的幼狼。",
	},
	[10012593] = {
		ID = 10012593,
		Speaker = "秋比",
		Text = "好可爱！白色的是雪球，黑色的是木炭！",
	},
	[10012594] = {
		ID = 10012594,
		Speaker = "黛莉亚",
		Text = "妳怎么知道名字？",
	},
	[10012595] = {
		ID = 10012595,
		Speaker = "秋比",
		Text = "因为它们看起来就是叫这个名字！",
	},
	[10012596] = {
		ID = 10012596,
		Speaker = "我",
		Text = "不，她说对了。",
	},
	[10012597] = {
		ID = 10012597,
		Speaker = "瑟蕾雅",
		Text = "这两只小东西身上的魔力，比外表危险太多。",
	},
	[10012598] = {
		ID = 10012598,
		Speaker = "秋比",
		Text = "乖狗狗，过来，秋比不是坏人。",
	},
	[10012599] = {
		ID = 10012599,
		Text = "白色幼狼咬住秋比的袖子，黑色幼狼咬住她的围巾，转身就跑。",
	},
	[10012600] = {
		ID = 10012600,
		Speaker = "秋比",
		Text = "哇！它们邀请秋比玩拔河！",
	},
	[10012601] = {
		ID = 10012601,
		Text = "黑暗中，幼狼的主人现身",
	},
	[10012602] = {
		ID = 10012602,
		Text = "红色兜帽从树上一跃而下，少女披着厚厚的兽毛斗篷，笑容像雪原里突然亮起的火。",
	},
	[10012603] = {
		ID = 10012603,
		Text = "少女嘴里还咬着刚刚秋比丢出来的面包。",
	},
	[10012604] = {
		ID = 10012604,
		Speaker = "神秘少女",
		Text = "雪球、木炭！过来！",
	},
	[10012605] = {
		ID = 10012605,
		Speaker = "我",
		Text = "看来是喜欢面包的好朋友！",
	},
	[10012606] = {
		ID = 10012606,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦只喜欢面包，不喜欢人类！",
	},
	[10012607] = {
		ID = 10012607,
		Text = "我拿出更多面包给伊尔瓦",
	},
	[10012608] = {
		ID = 10012608,
		Speaker = "我",
		Text = "不用客气！伊尔瓦？",
	},
	[10012609] = {
		ID = 10012609,
		Speaker = "伊尔瓦",
		Text = "嗷呜。",
	},
	[10012610] = {
		ID = 10012610,
		Speaker = "瑟蕾雅",
		Text = "她真的咬了！",
	},
	[10012611] = {
		ID = 10012611,
		Speaker = "黛莉亚",
		Text = "舰长先生，你还好吗！ ？",
	},
	[10012612] = {
		ID = 10012612,
		Speaker = "我",
		Text = "目前尊严受创比较严重。",
	},
	[10012613] = {
		ID = 10012613,
		Speaker = "伊尔瓦",
		Text = "嗯……你吃起来像鸡肉。",
	},
	[10012614] = {
		ID = 10012614,
		Speaker = "秋比",
		Text = "大玩偶变成鸡肉了！",
	},
	[10012615] = {
		ID = 10012615,
		Speaker = "伊尔瓦",
		Text = "从今天开始，你就是小公鸡。",
	},
	[10012616] = {
		ID = 10012616,
		Speaker = "我",
		Text = "我能拒绝这个名字吗？",
	},
	[10012618] = {
		ID = 10012618,
		Speaker = "黛莉亚",
		Text = "这个世界的命名制度真的需要整顿。",
	},
	[10012619] = {
		ID = 10012619,
		Speaker = "伊尔瓦",
		Text = "小公鸡，你胸口里有很吵的火。",
	},
	[10012620] = {
		ID = 10012620,
		Speaker = "我",
		Text = "妳感觉得到？",
	},
	[10012622] = {
		ID = 10012622,
		Speaker = "瑟蕾雅",
		Text = "妳到底是谁？",
	},
	[10012624] = {
		ID = 10012624,
		Speaker = "黛莉亚",
		Text = "妈妈？这两只看起来像博美。",
	},
	[10012625] = {
		ID = 10012625,
		Speaker = "伊尔瓦",
		Text = "现在是小毛球，以后会把太阳和月亮一口吞掉。",
	},
	[10012626] = {
		ID = 10012626,
		Speaker = "秋比",
		Text = "好厉害！秋比也想养会吃天体的狗狗！",
	},
	[10012627] = {
		ID = 10012627,
		Speaker = "我",
		Text = "居然把世界末日当宠物才艺！",
	},
	[10012629] = {
		ID = 10012629,
		Speaker = "伊尔瓦",
		Text = "吞掉太阳和月亮，不是为了让世界死掉。",
	},
	[10012630] = {
		ID = 10012630,
		Speaker = "伊尔瓦",
		Text = "是为了让旧世界睡着，让新的早晨重新出生。",
	},
	[10012631] = {
		ID = 10012631,
		Speaker = "黛莉亚",
		Text = "所以芬布尔之冬原本是重启，不是毁灭。",
	},
	[10012633] = {
		ID = 10012633,
		Speaker = "伊尔瓦",
		Text = "我想吃这里的太阳，但我找不到！",
	},
	[10012634] = {
		ID = 10012634,
		Speaker = "我",
		Text = "找不到？",
	},
	[10012635] = {
		ID = 10012635,
		Speaker = "伊尔瓦",
		Text = "是冰雪女王！",
	},
	[10012636] = {
		ID = 10012636,
		Speaker = "伊尔瓦",
		Text = "她把该结束的冬天拖得太长，把该醒来的东西关在雪里。",
	},
	[10012637] = {
		ID = 10012637,
		Text = "伊尔瓦又在我身上嗅了嗅。",
	},
	[10012638] = {
		ID = 10012638,
		Speaker = "伊尔瓦",
		Text = "我喜欢你的味道！很像会在狼肚子里唱歌的人！",
	},
	[10012639] = {
		ID = 10012639,
		Speaker = "我",
		Text = "谢谢你伊尔瓦，但妳知道这位冰雪女王在哪里吗？",
	},
	[10012640] = {
		ID = 10012640,
		Speaker = "伊尔瓦",
		Text = "冰雪女王？那是人类替哭太久的妖精取的漂亮名字。",
	},
	[10012641] = {
		ID = 10012641,
		Speaker = "我",
		Text = "妖精？",
	},
	[10012643] = {
		ID = 10012643,
		Speaker = "黛莉亚",
		Text = "她是不是故意想误导我们？",
	},
	[10012647] = {
		ID = 10012647,
		Speaker = "伊尔瓦",
		Text = "吵死了！伊尔瓦不说谎！你们人类才会说谎！",
	},
	[10012648] = {
		ID = 10012648,
		Speaker = "伊尔瓦",
		Text = "我如果吃了，早就离开这颗星球了！",
	},
	[10012649] = {
		ID = 10012649,
		Speaker = "伊尔瓦",
		Text = "就是没吃到！我才一直待在这里！",
	},
	[10012650] = {
		ID = 10012650,
		Speaker = "瑟蕾雅",
		Text = "所以真的是冰雪女王？",
	},
	[10012651] = {
		ID = 10012651,
		Speaker = "我",
		Text = "抱歉，需要一点介绍，这个女王是谁？",
	},
	[10012652] = {
		ID = 10012652,
		Speaker = "瑟蕾雅",
		Text = "她和这场冬天差不多时间出现",
	},
	[10012653] = {
		ID = 10012653,
		Speaker = "瑟蕾雅",
		Text = "她向大家宣告：「凡宣誓加入国度者，必获得永生」",
	},
	[10012654] = {
		ID = 10012654,
		Speaker = "瑟蕾雅",
		Text = "没有人清楚她的来历",
	},
	[10012655] = {
		ID = 10012655,
		Speaker = "瑟蕾雅",
		Text = "但我们都猜测是因为永冬助长了她的魔力",
	},
	[10012657] = {
		ID = 10012657,
		Speaker = "伊尔瓦",
		Text = "她会让人在寒冷中看见自己最想要的东西。",
	},
	[10012658] = {
		ID = 10012658,
		Speaker = "伊尔瓦",
		Text = "伊尔瓦不敢靠近她！",
	},
	[10012659] = {
		ID = 10012659,
		Speaker = "我",
		Text = "那你能带我们去找冰雪女王吗？",
	},
	[10012660] = {
		ID = 10012660,
		Text = "（听起来冰雪女王才是冰封魔法的源头？）",
	},
	[10012661] = {
		ID = 10012661,
		Speaker = "伊尔瓦",
		Text = "小公鸡，想去找冰雪女王，就给我面包吃！",
	},
	[10012663] = {
		ID = 10012663,
		Speaker = "瑟蕾雅",
		Text = "跟我们回希望之丘吧，那里有很多！",
	},
	[10012664] = {
		ID = 10012664,
		Text = "伊尔瓦吹了一声口哨，雪球与木炭化作两道黑白影子，朝暴雪深处奔去。",
	},
	[10012666] = {
		ID = 10012666,
		Text = "伊尔瓦带着众人穿出森林",
	},
	[10012667] = {
		ID = 10012667,
	},
	[10012668] = {
		ID = 10012668,
	},
	[10012669] = {
		ID = 10012669,
		Speaker = "伊尔瓦",
		Text = "到这里就安全了。",
	},
	[10012670] = {
		ID = 10012670,
		Text = "突然教堂钟声传来，声音不同以往",
	},
	[10012672] = {
		ID = 10012672,
	},
	[10012673] = {
		ID = 10012673,
	},
	[10012674] = {
		ID = 10012674,
		Text = "当众人赶回希望之丘时，西西雅的房间只剩下未干的墨水与一页被撕下的日记。",
	},
	[10012675] = {
		ID = 10012675,
		Speaker = "瑟蕾雅",
		Text = "西西……？",
	},
	[10012677] = {
		ID = 10012677,
	},
	[10012678] = {
		ID = 10012678,
	},
	[10012679] = {
		ID = 10012679,
		Text = "希望之丘的夜晚，本来应该有灯、有汤、有孩子们压低声音的笑。",
	},
	[10012680] = {
		ID = 10012680,
		Text = "但今晚，西西雅的房间只剩下半干的墨水与被风吹动的窗帘。",
	},
	[10012681] = {
		ID = 10012681,
		Speaker = "瑟蕾雅",
		Text = "西西……？",
	},
	[10012683] = {
		ID = 10012683,
		Speaker = "黛莉亚",
		Text = "窗户是从里面打开的，没有强行破坏。",
	},
	[10012684] = {
		ID = 10012684,
		Speaker = "瑟蕾雅",
		Text = "所以……她是自己走出去的？",
	},
	[10012685] = {
		ID = 10012685,
		Speaker = "我",
		Text = "至少表面上是。",
	},
	[10012687] = {
		ID = 10012687,
		Speaker = "艾蕾娜",
		Text = "灯火在窗边停过。",
	},
	[10012688] = {
		ID = 10012688,
		Speaker = "我",
		Text = "妳看得见？",
	},
	[10012690] = {
		ID = 10012690,
		Speaker = "黛莉亚",
		Text = "外面有脚印，很细，像是她的。",
	},
	[10012691] = {
		ID = 10012691,
		Speaker = "瑟蕾雅",
		Text = "我去追她！",
	},
	[10012692] = {
		ID = 10012692,
		Speaker = "我",
		Text = "等一下。",
	},
	[10012693] = {
		ID = 10012693,
		Speaker = "瑟蕾雅",
		Text = "不能等！西西的身体撑不住暴雪！",
	},
	[10012695] = {
		ID = 10012695,
		Speaker = "瑟蕾雅",
		Text = "可是我又没有守住她。",
	},
	[10012696] = {
		ID = 10012696,
		Speaker = "我",
		Text = "这不是妳的错。",
	},
	[10012698] = {
		ID = 10012698,
		Speaker = "我",
		Text = "不用担心，有我在。",
	},
	[10012699] = {
		ID = 10012699,
		Speaker = "我",
		Text = "忘了吗？我可以是你用掉愿望找来的人呢！",
	},
	[10012701] = {
		ID = 10012701,
		Speaker = "艾蕾娜",
		Text = "这里还有一小块没烧完的纸。",
	},
	[10012702] = {
		ID = 10012702,
		Speaker = "黛莉亚",
		Text = "上面有字，但被火烧掉一半。",
	},
	[10012703] = {
		ID = 10012703,
		Speaker = "我",
		Text = "「如果勒瓦杜兰记得我的愿望……」",
	},
	[10012704] = {
		ID = 10012704,
		Speaker = "瑟蕾雅",
		Text = "她？是谁？",
	},
	[10012706] = {
		ID = 10012706,
		Speaker = "艾蕾娜",
		Text = "她就是冰雪女王。",
	},
	[10012707] = {
		ID = 10012707,
		Speaker = "艾蕾娜",
		Text = "但我不知道为什么，灯不想追她。",
	},
	[10012708] = {
		ID = 10012708,
		Speaker = "瑟蕾雅",
		Text = "为什么？",
	},
	[10012709] = {
		ID = 10012709,
		Speaker = "艾蕾娜",
		Text = "因为灯害怕到达那里。",
	},
	[10012710] = {
		ID = 10012710,
		Speaker = "黛莉亚",
		Text = "一盏灯会害怕，这已经不是普通魔法道具了吧。",
	},
	[10012713] = {
		ID = 10012713,
		Speaker = "我",
		Text = "艾蕾娜，妳不只是灯架。",
	},
	[10012714] = {
		ID = 10012714,
		Speaker = "艾蕾娜",
		Text = "灯架？",
	},
	[10012715] = {
		ID = 10012715,
		Speaker = "艾蕾娜",
		Text = "我不晓得你的意思！",
	},
	[10012716] = {
		ID = 10012716,
		Speaker = "瑟蕾雅",
		Text = "这本笔记后面还有西西的字。",
	},
	[10012718] = {
		ID = 10012718,
		Speaker = "瑟蕾雅",
		Text = "这种时候还要骂我……",
	},
	[10012720] = {
		ID = 10012720,
		Speaker = "西西雅的笔记",
		Text = "「如果我猜对，不是芬布尔之冬夺走春天的。」",
	},
	[10012721] = {
		ID = 10012721,
		Speaker = "秋比",
		Text = "那春天是谁弄丢的？",
	},
	[10012722] = {
		ID = 10012722,
		Speaker = "我",
		Text = "也许是愿望。",
	},
	[10012723] = {
		ID = 10012723,
		Speaker = "瑟蕾雅",
		Text = "愿望会弄丢春天吗？",
	},
	[10012725] = {
		ID = 10012725,
		Speaker = "瑟蕾雅",
		Text = "你说得像亲眼见过。",
	},
	[10012726] = {
		ID = 10012726,
		Speaker = "我",
		Text = "活得久的人，难免看过几场不太体面的奇迹。",
	},
	[10012728] = {
		ID = 10012728,
		Speaker = "瑟蕾雅",
		Text = "笨蛋……妳明明知道我一定会去。",
	},
	[10012730] = {
		ID = 10012730,
		Speaker = "伊尔瓦",
		Text = "冰雪女王就在那里！",
	},
	[10012731] = {
		ID = 10012731,
		Speaker = "艾蕾娜",
		Text = "旧路没有灯。",
	},
	[10012732] = {
		ID = 10012732,
		Speaker = "我",
		Text = "那就带上妳。",
	},
	[10012736] = {
		ID = 10012736,
		Speaker = "我",
		Text = "因为她想在妳替她承担以前，先替妳挡一次。",
	},
	[10012737] = {
		ID = 10012737,
		Speaker = "瑟蕾雅",
		Text = "我不想再让她一个人挡了。",
	},
	[10012741] = {
		ID = 10012741,
		Speaker = "我",
		Text = "说得好。",
	},
	[10012743] = {
		ID = 10012743,
	},
	[10012744] = {
		ID = 10012744,
	},
	[10012745] = {
		ID = 10012745,
		Text = "希望之丘的灯一盏盏亮起，像在替离开的人记住回家的方向。",
	},
	[10012746] = {
		ID = 10012746,
		Text = "而在村外，西西雅细小的脚印，正一路通往没有灯的雪之深处。",
	},
	[10012747] = {
		ID = 10012747,
	},
	[10012748] = {
		ID = 10012748,
	},
	[10012749] = {
		ID = 10012749,
		Text = "希望之丘的灯还亮着，但村外的雪路已经吞没了西西雅最后的脚印。",
	},
	[10012750] = {
		ID = 10012750,
		Speaker = "瑟蕾雅",
		Text = "西西的脚印到这里就变淡了。",
	},
	[10012752] = {
		ID = 10012752,
		Speaker = "伊尔瓦",
		Text = "有东西在掩盖她的足迹。",
	},
	[10012753] = {
		ID = 10012753,
		Speaker = "我",
		Text = "还好有你在",
	},
	[10012754] = {
		ID = 10012754,
		Speaker = "瑟蕾雅",
		Text = "艾蕾娜，拜托妳了。",
	},
	[10012756] = {
		ID = 10012756,
		Speaker = "我",
		Text = "不只是妳会做的事，是只有妳能做的事。",
	},
	[10012757] = {
		ID = 10012757,
		Speaker = "艾蕾娜",
		Text = "这两句，有差别吗？",
	},
	[10012759] = {
		ID = 10012759,
		Speaker = "瑟蕾雅",
		Text = "村民们来了。",
	},
	[10012760] = {
		ID = 10012760,
		Speaker = "旁白",
		Text = "希望之丘的居民聚在灯下，孩子、雪人、积木小人，都抱着小小的包裹。",
	},
	[10012761] = {
		ID = 10012761,
		Speaker = "村民",
		Text = "圣女大人，请带上这些干粮。",
	},
	[10012762] = {
		ID = 10012762,
		Speaker = "孩子",
		Text = "西西雅姐姐会回来吗？",
	},
	[10012764] = {
		ID = 10012764,
		Speaker = "孩子",
		Text = "妳也会回来吗？",
	},
	[10012766] = {
		ID = 10012766,
		Speaker = "我",
		Text = "说得很好。",
	},
	[10012767] = {
		ID = 10012767,
		Speaker = "瑟蕾雅",
		Text = "因为有人教我，圣女也可以任性。",
	},
	[10012769] = {
		ID = 10012769,
		Text = "一行人离开希望之丘，身后的灯火越来越小，像被雪握在掌心的星星。",
	},
	[10012770] = {
		ID = 10012770,
		Speaker = "瑟蕾雅",
		Text = "从这里看，希望之丘好小。",
	},
	[10012772] = {
		ID = 10012772,
		Speaker = "艾蕾娜",
		Text = "小小的火苗，一吹就灭了。",
	},
	[10012773] = {
		ID = 10012773,
		Speaker = "我",
		Text = "但小火苗，也最容易被手护住。",
	},
	[10012774] = {
		ID = 10012774,
		Speaker = "艾蕾娜",
		Text = "你很会说话。",
	},
	[10012775] = {
		ID = 10012775,
		Speaker = "我",
		Text = "只是人家常常不信我。",
	},
	[10012776] = {
		ID = 10012776,
		Speaker = "我",
		Text = "说我通常像在拐人私奔。",
	},
	[10012778] = {
		ID = 10012778,
		Speaker = "伊尔瓦",
		Text = "私奔是什么？带面包逃跑吗？",
	},
	[10012779] = {
		ID = 10012779,
		Speaker = "瑟蕾雅",
		Text = "某种意义上很接近。",
	},
	[10012780] = {
		ID = 10012780,
		Speaker = "伊尔瓦",
		Text = "我喜欢人类的面包。",
	},
	[10012782] = {
		ID = 10012782,
		Text = "雪路越往北，越不像道路，而像一条被白色巨兽吞进肚子的舌头。",
	},
	[10012784] = {
		ID = 10012784,
		Speaker = "我",
		Text = "旧雪道旁边为什么画了一个骷髅？",
	},
	[10012785] = {
		ID = 10012785,
		Speaker = "瑟蕾雅",
		Text = "可能是古代警告标志。",
	},
	[10012786] = {
		ID = 10012786,
		Speaker = "我",
		Text = "也可能是古代观光推荐。",
	},
	[10012787] = {
		ID = 10012787,
		Text = "众人继续往前走",
	},
	[10012788] = {
		ID = 10012788,
		Speaker = "伊尔瓦",
		Text = "雪堆里埋着好多人",
	},
	[10012789] = {
		ID = 10012789,
		Speaker = "艾蕾娜",
		Text = "应该就是那些宣誓加入她国度的人吧？",
	},
	[10012790] = {
		ID = 10012790,
		Speaker = "伊尔瓦",
		Text = "埋在好深的雪里，应该站了很久吧？",
	},
	[10012791] = {
		ID = 10012791,
		Text = "艾蕾娜的灯光忽然变亮，本来冰封不动的士兵突然看了过来",
	},
	[10012792] = {
		ID = 10012792,
		Speaker = "艾蕾娜",
		Text = "它们……在看我。",
	},
	[10012793] = {
		ID = 10012793,
		Speaker = "积木士兵",
		Text = "灯……女王的……灯……",
	},
	[10012794] = {
		ID = 10012794,
		Speaker = "我",
		Text = "它们认得妳。",
	},
	[10012795] = {
		ID = 10012795,
		Speaker = "艾蕾娜",
		Text = "我不认得它们。",
	},
	[10012796] = {
		ID = 10012796,
		Speaker = "积木士兵",
		Text = "不要……靠近……王城……",
	},
	[10012797] = {
		ID = 10012797,
		Speaker = "瑟蕾雅",
		Text = "它们是在警告我们？",
	},
	[10012798] = {
		ID = 10012798,
		Speaker = "我",
		Text = "或是在执行已经坏掉的命令。",
	},
	[10012799] = {
		ID = 10012799,
		Speaker = "我",
		Text = "艾蕾娜，把灯举高。",
	},
	[10012800] = {
		ID = 10012800,
		Speaker = "艾蕾娜",
		Text = "嗯。",
	},
	[10012801] = {
		ID = 10012801,
		Text = "灯光照上积木士兵的胸口，黑雪一点一点融化，露出刻着类似愿望妖精的徽记。",
	},
	[10012802] = {
		ID = 10012802,
		Speaker = "我",
		Text = "这有点像愿望妖精的徽记，但多了一些雪花的纹路。",
	},
	[10012803] = {
		ID = 10012803,
		Speaker = "我",
		Text = "许愿妖精，冰雪女王……线终于接起来了。",
	},
	[10012804] = {
		ID = 10012804,
		Text = "积雪持续融化，裂谷后方出现一条向下延伸的冰阶。",
	},
	[10012805] = {
		ID = 10012805,
		Speaker = "瑟蕾雅",
		Text = "西西就在下面。",
	},
	[10012806] = {
		ID = 10012806,
		Speaker = "我",
		Text = "那就下去。",
	},
	[10012807] = {
		ID = 10012807,
		Speaker = "艾蕾娜",
		Text = "从这里开始，就是雪之深处。",
	},
	[10012808] = {
		ID = 10012808,
		Text = "众人踏上冰阶时，希望之丘的灯火已经看不见了。",
	},
	[10012809] = {
		ID = 10012809,
		Text = "只有艾蕾娜手中的灯，还在没有星星的雪下，替他们记住前方。",
	},
	[10012810] = {
		ID = 10012810,
		Speaker = "我",
		Text = "那就一起走。",
	},
	[10012811] = {
		ID = 10012811,
		Text = "我牵着瑟蕾雅，她轻轻回握你的手。",
	},
	[10012812] = {
		ID = 10012812,
		Speaker = "瑟蕾雅",
		Text = "谢谢您。",
	},
	[10012813] = {
		ID = 10012813,
		Text = "在冰封的王城深处。",
	},
	[10012814] = {
		ID = 10012814,
		Text = "过去的记忆，正一点一滴苏醒。",
	},
	[10012815] = {
		ID = 10012815,
		Text = "而愿望所隐藏的代价。",
	},
	[10012816] = {
		ID = 10012816,
		Text = "也开始在众人面前，露出真正的模样。",
	},
	[10012817] = {
		ID = 10012817,
	},
	[10012818] = {
		ID = 10012818,
	},
	[10012819] = {
		ID = 10012819,
		Text = "冰阶一路向下，像通往雪国心脏的一根白色骨刺。",
	},
	[10012820] = {
		ID = 10012820,
		Speaker = "伊尔瓦",
		Text = "不喜欢这条楼梯，森林没有这种路。",
	},
	[10012821] = {
		ID = 10012821,
		Speaker = "瑟蕾雅",
		Text = "冰层下面有金属导轨。",
	},
	[10012822] = {
		ID = 10012822,
		Speaker = "瑟蕾雅",
		Text = "导轨？这里以前有车吗？",
	},
	[10012823] = {
		ID = 10012823,
		Speaker = "我",
		Text = "不一定是车，也可能是运送魔力、灯火，或者……愿望的通道。",
	},
	[10012824] = {
		ID = 10012824,
		Speaker = "伊尔瓦",
		Text = "愿望也要搭车吗？",
	},
	[10012825] = {
		ID = 10012825,
		Speaker = "我",
		Text = "可能有些愿望太沉重了。",
	},
	[10012826] = {
		ID = 10012826,
		Speaker = "艾蕾娜",
		Text = "灯火变安静了。",
	},
	[10012827] = {
		ID = 10012827,
		Text = "冰阶尽头，是一座半埋在深雪下的巨大门扉。",
	},
	[10012828] = {
		ID = 10012828,
		Speaker = "我",
		Text = "找到了……古代遗迹的入口。",
	},
	[10012829] = {
		ID = 10012829,
		Speaker = "瑟蕾雅",
		Text = "这里有一样的雪花纹。",
	},
	[10012830] = {
		ID = 10012830,
		Speaker = "我",
		Text = "有雪花的羽翼。",
	},
	[10012831] = {
		ID = 10012831,
		Speaker = "瑟蕾雅",
		Text = "雪花代表冰雪，羽翼代表愿望妖精。",
	},
	[10012832] = {
		ID = 10012832,
		Speaker = "伊尔瓦",
		Text = "那合起来就是会飞的雪花？",
	},
	[10012833] = {
		ID = 10012833,
		Speaker = "我",
		Text = "妳的说法很粗糙，但没有错太远。",
	},
	[10012834] = {
		ID = 10012834,
		Speaker = "瑟蕾雅",
		Text = "艾蕾娜，妳不舒服吗？",
	},
	[10012836] = {
		ID = 10012836,
		Speaker = "我",
		Text = "那妳可以站在我旁边，不必站在最前面。",
	},
	[10012837] = {
		ID = 10012837,
		Speaker = "艾蕾娜",
		Text = "可是我应该引路。",
	},
	[10012838] = {
		ID = 10012838,
		Speaker = "我",
		Text = "引路的人，也可以有人陪她走。",
	},
	[10012839] = {
		ID = 10012839,
		Text = "门没有锁孔，但有三个凹槽，里面刻着古老的文字",
	},
	[10012840] = {
		ID = 10012840,
		Speaker = "瑟蕾雅",
		Text = "「失心者、执灯者、持愿者。」",
	},
	[10012841] = {
		ID = 10012841,
		Speaker = "我",
		Text = "用灯？",
	},
	[10012842] = {
		ID = 10012842,
		Speaker = "艾蕾娜",
		Text = "我试试看！",
	},
	[10012843] = {
		ID = 10012843,
		Text = "艾蕾娜将提灯靠近第一个凹槽，灯火拉成羽毛形状，轻轻落入门中。",
	},
	[10012844] = {
		ID = 10012844,
		Speaker = "艾蕾娜",
		Text = "它记得我。",
	},
	[10012845] = {
		ID = 10012845,
		Speaker = "我",
		Text = "这个呢？",
	},
	[10012846] = {
		ID = 10012846,
		Speaker = "瑟蕾雅",
		Text = "这个槽写着失心者……",
	},
	[10012847] = {
		ID = 10012847,
		Speaker = "瑟蕾雅",
		Text = "这个凹槽，和你有关吗？",
	},
	[10012848] = {
		ID = 10012848,
		Speaker = "我",
		Text = "这个槽的能量频率，跟飞船核心有微弱共鸣。",
	},
	[10012849] = {
		ID = 10012849,
		Speaker = "艾蕾娜",
		Text = "不是他的心脏。",
	},
	[10012850] = {
		ID = 10012850,
		Speaker = "众人",
	},
	[10012851] = {
		ID = 10012851,
		Speaker = "艾蕾娜",
		Text = "门要的不是心脏，是「曾经失去过心的人」的证明。",
	},
	[10012852] = {
		ID = 10012852,
		Speaker = "我",
		Text = "那我来试试看吧",
	},
	[10012853] = {
		ID = 10012853,
		Text = "我将手放在凹槽中，凹槽突然亮起，像心跳般微微跳动的光芒。",
	},
	[10012854] = {
		ID = 10012854,
		Text = "一阵低语从最后一个凹槽传出",
	},
	[10012855] = {
		ID = 10012855,
		Speaker = "古代门扉",
		Text = "「若欲进入，请交出一个不愿承认的愿望。」",
	},
	[10012856] = {
		ID = 10012856,
		Speaker = "我",
		Text = "不愿承认的愿望……这种要求太抽象了。",
	},
	[10012857] = {
		ID = 10012857,
		Speaker = "伊尔瓦",
		Text = "我有不愿承认的愿望！",
	},
	[10012858] = {
		ID = 10012858,
		Speaker = "瑟蕾雅",
		Text = "妳先不要乱交。",
	},
	[10012859] = {
		ID = 10012859,
		Speaker = "伊尔瓦",
		Text = "比起太阳，伊尔瓦现在更喜欢吃人类的面包！",
	},
	[10012861] = {
		ID = 10012861,
		Speaker = "我",
		Text = "很可爱，但门嫌妳太诚实了。",
	},
	[10012862] = {
		ID = 10012862,
		Speaker = "瑟蕾雅",
		Text = "我来。",
	},
	[10012863] = {
		ID = 10012863,
		Speaker = "我",
		Text = "瑟蕾雅？",
	},
	[10012866] = {
		ID = 10012866,
		Speaker = "我",
		Text = "还不够。",
	},
	[10012867] = {
		ID = 10012867,
		Speaker = "艾蕾娜",
		Text = "因为她承认了害怕，却还没承认愿望。",
	},
	[10012868] = {
		ID = 10012868,
		Speaker = "瑟蕾雅",
		Text = "那我再尝试一次",
	},
	[10012870] = {
		ID = 10012870,
		Text = "第三凹槽完全亮起，门扉缓缓向内开启。",
	},
	[10012871] = {
		ID = 10012871,
		Speaker = "古代门扉",
		Text = "「愿望确认。请进入被雪保存的真相。」",
	},
	[10012872] = {
		ID = 10012872,
		Speaker = "我",
		Text = "你刚刚想的是什么啊？",
	},
	[10012873] = {
		ID = 10012873,
		Speaker = "瑟蕾雅",
		Text = "就是不好意思说，才没讲出来嘛！",
	},
	[10012874] = {
		ID = 10012874,
		Speaker = "我",
		Text = "那等这一切结束之后，我再问你吧！",
	},
	[10012875] = {
		ID = 10012875,
		Text = "众人踏入古代遗迹，门在身后缓缓合上。",
	},
	[10012876] = {
		ID = 10012876,
		Text = "黑暗深处，一排排熄灭的灯，像无数没有实现的愿望，静静等待他们经过。",
	},
	[10012877] = {
		ID = 10012877,
	},
	[10012878] = {
		ID = 10012878,
	},
	[10012879] = {
		ID = 10012879,
		Text = "遗迹深处的记录室里，冰壁像一页页竖立的书。",
	},
	[10012880] = {
		ID = 10012880,
		Text = "无数晶板埋藏在冰层之中，静静发出微弱的光。",
	},
	[10012881] = {
		ID = 10012881,
		Speaker = "瑟蕾雅",
		Text = "这里是我看过最浪漫的资料库。",
	},
	[10012882] = {
		ID = 10012882,
		Speaker = "伊尔瓦",
		Text = "书在发光。",
	},
	[10012883] = {
		ID = 10012883,
		Speaker = "我",
		Text = "代表它们很期待被阅读。",
	},
	[10012884] = {
		ID = 10012884,
		Speaker = "瑟蕾雅",
		Text = "西西……妳果然来过这里吗？",
	},
	[10012885] = {
		ID = 10012885,
		Speaker = "艾蕾娜",
		Text = "这边有名字。",
	},
	[10012886] = {
		ID = 10012886,
		Text = "在灯火照耀下，冰壁上浮现一行古老文字。",
	},
	[10012887] = {
		ID = 10012887,
		Speaker = "艾蕾娜",
		Text = "勒瓦杜兰。",
	},
	[10012888] = {
		ID = 10012888,
		Speaker = "瑟蕾雅",
		Text = "冰雪女王。",
	},
	[10012889] = {
		ID = 10012889,
		Speaker = "我",
		Text = "每个童话，在很久以前都只是某个人的真实。",
	},
	[10012890] = {
		ID = 10012890,
		Speaker = "我",
		Text = "这里不是神话记录。",
	},
	[10012891] = {
		ID = 10012891,
		Speaker = "艾蕾娜",
		Text = "你发现什么？",
	},
	[10012893] = {
		ID = 10012893,
		Speaker = "瑟蕾雅",
		Text = "许愿妖精……",
	},
	[10012894] = {
		ID = 10012894,
		Speaker = "我",
		Text = "「个体名称：勒瓦杜兰。」",
	},
	[10012895] = {
		ID = 10012895,
		Speaker = "我",
		Text = "「分类：许愿妖精。」",
	},
	[10012896] = {
		ID = 10012896,
		Speaker = "我",
		Text = "所以冰雪女王，原本只是普通的许愿妖精。",
	},
	[10012897] = {
		ID = 10012897,
		Speaker = "我",
		Text = "被感谢的人，与被恐惧的人，有时候本来就是同一个。",
	},
	[10012898] = {
		ID = 10012898,
		Speaker = "瑟蕾雅",
		Text = "后面有一段重要记录。",
	},
	[10012899] = {
		ID = 10012899,
		Speaker = "瑟蕾雅",
		Text = "「为完成指定愿望，接触太阳媒介。」",
	},
	[10012900] = {
		ID = 10012900,
		Speaker = "瑟蕾雅",
		Text = "太阳媒介……",
	},
	[10012901] = {
		ID = 10012901,
		Speaker = "艾蕾娜",
		Text = "她碰触了太阳。",
	},
	[10012902] = {
		ID = 10012902,
		Speaker = "我",
		Text = "不只是碰触。",
	},
	[10012903] = {
		ID = 10012903,
		Speaker = "我",
		Text = "她把太阳带走了。",
	},
	[10012904] = {
		ID = 10012904,
		Text = "记录室陷入短暂沉默。",
	},
	[10012905] = {
		ID = 10012905,
		Speaker = "伊尔瓦",
		Text = "她把春天抱走了。",
	},
	[10012906] = {
		ID = 10012906,
		Speaker = "瑟蕾雅",
		Text = "所以……永夜和永冬，都是因为她想实现某个愿望。",
	},
	[10012907] = {
		ID = 10012907,
