		Speaker = "瑟蕾雅",
		Text = "我从来不希望有人替我们承担到这种地步。",
	},
	[10013188] = {
		ID = 10013188,
		Speaker = "勒瓦杜兰",
		Text = "但这是我唯一能做到的事。",
	},
	[10013189] = {
		ID = 10013189,
		Speaker = "艾蕾娜",
		Text = "不。",
	},
	[10013190] = {
		ID = 10013190,
		Speaker = "艾蕾娜",
		Text = "妳还做了一件事。",
	},
	[10013191] = {
		ID = 10013191,
		Speaker = "艾蕾娜",
		Text = "妳把自己的温柔留了下来。",
	},
	[10013192] = {
		ID = 10013192,
		Text = "勒瓦杜兰看着艾蕾娜，像是在凝视一面失落已久的镜子。",
	},
	[10013193] = {
		ID = 10013193,
		Speaker = "勒瓦杜兰",
		Text = "我的灯火。",
	},
	[10013194] = {
		ID = 10013194,
		Speaker = "艾蕾娜",
		Text = "我一直在替妳照路。",
	},
	[10013195] = {
		ID = 10013195,
		Speaker = "艾蕾娜",
		Text = "现在，轮到妳回来了。",
	},
	[10013196] = {
		ID = 10013196,
		Text = "王座周围的风雪剧烈翻涌。",
	},
	[10013197] = {
		ID = 10013197,
		Speaker = "勒瓦杜兰",
		Text = "不可以。",
	},
	[10013198] = {
		ID = 10013198,
		Speaker = "勒瓦杜兰",
		Text = "如果春天回来，西西雅可能会死。",
	},
	[10013199] = {
		ID = 10013199,
		Speaker = "西西雅",
		Text = "那是我的人生。",
	},
	[10013200] = {
		ID = 10013200,
		Speaker = "西西雅",
		Text = "不该由妳替我决定季节。",
	},
	[10013201] = {
		ID = 10013201,
		Speaker = "勒瓦杜兰",
		Text = "可是我害怕。",
	},
	[10013202] = {
		ID = 10013202,
		Speaker = "勒瓦杜兰",
		Text = "我不想失去第一个把我当成朋友的人。",
	},
	[10013203] = {
		ID = 10013203,
		Speaker = "伊尔瓦",
		Text = "原来女王也会怕。",
	},
	[10013204] = {
		ID = 10013204,
		Speaker = "我",
		Text = "勒瓦杜兰。",
	},
	[10013205] = {
		ID = 10013205,
		Speaker = "勒瓦杜兰",
		Text = "人类，你又想说什么？",
	},
	[10013206] = {
		ID = 10013206,
		Speaker = "我",
		Text = "我想说，妳做得很好。",
	},
	[10013207] = {
		ID = 10013207,
		Speaker = "勒瓦杜兰",
		Text = "……什么？",
	},
	[10013208] = {
		ID = 10013208,
		Speaker = "我",
		Text = "妳为了一句小小的愿望，对抗太阳，对抗时间，甚至对抗世界。",
	},
	[10013209] = {
		ID = 10013209,
		Speaker = "我",
		Text = "能做到这种地步的人，值得被尊敬。",
	},
	[10013210] = {
		ID = 10013210,
		Speaker = "勒瓦杜兰",
		Text = "你不责怪我？",
	},
	[10013211] = {
		ID = 10013211,
		Speaker = "我",
		Text = "我只觉得，妳已经一个人撑得太久了。",
	},
	[10013212] = {
		ID = 10013212,
		Speaker = "我",
		Text = "而现在，妳不必再独自守着冬天。",
	},
	[10013213] = {
		ID = 10013213,
		Speaker = "瑟蕾雅",
		Text = "我们都在这里。",
	},
	[10013214] = {
		ID = 10013214,
		Speaker = "西西雅",
		Text = "而且这一次，我不会再把责任丢给妳。",
	},
	[10013215] = {
		ID = 10013215,
		Speaker = "艾蕾娜",
		Text = "妳的光，从来没有消失。",
	},
	[10013216] = {
		ID = 10013216,
		Text = "勒瓦杜兰闭上眼。",
	},
	[10013217] = {
		ID = 10013217,
		Text = "一滴透明的泪水，从她冰雪般的面容上落下。",
	},
	[10013218] = {
		ID = 10013218,
		Speaker = "勒瓦杜兰",
		Text = "……如果我放手。",
	},
	[10013219] = {
		ID = 10013219,
		Speaker = "勒瓦杜兰",
		Text = "春天真的还会回来吗？",
	},
	[10013220] = {
		ID = 10013220,
		Speaker = "我",
		Text = "春天本来就一直在路上。",
	},
	[10013221] = {
		ID = 10013221,
		Speaker = "我",
		Text = "只是它也在等妳愿意相信。",
	},
	[10013222] = {
		ID = 10013222,
		Text = "王都上空，被冰封的太阳微微震动。",
	},
	[10013223] = {
		ID = 10013223,
		Text = "整座冰雪王国开始发出低沉的共鸣。",
	},
	[10013224] = {
		ID = 10013224,
		Speaker = "勒瓦杜兰",
		Text = "那么……",
	},
	[10013225] = {
		ID = 10013225,
		Speaker = "勒瓦杜兰",
		Text = "就让我看看，春天是否还愿意原谅我。",
	},
	[10013226] = {
		ID = 10013226,
	},
	[10013227] = {
		ID = 10013227,
	},
	[10013228] = {
		ID = 10013228,
		Speaker = "勒瓦杜兰",
		Text = "解除永冬的方法，其实一直都很简单。",
	},
	[10013229] = {
		ID = 10013229,
		Speaker = "勒瓦杜兰",
		Text = "只要把太阳送回天空。",
	},
	[10013230] = {
		ID = 10013230,
		Speaker = "瑟蕾雅",
		Text = "那……为什么妳一直没有这么做？",
	},
	[10013231] = {
		ID = 10013231,
		Speaker = "勒瓦杜兰",
		Text = "因为太阳早已不再完整。",
	},
	[10013232] = {
		ID = 10013232,
		Speaker = "艾蕾娜",
		Text = "……",
	},
	[10013233] = {
		ID = 10013233,
		Speaker = "勒瓦杜兰",
		Text = "当年我吞下太阳之后，无法承受那份力量。",
	},
	[10013234] = {
		ID = 10013234,
		Speaker = "勒瓦杜兰",
		Text = "于是我将自己一分为二。",
	},
	[10013235] = {
		ID = 10013235,
		Speaker = "勒瓦杜兰",
		Text = "妳带走了我最温暖的部分，也带走了整个太阳。",
	},
	[10013236] = {
		ID = 10013236,
		Speaker = "艾蕾娜",
		Text = "所以……我一直是靠着太阳的力量存在着。",
	},
	[10013237] = {
		ID = 10013237,
		Speaker = "瑟蕾雅",
		Text = "如果太阳回归，艾蕾娜就会失去存在基础？",
