	[10013240] = {
		ID = 10013240,
		Speaker = "西西雅",
		Text = "这就是我最害怕的事。",
	},
	[10013241] = {
		ID = 10013241,
		Speaker = "艾蕾娜",
		Text = "如果这能让春天回来，我愿意。",
	},
	[10013242] = {
		ID = 10013242,
		Speaker = "瑟蕾雅",
		Text = "不要说得这么轻松……",
	},
	[10013243] = {
		ID = 10013243,
		Speaker = "瑟蕾雅",
		Text = "古代纪录里只有「重新融合」这个解法。",
