	[10013244] = {
		ID = 10013244,
		Speaker = "瑟蕾雅",
		Text = "也就是艾蕾娜的自我将不再独立。",
	},
	[10013245] = {
		ID = 10013245,
		Speaker = "我",
		Text = "……",
	},
	[10013246] = {
		ID = 10013246,
		Speaker = "勒瓦杜兰",
		Text = "人类，你似乎有不同的想法。",
	},
	[10013247] = {
		ID = 10013247,
		Speaker = "我",
		Text = "我只是觉得，童话最大的缺点，就是作者太喜欢二选一。",
	},
	[10013248] = {
		ID = 10013248,
		Speaker = "我",
		Text = "妳的存在，需要能量。",
