	[10013305] = {
		ID = 10013305,
	},
	[10013306] = {
		ID = 10013306,
	},
	[10013307] = {
		ID = 10013307,
		Text = "春天回来后的第三天，希望之丘的雪已退到山坡与屋檐阴影之中。",
	},
	[10013308] = {
