	[10013318] = {
		ID = 10013318,
		Speaker = "瑟蕾雅",
		Text = "不、不是那个意思。",
	},
	[10013319] = {
		ID = 10013319,
		Speaker = "我",
		Text = "可惜，我还挺期待的。",
