	[10013326] = {
		ID = 10013326,
		Speaker = "瑟蕾雅",
		Text = "可是现在，它真的回来了。",
	},
	[10013327] = {
		ID = 10013327,
		Speaker = "我",
		Text = "因为有人从来没有放弃相信它。",
	},
	[10013328] = {
		ID = 10013328,
		Speaker = "瑟蕾雅",
		Text = "不。",
	},
	[10013329] = {
		ID = 10013329,
		Speaker = "瑟蕾雅",
		Text = "是因为你来了。",
	},
	[10013331] = {
		ID = 10013331,
		Speaker = "瑟蕾雅",
		Text = "我以前一直以为，圣女的工作就是让别人安心。",
	},
	[10013332] = {
		ID = 10013332,
		Speaker = "瑟蕾雅",
		Text = "所以我不能害怕，也不能软弱。",
	},
	[10013333] = {
		ID = 10013333,
		Speaker = "瑟蕾雅",
		Text = "可是在你面前，我好像可以不用那么努力。",
	},
	[10013334] = {
		ID = 10013334,
		Speaker = "我",
		Text = "那不是软弱。",
	},
	[10013335] = {
		ID = 10013335,
		Speaker = "我",
		Text = "那是信任。",
	},
	[10013336] = {
		ID = 10013336,
		Speaker = "瑟蕾雅",
		Text = "我知道。",
	},
	[10013337] = {
		ID = 10013337,
		Speaker = "瑟蕾雅",
		Text = "所以……我有话想告诉你。",
	},
	[10013338] = {
		ID = 10013338,
		Speaker = "我",
		Text = "我在听。",
	},
	[10013339] = {
		ID = 10013339,
		Speaker = "瑟蕾雅",
		Text = "我喜欢你。",
	},
	[10013340] = {
		ID = 10013340,
		Speaker = "瑟蕾雅",
		Text = "很喜欢，很喜欢。",
	},
	[10013341] = {
		ID = 10013341,
		Speaker = "瑟蕾雅",
		Text = "喜欢到有时候只是看到你站在那里，就觉得很安心。",
	},
	[10013342] = {
		ID = 10013342,
		Speaker = "瑟蕾雅",
		Text = "也喜欢到想到你总有一天会离开，就会觉得很难过。",
	},
	[10013343] = {
		ID = 10013343,
		Speaker = "我",
		Text = "……",
	},
	[10013344] = {
		ID = 10013344,
		Speaker = "瑟蕾雅",
		Text = "可是，我不是要把你留下来。",
	},
	[10013345] = {
		ID = 10013345,
		Speaker = "瑟蕾雅",
		Text = "我知道你属于天空，也属于很多很多还没抵达的地方。",
	},
	[10013346] = {
		ID = 10013346,
		Speaker = "瑟蕾雅",
		Text = "我喜欢的，就是这样的你。",
	},
	[10013347] = {
		ID = 10013347,
		Speaker = "瑟蕾雅",
		Text = "所以……",
	},
	[10013348] = {
		ID = 10013348,
		Speaker = "瑟蕾雅",
		Text = "我只希望你知道。",
	},
	[10013349] = {
		ID = 10013349,
		Speaker = "瑟蕾雅",
		Text = "不管你飞到多远的地方，这里都会有人等你。",
	},
	[10013350] = {
		ID = 10013350,
		Text = "这就是，少女不愿承认的愿望",
	},
	[10013351] = {
		ID = 10013351,
		Text = "那句话像一把温柔的钥匙，打开了他心中很久没有被触碰的门。",
	},
	[10013352] = {
		ID = 10013352,
		Speaker = "我",
		Text = "我活了很久。",
	},
	[10013353] = {
		ID = 10013353,
		Speaker = "我",
		Text = "久到习惯每次离开时，都不回头。",
	},
	[10013354] = {
		ID = 10013354,
		Speaker = "我",
		Text = "因为只要不回头，就不会发现自己其实有点寂寞。",
	},
	[10013355] = {
		ID = 10013355,
		Speaker = "瑟蕾雅",
		Text = "……",
	},
	[10013356] = {
		ID = 10013356,
		Speaker = "我",
		Text = "妳很危险，瑟蕾雅。",
	},
	[10013357] = {
		ID = 10013357,
		Speaker = "瑟蕾雅",
		Text = "危险？",
	},
	[10013358] = {
		ID = 10013358,
		Speaker = "我",
		Text = "因为妳让我第一次开始认真思考。",
	},
	[10013359] = {
		ID = 10013359,
		Speaker = "我",
		Text = "自由，是不是也包含想回到某个地方。",
	},
	[10013360] = {
		ID = 10013360,
		Speaker = "瑟蕾雅",
		Text = "……",
	},
	[10013361] = {
		ID = 10013361,
		Speaker = "我",
		Text = "我不能答应永远留下。",
	},
	[10013362] = {
		ID = 10013362,
		Speaker = "我",
		Text = "但我可以答应妳。",
	},
	[10013363] = {
		ID = 10013363,
		Speaker = "我",
		Text = "我一定会回来。",
	},
	[10013364] = {
		ID = 10013364,
		Speaker = "瑟蕾雅",
		Text = "……真的？",
	},
	[10013365] = {
		ID = 10013365,
		Speaker = "我",
		Text = "毕竟，我的心有一部分，已经被妳拿走了。",
	},
	[10013366] = {
		ID = 10013366,
		Speaker = "瑟蕾雅",
		Text = "你又说这种让人犯规的话……",
	},
	[10013367] = {
		ID = 10013367,
		Speaker = "我",
		Text = "所以，圣女小姐。",
	},
	[10013368] = {
		ID = 10013368,
		Speaker = "我",
		Text = "妳愿意和一个很少停下来的人更进一步吗？",
	},
	[10013369] = {
		ID = 10013369,
		Speaker = "瑟蕾雅",
		Text = "我愿意。",
	},
	[10013370] = {
		ID = 10013370,
		Text = "她扑进他的怀里，像终于等到春天的第一朵花。",
	},
	[10013371] = {
		ID = 10013371,
		Speaker = "我",
		Text = "小心一点。",
	},
	[10013372] = {
		ID = 10013372,
		Speaker = "我",
		Text = "我现在的心脏输出比平常低。",
	},
	[10013373] = {
		ID = 10013373,
		Speaker = "瑟蕾雅",
		Text = "那我会轻一点抱你。",
	},
	[10013374] = {
		ID = 10013374,
		Speaker = "我",
		Text = "不。",
	},
	[10013375] = {
		ID = 10013375,
		Speaker = "我",
		Text = "可以抱得再紧一点。",
	},
	[10013376] = {
		ID = 10013376,
		Text = "在融雪与花香之中，他低头吻住了她。",
	},
	[10013377] = {
		ID = 10013377,
		Speaker = "瑟蕾雅",
		Text = "……嗯。",
	},
	[10013378] = {
		ID = 10013378,
		Text = "那个吻很轻，却像春天本身一样，温柔而确定。",
	},
	[10013379] = {
		ID = 10013379,
		Speaker = "瑟蕾雅",
		Text = "我会等你。",
	},
	[10013380] = {
		ID = 10013380,
		Speaker = "我",
		Text = "那我就有了非回来不可的理由。",
	},
	[10013381] = {
		ID = 10013381,
		Text = "花园里的白花随风摇曳，像一场无声的祝福。",
	},
	[10013382] = {
		ID = 10013382,
		Text = "对旅人而言，自由从不是没有牵挂。",
	},
	[10013383] = {
		ID = 10013383,
		Text = "而是终于遇见了一个，让他甘愿回头的人。",
	},
	[10013384] = {
		ID = 10013384,
		Text = "对圣女而言，奇迹也不是把谁留下。",
	},
	[10013385] = {
		ID = 10013385,
		Text = "而是即使知道对方终将远行，仍相信他一定会回来。",
	},
	[10013386] = {
		ID = 10013386,
		Text = "于是，在春天重新降临的花园里，两颗孤单已久的心，终于找到了彼此。",
	},
	[10013387] = {
		ID = 10013387,
	},
	[10013388] = {
		ID = 10013388,
	},
	[10013389] = {
		ID = 10013389,
		Text = "又过了几天，希望之丘的雪已经退到山脉与森林的阴影里。",
	},
	[10013390] = {
		ID = 10013390,
		Text = "屋檐开始滴水，泥土重新露出气息，孩子们第一次在草地上奔跑。",
	},
	[10013391] = {
		ID = 10013391,
		Text = "春天像一位迟到太久的旅人，终于敲响了这个国家的门。",
	},
	[10013392] = {
		ID = 10013392,
		Speaker = "黛莉亚",
		Text = "推进器校准完成！",
	},
	[10013393] = {
		ID = 10013393,
		Speaker = "黛莉亚",
		Text = "飞船已经恢复到可以飞行的状态！",
	},
	[10013394] = {
		ID = 10013394,
		Speaker = "我",
		Text = "看来我的心脏还是蛮有力的！",
	},
	[10013395] = {
		ID = 10013395,
		Speaker = "伊丝娜",
		Text = "下次不要再把心脏当万用电池。",
	},
	[10013396] = {
		ID = 10013396,
		Speaker = "我",
		Text = "我会努力改进。",
	},
	[10013397] = {
		ID = 10013397,
		Speaker = "伊丝娜",
		Text = "本来要称赞你让冰雪女王帮我解冰封，",
	},
	[10013398] = {
		ID = 10013398,
		Speaker = "伊丝娜",
		Text = "但看到你这笑容就想打你！",
	},
	[10013399] = {
		ID = 10013399,
		Speaker = "艾蕾娜",
		Text = "你如果坏掉，瑟蕾雅会哭的。",
	},
	[10013400] = {
		ID = 10013400,
		Speaker = "我",
		Text = "妳最近越来越会说重点了。",
	},
	[10013401] = {
		ID = 10013401,
		Speaker = "艾蕾娜",
		Text = "我正在学习，什么叫做「自己」。",
	},
	[10013402] = {
		ID = 10013402,
		Text = "艾蕾娜胸前的光芒温柔而稳定。",
	},
	[10013403] = {
		ID = 10013403,
		Text = "一半是太阳，一半是来自飞船的心跳。",
	},
	[10013404] = {
		ID = 10013404,
		Speaker = "黛莉亚",
		Text = "从工程角度来说，这根本是史诗级的跨系统兼容。",
	},
	[10013405] = {
		ID = 10013405,
		Speaker = "我",
		Text = "如果用秋比的话来说，艾蕾娜现在是半个飞船。",
	},
	[10013406] = {
		ID = 10013406,
		Speaker = "艾蕾娜",
		Text = "那我需要停靠费吗？",
	},
	[10013407] = {
		ID = 10013407,
		Speaker = "伊丝娜",
		Text = "这个团队的常识正在持续崩坏。",
	},
	[10013408] = {
		ID = 10013408,
	},
	[10013409] = {
		ID = 10013409,
	},
	[10013410] = {
		ID = 10013410,
		Text = "希望之丘的居民陆续聚集在广场上。",
	},
	[10013411] = {
		ID = 10013411,
		Text = "雪人、积木小人、孩子们，都跟秋比玩成一块。",
	},
	[10013412] = {
		ID = 10013412,
		Speaker = "村民A",
		Text = "圣女大人！旅人先生！谢谢你们！",
	},
	[10013413] = {
		ID = 10013413,
		Speaker = "小孩A",
		Text = "大哥哥，下次还要从天上掉下来喔！",
	},
	[10013414] = {
		ID = 10013414,
		Speaker = "我",
		Text = "我会尽量用比较优雅的方式登场。",
	},
	[10013415] = {
		ID = 10013415,
		Speaker = "小孩B",
		Text = "约好了！",
	},
	[10013416] = {
		ID = 10013416,
		Text = "西西雅站在瑟蕾雅身旁，披着厚披肩，脸色仍有些苍白。",
	},
	[10013417] = {
		ID = 10013417,
		Speaker = "西西雅",
		Text = "医学史上，这大概是最荒谬的治疗案例。",
	},
	[10013418] = {
		ID = 10013418,
		Speaker = "我",
		Text = "妳气色好多了。",
	},
	[10013419] = {
		ID = 10013419,
		Speaker = "西西雅",
		Text = "我只是从「快死了」进步到「暂时不死」。",
	},
	[10013420] = {
		ID = 10013420,
		Speaker = "瑟蕾雅",
		Text = "西西……",
	},
	[10013421] = {
		ID = 10013421,
		Speaker = "西西雅",
		Text = "不过……谢谢你。",
	},
	[10013422] = {
		ID = 10013422,
		Speaker = "我",
		Text = "能听到妳道谢，这趟旅程已经值回票价。",
	},
	[10013424] = {
		ID = 10013424,
		Speaker = "伊尔瓦",
		Text = "小公鸡！不要忘记春天也会咬人喔！",
	},
	[10013425] = {
		ID = 10013425,
		Text = "伊尔瓦坐在树枝上，红斗篷在风中飞扬。",
	},
	[10013426] = {
		ID = 10013426,
		Speaker = "雪球",
		Text = "嗷！",
	},
	[10013427] = {
		ID = 10013427,
		Speaker = "木炭",
		Text = "嗷呜！",
	},
	[10013429] = {
		ID = 10013429,
		Speaker = "伊尔瓦",
		Text = "那要看那个星球的面包好不好吃啰？",
	},
	[10013430] = {
		ID = 10013430,
		Text = "广场上响起一阵笑声。",
	},
	[10013431] = {
		ID = 10013431,
	},
	[10013432] = {
		ID = 10013432,
	},
	[10013433] = {
		ID = 10013433,
		Speaker = "艾蕾娜",
		Text = "我不会和你们一起离开。",
	},
	[10013434] = {
		ID = 10013434,
		Speaker = "我",
		Text = "我知道。",
	},
	[10013435] = {
		ID = 10013435,
		Speaker = "艾蕾娜",
		Text = "以前，我只是灯。",
	},
	[10013436] = {
		ID = 10013436,
		Speaker = "艾蕾娜",
		Text = "现在，我想以艾蕾娜的身份活下去。",
	},
	[10013437] = {
		ID = 10013437,
		Speaker = "我",
		Text = "这是非常好的名字。",
	},
	[10013438] = {
		ID = 10013438,
		Speaker = "艾蕾娜",
		Text = "谢谢你，让我不再只是谁的一部分。",
	},
	[10013439] = {
		ID = 10013439,
		Speaker = "我",
		Text = "妳从一开始就是妳自己。",
	},
	[10013440] = {
		ID = 10013440,
		Text = "艾蕾娜轻轻抱住了我。",
	},
	[10013441] = {
		ID = 10013441,
		Speaker = "艾蕾娜",
		Text = "祝你一路平安。",
	},
	[10013442] = {
		ID = 10013442,
		Text = "飞船的登船梯缓缓放下。",
	},
	[10013443] = {
		ID = 10013443,
		Speaker = "黛莉亚",
		Text = "全员准备登舰！",
	},
	[10013444] = {
		ID = 10013444,
		Speaker = "秋比",
		Text = "春天国度，下次见！",
	},
	[10013445] = {
		ID = 10013445,
		Speaker = "伊丝娜",
		Text = "再见了！",
	},
	[10013446] = {
		ID = 10013446,
		Text = "瑟蕾雅走到我面前，手中握着一条用白色花朵编成的小护符。",
	},
	[10013447] = {
		ID = 10013447,
		Speaker = "瑟蕾雅",
		Text = "这个送给你。",
	},
	[30000605] = {
		ID = 30000605,
		Speaker = "黛莉亚",
		Text = "今天差不多该去检查飞船的顶部结构了，要不要一起上去看看？",
	},
	[30000656] = {
		ID = 30000656,
		Speaker = "我",
		Text = "给你三分颜色，你就开起染坊来了？",
	},
	[20060568] = {
		ID = 20060568,
		Text = "清晨的阳光洒落在甲板上。",
	},
	[20130091] = {
		ID = 20130091,
		Text = "……",
	},
	[20151024] = {
		ID = 20151024,
		Speaker = "爱诗塔",
		Text = "……只是这里确实比较有趣。仅此而已。",
	},
	[20151025] = {
		ID = 20151025,
		Text = "（再往前走了一段，通道突然分成三条。）",
	},
	[20151026] = {
		ID = 20151026,
		Text = "（左边的路宽阔平整，岩壁打磨得很光滑，墙壁上有许多的装饰。）",
	},
	[20151027] = {
		ID = 20151027,
		Text = "（右边的路坑坑洼洼，黏腻的风从里面吹出，令人不寒而栗。）",
	},
	[20151028] = {
		ID = 20151028,
		Text = "（中间那条最窄，只够一个人侧身通过，火把的光几乎照不进去，但似乎并不深。）",
	},
	[20151029] = {
		ID = 20151029,
		Text = "（黑画面转场）",
	},
	[20151030] = {
		ID = 20151030,
		Text = "两人继续向前走了一段时间。",
	},
	[20151031] = {
		ID = 20151031,
		Text = "一间偌大的房间在眼前出现。",
	},
	[20151032] = {
		ID = 20151032,
		Text = "房间内摆着大量的架子，陶罐和书卷散落在地板上。",
	},
	[20151033] = {
		ID = 20151033,
	},
	[20151034] = {
		ID = 20151034,
		Text = "（史莱姆们的动静慢慢平息了。那些圆滚滚的生物一个接一个黑暗深处蠕动。）",
	},
	[20151035] = {
		ID = 20151035,
		Text = "（留下几道在火把光下闪着光泽的黏液痕迹，就这样消失进走廊尽头的阴影里。它们看起来非常满足。）",
	},
	[20151036] = {
		ID = 20151036,
		Text = "（我往地上看了一眼，爱诗塔的薄纱还有身上所有大大小小的布料——已经全不见了。地面只剩几道闪亮的残迹，像某种静悄悄的犯罪现场。一件都不剩。）",
	},
	[20151037] = {
		ID = 20151037,
		Text = "（爱诗塔 没有说话。她就这样，以一种让人说不出话的平静，直接在原地往地上趴了下去。）",
	},
	[10012733] = {
		ID = 10012733,
		Speaker = "艾蕾娜",
		Text = "带上我，还是带上灯？",
	},
	[10013448] = {
		ID = 10013448,
		Speaker = "瑟蕾雅",
		Text = "这是今年第一批盛开的花。",
	},
	[10013449] = {
		ID = 10013449,
		Speaker = "瑟蕾雅",
		Text = "也是春天真的存在过的证明。",
	},
	[10013450] = {
