	[10013453] = {
		ID = 10013453,
		Speaker = "我",
		Text = "因为这里，已经成了我想回来的地方。",
	},
	[10013454] = {
		ID = 10013454,
		Speaker = "瑟蕾雅",
		Text = "我会一直等你。",
	},
	[10013455] = {
		ID = 10013455,
		Speaker = "我",
		Text = "那就请妳等我。",
