		Speaker = "伊丝娜",
		Text = "……完全没有计画的一天，真是的。",
	},
	[40000050] = {
		ID = 40000050,
	},
	[40000052] = {
		ID = 40000052,
		Speaker = "伊丝娜",
		Text = "后辈，这个……算是正式的祭典吗？",
