	[40000053] = {
		ID = 40000053,
		Speaker = "我",
		Text = "还挺有过节气氛的不是吗？或许你该放轻松点？",
	},
	[40000054] = {
		ID = 40000054,
		Speaker = "我",
		Text = "要喝吗？花蜜？",
	},
	[40000055] = {
		ID = 40000055,
		Speaker = "伊丝娜",
		Text = "就算是祭典，身为专业人员还是必须时刻保持警戒……",
	},
	[40000056] = {
		ID = 40000056,
		Speaker = "我",
		Text = "学姊，那边那只在看妳。",
	},
	[40000057] = {
		ID = 40000057,
		Speaker = "伊丝娜",
		Text = "啊……它、它是在跟我挥手吗……？",
	},
	[40000060] = {
		ID = 40000060,
		Speaker = "伊丝娜",
		Text = "……谢谢。",
	},
	[40000061] = {
		ID = 40000061,
		Speaker = "我",
		Text = "学姊抱着花的样子还蛮温柔的。",
	},
	[40000062] = {
		ID = 40000062,
		Speaker = "伊丝娜",
		Text = "胡说八道！我哪有什么温柔不温柔的。",
	},
	[40000063] = {
		ID = 40000063,
		Speaker = "我",
		Text = "那就继续往前走吧。",
	},
	[40000064] = {
		ID = 40000064,
		Text = "（往前走了几个摊位，毛球们越来越热情——带着花蜜的、带着花环的，也有只是围上来蹭了几下就跑掉的。）",
	},
	[40000065] = {
		ID = 40000065,
		Text = "（毛球叠成高塔，在伊丝娜还没来得及出声阻止之前，把一个白色花环稳稳地戴在了她的头上。）",
	},
	[40000066] = {
		ID = 40000066,
		Speaker = "伊丝娜",
		Text = "欸欸——等一下，我还没说……",
	},
	[40000067] = {
		ID = 40000067,
		Speaker = "我",
		Text = "学姊，看我这边。",
	},
	[40000068] = {
		ID = 40000068,
		Speaker = "伊丝娜",
		Text = "什么？",
