	[40000069] = {
		ID = 40000069,
		Speaker = "伊丝娜",
		Text = "！ ！ ！ ！ ！ ！",
	},
	[40000070] = {
		ID = 40000070,
		Speaker = "我",
		Text = "很可爱喔，拍张照片留念。",
