	[40000072] = {
		ID = 40000072,
		Speaker = "我",
		Text = "执行公务的人也可以很可爱啊。",
	},
	[40000073] = {
		ID = 40000073,
		Speaker = "伊丝娜",
		Text = "后辈，你到底在说什么？",
