		Text = "（甲板靠栏杆的角落，一个裹着大毯子的银白色身影半蹲在那，眼睛周围红肿，鼻头也是。）",
	},
	[40000154] = {
		ID = 40000154,
		Text = "（旁边的地板上，李奥纳多头顶顶着一大卷卫生纸，任由黛莉亚一张一张往外抽。）",
	},
	[40000155] = {
		ID = 40000155,
		Speaker = "我",
		Text = "……黛莉亚，妳还好吗？",
	},
	[40000156] = {
		ID = 40000156,
		Speaker = "黛莉亚",
		Text = "舰长先——哈啾！",
	},
	[40000157] = {
		ID = 40000157,
		Speaker = "黛莉亚",
		Text = "舰长先生！ ！",
	},
	[40000159] = {
		ID = 40000159,
		Speaker = "黛莉亚",
		Text = "啊，这个！因为我一直要用嘛，叫他帮我顶着比较方便拿，哈哈！",
	},
	[40000160] = {
		ID = 40000160,
		Speaker = "黛莉亚",
		Text = "哈啾！ ！",
