		Text = "伊丝娜沉默了很久， 她只是坐在那里，和黛莉亚一起看着时钟塔。",
	},
	[10011102] = {
		ID = 10011102,
		Text = "是否意味着蒸气女神也接近终点了呢？这个疑问在两人心里流转。",
	},
	[10011103] = {
		ID = 10011103,
		Text = "此刻谁也说不出口。",
	},
	[10011104] = {
		ID = 10011104,
		Text = "我默默站在角落，他原本只是无意间停下脚步，",
	},
	[10011105] = {
		ID = 10011105,
		Text = "却刚好把伊丝娜与黛莉亚的整段对话听得一清二楚。",
	},
	[10011106] = {
		ID = 10011106,
		Speaker = "我",
		Text = "（虽然不是刻意偷听，但也差不多走到该分别的时候了……）",
	},
	[10011111] = {
		ID = 10011111,
	},
	[10011112] = {
		ID = 10011112,
	},
	[10011113] = {
		ID = 10011113,
		Text = "飞船的通讯设备突然传来提示声。",
	},
	[10011114] = {
		ID = 10011114,
		Speaker = "黛莉亚",
		Text = "舰长先生！ ！你的通讯系统恢复了！",
	},
	[10011116] = {
		ID = 10011116,
		Text = "我假装这时候才经过。",
	},
	[10011117] = {
		ID = 10011117,
		Speaker = "我",
		Text = "什么？",
	},
	[10011118] = {
		ID = 10011118,
		Speaker = "我",
		Text = "会是谁呢？",
	},
	[10011119] = {
		ID = 10011119,
		Text = "连线成功的瞬间，一阵带着海风气息的清凉感几乎从萤幕另一头扑了出来。",
	},
	[10011120] = {
		ID = 10011120,
		Text = "画面里，一群穿着清凉的年轻女子正赤着脚，在阳光灿烂的沙滩上追逐嬉闹，笑声此起彼落。",
	},
	[10011121] = {
		ID = 10011121,
		Speaker = "女子",
		Text = "舰长～～～你到底什么时候才要到呀？",
	},
	[10011122] = {
		ID = 10011122,
		Speaker = "女子",
		Text = "我们等你很久了耶～～～你是不是跑错星球了啦！",
	},
	[10011123] = {
		ID = 10011123,
		Speaker = "我",
		Text = "呵呵，马上～～马上就到～～沙滩星球嘛，我记得！",
	},
	[10011124] = {
		ID = 10011124,
		Text = "伊丝娜与黛莉亚忍不住翻白眼，刚才的离愁瞬间被冲得一干二净",
	},
	[10011126] = {
		ID = 10011126,
		Text = "我切掉通讯，顾作烦恼地叹气。",
	},
	[10011127] = {
		ID = 10011127,
		Speaker = "我",
		Text = "我不过就是把自己的照片提前先发过去，",
