	[10011129] = {
		ID = 10011129,
		Speaker = "伊丝娜",
		Text = "既然如此，后辈就赶快出发吧。",
	},
	[10011130] = {
		ID = 10011130,
		Speaker = "黛莉亚",
		Text = "对呀，舰长先生，飞船已经维修完成，",
	},
	[10011131] = {
		ID = 10011131,
		Speaker = "黛莉亚",
		Text = "你随时都可以出发。",
	},
	[10011133] = {
		ID = 10011133,
		Speaker = "我",
		Text = "我们不是一起出生入死的伙伴吗？",
