	[10011140] = {
		ID = 10011140,
		Speaker = "伊丝娜",
		Text = "谢谢你的好意。",
	},
	[10011142] = {
		ID = 10011142,
		Speaker = "伊丝娜",
		Text = "那你干嘛还问？",
	},
	[10011143] = {
		ID = 10011143,
		Speaker = "我",
		Text = "我只能说，这个宇宙最复杂的生物，不是人。",
