	[10011150] = {
		ID = 10011150,
		Speaker = "我",
		Text = "我不晓得是谁安排，总之我不是第一次碰到这种攻击。",
	},
	[10011151] = {
		ID = 10011151,
		Speaker = "伊丝娜",
		Text = "后辈，城市机械警卫失控攻击你，我要代表这个星球向你致歉。",
	},
	[10011152] = {
		ID = 10011152,
		Speaker = "伊丝娜",
		Text = "但请你不要说得好像我们是邪恶之人。",
	},
	[10011153] = {
		ID = 10011153,
		Speaker = "我",
		Text = "学姊，你看时钟塔，那个指针。",
	},
	[10011154] = {
		ID = 10011154,
		Speaker = "我",
		Text = "那个指针是我眼睁睁看着002爬到塔上摘下来的！",
