	[10011157] = {
		ID = 10011157,
		Speaker = "我",
		Text = "002身上的伤你们也看到了，那表示有人从他手上抢走指针装回去！",
	},
	[10011158] = {
		ID = 10011158,
		Speaker = "伊丝娜",
		Text = "为什么要这么做？",
	},
	[10011162] = {
		ID = 10011162,
		Speaker = "我",
		Text = "我不知道是谁设计的，但我觉得你们应该跟我走。",
	},
	[10011163] = {
		ID = 10011163,
		Speaker = "伊丝娜",
		Text = "闭嘴！你走吧，不要再回来了！",
	},
	[10011164] = {
		ID = 10011164,
		Speaker = "伊丝娜",
		Text = "蒸气女神绝对不会做出伤害子民的事！",
	},
	[10011165] = {
		ID = 10011165,
		Text = "气氛顿时凝结，伊丝娜怒目瞪着我。",
	},
	[10011168] = {
		ID = 10011168,
		Speaker = "我",
		Text = "那看来我们要在此分道扬镳了呢。",
