	},
	[10011896] = {
		ID = 10011896,
		Text = "蒸气、冰晶、木屑与雪花交错飞散。",
	},
	[10011897] = {
		ID = 10011897,
		Text = "忽然一道光打在伊丝娜身上，伊丝娜毫无预警地变成一座人形冰雕。",
	},
	[10011899] = {
		ID = 10011899,
