	[10011900] = {
		ID = 10011900,
		Speaker = "我",
		Text = "怎么会这样？",
	},
	[10011901] = {
		ID = 10011901,
		Text = "我分神，一转头雪人的光波竟全数袭向黛莉亚与秋比",
	},
	[10011902] = {
		ID = 10011902,
		Text = "我牙一咬，用肉身挡住所有光波。",
