	},
	[10011914] = {
		ID = 10011914,
		Text = "突然狼嚎声四起，我感受到迫切的危机。",
	},
	[10011915] = {
		ID = 10011915,
		Speaker = "我",
		Text = "黛莉亚，秋比！我们要赶快离开！",
	},
	[10011917] = {
		ID = 10011917,
		Speaker = "我",
		Text = "等等回来救！",
	},
	[10011919] = {
		ID = 10011919,
	},
	[10011921] = {
		ID = 10011921,
		Text = "金色灯火在暴雪中逐渐靠近。",
	},
	[10011922] = {
		ID = 10011922,
		Text = "少女提着灯从风雪中现身。",
