		Speaker = "爱诗塔",
		Text = "咕呜……每当君主大人的舌头滑过我的乳头……",
	},
	[30001708] = {
		ID = 30001708,
		Speaker = "爱诗塔",
		Text = "就像是电流通过一样……咕……",
	},
	[30001709] = {
		ID = 30001709,
		Speaker = "我",
		Text = "爱诗塔，还撑得住吗？",
	},
	[30001710] = {
		ID = 30001710,
		Speaker = "爱诗塔",
		Text = "君主大人的阳具也是……哈啊……",
	},
	[30001711] = {
		ID = 30001711,
		Speaker = "爱诗塔",
		Text = "明明就只是温柔的触碰……咕呜呜……",
	},
	[30001712] = {
		ID = 30001712,
		Speaker = "爱诗塔",
		Text = "却总是能搔中我的痒处……哈啊……",
	},
	[30001713] = {
		ID = 30001713,
		Speaker = "爱诗塔",
		Text = "随便碰一下……呜呜……",
	},
	[30001714] = {
		ID = 30001714,
		Speaker = "爱诗塔",
		Text = "就能碰到我最敏感的地方……",
	},
	[30001715] = {
		ID = 30001715,
		Speaker = "我",
		Text = "你这不是开始享受了吗？爱诗塔。",
	},
	[30001716] = {
		ID = 30001716,
		Speaker = "我",
		Text = "那么，我要开始加速啰。",
	},
	[30001717] = {
		ID = 30001717,
		Speaker = "爱诗塔",
		Text = "等、等等……呜！君主大人！",
	},
	[30001718] = {
		ID = 30001718,
		Speaker = "爱诗塔",
		Text = "这样的节奏……哈啊……我、我有点跟不上……！咕呜！",
	},
	[30001719] = {
		ID = 30001719,
		Speaker = "爱诗塔",
		Text = "君主大人的舌头……现在变得好像是烙铁……",
	},
	[30001720] = {
		ID = 30001720,
		Speaker = "爱诗塔",
		Text = "随便碰一下……咕呜！就让我的胸部……变得好热！",
	},
	[30001721] = {
		ID = 30001721,
		Speaker = "爱诗塔",
		Text = "君主大人的手指也是……咕呜……像是用羽毛做成的一样……咕！",
	},
	[30001722] = {
		ID = 30001722,
		Speaker = "爱诗塔",
		Text = "无论碰到哪里……都会让人痒的受不了……",
	},
	[30001723] = {
		ID = 30001723,
		Speaker = "我",
		Text = "嘿嘿，被你这么一番称赞，我都觉得自己似乎真的挺了不起的。",
	},
	[30001724] = {
		ID = 30001724,
		Speaker = "爱诗塔",
		Text = "君主大人……君主大人……君主大人！",
	},
	[30001725] = {
		ID = 30001725,
		Speaker = "爱诗塔",
		Text = "求求您……先暂时放过我吧……咕呜！",
	},
	[30001726] = {
		ID = 30001726,
		Speaker = "爱诗塔",
		Text = "要是再这样……呜呜，被您宠爱下去……咕！",
	},
	[30001727] = {
		ID = 30001727,
		Speaker = "爱诗塔",
		Text = "我怕……我怕……哈啊啊啊……",
	},
	[30001728] = {
		ID = 30001728,
		Speaker = "爱诗塔",
		Text = "我怕，我就会变得再也不像是原来的我──",
	},
	[30001729] = {
		ID = 30001729,
		Speaker = "我",
		Text = "……不会的，因为，有我在这里呢……",
	},
	[30001730] = {
		ID = 30001730,
		Speaker = "爱诗塔",
		Text = "咕呜──呀啊啊啊啊啊啊啊啊啊啊！",
	},
	[30001731] = {
		ID = 30001731,
		Speaker = "爱诗塔",
		Text = "君主大人的精液……在我的小穴里面……射得到处都是……！",
	},
	[30001732] = {
		ID = 30001732,
		Speaker = "爱诗塔",
		Text = "哈啊……哈啊啊啊……",
	},
	[30001733] = {
		ID = 30001733,
		Speaker = "爱诗塔",
		Text = "君主大人……我今晚的侍奉……还算可以吗？",
	},
