	[20030001] = {
		ID = 20030001,
	},
	[20030002] = {
		ID = 20030002,
		Speaker = "我",
		Text = "喂！有人在吗？",
	},
	[20030003] = {
		ID = 20030003,
		Speaker = "我",
		Text = "开门！",
	},
	[20030004] = {
		ID = 20030004,
		Speaker = "我",
		Text = "我知道你在里面！",
	},
	[20030005] = {
		ID = 20030005,
		Text = "（木门被打开了，眼前的邪神看起来和往常完全不同。）",
	},
	[20030007] = {
		ID = 20030007,
		Text = "（她的白色长发有些凌乱，眼神有些呆滞，像是刚起床似的。）",
	},
	[20030008] = {
		ID = 20030008,
		Speaker = "赛诃希丝",
		Text = "哈……？",
	},
	[20030009] = {
		ID = 20030009,
		Speaker = "赛诃希丝",
		Text = "你……怎么自己来了？而且你为什么一件衣服都没有穿啊！",
	},
	[20030010] = {
		ID = 20030010,
		Speaker = "我",
		Text = "我怎么知道，你又想弄死我了是不是？",
	},
	[20030011] = {
		ID = 20030011,
		Speaker = "赛诃希丝",
		Text = "不——不不不，我没有安排啊？",
	},
	[20030012] = {
		ID = 20030012,
		Speaker = "我",
		Text = "那你现在又在干什么？",
	},
	[20030013] = {
		ID = 20030013,
		Speaker = "赛诃希丝",
		Text = "还不够明显吗？你这个蠢货！",
	},
	[20030014] = {
		ID = 20030014,
		Speaker = "赛诃希丝",
		Text = "我很明显在睡觉。",
	},
	[20030015] = {
		ID = 20030015,
		Speaker = "我",
		Text = "喔？",
	},
	[20030016] = {
		ID = 20030016,
		Speaker = "赛诃希丝",
		Text = "是真的！我没有把你弄进来！",
	},
	[20030017] = {
		ID = 20030017,
		Speaker = "我",
		Text = "那我是怎么进来的？",
	},
	[20030018] = {
		ID = 20030018,
		Speaker = "赛诃希丝",
		Text = "怎么办、怎么办才好呢？",
	},
	[20030019] = {
		ID = 20030019,
		Speaker = "赛诃希丝",
		Text = "我也不知道啊！",
	},
	[20030020] = {
		ID = 20030020,
		Speaker = "我",
		Text = "……你不知道？",
	},
	[20030021] = {
		ID = 20030021,
		Speaker = "赛诃希丝",
		Text = "这个答案让你很失望吗？",
	},
	[20030022] = {
		ID = 20030022,
		Speaker = "我",
		Text = "不是失望，只是有点意外。",
	},
	[20030023] = {
		ID = 20030023,
		Speaker = "我",
		Text = "通常的流程不是——你把我抓进来，嘲笑我——",
	},
	[20030024] = {
		ID = 20030024,
		Speaker = "我",
		Text = "然后试着上我吗？",
	},
	[20030025] = {
		ID = 20030025,
		Speaker = "赛诃希丝",
		Text = "呀──哈哈哈哈！",
	},
	[20030026] = {
		ID = 20030026,
		Speaker = "赛诃希丝",
		Text = "你居然已经把整套流程背下来了！",
	},
	[20030027] = {
		ID = 20030027,
		Speaker = "赛诃希丝",
		Text = "一想到你已经把被我抓进来当成日常的这件事……我就快要……",
	},
	[20030028] = {
		ID = 20030028,
		Speaker = "我",
		Text = "跑了这么多次，不背下来才奇怪吧。",
	},
	[20030030] = {
		ID = 20030030,
		Text = "（她用触手揉了揉眼睛，把我往房子内招呼。）",
	},
	[20030032] = {
		ID = 20030032,
		Speaker = "赛诃希丝",
		Text = "你来都来了，现在也出不去——",
	},
	[20030033] = {
		ID = 20030033,
		Speaker = "赛诃希丝",
		Text = "这个空间除非是小星星把墙壁劈开。",
	},
	[20030034] = {
		ID = 20030034,
		Speaker = "赛诃希丝",
		Text = "不然进来了要等一段时间才可以走。",
	},
	[20030035] = {
		ID = 20030035,
		Speaker = "我",
		Text = "喔，所以你没有要趁这个机会把我怎样吗？",
	},
	[20030036] = {
		ID = 20030036,
		Speaker = "赛诃希丝",
		Text = "怎么？你以为邪恶计画是从天上掉下来的吗？",
	},
	[20030037] = {
		ID = 20030037,
		Speaker = "赛诃希丝",
		Text = "你这样突然跑来，我根本没有时间准备。",
	},
	[20030038] = {
		ID = 20030038,
		Speaker = "赛诃希丝",
		Text = "我可不会把半吊子的计画拿出来用。",
	},
	[20030039] = {
		ID = 20030039,
		Speaker = "我",
		Text = "所以……就这样？",
	},
	[20030040] = {
		ID = 20030040,
		Speaker = "赛诃希丝",
		Text = "就这样。",
	},
	[20030042] = {
		ID = 20030042,
	},
	[20030043] = {
		ID = 20030043,
		Text = "（我后退几步，全力往门上冲撞而去。）",
	},
	[20030045] = {
		ID = 20030045,
		Speaker = "我",
		Text = "开门！",
	},
	[20030046] = {
		ID = 20030046,
		Text = "（我又撞了一次。）",
	},
	[20030047] = {
		ID = 20030047,
		Speaker = "我",
		Text = "我知道你在里面！",
	},
	[20030048] = {
		ID = 20030048,
		Speaker = "赛诃希丝",
		Text = "谁啊！大半夜的！在那边撞门！",
	},
	[20030049] = {
		ID = 20030049,
		Text = "（木门被打开了，眼前的邪神看起来和往常完全不同。）",
