	[20050312] = {
		ID = 20050312,
		Speaker = "黛莉亚",
		Text = "……咦？",
	},
	[20050313] = {
		ID = 20050313,
		Speaker = "黛莉亚",
		Text = "妈、妈妈！ ？我哪有像妈妈！ ！",
	},
	[20050314] = {
		ID = 20050314,
		Speaker = "黛莉亚",
		Text = "那、那只是因为是工匠的职责！机械或生物都一样！跟妈妈没有关系的！ ！",
	},
	[20050315] = {
		ID = 20050315,
		Speaker = "黛莉亚",
		Text = "真的要当妈妈的话果然还是会希望自己的孩子是巨大机器人吧！",
	},
	[20050316] = {
		ID = 20050316,
		Speaker = "黛莉亚",
		Text = "离题了！我们应该得找更多鸟能吃的东西吧？",
	},
	[20050317] = {
		ID = 20050317,
		Speaker = "黛莉亚",
		Text = "但它们到底吃什么比较好？",
	},
	[20050318] = {
		ID = 20050318,
	},
	[20050319] = {
		ID = 20050319,
		Speaker = "我",
		Text = "真的吗？那我开门了喔！",
	},
	[20050320] = {
		ID = 20050320,
		Speaker = "黛莉亚",
		Text = "开门！",
	},
	[20050322] = {
		ID = 20050322,
		Speaker = "黛莉亚",
		Text = "呀啊！小鸟！",
	},
	[20050323] = {
		ID = 20050323,
		Speaker = "我",
		Text = "没礼貌！不是你说要我开门的吗？",
	},
	[20050325] = {
		ID = 20050325,
		Speaker = "我",
		Text = "才不小呢！",
	},
	[20050326] = {
		ID = 20050326,
		Text = "（蹦的一声，黛莉亚把门甩上。）",
	},
	[20050327] = {
		ID = 20050327,
		Speaker = "黛莉亚",
		Text = "至少穿一件裤子啊！只有蒸汽机会这样子运作指令的吧！",
	},
	[20050328] = {
		ID = 20050328,
		Text = "（几分钟后我穿好衣服，打开门。）",
	},
	[20050331] = {
		ID = 20050331,
		Speaker = "黛莉亚",
		Text = "不对！这不是重点！",
	},
	[20050332] = {
		ID = 20050332,
		Speaker = "黛莉亚",
		Text = "总之舰长先生，跟我来一下！",
	},
	[20050333] = {
		ID = 20050333,
		Speaker = "我",
		Text = "去哪里？",
	},
	[20050334] = {
		ID = 20050334,
		Speaker = "黛莉亚",
		Text = "我的房间！有很重要的东西要让你看！快快快！",
	},
	[20050335] = {
		ID = 20050335,
		Text = "（黛莉亚已经伸手拽住我的袖子往走廊方向拖，我的拖鞋都还没踩好就被带着走了。）",
	},
	[20050336] = {
		ID = 20050336,
		Text = "（黛莉亚的房间本来就塞得跟仓库差不多，拆到一半的零件堆满每个角落。）",
	},
	[20050337] = {
		ID = 20050337,
		Text = "（我才踏进门，就察觉角落的小巢附近有什么东西在轻轻蠕动。）",
	},
	[20050338] = {
		ID = 20050338,
		Speaker = "我",
		Text = "那是……",
	},
	[20050339] = {
		ID = 20050339,
		Speaker = "黛莉亚",
		Text = "嘘！小声一点！别吓到他们！",
	},
	[20050340] = {
		ID = 20050340,
		Speaker = "我",
		Text = "他们……？",
	},
	[20050341] = {
		ID = 20050341,
		Speaker = "黛莉亚",
		Text = "雏鸟！昨天晚上孵出来的！你看你看！",
	},
	[20050342] = {
		ID = 20050342,
		Text = "（我凑过去——原本的两颗蛋，如今换成了两只毛茸茸的小东西。）",
	},
	[20050343] = {
		ID = 20050343,
		Text = "（它们缩在黛莉亚拿电线和碎布围起来的小巢里，眼睛还没完全睁开，呼吸均匀。）",
	},
	[20050344] = {
		ID = 20050344,
		Speaker = "我",
		Text = "哇，真的孵出来了。",
	},
	[20050345] = {
		ID = 20050345,
		Speaker = "黛莉亚",
		Text = "对吧！感觉昨晚就已经有动静了，我就一直守在旁边，然后——啵——就出来了！",
	},
	[20050346] = {
		ID = 20050346,
		Speaker = "我",
		Text = "你守了一整晚？",
	},
	[20050347] = {
		ID = 20050347,
		Speaker = "黛莉亚",
		Text = "差不多吧，睡不着嘛。",
	},
	[20050348] = {
		ID = 20050348,
		Speaker = "我",
		Text = "这个巢是你重新做的吗？",
	},
	[20050350] = {
		ID = 20050350,
		Speaker = "我",
		Text = "「感觉刚好」是哪个标准……",
