	},
	[20100421] = {
		ID = 20100421,
		Speaker = "耶珥",
		Text = "少年你要帮妾身缝衣服，妾身自然得把衣服脱下来给你缝，对吧。",
	},
	[20100422] = {
		ID = 20100422,
		Speaker = "我",
		Text = "……缝个破洞需要把整件衣服都脱掉吗。",
