	[20130001] = {
		ID = 20130001,
		Text = "黑画面转场",
	},
	[20130002] = {
		ID = 20130002,
		Speaker = "我",
		Text = "非常的适合呢！",
	},
	[20130003] = {
		ID = 20130003,
		Speaker = "伊丝娜",
		Text = "喔？",
	},
	[20130004] = {
		ID = 20130004,
		Speaker = "伊丝娜",
		Text = "称赞一个女生说非常适合兔女郎装。",
	},
	[20130005] = {
		ID = 20130005,
		Speaker = "伊丝娜",
		Text = "这不是活脱脱的性骚扰吗？",
	},
	[20130006] = {
		ID = 20130006,
		Speaker = "伊丝娜",
		Text = "哼！别以为这样就会让我开心了！",
	},
	[20130007] = {
		ID = 20130007,
		Speaker = "我",
		Text = "学姊看起来非常的开心没错啊。",
	},
	[20130008] = {
		ID = 20130008,
		Speaker = "伊丝娜",
		Text = "少废话，那是灯光给你带来的错觉。",
	},
	[20130009] = {
		ID = 20130009,
		Speaker = "伊丝娜",
		Text = "总之快坐下！既然都来了，就好好让我展示一下什么叫正确的酒吧文化！",
	},
	[20130010] = {
		ID = 20130010,
		Text = "黑画面转场",
	},
	[20130011] = {
		ID = 20130011,
		Speaker = "我",
		Text = "这样穿看起来和平时差很多呢。",
	},
	[20130012] = {
		ID = 20130012,
		Speaker = "伊丝娜",
		Text = "肯定差很多，这是我特别挑的。",
	},
	[20130013] = {
		ID = 20130013,
		Speaker = "伊丝娜",
		Text = "今天心情好，可以让你再多称赞我一些。",
	},
	[20130014] = {
		ID = 20130014,
		Speaker = "我",
		Text = "学姊穿这套衣服，感觉胸部特别的显眼，腰特别细，还有高衩的关系——",
	},
	[20130015] = {
		ID = 20130015,
		Speaker = "我",
		Text = "屁股看起来特别大呢，真的很好看！",
	},
	[20130017] = {
		ID = 20130017,
		Speaker = "伊丝娜",
		Text = "这完全就是性骚扰！",
	},
	[20130018] = {
		ID = 20130018,
		Speaker = "伊丝娜",
		Text = "你这家伙！这些想法在心里面想想就好，千万不要给我说出来！",
	},
	[20130019] = {
		ID = 20130019,
		Speaker = "伊丝娜",
		Text = "就算要说，也只对着我说就好！",
	},
	[20130020] = {
		ID = 20130020,
		Speaker = "伊丝娜",
		Text = "真是的！",
	},
	[20130021] = {
		ID = 20130021,
		Speaker = "伊丝娜",
		Text = "你这种说话方式，哪天被警察给抓走都不奇怪！",
	},
	[20130022] = {
		ID = 20130022,
		Text = "（伊丝娜的脸红到耳根，别过头去。）",
	},
	[20130023] = {
		ID = 20130023,
		Speaker = "伊丝娜",
		Text = "总之快坐下！既然都来了，就好好让我展示一下什么叫正确的酒吧文化！",
	},
	[20130024] = {
		ID = 20130024,
	},
	[20130025] = {
		ID = 20130025,
		Speaker = "我",
		Text = "便宜的啤酒就好了。",
	},
	[20130026] = {
		ID = 20130026,
		Speaker = "伊丝娜",
		Text = "……什么？",
	},
	[20130027] = {
		ID = 20130027,
		Speaker = "伊丝娜",
		Text = "你说便宜的啤酒？",
	},
	[20130028] = {
		ID = 20130028,
		Speaker = "伊丝娜",
		Text = "后辈，你确定？",
	},
	[20130029] = {
		ID = 20130029,
		Speaker = "我",
		Text = "对啊，味道差不多嘛。",
	},
	[20130031] = {
		ID = 20130031,
		Speaker = "伊丝娜",
		Text = "你知道那种东西是什么概念吗？喝那种便宜货，怎么对得起自己的身分？",
	},
	[20130032] = {
		ID = 20130032,
		Speaker = "我",
		Text = "我的身分……就是个普通后辈啊。",
	},
	[20130033] = {
		ID = 20130033,
		Speaker = "伊丝娜",
		Text = "所以你更要讲究！",
	},
	[20130034] = {
		ID = 20130034,
		Speaker = "伊丝娜",
		Text = "品味是从日常的选择里养出来的。",
	},
	[20130035] = {
		ID = 20130035,
		Speaker = "伊丝娜",
		Text = "在底层生活的社畜如果日复一日喝着廉价的啤酒，那就永远都只能是社畜了！",
	},
	[20130037] = {
		ID = 20130037,
		Speaker = "我",
		Text = "那不如这样？",
	},
	[20130038] = {
		ID = 20130038,
		Speaker = "我",
		Text = "学姊你喝酒的阅历肯定比我丰富多了，要不要帮我挑一杯？",
	},
	[20130039] = {
		ID = 20130039,
		Speaker = "伊丝娜",
		Text = "……什么？",
	},
	[20130040] = {
		ID = 20130040,
		Speaker = "伊丝娜",
		Text = "等等，你说……让我帮你挑？",
	},
	[20130042] = {
		ID = 20130042,
		Speaker = "伊丝娜",
		Text = "也……也不是不行啦。",
	},
	[20130043] = {
		ID = 20130043,
		Speaker = "伊丝娜",
		Text = "我确实比你有经验，这一点不需要你提醒。",
	},
	[20130044] = {
		ID = 20130044,
		Speaker = "我",
		Text = "那就麻烦学姊了。",
	},
	[20130045] = {
		ID = 20130045,
		Speaker = "伊丝娜",
		Text = "胡说八道，谁说要麻烦我了。",
	},
	[20130046] = {
		ID = 20130046,
		Speaker = "伊丝娜",
		Text = "真是拿你没办法……",
	},
	[20130047] = {
		ID = 20130047,
		Speaker = "我",
		Text = "喔？学姊你刚才是在笑吗？",
	},
	[20130048] = {
		ID = 20130048,
		Speaker = "伊丝娜",
		Text = "我有吗！我没有！",
	},
	[20130049] = {
		ID = 20130049,
		Speaker = "伊丝娜",
		Text = "安静一下，让我想。",
	},
	[20130050] = {
		ID = 20130050,
		Text = "（我看着她低头调酒——冰块、一点透明的基底、再加几滴颜色深一些的甜酒——）",
	},
	[20130051] = {
		ID = 20130051,
		Speaker = "伊丝娜",
		Text = "好了。",
	},
	[20130052] = {
		ID = 20130052,
		Text = "（学姊把一杯透着粉橘色的鸡尾酒推到我面前。）",
	},
	[20130054] = {
		ID = 20130054,
		Speaker = "我",
		Text = "……学姊帮我想得挺仔细的嘛。",
	},
	[20130055] = {
		ID = 20130055,
		Speaker = "伊丝娜",
		Text = "别误会，我只是不想让人说我调的酒不好喝。",
	},
	[20130056] = {
