	[20130287] = {
		ID = 20130287,
		Speaker = "伊丝娜",
		Text = "等等，我哪有一个人揽着……你是不是误会了什么？",
	},
	[20130288] = {
		ID = 20130288,
		Speaker = "我",
		Text = "是吗？",
	},
	[20130289] = {
