	},
	[20130298] = {
		ID = 20130298,
		Speaker = "我",
		Text = "学姊，妳的脸怎么有点红？",
	},
	[20130299] = {
		ID = 20130299,
		Speaker = "伊丝娜",
		Text = "哪、哪里有红！就是这里太热了！你都感觉不到吗？这里的温度一点都不负和规范。",
	},
	[20130300] = {
