		Speaker = "伊丝娜",
		Text = "我还是会在那颗无聊的星球上，当一个不讨喜的坏坏主管～",
	},
	[20130446] = {
		ID = 20130446,
		Speaker = "伊丝娜",
		Text = "后辈～你还在听嘛～？",
	},
	[20130447] = {
		ID = 20130447,
		Speaker = "我",
		Text = "我还在，学姊，你该休息了。",
	},
	[20130448] = {
		ID = 20130448,
		Speaker = "伊丝娜",
		Text = "噗要～还想要后辈多陪我一点～",
	},
	[20130449] = {
		ID = 20130449,
		Speaker = "伊丝娜",
		Text = "好久好久，没有像这样放轻松。",
	},
	[20130450] = {
		ID = 20130450,
		Speaker = "伊丝娜",
		Text = "压力真的好大好大。",
	},
	[20130451] = {
		ID = 20130451,
		Speaker = "伊丝娜",
		Text = "我一直都好努力，好努力想做好一切～",
	},
	[20130452] = {
		ID = 20130452,
		Speaker = "伊丝娜",
		Text = "我已经是个大人了，所以不能像秋比一样撒娇。",
	},
	[20130454] = {
		ID = 20130454,
		Speaker = "伊丝娜",
		Text = "可以只看着我、可以陪在我身边、陪我一起喝酒。",
	},
	[20130455] = {
		ID = 20130455,
		Speaker = "伊丝娜",
		Text = "我就觉得来到这个地方。",
	},
	[20130458] = {
		ID = 20130458,
		Speaker = "伊丝娜",
		Text = "我想要后辈，在给我多一点的鼓励。",
	},
	[20130460] = {
		ID = 20130460,
		Speaker = "伊丝娜",
		Text = "我做的好吗？",
	},
	[20130461] = {
		ID = 20130461,
		Speaker = "伊丝娜",
		Text = "后辈。",
	},
	[20130462] = {
		ID = 20130462,
	},
	[20130463] = {
		ID = 20130463,
		Speaker = "我",
		Text = "……学姊，妳到底喝了几杯。",
	},
	[20130464] = {
		ID = 20130464,
		Speaker = "伊丝娜",
		Text = "才、才没有喝多！我完全清醒！",
	},
	[20130465] = {
		ID = 20130465,
		Speaker = "伊丝娜",
		Text = "这是第一杯～嘿嘿～。",
	},
	[20130466] = {
		ID = 20130466,
		Text = "（伊丝娜躺在沙发上，抱着一个空酒瓶用胸部夹住，整个人左扭右扭的。）",
	},
	[20130467] = {
		ID = 20130467,
		Speaker = "我",
		Text = "学姊，那是第七个空瓶子。",
	},
	[20130468] = {
		ID = 20130468,
		Speaker = "伊丝娜",
		Text = "……不可能。",
	},
	[20130470] = {
		ID = 20130470,
		Speaker = "伊丝娜",
		Text = "嘿嘿～",
	},
	[20130472] = {
		ID = 20130472,
		Speaker = "伊丝娜",
		Text = "不要！",
	},
	[20130473] = {
		ID = 20130473,
		Text = "（她立刻坐直，差点从高脚椅滑下去，手忙脚乱地抓住吧台边缘）",
	},
	[20130475] = {
		ID = 20130475,
		Speaker = "伊丝娜",
		Text = "……那是……那是意外。",
	},
	[20130476] = {
		ID = 20130476,
		Speaker = "我",
		Text = "走吧，我扶妳回去。",
	},
	[20130477] = {
		ID = 20130477,
		Speaker = "伊丝娜",
		Text = "不要～",
	},
	[20130480] = {
		ID = 20130480,
		Text = "（然后视线落到吧台角落那片飞镖靶上——那个眼神突然清晰了起来，带着某种危险的干劲。）",
	},
	[20130481] = {
		ID = 20130481,
		Speaker = "伊丝娜",
		Text = "比飞镖？",
	},
	[20130482] = {
		ID = 20130482,
		Speaker = "我",
		Text = "……咦？",
	},
	[20130483] = {
		ID = 20130483,
		Speaker = "伊丝娜",
		Text = "我们来比飞镖！输的人听赢的人说话！",
	},
	[20130484] = {
		ID = 20130484,
		Text = "（她双手叉腰，站稳了，表情充满迎战的气势）",
	},
	[20130485] = {
		ID = 20130485,
		Speaker = "我",
		Text = "学姊，妳现在站直都有点……",
	},
	[20130486] = {
		ID = 20130486,
		Speaker = "伊丝娜",
		Text = "我完全没问题！",
	},
	[20130487] = {
		ID = 20130487,
		Speaker = "我",
		Text = "（醉成这样，飞镖怎么可能射得准……这不就是白给的胜利吗。）",
	},
	[20130488] = {
		ID = 20130488,
		Speaker = "我",
		Text = "好，比就比。",
	},
	[20130489] = {
		ID = 20130489,
		Speaker = "伊丝娜",
		Text = "要是我赢了，你今晚不准再提「回去睡觉」这六个字！",
	},
	[20130490] = {
		ID = 20130490,
		Text = "（一脸理直气壮，手指在空中比了个「三」）",
	},
	[20130491] = {
		ID = 20130491,
		Speaker = "我",
		Text = "那学姊要是输了呢？",
	},
	[20130492] = {
		ID = 20130492,
		Speaker = "伊丝娜",
		Text = "哼！我才不会输！",
	},
	[20130493] = {
		ID = 20130493,
		Text = "（伊丝娜像刺客投掷飞刀一样，瞬间甩出了三只飞镖。）",
	},
	[20130494] = {
		ID = 20130494,
		Speaker = "我",
		Text = "（……她刚才那个动作怎么那么利落。）",
	},
	[20130495] = {
		ID = 20130495,
		Text = "（三支飞镖全数插在靶心附近，掷出时的眼神清晰得像换了个人。）",
	},
	[20130496] = {
		ID = 20130496,
		Text = "（我低头看了看靶上自己前两支飞镖的落点，再看了看手中最后一支。）",
	},
	[20130497] = {
		ID = 20130497,
		Speaker = "伊丝娜",
		Text = "耶～赢了！赢了～",
	},
	[20130498] = {
		ID = 20130498,
		Speaker = "伊丝娜",
		Text = "嘿嘿～",
	},
	[20130499] = {
		ID = 20130499,
		Speaker = "伊丝娜",
		Text = "那我要来领取胜者的奖励啰～",
	},
	[20130501] = {
		ID = 20130501,
		Text = "（我还来不及搞清楚发生了什么事情，伊丝娜便直接扑了上来。）",
	},
	[20130502] = {
		ID = 20130502,
		Text = "（双唇快速的贴上我的嘴，并直接把舌头伸了进来。）",
	},
	[20130503] = {
