	[10013777] = {
		ID = 10013777,
	},
	[10013778] = {
		ID = 10013778,
		Text = "春天回来后的第三天，希望之丘的雪已退到山坡与屋檐阴影之中。",
	},
	[10013779] = {
		ID = 10013779,
		Text = "教堂后方的小花园里，第一批不知名的白色小花正安静绽放。",
	},
	[10013780] = {
		ID = 10013780,
		Text = "融雪沿着石阶滴落，像冬天正在一点一点学会放手。",
