	[10013785] = {
		ID = 10013785,
		Speaker = "瑟蕾雅",
		Text = "只是相信。",
	},
	[10013786] = {
		ID = 10013786,
		Speaker = "我",
		Text = "这里和我第一次见到妳的时候，已经完全不同了。",
