	[10013789] = {
		ID = 10013789,
		Speaker = "瑟蕾雅",
		Text = "不、不是那个意思。",
	},
	[10013790] = {
		ID = 10013790,
		Speaker = "我",
		Text = "可惜，我还挺期待的。",
	},
	[10013791] = {
		ID = 10013791,
		Speaker = "瑟蕾雅",
		Text = "你总是在重要的时候故意让人害羞。",
