	[10013794] = {
		ID = 10013794,
		Speaker = "旁白",
		Text = "风穿过花园，带来泥土与融雪的气息。",
	},
	[10013795] = {
		ID = 10013795,
		Speaker = "瑟蕾雅",
		Text = "小时候，我一直以为春天只是故事里的东西。",
