	},
	[20000004] = {
		ID = 20000004,
		Text = "（就在我踱步等待时，脚边的某个东西吸引了我的注意。)",
	},
	[20000005] = {
		ID = 20000005,
		Text = "（冰面上有个凿好的圆洞，旁边摆着一根有些磨损的钓竿，看起来不像私人物品。）",
	},
	[20000006] = {
