	[20000013] = {
		ID = 20000013,
		Speaker = "我",
		Text = "喔，在这里！",
	},
	[20000014] = {
		ID = 20000014,
		Text = "（瑟蕾雅踏过积雪而来，银白的长发随步伐轻轻甩动，裙摆在雪地上留下一道淡淡的痕迹。）",
