	[20000123] = {
		ID = 20000123,
		Speaker = "瑟蕾雅",
		Text = "咦咦……为什么老是散掉？",
	},
	[20000124] = {
		ID = 20000124,
		Speaker = "我",
		Text = "要一边滚一边压。",
	},
	[20000126] = {
		ID = 20000126,
		Speaker = "瑟蕾雅",
		Text = "啊！成功了——晨星先生你真的好厉害！",
	},
	[20000127] = {
		ID = 20000127,
		Speaker = "我",
		Text = "差不多了，来试着做个人形吧。",
	},
	[20000128] = {
		ID = 20000128,
		Text = "（把几个雪球叠起来，顺手在脸上捏出特征——紧皱的眉头，和不悦的表情。）",
	},
	[20000129] = {
		ID = 20000129,
		Speaker = "瑟蕾雅",
		Text = "咦……咦咦！是迷你的伊丝娜小姐！",
	},
	[20000130] = {
		ID = 20000130,
		Speaker = "瑟蕾雅",
		Text = "好厉害！完全就是那个人的感觉！",
	},
	[20000131] = {
		ID = 20000131,
		Speaker = "我",
		Text = "再来一个。",
	},
	[20000132] = {
		ID = 20000132,
		Speaker = "瑟蕾雅",
		Text = "咦，这个是点灯人小姐，认出来了，那个表情！",
	},
	[20000133] = {
		ID = 20000133,
		Speaker = "瑟蕾雅",
		Text = "那个……这两个人平时大概不知道自己的雪人长这样吧？",
	},
	[20000134] = {
		ID = 20000134,
		Speaker = "瑟蕾雅",
		Text = "可以把他们带回去放在家门口吗？",
	},
	[20000136] = {
		ID = 20000136,
		Speaker = "我",
		Text = "这边这个放着当纪念就好。",
	},
	[20000137] = {
		ID = 20000137,
		Speaker = "瑟蕾雅",
		Text = "下次回来说不定还能再看到它们呢！到时候要帮它们增加更多家人才行！",
	},
	[20000138] = {
		ID = 20000138,
		Speaker = "瑟蕾雅",
		Text = "那我也要做一个——我要做西西！",
	},
	[20000141] = {
		ID = 20000141,
		Speaker = "瑟蕾雅",
		Text = "好了——！这个就是西西！",
	},
	[20000142] = {
		ID = 20000142,
		Text = "（雪人的头上插着小花）",
	},
	[20000143] = {
		ID = 20000143,
		Speaker = "我",
		Text = "这个表情看起来开心过头了吧？",
	},
	[20000144] = {
		ID = 20000144,
		Speaker = "瑟蕾雅",
		Text = "可是西西平时就是这样子的表情吧？",
	},
	[20000145] = {
		ID = 20000145,
		Speaker = "我",
		Text = "跟我印象中的差的有点多，我认识的西西雅可不是这么温柔的。",
	},
	[20000146] = {
		ID = 20000146,
		Speaker = "瑟蕾雅",
		Text = "才不是呢，西西是个很可爱的孩子的。",
	},
	[20000147] = {
		ID = 20000147,
		Speaker = "我",
		Text = "……这个阵容，还是先不让他们看到比较好。",
	},
	[20000148] = {
		ID = 20000148,
		Speaker = "瑟蕾雅",
		Text = "那个……要不要退远一点看全景？这样可以把所有人都看到——咦——！",
	},
	[20000149] = {
		ID = 20000149,
		Speaker = "瑟蕾雅",
		Text = "——呼欸欸！",
	},
	[20000150] = {
		ID = 20000150,
		Text = "（下一秒，瑟蕾雅脚踩上了一块被薄雪盖住的冰面。）",
	},
	[20000151] = {
		ID = 20000151,
		Text = "（整个人失去重心，直直朝我撞上，我没来得及躲，两个人一起往后倒下去。）",
	},
	[20000152] = {
		ID = 20000152,
	},
	[20000153] = {
		ID = 20000153,
		Speaker = "我",
		Text = "这里雪这么多……要不要打个雪仗？",
	},
	[20000154] = {
		ID = 20000154,
		Speaker = "瑟蕾雅",
		Text = "咦？打……打雪仗？听起来很危险？",
	},
	[20000155] = {
		ID = 20000155,
		Speaker = "我",
		Text = "不不，那就只是互丢雪球而已？像这样。",
	},
	[20000156] = {
		ID = 20000156,
		Text = "（我从地板上做出一颗雪球朝瑟蕾雅扔去，击中了瑟蕾雅的肩膀）",
	},
	[20000157] = {
		ID = 20000157,
		Speaker = "瑟蕾雅",
		Text = "哇呀！",
