	[20000158] = {
		ID = 20000158,
		Speaker = "瑟蕾雅",
		Text = "好像挺有趣的，看我的——！",
	},
	[20000159] = {
		ID = 20000159,
		Text = "（第一颗雪球带着点偏斜飞过来，我侧身一让，雪球打散在身后的树干上。）",
	},
	[20000160] = {
		ID = 20000160,
		Speaker = "瑟蕾雅",
		Text = "嘿！",
	},
	[20000161] = {
		ID = 20000161,
		Text = "（第二颗雪球不偏不倚地打在我的脸上）",
	},
	[20000162] = {
		ID = 20000162,
		Speaker = "瑟蕾雅",
		Text = "呼欸欸！ ……晨星先生，有没有受伤啊？雪球会不会太硬？",
