	[20000164] = {
		ID = 20000164,
		Speaker = "瑟蕾雅",
		Text = "都要！ ——哇啊！",
	},
	[20000165] = {
		ID = 20000165,
		Speaker = "我",
		Text = "那怎么好意思让妳兼顾——",
	},
	[20000166] = {
		ID = 20000166,
		Text = "（瑟蕾雅躲在横躺的枯木后方）",
	},
	[20000167] = {
		ID = 20000167,
		Speaker = "我",
		Text = "往那边躲吗？绕一圈就找到妳了。",
	},
	[20000168] = {
		ID = 20000168,
		Speaker = "瑟蕾雅",
		Text = "咦咦咦——看我的！",
	},
	[20000169] = {
		ID = 20000169,
		Text = "（瑟蕾雅开始把各种不成形的雪团扔向我，在空中就散成了白雾。）",
