	[20000170] = {
		ID = 20000170,
		Speaker = "我",
		Text = "嘿呀！看我的炮击！",
	},
	[20000171] = {
		ID = 20000171,
		Speaker = "瑟蕾雅",
		Text = "好冰！我要认真还击了！晨星先生！",
	},
	[20000172] = {
		ID = 20000172,
		Speaker = "瑟蕾雅",
		Text = "嘿咻！",
	},
	[20000174] = {
		ID = 20000174,
		Text = "（那颗雪球在空中划出一道抛物线，砸中我的头顶。）",
	},
	[20000175] = {
		ID = 20000175,
		Text = "（瑟蕾雅先是呆了两秒，然后双手高举，欢呼声在整个林子里都听得见。）",
