	[20000275] = {
		ID = 20000275,
		Speaker = "瑟蕾雅",
		Text = "你！",
	},
	[20000276] = {
		ID = 20000276,
		Speaker = "瑟蕾雅",
		Text = "呜！真是的！亏我还这么担心你！",
	},
	[20000277] = {
		ID = 20000277,
		Text = "（瑟蕾雅的拳头软绵绵的一拳接一拳打在我的胸口）",
	},
	[20000278] = {
		ID = 20000278,
		Text = "(希望之丘附近的雪地。)",
	},
	[20000281] = {
		ID = 20000281,
		Text = "雪地从脚下缓缓延伸，在远处的山丘上勾起一个平缓的坡度。",
	},
	[20000282] = {
		ID = 20000282,
		Text = "瑟蕾雅哼着小曲，手里拉着绳子，连接到身后的雪橇，在雪地上拖行出一条摇摇晃晃的曲线。",
	},
	[20000283] = {
		ID = 20000283,
		Text = "两人在雪地里踩出两条相邻的脚印，迤逦往前走了一段。",
	},
	[20000284] = {
		ID = 20000284,
		Speaker = "瑟蕾雅",
		Text = "晨星先生，您之前有坐过雪橇吗？",
	},
	[20000285] = {
		ID = 20000285,
		Speaker = "我",
		Text = "从来就没有！",
	},
	[20000286] = {
		ID = 20000286,
		Speaker = "瑟蕾雅",
		Text = "欸欸！ ？我们这样子两个人都不会的话真的安全吗？",
	},
	[20000287] = {
		ID = 20000287,
		Speaker = "我",
		Text = "两个新手一起摔，跌起来也比较不孤单，不是吗？",
	},
	[20000288] = {
		ID = 20000288,
		Speaker = "我",
		Text = "再说了，我连空中飞船都会开了，区区冰块上的木头片而已，怎么难的倒我？",
	},
	[20000289] = {
		ID = 20000289,
		Speaker = "瑟蕾雅",
		Text = "说得有道理，好像确实是这样没错呢！",
	},
	[20000290] = {
		ID = 20000290,
		Text = "瑟蕾雅回头，银白色的长发被山丘上的冷风轻轻扬起，落下来又贴回肩膀。",
	},
	[20000291] = {
		ID = 20000291,
		Text = "（瑟蕾雅回头望向山坡的另一端。）",
	},
	[20000292] = {
		ID = 20000292,
		Text = "（满天星空的光辉将两人的倒影拉成细细长长的。）",
	},
	[20000294] = {
		ID = 20000294,
		Speaker = "瑟蕾雅",
		Text = "就好久没有这样子静下心来看着风景了。",
	},
	[20000295] = {
		ID = 20000295,
		Speaker = "瑟蕾雅",
		Text = "这片星空明明就从来没有离开过。",
	},
	[20000296] = {
		ID = 20000296,
		Speaker = "瑟蕾雅",
		Text = "但现在这种心情，还是第一次呢。",
	},
	[20000297] = {
		ID = 20000297,
		Speaker = "我",
		Text = "我们下次来看日出吧，如果是白天的话，这个风景绝对会更漂亮的。",
	},
	[20000298] = {
		ID = 20000298,
		Speaker = "瑟蕾雅",
		Text = "说的也是呢，仔细想想，应该要白天来了，这种天色出门感觉只有我会习惯呢。",
	},
	[20000299] = {
		ID = 20000299,
		Speaker = "瑟蕾雅",
		Text = "啊哈哈——咦！",
	},
	[20000300] = {
		ID = 20000300,
		Speaker = "瑟蕾雅",
		Text = "下次还可以来吗！ ？",
	},
	[20000301] = {
		ID = 20000301,
		Speaker = "我",
		Text = "当然没问题。",
	},
	[20000302] = {
		ID = 20000302,
		Speaker = "瑟蕾雅",
		Text = "太好了，已经开始期待下次了呢～",
	},
	[20000303] = {
		ID = 20000303,
		Speaker = "我",
		Text = "先好好享受这次吧！",
	},
	[20000305] = {
		ID = 20000305,
		Text = "（瑟蕾雅拉起控制雪橇的绳子）",
	},
	[20000306] = {
		ID = 20000306,
		Speaker = "瑟蕾雅",
		Text = "靠着一两根绳子真的有办法控制方向吗？",
	},
	[20000307] = {
		ID = 20000307,
		Speaker = "我",
		Text = "相信古人的智慧吧，他们能活这么久绝对不是没道理的吧？",
	},
	[20000308] = {
		ID = 20000308,
		Speaker = "瑟蕾雅",
		Text = "说的也是呢。",
	},
	[20000309] = {
		ID = 20000309,
	},
	[20000310] = {
		ID = 20000310,
		Text = "（转场表示时间推移）",
	},
	[20000311] = {
		ID = 20000311,
		Speaker = "我",
		Text = "呼，总算到坡顶了，这边应该就没有问题了吧？",
	},
	[20000315] = {
		ID = 20000315,
		Text = "（瑟蕾雅愣在原地）",
	},
	[20000317] = {
		ID = 20000317,
		Text = "（瑟蕾雅揉了揉自己有点肉的小腹）",
	},
	[20000318] = {
		ID = 20000318,
		Text = "(希望之丘附近的雪地。)",
	},
	[20000321] = {
		ID = 20000321,
		Text = "雪地从脚下缓缓延伸，在远处的山丘上勾起一个平缓的坡度。",
	},
	[20000322] = {
		ID = 20000322,
		Speaker = "我",
		Text = "要上了喔！",
	},
	[20000323] = {
		ID = 20000323,
		Speaker = "瑟蕾雅",
		Text = "好的，我抓紧了！",
	},
	[20000324] = {
		ID = 20000324,
		Text = "虽然坡度趋于平缓，但瑟蕾雅还是在我背后紧紧的抱住了我的腰。",
	},
	[20000325] = {
		ID = 20000325,
		Text = "两坨过于沉重的东西压得我喘不过气。",
	},
	[20000326] = {
		ID = 20000326,
		Text = "（我用力蹬了地——雪橇不情愿地挪动了一下，然后停住了。）",
	},
	[20000327] = {
		ID = 20000327,
		Speaker = "瑟蕾雅",
		Text = "咦？它不滑吗？",
	},
	[20000328] = {
		ID = 20000328,
		Speaker = "我",
		Text = "像这种坡度的话，大概要等到我们变冰块才有可能动喔。",
	},
	[20000329] = {
		ID = 20000329,
		Text = "（瑟蕾雅的身子往前蹬两下，雪橇只在原地扭动，丝毫没有要前进的意思。）",
	},
	[20000330] = {
		ID = 20000330,
		Speaker = "我",
		Text = "坡度不太够，我们还是往更陡一点的地方试试吧。",
	},
	[20000331] = {
		ID = 20000331,
		Speaker = "瑟蕾雅",
		Text = "呼欸欸？那样不会很危险吗？",
	},
	[20000332] = {
		ID = 20000332,
		Speaker = "瑟蕾雅",
		Text = "总感觉那样很可怕，速度太快的话不会失控吗？",
	},
	[20000333] = {
		ID = 20000333,
		Text = "（瑟蕾雅抬头望向山坡顶。）",
	},
	[20000336] = {
		ID = 20000336,
		Speaker = "我",
		Text = "顺便让瑟蕾雅多习惯一下坐在雪橇上的感觉。",
	},
	[20000337] = {
		ID = 20000337,
		Speaker = "瑟蕾雅",
		Text = "真的没问题吗？",
	},
	[20000338] = {
		ID = 20000338,
		Speaker = "瑟蕾雅",
		Text = "那就麻烦您了。",
	},
	[20000339] = {
		ID = 20000339,
		Text = "（瑟蕾雅乘着雪橇，缓慢地被我往山丘上推去。）",
	},
	[20000340] = {
