	},
	[20000375] = {
		ID = 20000375,
		Speaker = "我",
		Text = "感觉从这边到坡顶天都要亮了。",
	},
	[20000376] = {
		ID = 20000376,
		Speaker = "瑟蕾雅",
		Text = "咦——！我还真的没有想过这个问题。",
	},
	[20000379] = {
		ID = 20000379,
		Speaker = "瑟蕾雅",
		Text = "晨星先生有时候会说出让人难以理解的词呢。",
	},
	[20000380] = {
		ID = 20000380,
		Text = "（两人正陷入沉默、各自盯着那条白色坡道的当下，雪地里忽然传来轻快的踩踏声）",
	},
	[20000381] = {
		ID = 20000381,
		Text = "（两只一黑一白博美犬像两颗蓬松的棉花球从坡道旁窜出来。）",
	},
	[20000382] = {
		ID = 20000382,
		Text = "（桃粉色的小舌头吐在外面，摇着尾巴跑得浑身毛发抖动。）",
	},
	[20000383] = {
		ID = 20000383,
		Speaker = "瑟蕾雅",
		Text = "咦咦！ ？伊尔瓦小姐的狼——！",
	},
	[20000384] = {
		ID = 20000384,
		Speaker = "我",
		Text = "……喔？",
	},
	[20000385] = {
		ID = 20000385,
		Speaker = "我",
		Text = "那个……我有个不一定行得通的想法。",
	},
	[20000386] = {
		ID = 20000386,
		Speaker = "我",
		Text = "让它们咬住绳子，把我们两个拖上山。",
	},
	[20000387] = {
		ID = 20000387,
		Speaker = "瑟蕾雅",
		Text = "咦……那个，狼……听得懂我们说话吗？",
	},
	[20000388] = {
		ID = 20000388,
		Speaker = "我",
		Text = "嘿，你们两个——能不能咬住这条绳子，带我们上那个坡？",
	},
	[20000389] = {
		ID = 20000389,
		Text = "（两只博美犬同时停下脚步，歪头盯着绳子看了看，又互相对了一眼——。）",
	},
	[20000390] = {
		ID = 20000390,
		Text = "（然后其中一只叼起了绳头，另一只紧跟着咬住另一条绳子。）",
	},
	[20000391] = {
		ID = 20000391,
		Text = "（它们摇着尾巴，看样子像是完全听懂了）",
	},
	[20000392] = {
		ID = 20000392,
		Speaker = "瑟蕾雅",
		Text = "……它们、它们听懂了！ ！",
	},
	[20000393] = {
		ID = 20000393,
		Speaker = "我",
		Text = "坐上去吧。",
	},
	[20000394] = {
		ID = 20000394,
		Speaker = "瑟蕾雅",
		Text = "真、真的吗……？那个，它们真的拉得动吗……？",
	},
	[20000395] = {
		ID = 20000395,
		Speaker = "我",
		Text = "两位，拜托了——出发。",
	},
	[20000396] = {
		ID = 20000396,
		Speaker = "瑟蕾雅",
		Text = "咦咦咦咦咦——！ ！",
	},
	[20000397] = {
		ID = 20000397,
		Text = "（两只小狗高速挥动短腿在雪地中破开一条路，瑟蕾雅的白发和头巾在空中飘扬。）",
	},
	[20000398] = {
		ID = 20000398,
		Speaker = "我",
		Text = "哈——比我想的快上不少。",
	},
	[20000399] = {
		ID = 20000399,
		Speaker = "瑟蕾雅",
		Text = "怎么可以这么快！ ？狼可以这么有力气吗！ ？",
	},
	[20000400] = {
		ID = 20000400,
		Speaker = "瑟蕾雅",
		Text = "啊——！",
	},
	[20000401] = {
		ID = 20000401,
		Speaker = "瑟蕾雅",
		Text = "到山顶了！ ！到山顶了！ ！",
	},
	[20000402] = {
		ID = 20000402,
		Text = "（雪橇在山顶来了一个华丽的大甩尾，随后稳稳的停住了。）",
	},
	[20000403] = {
		ID = 20000403,
		Text = "（其中一只开心地跳到瑟蕾雅的身上猛蹭，随后便和伙伴一起跑走了。）",
	},
	[20000404] = {
		ID = 20000404,
		Speaker = "我",
		Text = "谢啦两位，回去再请你们吃肉！",
	},
	[20000407] = {
		ID = 20000407,
		Text = "（瑟蕾雅揉了揉自己有点肉的小腹）",
	},
	[20000409] = {
		ID = 20000409,
		Speaker = "我",
		Text = "你这个问题让我很难做人呢。",
	},
	[20000410] = {
		ID = 20000410,
		Speaker = "瑟蕾雅",
		Text = "咦耶！为什么！",
	},
	[20000411] = {
		ID = 20000411,
		Speaker = "我",
		Text = "当女生问出这种问题的时候。",
	},
	[20000412] = {
		ID = 20000412,
		Speaker = "我",
		Text = "回答轻了，就像是在说谎。",
	},
	[20000413] = {
		ID = 20000413,
		Speaker = "我",
		Text = "回答重了，那就彻底完蛋了。",
	},
	[20000414] = {
		ID = 20000414,
		Speaker = "瑟蕾雅",
		Text = "仔细想想确实是这样呢。",
	},
	[20000415] = {
		ID = 20000415,
		Speaker = "瑟蕾雅",
		Text = "女孩子真是神奇的生物呢。",
	},
	[20000416] = {
		ID = 20000416,
		Speaker = "我",
		Text = "……",
	},
	[20000417] = {
		ID = 20000417,
		Speaker = "瑟蕾雅",
		Text = "那个，我想再多问一步。",
	},
	[20000418] = {
		ID = 20000418,
		Speaker = "我",
		Text = "哦？",
	},
	[20000419] = {
		ID = 20000419,
		Speaker = "瑟蕾雅",
		Text = "如果你说「不重」，那就是在说谎，对吗？",
	},
	[20000421] = {
		ID = 20000421,
		Speaker = "瑟蕾雅",
		Text = "但如果你说「不重」，而且你确实那么觉得……",
	},
	[20000422] = {
		ID = 20000422,
		Speaker = "瑟蕾雅",
		Text = "那不就是……那个，你说谎反而才是真话……",
	},
	[20000423] = {
		ID = 20000423,
		Speaker = "瑟蕾雅",
		Text = "咦咦咦？等等我说了什么？",
	},
	[20000424] = {
		ID = 20000424,
		Speaker = "我",
		Text = "妳在自己把自己绕进去呢。",
	},
	[20000425] = {
		ID = 20000425,
		Speaker = "瑟蕾雅",
		Text = "啊啊啊，对对对……",
	},
	[20000426] = {
