	},
	[20000893] = {
		ID = 20000893,
		Text = "（黑画面表示时间推移）",
	},
	[20000894] = {
		ID = 20000894,
		Speaker = "我",
		Text = "现在有了火……就可以解决下一个问题了。",
	},
	[20000896] = {
		ID = 20000896,
		Speaker = "瑟蕾雅",
		Text = "不在身上……",
	},
	[20000898] = {
		ID = 20000898,
		Speaker = "瑟蕾雅",
		Text = "脱……脱掉？",
	},
	[20000899] = {
		ID = 20000899,
		Speaker = "瑟蕾雅",
		Text = "又要脱光光了吗？",
	},
	[20000903] = {
		ID = 20000903,
		Speaker = "瑟蕾雅",
		Text = "我、我也背对你！ ！",
	},
	[20000904] = {
		ID = 20000904,
	},
	[20000905] = {
		ID = 20000905,
		Text = "（天空飘落着缓缓的细雪，只有一点火光中山洞中透出，在雪原中格外显眼。）",
	},
	[20000908] = {
		ID = 20000908,
		Speaker = "瑟蕾雅",
		Text = "那个……晨星先生，有没有哪里不舒服？有受伤吗？冰水很冷的，有没有呛到……？",
	},
	[20000909] = {
		ID = 20000909,
		Text = "（瑟蕾雅用头巾把自己裹紧了一点，视线越过火堆过来，眼神带着某种担忧的认真。）",
	},
	[20000910] = {
		ID = 20000910,
		Speaker = "我",
		Text = "没事，还好只是滚进了河里面？瑟蕾雅也没事吧？",
	},
	[20000911] = {
		ID = 20000911,
		Speaker = "瑟蕾雅",
		Text = "我……我也没事！不过晨星先生真的确定吗？有时候撞到冰层之后不会马上感觉到的……",
	},
	[20000912] = {
		ID = 20000912,
		Speaker = "我",
		Text = "真的没事的，等衣服干了我们再离开这个洞窟就好了。",
	},
	[20000914] = {
		ID = 20000914,
		Speaker = "我",
		Text = "怎么能算妳的错？",
	},
	[20000916] = {
		ID = 20000916,
		Speaker = "我",
		Text = "现在说这些都没用了，别想太多。",
	},
	[20000917] = {
		ID = 20000917,
		Speaker = "我",
		Text = "玩得开心吗？",
	},
	[20000918] = {
		ID = 20000918,
		Speaker = "瑟蕾雅",
		Text = "这个……不是很确定……应该……很开心吧……",
	},
	[20000921] = {
		ID = 20000921,
		Speaker = "瑟蕾雅",
		Text = "那个……那是应该的嘛！不管换了谁都会回去拉的……",
	},
	[20000922] = {
		ID = 20000922,
		Speaker = "我",
		Text = "怎么，不能说谢谢？",
	},
	[20000923] = {
		ID = 20000923,
		Speaker = "瑟蕾雅",
		Text = "不是这样的！只是……只是这样说的话……咦？我的脸为什么这么热……？",
	},
	[20000924] = {
		ID = 20000924,
		Speaker = "我",
		Text = "只是你靠火太近了吧？",
	},
	[20000925] = {
		ID = 20000925,
		Speaker = "瑟蕾雅",
		Text = "不是靠火太近！就是……啊！也许确实是靠太近了？对对对，就是那个原因……",
	},
	[20000926] = {
		ID = 20000926,
		Speaker = "我",
		Text = "嗯？",
	},
	[20000927] = {
		ID = 20000927,
		Speaker = "瑟蕾雅",
		Text = "咿！晨星先生你为什么用那种眼神看我！",
	},
	[20000928] = {
		ID = 20000928,
		Text = "（瑟蕾雅尝试用头巾把自己的上半身包住。）",
	},
	[20000929] = {
		ID = 20000929,
		Speaker = "我",
		Text = "妳还在发抖。",
	},
	[20000930] = {
		ID = 20000930,
		Speaker = "瑟蕾雅",
		Text = "没有！没有在发抖！就是……就是稍微、一点点……",
	},
	[20000931] = {
		ID = 20000931,
		Speaker = "瑟蕾雅",
		Text = "啊……那个……那个……",
	},
	[20000932] = {
		ID = 20000932,
		Speaker = "瑟蕾雅",
		Text = "要不要做点运动，说不定就会暖活起来了？",
	},
	[20000933] = {
		ID = 20000933,
		Speaker = "我",
		Text = "运动？在这种地方能做什么运动？",
	},
	[20000934] = {
		ID = 20000934,
		Speaker = "瑟蕾雅",
		Text = "那个……那个……",
	},
	[20000936] = {
		ID = 20000936,
		Text = "（瑟蕾雅的声音越来越小）",
	},
	[20000937] = {
		ID = 20000937,
		Speaker = "我",
		Text = "嗯？我听不清楚喔？",
	},
	[20000939] = {
		ID = 20000939,
		Speaker = "我",
		Text = "我开玩笑的，我当然知道瑟蕾雅讲的是什么。",
	},
	[20000941] = {
		ID = 20000941,
		Speaker = "我",
		Text = "真是让人想不到，瑟蕾雅居然这么好色，想要在外面做吗？",
	},
	[20000943] = {
		ID = 20000943,
		Text = "（我将瑟蕾雅的腿往上抬起，让瑟蕾雅变为侧躺着的姿势）",
	},
	[20000944] = {
		ID = 20000944,
		Speaker = "我",
		Text = "只是被看着裸体就可以湿成这样了吗？",
	},
	[20000945] = {
		ID = 20000945,
		Speaker = "我",
		Text = "瑟蕾雅还真是个不得了的变态。",
	},
	[20000947] = {
		ID = 20000947,
		Speaker = "瑟蕾雅",
		Text = "那是河水，才不是那种东西。",
	},
	[20000948] = {
		ID = 20000948,
		Speaker = "我",
		Text = "河水怎么可能会是这种滑滑的触感。",
	},
	[20000949] = {
		ID = 20000949,
		Speaker = "我",
		Text = "就让我代替女神，给你这个爱说谎的圣女一点惩罚吧。",
	},
	[20000950] = {
		ID = 20000950,
		Text = "（转场，插入CG）",
