	},
	[20000953] = {
		ID = 20000953,
		Speaker = "瑟蕾雅",
		Text = "晨星先生的肉棒，在这种野外，插进来了。",
	},
	[20000954] = {
		ID = 20000954,
		Speaker = "我",
		Text = "连里面都湿成这样还敢说是河水吗。",
	},
	[20000956] = {
		ID = 20000956,
		Speaker = "瑟蕾雅",
		Text = "像这样子，全身都热起来了。",
	},
	[20000958] = {
