		Speaker = "李奥纳多",
		Text = "啾！",
	},
	[20002042] = {
		ID = 20002042,
		Speaker = "黛莉亚",
		Text = "我只是想帮它们补充能量……",
	},
	[20002043] = {
		ID = 20002043,
		Speaker = "我",
		Text = "我站李奥纳多那边。",
	},
	[20002044] = {
		ID = 20002044,
		Speaker = "黛莉亚",
		Text = "不是你说要喂鸡油的吗？不然应该喂什么？",
