		ID = 20002400,
		Speaker = "黛莉亚",
		Text = "舰长先生这样......射在人家的屁股上跟背后......",
	},
	[20002401] = {
		ID = 20002401,
		Speaker = "黛莉亚",
		Text = "刚刚的澡不都白洗了吗......？",
	},
	[20002402] = {
		ID = 20002402,
		Speaker = "黛莉亚",
		Text = "既然等等还要洗澡，那就......轮到我进攻了喔？",
	},
	[20002403] = {
		ID = 20002403,
		Speaker = "黛莉亚",
		Text = "到时候，你可不要求饶......哈啊......",
	},
	[20002404] = {
		ID = 20002404,
		Text = "黛莉亚约会系统占位CG3-6",
	},
	[20002405] = {
		ID = 20002405,
		Text = "黛莉亚约会系统占位CG3-7",
	},
	[20002406] = {
		ID = 20002406,
		Text = "黛莉亚约会系统占位CG3-8",
