	[20002407] = {
		ID = 20002407,
		Text = "黛莉亚约会系统占位CG3-9",
	},
	[20002408] = {
		ID = 20002408,
	},
	[20002409] = {
		ID = 20002409,
		Text = "（下午时分，为了补充飞船上的物资，我们靠近了像是休息站点的星球。）",
	},
	[20002410] = {
		ID = 20002410,
		Speaker = "黛莉亚",
		Text = "那两个……靠个岸而已，跑这么快干什么啊！",
	},
	[20002411] = {
		ID = 20002411,
		Speaker = "我",
		Text = "秋比说想要去找会爆炸的东西一溜烟得就跑掉了。",
	},
	[20002412] = {
		ID = 20002412,
		Speaker = "我",
		Text = "伊丝娜则是害怕我们背上天价罚款，所以急忙地追了上去。",
	},
	[20002413] = {
		ID = 20002413,
		Speaker = "黛莉亚",
		Text = "难得停靠，也不问一下我这边需不需要人手！",
	},
	[20002414] = {
		ID = 20002414,
		Speaker = "黛莉亚",
		Text = "……算了！反正我本来就打算今天在船上做一次完整的检修！趁人少安静的时候做最好！",
	},
	[20002415] = {
		ID = 20002415,
		Speaker = "黛莉亚",
		Text = "况且，适时地下船走走才不会把身体闷坏。",
	},
	[20002416] = {
		ID = 20002416,
		Speaker = "我",
		Text = "那我也留下来帮你。",
	},
	[20002417] = {
		ID = 20002417,
		Speaker = "黛莉亚",
		Text = "欸？舰长先生？但是……难得靠岸，不也去外面逛一逛吗？",
	},
	[20002418] = {
		ID = 20002418,
		Speaker = "我",
		Text = "也该偶尔关心一下自己的船还有我可爱的船员了。",
	},
	[20002419] = {
		ID = 20002419,
		Speaker = "黛莉亚",
		Text = "……这样说倒也没错啦。",
	},
	[20002420] = {
		ID = 20002420,
		Speaker = "黛莉亚",
		Text = "好！那舰长先生今天就跟着我！主要工作是帮我拿工具！",
	},
	[20002421] = {
		ID = 20002421,
		Speaker = "我",
		Text = "了解！从哪里开始？",
	},
	[20002422] = {
		ID = 20002422,
		Speaker = "黛莉亚",
		Text = "这几天我一直觉得空气系统有一点怪怪的。",
	},
	[20002423] = {
		ID = 20002423,
		Speaker = "黛莉亚",
		Text = "我们去看看吧！",
	},
	[20002424] = {
		ID = 20002424,
	},
	[20002425] = {
		ID = 20002425,
		Text = "（黛莉亚的上半身钻进了管道内，里面传来阵阵拆装机械的声响。）",
	},
	[20002426] = {
		ID = 20002426,
		Speaker = "黛莉亚",
		Text = "舰长先生！帮我拿一下那个！",
	},
	[20002427] = {
		ID = 20002427,
	},
	[20002428] = {
		ID = 20002428,
		Text = "（清晨，我仍蜷在大床铺上，毯子滑到腰际。窗缝里透着稀薄的光，天色刚亮。）",
	},
	[20002429] = {
		ID = 20002429,
		Speaker = "黛莉亚",
		Text = "舰长先生！",
	},
	[20002430] = {
		ID = 20002430,
		Speaker = "黛莉亚",
		Text = "舰长先生！舰长先生！快起床了！ ！",
	},
	[20002431] = {
		ID = 20002431,
		Speaker = "我",
		Text = "……嗯？",
	},
	[20002432] = {
		ID = 20002432,
		Speaker = "黛莉亚",
		Text = "我等了好久了欸！你怎么睡到现在啊！",
	},
	[20002433] = {
		ID = 20002433,
		Speaker = "我",
		Text = "黛莉亚……现在是几点？",
	},
	[20002434] = {
		ID = 20002434,
