	[20003122] = {
		ID = 20003122,
		Speaker = "耶珥",
		Text = "那还真有趣呢。",
	},
	[20003123] = {
		ID = 20003123,
		Speaker = "耶珥",
		Text = "世上的事，很多时候都只是巧合，可谓命运的安排呢。",
	},
	[20003124] = {
		ID = 20003124,
		Speaker = "我",
		Text = "这话听起来更让我不放心。",
	},
	[20003125] = {
		ID = 20003125,
		Speaker = "耶珥",
		Text = "呵呵……放轻松，少年。这片林子有什么值得妾身特地设局的？",
	},
	[20003126] = {
		ID = 20003126,
		Speaker = "我",
		Text = "施法阵？祭祀什么上古邪神？",
	},
	[20003127] = {
		ID = 20003127,
		Speaker = "耶珥",
		Text = "哈……少年的想像力确实丰富。",
	},
	[20003128] = {
		ID = 20003128,
		Speaker = "我",
		Text = "我觉得这些都不是不可能。",
	},
	[20003129] = {
		ID = 20003129,
		Speaker = "耶珥",
		Text = "真麻烦呢，那些事情下星期再做吧？",
	},
	[20003130] = {
		ID = 20003130,
		Speaker = "耶珥",
		Text = "既然你「刚好路过」了，不如......？",
	},
	[20003131] = {
		ID = 20003131,
		Speaker = "耶珥",
		Text = "我正在采一些草药，强壮的少年就来帮帮弱女子吧。",
	},
	[20003132] = {
		ID = 20003132,
		Speaker = "我",
		Text = "这话从你嘴里说出来，有点缺乏说服力。",
	},
	[20003133] = {
		ID = 20003133,
		Speaker = "耶珥",
		Text = "妾身就当作你同意啰。",
	},
	[20003134] = {
		ID = 20003134,
		Speaker = "我",
		Text = "......",
	},
	[20003135] = {
		ID = 20003135,
		Speaker = "耶珥",
		Text = "总之在这个区域，有一种长得像是这种样子的草，多帮我找一点来吧。",
	},
	[20003136] = {
		ID = 20003136,
		Text = "(耶珥递给我一张发黄的纸张，上面印着一种五片叶子的草。)",
	},
	[20003137] = {
		ID = 20003137,
		Speaker = "我",
		Text = "这种草我见都没见过。",
	},
	[20003138] = {
		ID = 20003138,
		Speaker = "耶珥",
		Text = "走多了就会看到了，还是——",
	},
	[20003139] = {
		ID = 20003139,
		Speaker = "耶珥",
		Text = "你想牵着妾身的手呢？让大姊姊带你一步一步去找呢？",
	},
	[20003140] = {
		ID = 20003140,
		Speaker = "我",
		Text = "总感觉像是在被牵着鼻子走......",
	},
	[20003141] = {
		ID = 20003141,
		Speaker = "耶珥",
		Text = "少年在说什么，妾身没听懂呦。",
	},
	[20003142] = {
		ID = 20003142,
		Speaker = "我",
		Text = "……算了。",
	},
	[20003143] = {
		ID = 20003143,
		Text = "（结果我还是跟了上去，不是因为真的信了她说的「只是散步。）",
	},
	[20003144] = {
		ID = 20003144,
		Text = "（而是不跟反而​​不知道她在打什么算盘——至少保持在视线范围之内，要掌握主动一点。",
	},
	[20003145] = {
		ID = 20003145,
		Text = "（ ……话虽如此，她走起路来比我想像中从容多了，就好像真的在散步一样。）",
	},
	[20003146] = {
		ID = 20003146,
		Speaker = "耶珥",
		Text = "好啦，我可爱的少年，快点跟上吧，这条林中步道可是很舒服的。",
