	[20003521] = {
		ID = 20003521,
		Speaker = "我",
		Text = "我这不是顾全你的采药大计吗。白追了多可惜。",
	},
	[20003522] = {
		ID = 20003522,
		Speaker = "耶珥",
		Text = "……算了，今日就让它多活两天吧，那东西的生命力很强韧，迟早会回到洞窟的。",
	},
	[20003523] = {
		ID = 20003523,
		Speaker = "我",
		Text = "看来是失败了......倒是耶珥你......",
	},
	[20003524] = {
		ID = 20003524,
		Speaker = "耶珥",
		Text = "有点透气呢。",
	},
	[20003525] = {
		ID = 20003525,
		Speaker = "我",
		Text = "你的屁股整个都露出来了！你的衣服！",
