	[20003823] = {
		ID = 20003823,
		Text = "黑画面转场",
	},
	[20003824] = {
		ID = 20003824,
		Speaker = "我",
		Text = "非常的适合呢！",
	},
	[20003825] = {
		ID = 20003825,
		Speaker = "伊丝娜",
		Text = "喔？",
	},
	[20003826] = {
		ID = 20003826,
		Speaker = "伊丝娜",
		Text = "称赞一个女生说非常适合兔女郎装。",
	},
	[20003827] = {
		ID = 20003827,
		Speaker = "伊丝娜",
		Text = "这不是活脱脱的性骚扰吗？",
	},
	[20003828] = {
		ID = 20003828,
		Speaker = "伊丝娜",
		Text = "哼！别以为这样就会让我开心了！",
	},
	[20003829] = {
		ID = 20003829,
		Speaker = "我",
		Text = "学姊看起来非常的开心没错啊。",
	},
	[20003830] = {
		ID = 20003830,
		Speaker = "伊丝娜",
		Text = "少废话，那是灯光给你带来的错觉。",
	},
	[20003831] = {
		ID = 20003831,
		Speaker = "伊丝娜",
		Text = "总之快坐下！既然都来了，就好好让我展示一下什么叫正确的酒吧文化！",
	},
	[20003832] = {
		ID = 20003832,
		Text = "黑画面转场",
	},
	[20003833] = {
		ID = 20003833,
		Speaker = "我",
		Text = "这样穿看起来和平时差很多呢。",
	},
	[20003834] = {
		ID = 20003834,
		Speaker = "伊丝娜",
		Text = "肯定差很多，这是我特别挑的。",
	},
	[20003835] = {
		ID = 20003835,
		Speaker = "伊丝娜",
		Text = "今天心情好，可以让你再多称赞我一些。",
	},
	[20003836] = {
		ID = 20003836,
		Speaker = "我",
		Text = "学姊穿这套衣服，感觉胸部特别的显眼，腰特别细，还有高衩的关系——",
	},
	[20003837] = {
		ID = 20003837,
		Speaker = "我",
		Text = "屁股看起来特别大呢，真的很好看！",
	},
	[20003838] = {
		ID = 20003838,
		Speaker = "伊丝娜",
		Text = "你这家伙在湖说些什么鬼话呀！",
	},
	[20003839] = {
		ID = 20003839,
		Speaker = "伊丝娜",
		Text = "这完全就是性骚扰！",
	},
	[20003840] = {
		ID = 20003840,
		Speaker = "伊丝娜",
		Text = "你这家伙！这些想法在心里面想想就好，千万不要给我说出来！",
	},
	[20003841] = {
		ID = 20003841,
		Speaker = "伊丝娜",
		Text = "就算要说，也只对着我说就好！",
	},
	[20003842] = {
		ID = 20003842,
		Speaker = "伊丝娜",
		Text = "真是的！",
	},
	[20003843] = {
		ID = 20003843,
		Speaker = "伊丝娜",
		Text = "你这种说话方式，哪天被警察给抓走都不奇怪！",
	},
	[20003844] = {
		ID = 20003844,
		Text = "（伊丝娜的脸红到耳根，别过头去。）",
	},
	[20003845] = {
		ID = 20003845,
		Speaker = "伊丝娜",
		Text = "总之快坐下！既然都来了，就好好让我展示一下什么叫正确的酒吧文化！",
	},
	[20003846] = {
		ID = 20003846,
	},
	[20003847] = {
		ID = 20003847,
		Speaker = "我",
		Text = "便宜的啤酒就好了。",
	},
	[20003848] = {
		ID = 20003848,
		Speaker = "伊丝娜",
		Text = "……什么？",
	},
	[20003849] = {
		ID = 20003849,
		Speaker = "伊丝娜",
		Text = "你说便宜的啤酒？",
	},
	[20003850] = {
		ID = 20003850,
		Speaker = "伊丝娜",
		Text = "后辈，你确定？",
	},
	[20003851] = {
		ID = 20003851,
		Speaker = "我",
		Text = "对啊，味道差不多嘛。",
	},
	[20003852] = {
		ID = 20003852,
		Speaker = "伊丝娜",
		Text = "不对吧。差很多好吗！",
	},
	[20003853] = {
		ID = 20003853,
		Speaker = "伊丝娜",
		Text = "你知道那种东西是什么概念吗？喝那种便宜货，怎么对得起自己的身分？",
	},
	[20003854] = {
		ID = 20003854,
		Speaker = "我",
		Text = "我的身分……就是个普通后辈啊。",
	},
	[20003855] = {
		ID = 20003855,
		Speaker = "伊丝娜",
		Text = "所以你更要讲究！",
	},
	[20003856] = {
		ID = 20003856,
		Speaker = "伊丝娜",
		Text = "品味是从日常的选择里养出来的。",
	},
	[20003857] = {
		ID = 20003857,
		Speaker = "伊丝娜",
		Text = "在底层生活的社畜如果日复一日喝着廉价的啤酒，那就永远都只能是社畜了！",
	},
	[20003858] = {
		ID = 20003858,
		Speaker = "我",
		Text = "现实......这么残酷的吗？",
	},
	[20003859] = {
		ID = 20003859,
		Speaker = "我",
		Text = "那不如这样？",
	},
	[20003860] = {
		ID = 20003860,
		Speaker = "我",
		Text = "学姊你喝酒的阅历肯定比我丰富多了，要不要帮我挑一杯？",
	},
	[20003861] = {
		ID = 20003861,
		Speaker = "伊丝娜",
		Text = "……什么？",
	},
	[20003862] = {
		ID = 20003862,
		Speaker = "伊丝娜",
		Text = "等等，你说……让我帮你挑？",
	},
	[20003863] = {
		ID = 20003863,
		Text = "（她的动作顿了一下。手指抬起来碰了碰浏海，又放下——）",
	},
	[20003864] = {
		ID = 20003864,
		Speaker = "伊丝娜",
		Text = "也……也不是不行啦。",
	},
	[20003865] = {
		ID = 20003865,
		Speaker = "伊丝娜",
		Text = "我确实比你有经验，这一点不需要你提醒。",
	},
	[20003866] = {
		ID = 20003866,
		Speaker = "我",
		Text = "那就麻烦学姊了。",
	},
	[20003867] = {
		ID = 20003867,
		Speaker = "伊丝娜",
		Text = "胡说八道，谁说要麻烦我了。",
	},
	[20003868] = {
		ID = 20003868,
		Speaker = "伊丝娜",
		Text = "真是拿你没办法……",
	},
	[20003869] = {
		ID = 20003869,
		Speaker = "我",
		Text = "喔？学姊你刚才是在笑吗？",
	},
	[20003870] = {
		ID = 20003870,
		Speaker = "伊丝娜",
		Text = "我有吗！我没有！",
	},
	[20003871] = {
		ID = 20003871,
		Speaker = "伊丝娜",
		Text = "安静一下，让我想。",
	},
	[20003872] = {
		ID = 20003872,
		Text = "（我看着她低头调酒——冰块、一点透明的基底、再加几滴颜色深一些的甜酒——）",
	},
	[20003873] = {
		ID = 20003873,
		Speaker = "伊丝娜",
		Text = "好了。",
	},
	[20003874] = {
		ID = 20003874,
		Text = "（学姊把一杯透着粉橘色的鸡尾酒推到我面前。）",
	},
	[20003875] = {
		ID = 20003875,
		Speaker = "伊丝娜",
		Text = "甜的，你应该喝得惯。比你说的那什么便宜啤酒好喝一百倍。",
	},
	[20003876] = {
		ID = 20003876,
		Speaker = "我",
		Text = "……学姊帮我想得挺仔细的嘛。",
	},
	[20003877] = {
		ID = 20003877,
		Speaker = "伊丝娜",
		Text = "别误会，我只是不想让人说我调的酒不好喝。",
	},
	[20003878] = {
		ID = 20003878,
		Speaker = "伊丝娜",
		Text = "快喝看看，别忘了告诉我心得。",
	},
	[20003879] = {
		ID = 20003879,
	},
	[20003880] = {
		ID = 20003880,
		Speaker = "伊丝娜",
		Text = "后辈，你想喝什么？这里种类还算齐全，轻的重的都有，说说看。",
	},
	[20003881] = {
		ID = 20003881,
		Speaker = "我",
		Text = "不然就那个，最高的那支。",
	},
	[20003882] = {
		ID = 20003882,
		Speaker = "伊丝娜",
		Text = "……等等，你说的是哪一支？",
	},
	[20003883] = {
		ID = 20003883,
		Speaker = "我",
		Text = "就那支。看起来最贵的那个。",
	},
	[20003884] = {
		ID = 20003884,
		Speaker = "伊丝娜",
		Text = "你确定吗？那是这个航程从蒸气蒸馏厂直送的稀酿，通常只有对烈酒有研究的行家才会点。",
	},
	[20003885] = {
		ID = 20003885,
		Speaker = "伊丝娜",
		Text = "你压根不知道这是什么的话，为什么它会在你的船上啊？",
	},
	[20003886] = {
		ID = 20003886,
		Speaker = "我",
		Text = "好问题，说不定曾经我的船上有很喜欢喝酒的同伴？",
	},
	[20003887] = {
		ID = 20003887,
		Speaker = "我",
		Text = "总之，酒听起来很不得了。那就它了，学姊。",
	},
	[20003888] = {
		ID = 20003888,
		Speaker = "伊丝娜",
		Text = "……啧，好，你说的。",
	},
	[20003889] = {
		ID = 20003889,
		Speaker = "伊丝娜",
		Text = "我从来没开过这么贵的酒，总感觉应该要更有仪式感一点才对。",
	},
	[20003890] = {
		ID = 20003890,
		Speaker = "我",
		Text = "这次就当作练习吧，下次我们一起去真的酒吧。",
	},
	[20003891] = {
		ID = 20003891,
		Speaker = "伊丝娜",
		Text = "后辈你还真有几分眼光——第一次来酒吧，上来就挑整架最贵的那支，我算是见识到了。",
	},
	[20003892] = {
		ID = 20003892,
		Speaker = "我",
		Text = "喔？学姊是在夸我？",
	},
	[20003893] = {
		ID = 20003893,
		Speaker = "伊丝娜",
		Text = "我只是在陈述事实，不要理解歪了。",
	},
	[20003894] = {
		ID = 20003894,
		Speaker = "我",
		Text = "那我喝了。",
	},
	[20003895] = {
		ID = 20003895,
		Text = "（端起杯，往里面闻了一下——气味很冲，带着蒸气机油和熏木的混合味道）",
	},
	[20003896] = {
		ID = 20003896,
		Text = "（我喝了一口。入喉的瞬间像有什么东西在舌根点了一把火，沿着喉咙一路烫到胸口。）",
	},
	[20003897] = {
		ID = 20003897,
		Speaker = "我",
		Text = "……嗯。有点，难以入口。",
	},
	[20003898] = {
		ID = 20003898,
		Speaker = "伊丝娜",
		Text = "你说它难以入口？",
	},
	[20003899] = {
		ID = 20003899,
		Speaker = "我",
		Text = "嗯。很烈，而且辣。",
	},
	[20003900] = {
		ID = 20003900,
		Speaker = "伊丝娜",
