	[30000001] = {
		ID = 30000001,
		Speaker = "瑟蕾雅",
		Text = "晨星先生！您也懂分辨可食用植物的诀窍吗？",
	},
	[30000002] = {
		ID = 30000002,
		Speaker = "我",
		Branches = {
			{ Text = "姑且可以算是略知一二吧。", Order = 3 },
		},
	},
	[30000003] = {
		ID = 30000003,
		Speaker = "我",
		Branches = {
			{ Text = "去过的地方多了，对于植物能不能吃也有点基本的观念。", Order = 4 },
		},
	},
	[30000004] = {
		ID = 30000004,
		Speaker = "瑟蕾雅",
		Text = "真不愧是晨星先生，真的好像是什么都知道一样！",
	},
	[30000005] = {
		ID = 30000005,
		Speaker = "瑟蕾雅",
		Text = "身为一个在这块土地上长大的人，我可不能输给您呢！",
	},
	[30000006] = {
		ID = 30000006,
		Speaker = "瑟蕾雅",
		Text = "……啊，在那边的似乎是很珍贵的香菇呢！有股很强烈的香气。",
	},
	[30000007] = {
		ID = 30000007,
		Speaker = "瑟蕾雅",
		Text = "我这就去采过来，请晨星先生在这边稍等一下就好！ 。",
	},
	[30000008] = {
		ID = 30000008,
		Text = "(瑟蕾雅消失)",
	},
	[30000009] = {
		ID = 30000009,
		Speaker = "我",
		Branches = {
			{ Text = "真是的，你这样也兴奋过头了吧。", Order = 10 },
		},
	},
	[30000010] = {
		ID = 30000010,
		Speaker = "我",
		Branches = {
			{ Text = "小心点，可别又摔倒了喔。", Order = 11 },
		},
	},
	[30000011] = {
		ID = 30000011,
		Speaker = "瑟蕾雅",
		Text = "(画面摇晃，表现出跌倒的感觉，从画面外飞出一些有出包感的表情符号)",
	},
	[30000012] = {
		ID = 30000012,
		Speaker = "瑟蕾雅",
		Text = "唉呀！",
	},
	[30000013] = {
		ID = 30000013,
		Speaker = "我",
		Branches = {
			{ Text = "……都已经提醒过了……居然还可以摔成这样，这也是种才能了。", Order = 14 },
		},
	},
	[30000014] = {
		ID = 30000014,
		Speaker = "我",
		Branches = {
			{ Text = "喂，瑟蕾雅，没有受伤吧？", Order = 15 },
		},
	},
	[30000015] = {
		ID = 30000015,
		Speaker = "瑟蕾雅",
		Text = "受伤……？欸嘿嘿……没有呀……",
	},
	[30000016] = {
		ID = 30000016,
		Speaker = "瑟蕾雅",
		Text = "反而……嘿嘿嘿……有点轻飘飘的感觉？",
	},
	[30000017] = {
		ID = 30000017,
		Speaker = "我",
		Branches = {
			{ Text = "瑟蕾雅？", Order = 18 },
		},
	},
	[30000018] = {
		ID = 30000018,
		Speaker = "我",
		Branches = {
			{ Text = "不对，你刚刚跌倒时吃下的香菇，该不会是……", Order = 19 },
		},
	},
	[30000019] = {
		ID = 30000019,
		Speaker = "瑟蕾雅",
		Text = "香菇？对喔……我们是来搜集食物的……",
	},
	[30000020] = {
		ID = 30000020,
		Speaker = "瑟蕾雅",
		Text = "咦？晨星先生是什么时候采到了这个大香菇的？",
	},
	[30000021] = {
		ID = 30000021,
		Text = "转场",
	},
	[30000022] = {
		ID = 30000022,
	},
	[30000023] = {
		ID = 30000023,
		Speaker = "瑟蕾雅",
		Text = "晨星先生……真的好厉害呢！",
	},
	[30000024] = {
		ID = 30000024,
		Speaker = "瑟蕾雅",
		Text = "这么大一朵的香菇……我还是第一次看到呢……",
	},
	[30000025] = {
		ID = 30000025,
		Speaker = "瑟蕾雅",
		Text = "光是看着……就让人好想吃一口……咕呜。",
	},
	[30000026] = {
		ID = 30000026,
		Speaker = "我",
		Text = "这个眼神……喂喂，你真的看到香菇了吗？",
	},
	[30000027] = {
		ID = 30000027,
		Speaker = "瑟蕾雅",
		Text = "咦？这除了香菇还能是什么……晨星先生是在故意考我吗？",
	},
	[30000028] = {
		ID = 30000028,
		Speaker = "瑟蕾雅",
		Text = "瑟蕾雅我啊，平时虽然很迷糊，但是这点事情还是不会搞错的。",
	},
	[30000030] = {
		ID = 30000030,
		Speaker = "瑟蕾雅",
		Text = "咦……？那当然是因为很热啊。",
	},
	[30000031] = {
		ID = 30000031,
		Speaker = "瑟蕾雅",
		Text = "很热，就要把衣服脱掉啊？",
	},
	[30000032] = {
		ID = 30000032,
		Speaker = "瑟蕾雅",
		Text = "嘻嘻嘻……好奇怪喔？晨星先生怎么都在问这些笨问题呀？",
	},
	[30000033] = {
		ID = 30000033,
		Speaker = "我",
		Text = "（错不了，这是那些香菇的毒性有致幻成分。）",
	},
	[30000034] = {
		ID = 30000034,
		Speaker = "我",
		Text = "（如果要让瑟蕾雅服下解药的话，方法就只有那个了。）",
	},
	[30000035] = {
		ID = 30000035,
		Speaker = "我",
		Text = "嗯，这是我刚找到的罕见香菇，你来尝尝味道吧？",
	},
	[30000036] = {
		ID = 30000036,
		Speaker = "瑟蕾雅",
		Text = "那我就开动了──啊姆……",
	},
	[30000037] = {
		ID = 30000037,
		Speaker = "瑟蕾雅",
		Text = "欸欸──！ ？这个香菇……有点……呜呜……粗呢……",
	},
	[30000038] = {
		ID = 30000038,
